INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('3/4 Sit-Up', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol and secure vos pieds. vos jambes should be bent at the genoux. 2. Place vos mains behind or to the side of your head. You will begin with votre dos on the ground. Position de depart. 3. Flex your hips and spine to raise your torse toward your genoux. 4. At the top of the contraction your torse should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/3_4_Sit-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('90/90 Hamstring', 'Ischio-jambiers', 'Poids de corps', '1. Allongez-vous au sol, with one leg extended straight out. 2. With the other leg, bend the hip and genoux to 90 degrees. You may brace your leg with vos mains if necessary. Position de depart. 3. Extend your leg straight into the air, pausing briefly at the top. Return the leg to the position de depart. 4. Repetez for 10-20 repetitions, and then switch to the other leg.', 'Muscles secondaires : Mollets. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/90_90_Hamstring/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Ab Crunch Machine', 'Abdominaux', 'Machine', '1. Select a light resistance and sit down on the ab machine placing vos pieds under the pads provided and grabbing the top handles. vos bras should be bent at a 90 degree angle as you rest the triceps on the pads provided. Position de depart. 2. At the same time, begin to lift the legs up as you crunch your upper torse. Expirez as you perform this movement. Conseil : Be sure to use a slow and controlled motion. Concentrate on using your abdominaux to move the poids while relaxing vos jambes and feet. 3. Apres une pause, Lentement, Revenez en position de depart as you Inspirez. 4. Repetez le mouvement for the prescribed amount of repetitions.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ab_Crunch_Machine/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Ab Roller', 'Abdominaux', 'Autre', '1. Hold the Ab Roller with both hands and kneel on le sol. 2. Now place the ab roller on le sol in front of you so that you are on all vos mains and genoux (as in a kneeling push up position). Position de depart. 3. Lentement, roll the ab roller straight forward, stretching votre corps into a straight position. Conseil : Go down as far as you can without touching le sol with votre corps. Inspirez during this portion of le mouvement. 4. Apres une pause, at the stretched position, start pulling yourself back to the position de depart as you Expirez. Conseil : Go Lentement, and keep your abdominaux tight en permanence.', 'Muscles secondaires : Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ab_Roller/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Adductor', 'Adducteurs', 'Foam roller', '1. Lie face down with one leg on a foam roll. 2. Rotate the leg so that the foam roll contacts against your inner cuisses. Shift as much poids onto the foam roll as can be tolerated. 3. While trying to relax the muscles if the inner cuisses, roll over the foam between your hip and genoux, holding points of tension for 10-30 seconds. Repetez with the other leg.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Adductor/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Adductor/Groin', 'Adducteurs', 'Autre', '1. Allongez-vous au sol with vos pieds raised towards the ceiling. 2. Have your partner hold vos pieds or ankles. Abduct vos jambes as far as you can. Position de depart. 3. Attempt to squeeze vos jambes together for 10 or more seconds, while your partner prevents you from doing so. 4. Now, relax the muscles in vos jambes as your partner pushes vos pieds apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Adductor_Groin/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Advanced Kettlebell Windmill', 'Abdominaux', 'Kettlebell', '1. Clean and press a kettlebells overhead with one arm. 2. Keeping the kettlebells locked out en permanence, push your butt out in the direction of the locked out kettlebells. Keep the non-working arm behind votre dos and turn vos pieds out at a forty-five degree angle from the arm with the kettlebells. 3. Lower yourself as far as possible. 4. Pause for a second and reverse the motion back to the position de depart.', 'Muscles secondaires : Fessiers, Ischio-jambiers, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Advanced_Kettlebell_Windmill/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Air Bike', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol with your lower back pressed to the ground. For this exercise, you will need to put vos mains beside your head. Be careful however to not strain with the neck as you perform it. Now lift your epaules into the crunch position. 2. Bring genoux up to where they are perpendicular to le sol, with your lower legs parallel to le sol. Position de depart. 3. Now simultaneously, Lentement, go through a cycle pedal motion kicking forward with the right leg and bringing in the genoux of the left leg. Bring your right coudes close to your left genoux by crunching to the side, as you Expirez. 4. Go back to the initial position as you Inspirez. 5. Crunch to the opposite side as you cycle vos jambes and bring closer your left coudes to your right genoux and exhale. 6. Continue alternating in this manner until all of the recommended repetitions for each side have been completed.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Air_Bike/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('All Fours Quad Stretch', 'Quadriceps', 'Poids de corps', '1. Start off on vos mains and genoux, then lift your leg off le sol and hold the foot with your hand. 2. Use your hand to hold the foot or ankle, keeping the genoux fully flexed, stretching the quadriceps and hip flexors. 3. Focus on extending your hips, thrusting them towards le sol. Hold for 10-20 seconds and then switch sides.', 'Muscles secondaires : Quadriceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/All_Fours_Quad_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternate Hammer Curl', 'Biceps', 'Haltères', '1. Tenez-vous debout avec your torse upright and a halteres in each hand being held bras tendus. The coudes should be close to the torse. 2. The palms of the hands should be facing your torse. Position de depart. 3. While holding the upper arm stationary, curl the right poids forward while contracting the biceps as you Expirez. Continue le mouvement until your biceps is entierement contracte and the halteres are at epaules level. Maintenez 1 seconde as you squeeze the biceps. Conseil : Only the forearms should move. 4. Lentement, begin to bring the halteres back to position de depart as your Inspirez. 5. Repetez le mouvement with the left hand. This equals one repetition. 6. Continue alternating in this manner for the recommended amount of repetitions.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Hammer_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternate Heel Touchers', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol with the genoux bent and the feet on le sol around 18-24 inches apart. vos bras should be extended by your side. Position de depart. 2. Crunch over your torse forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement. 3. Now go back Lentement, to the position de depart en inspirant. 4. Now crunch over your torse forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the position de depart en inspirant. Now that both heels have been touched, that is considered 1 repetition. 5. Continue alternating sides in this manner until all prescribed repetitions are done.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Heel_Touchers/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternate Incline Dumbbell Curl', 'Biceps', 'Haltères', '1. Asseyez-vous sur un banc with a halteres in each hand being held bras tendus. Conseil : Keep the coudes close to the torse.Position de depart. 2. While holding the upper arm stationary, curl the right poids forward while contracting the biceps as you Expirez. As you do so, rotate the hand so that the palm is facing up. Continue le mouvement until your biceps is entierement contracte and the halteres are at epaules level. Maintenez 1 seconde as you squeeze the biceps. Conseil : Only the forearms should move. 3. Lentement, begin to bring the halteres back to position de depart as your Inspirez. 4. Repetez le mouvement with the left hand. This equals one repetition. 5. Continue alternating in this manner for the recommended amount of repetitions.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Incline_Dumbbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternate Leg Diagonal Bound', 'Quadriceps', 'Autre', '1. Assume a comfortable stance with one foot slightly in front of the other. 2. Begin by pushing off with the front leg, driving the opposite genoux forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound. 3. It may help to use a line on the ground to guage distance from side to side. 4. Repetez the sequence with the other leg.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Leg_Diagonal_Bound/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternating Cable Shoulder Press', 'Épaules', 'Poulie', '1. Move the cables to the bottom of the tower and select an appropriate poids. 2. Grasp the cables and hold them at epaules height, palms facing forward. Position de depart. 3. Keeping your head and poitrine up, extend through the coudes to press one side directly over head. 4. After pausing at the top, Revenez en position de depart and Repetez de l autre cote.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Cable_Shoulder_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternating Deltoid Raise', 'Épaules', 'Haltères', '1. In a standing position, hold a pair of halteres at your side. 2. Keeping your coudes slightly bent, raise the poids directly in front of you to epaules height, avoiding any swinging or cheating. 3. Return the poids to your side. 4. On the next repetition, raise the poids laterally, raising them out to your side to about epaules height. 5. Return the poids to the position de depart and continue alternating to the front and side.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Deltoid_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternating Floor Press', 'Pectoraux', 'Kettlebell', '1. Allongez-vous au sol with two kettlebells next to your epaules. 2. Position one in place on your poitrine and then the other, gripping the kettlebells on the handle with the palms facing forward. 3. Extend both arms, so that the kettlebells are being held above your poitrine. Lower one kettlebells, bringing it to your poitrine and turn the poignets in the direction of the locked out kettlebells. 4. Raise the kettlebells and Repetez de l autre cote.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Floor_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternating Hang Clean', 'Ischio-jambiers', 'Kettlebell', '1. Place two kettlebells between vos pieds. To get in the position de depart, push your butt back and look straight ahead. 2. Clean one kettlebells to your epaules and hold on to the other kettlebells in a hanging position. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so. 3. Lower the cleaned kettlebells to a hanging position and clean the alternate kettlebells. Repetez.', 'Muscles secondaires : Biceps, Mollets, Avant-bras, Fessiers, Bas du dos, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Hang_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternating Kettlebell Press', 'Épaules', 'Kettlebell', '1. Clean two kettlebells to your epaules. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so. 2. Press one directly overhead by extending through the coudes, turning it so the palm faces forward while holding the other kettlebells stationary . 3. Lower the pressed kettlebells to the position de depart and immediately press with your other arm.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Kettlebell_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternating Kettlebell Row', 'Milieu du dos', 'Kettlebell', '1. Place two kettlebells in front of vos pieds. Bend your genoux slightly and push your butt out as much as possible. As you bend over to get into the position de depart grab both kettlebells by the handles. 2. Pull one kettlebells off of le sol while holding on to the other kettlebells. Retract the omoplates of the working side, as you flex the coudes, drawing the kettlebells towards your stomach or rib cage. 3. Lower the kettlebells in the working arm and Repetez with your other arm.', 'Muscles secondaires : Biceps, Dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Kettlebell_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternating Renegade Row', 'Milieu du dos', 'Kettlebell', '1. Place two kettlebells on le sol about epaules width apart. Position yourself on your toes and vos mains as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position vos pieds wide for support. 2. Push one kettlebells into le sol and row the other kettlebells, retracting the omoplates of the working side as you flex the coudes, pulling it to your side. 3. Then lower the kettlebells to le sol and begin the kettlebells in the opposite hand. Repetez for several reps.', 'Muscles secondaires : Abdominaux, Biceps, Pectoraux, Dos, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Renegade_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Ankle Circles', 'Mollets', 'Autre', '1. Use a sturdy object like a squat rack to hold yourself. 2. Lift the right leg in the air (just around 2 inches from le sol) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Conseil : One circle equals 1 repetition. Breathe normally as you perform le mouvement. 3. When you are done with the right foot, then Repetez with the left leg.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ankle_Circles/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Ankle On The Knee', 'Fessiers', 'Autre', '1. From a lying position, bend your genoux and keep vos pieds on le sol. 2. Place your ankle of one foot on your opposite genoux. 3. Grasp the cuisses or genoux of the bottom leg and pull both of vos jambes into the poitrine. Relax your neck and epaules. Hold for 10-20 seconds and then switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ankle_On_The_Knee/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Anterior Tibialis-SMR', 'Mollets', 'Autre', '1. Begin seated on the ground with vos jambes bent and vos pieds on le sol. 2. Using a Muscle Roller or a rolling pin, apply pressure to the muscles on the outside of your shins. Work from just below the genoux to above the ankle, pausing at points of tension for 10-30 seconds. Repetez de l autre cote.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Anterior_Tibialis-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Anti-Gravity Press', 'Épaules', 'Barre', '1. Place a bar on the ground behind the head of an incline banc. 2. Lay on the banc face down. With a pronated grip, pick the barre up from le sol. Flex the coudes, performing a reverse curl to bring the bar near your poitrine. Position de depart. 3. To begin, press the barre out in front of your head by extending your coudes. Keep vos bras parallel to the ground throughout le mouvement. 4. Revenez en position de depart and Repetez to complete the set.', 'Muscles secondaires : Milieu du dos, Trapèzes, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Anti-Gravity_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Arm Circles', 'Épaules', 'Autre', '1. Stand up and extend vos bras straight out by the sides. The arms should be parallel to le sol and perpendicular (90-degree angle) to your torse. Position de depart. 2. Lentement, start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform le mouvement. 3. Continue the circular motion of the outstretched arms for about ten seconds. Then reverse le mouvement, going the opposite direction.', 'Muscles secondaires : Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arm_Circles/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Arnold Dumbbell Press', 'Épaules', 'Haltères', '1. Asseyez-vous sur un banc with back support and hold two halteres in front of you at about upper poitrine level with your palms facing votre corps and your coudes bent. Conseil : vos bras should be next to your torse. The position de depart should look like the contracted portion of a halteres curl. 2. Now to perform le mouvement, raise the halteres as you rotate the palms of vos mains until they are facing forward. 3. Continue lifting the halteres until vos bras are extended above you in straight arm position. Expirez as you perform this portion of le mouvement. 4. Apres une pause, at the top, begin to lower the halteres to the original position by rotating the palms of vos mains towards you. Conseil : The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Inspirez as you perform this portion of le mouvement. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Around The Worlds', 'Pectoraux', 'Haltères', '1. Lay down on a flat banc holding a halteres in each hand with the palms of the hands facing towards the ceiling. Conseil : vos bras should be parallel to le sol and next to your cuisses. To avoid injury, make sure that you keep your coudes slightly bent. Position de depart. 2. Now move the halteres by creating a semi-circle as you displace them from the initial position to over the head. All of le mouvement should happen with the arms parallel to le sol en permanence. Inspirez as you perform this portion of le mouvement. 3. Reverse le mouvement to return the poids to the position de depart en expirant.', 'Muscles secondaires : Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Around_The_Worlds/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Atlas Stone Trainer', 'Bas du dos', 'Autre', '1. This trainer is effective for developing Atlas Stone strength for those who don''t have access to stones, and are typically made from bar ends or heavy pipe. 2. Begin by loading the desired poids onto the bar. Straddle the poids, wrapping vos bras around the implement, bending at the hips. 3. Begin by pulling the poids up past the genoux, extending through the hips. As the poids clears the genoux, it can be lapped by resting it on your cuisses and sitting back, hugging it tightly to your poitrine. 4. Finish le mouvement by extending through your hips and genoux to raise the poids as high as possible. The poids can be returned to the lap or to the ground for successive repetitions.', 'Muscles secondaires : Biceps, Avant-bras, Fessiers, Ischio-jambiers, Quadriceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Atlas_Stone_Trainer/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Atlas Stones', 'Bas du dos', 'Autre', '1. Begin with the atlas stone between vos pieds. Bend at the hips to wrap vos bras vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold. 2. Pulling the stone into your torse, drive through the back half of vos pieds to pull the stone from the ground. 3. As the stone passes the genoux, lap it by sitting backward, pulling the stone on top of your cuisses. 4. Sit low, getting the stone high onto your poitrine as you change your grip to reach over the stone. Stand, driving through with your hips. Close distance to the loading platform, and lean back, extending the hips to get the stone as high as possible.', 'Muscles secondaires : Abdominaux, Adducteurs, Biceps, Mollets, Avant-bras, Fessiers, Ischio-jambiers, Milieu du dos, Quadriceps, Trapèzes. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Atlas_Stones/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Axle Deadlift', 'Bas du dos', 'Autre', '1. Approach the bar so that it is centered over vos pieds. You feet should be about hip width apart. Bend at the hip to grip the bar at epaules width, allowing your omoplates to protract. Typically, you would use an over/under grip. 2. With vos pieds and your grip set, take a big breath and then lower your hips and flex the genoux until your shins contact the bar. Look forward with your head, keep your poitrine up and votre dos arched, and begin driving through the heels to move the poids upward. 3. After the bar passes the genoux, aggressively pull the bar back, pulling your omoplates together as you drive your hips forward into the bar. 4. Lower the bar by bending at the hips and guiding it to le sol.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Milieu du dos, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Axle_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Back Flyes - With Bands', 'Épaules', 'Élastique', '1. Run a band around a stationary post like that of a squat rack. 2. Grab the band by the handles and stand back so that the tension in the band rises. 3. Extend and lift the arms straight in front of you. Conseil : vos bras should be straight and parallel to le sol while perpendicular to your torse. vos pieds should be firmly planted on le sol spread at epaules width. Position de depart. 4. en expirant, move vos bras to the sides and back. Keep vos bras extended and parallel to le sol. Continue le mouvement until the arms are extended to your sides. 5. Apres une pause, go back to the original position en inspirant. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Milieu du dos, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Back_Flyes_-_With_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Backward Drag', 'Quadriceps', 'Autre', '1. Load a sled with the desired poids, attaching a rope or straps to the sled that you can hold onto. 2. Begin the exercise by moving backwards for a given distance. Leaning back, extend through the legs for short steps to move as quickly as possible.', 'Muscles secondaires : Mollets, Avant-bras, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Backward_Drag/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Backward Medicine Ball Throw', 'Épaules', 'Medecine ball', '1. This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall. 2. Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between vos jambes. 3. Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner. 4. Your partner can then roll the ball back to you. Repetez for the desired number of repetitions.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Backward_Medicine_Ball_Throw/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Balance Board', 'Mollets', 'Autre', '1. Place a balance board in front of you. 2. Stand up on it and try to balance yourself. 3. Hold the balance for as long as desired.', 'Muscles secondaires : Ischio-jambiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Balance_Board/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Ball Leg Curl', 'Ischio-jambiers', 'Swiss ball', '1. Begin on le sol laying on votre dos with vos pieds on top of the ball. 2. Position the ball so that when vos jambes are extended your ankles are on top of the ball. Position de depart. 3. Raise your hips off of the ground, keeping your poids on the omoplates and vos pieds. 4. Flex the genoux, pulling the ball as close to you as you can, contracting the ischio-jambiers. 5. Apres une pause, Revenez en position de depart.', 'Muscles secondaires : Mollets, Fessiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ball_Leg_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Band Assisted Pull-Up', 'Dos', 'Autre', '1. Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance. 2. Pull the end of the band down, and place one bent genoux into the loop, ensuring it won''t slip out. Take a medium to prise large on the bar. Position de depart. 3. Pull yourself upward by contracting the lats as you flex the coudes. The coudes should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements. 4. Apres une pause, Revenez en position de depart.', 'Muscles secondaires : Abdominaux, Avant-bras, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Assisted_Pull-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Band Good Morning', 'Ischio-jambiers', 'Élastique', '1. Using a 41 inch band, stand on one end, spreading vos pieds a small amount. Bend at the hips to loop the end of the band behind your neck. Position de depart. 2. Keeping vos jambes straight, extend through the hips to come to a near vertical position. 3. Ensure that you do not round votre dos as you go down back to the position de depart.', 'Muscles secondaires : Fessiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Good_Morning/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Band Good Morning (Pull Through)', 'Ischio-jambiers', 'Élastique', '1. Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. vos mains can help hold the band in position. 2. Begin by bending at the hips, getting your butt back as far as possible. Keep votre dos flat and bend forward to about 90 degrees. Your genoux should be only slightly bent. 3. Revenez en position de depart be driving through with the hips to come back to a standing position.', 'Muscles secondaires : Fessiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Good_Morning_Pull_Through/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Band Hip Adductions', 'Adducteurs', 'Élastique', '1. Anchor a band around a solid post or other object. 2. Tenez-vous debout avec your left side to the post, and put your right foot through the band, getting it around the ankle. 3. Stand up straight and hold onto the post if needed. Position de depart. 4. Keeping the genoux straight, raise your right legs out to the side as far as you can. 5. Revenez en position de depart and Repetez for the desired rep count. 6. Switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Hip_Adductions/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Band Pull Apart', 'Épaules', 'Élastique', '1. Begin with vos bras extended straight out in front of you, holding the band with both hands. 2. Initiate le mouvement by performing a reverse fly motion, moving vos mains out laterally to your sides. 3. Keep your coudes extended as you perform le mouvement, bringing the band to your poitrine. Ensure that you keep your epaules back during the exercise. 4. Pause as you complete le mouvement, returning to the position de depart under control.', 'Muscles secondaires : Milieu du dos, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Pull_Apart/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Band Skull Crusher', 'Triceps', 'Élastique', '1. Secure a band to the base of a rack or the banc. Lay on the banc so that the band is lined up with your head. 2. Take hold of the band, raising your coudes so that the upper arm is perpendicular to le sol. With the coudes flexed, the band should be above your head. Position de depart. 3. Extend through the coudes to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and Revenez en position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Skull_Crusher/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Ab Rollout', 'Abdominaux', 'Barre', '1. For this exercise you will need to get into a pushup position, but instead of having vos mains of le sol, you will be grabbing on to an Olympic barre (loaded with 5-10 lbs on each side) instead. Position de depart. 2. While keeping a slight arch on votre dos, lift your hips and roll the barre towards vos pieds en expirant. Conseil : As you perform le mouvement, your fessiers should be coming up, you should be keeping the abdominaux tight and should maintain votre dos posture en permanence. Also vos bras should be staying perpendicular to le sol throughout le mouvement. If you don''t, you will work out your epaules and back more than the abdominaux. 3. After a second contraction at the top, start to roll the barre back forward to the position de depart Lentement, en inspirant. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Bas du dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Ab_Rollout/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Ab Rollout - On Knees', 'Abdominaux', 'Barre', '1. Hold an Olympic barre loaded with 5-10lbs on each side and kneel on le sol. 2. Now place the barre on le sol in front of you so that you are on all vos mains and genoux (as in a kneeling push up position). Position de depart. 3. Lentement, roll the barre straight forward, stretching votre corps into a straight position. Conseil : Go down as far as you can without touching le sol with votre corps. Inspirez during this portion of le mouvement. 4. Apres une pause, at the stretched position, start pulling yourself back to the position de depart as you Expirez. Conseil : Go Lentement, and keep your abdominaux tight en permanence.', 'Muscles secondaires : Bas du dos, Épaules. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Ab_Rollout_-_On_Knees/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Bench Press - Medium Grip', 'Pectoraux', 'Barre', '1. Allongez-vous au sol on a flat banc. Using a prise moyenne (a grip that creates a 90-degree angle in the middle of le mouvement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with vos bras locked. Position de depart. 2. From the position de depart, Inspirez and begin coming down Lentement, until the bar touches your middle poitrine. 3. Apres une pause, push the bar back to the position de depart as you Expirez. Focus on pushing the bar using your poitrine muscles. Lock vos bras and squeeze your poitrine in the contracted position at the top of the motion, Maintenez 1 seconde and then start coming down Lentement, again. Conseil : Ideally, lowering the poids should take about twice as long as raising it. 4. Repetez le mouvement for the prescribed amount of repetitions. 5. When you are done, place the bar back in the rack.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Curl', 'Biceps', 'Barre', '1. Tenez-vous debout avec your torse upright while holding a barre at a epaules-width grip. The palm of vos mains should be facing forward and the coudes should be close to the torse. Position de depart. 2. While holding the upper arms stationary, curl the poids forward while contracting the biceps as you Expirez. Conseil : Only the forearms should move. 3. Continue le mouvement until your biceps are entierement contracte and the bar is at epaules level. Maintenez 1 seconde and squeeze the biceps hard. 4. Lentement, begin to bring the bar back to position de depart as your Inspirez. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Curls Lying Against An Incline', 'Biceps', 'Barre', '1. Lie against an incline banc, with vos bras holding a barre and hanging down in a horizontal line. Position de depart. 2. While keeping the upper arms stationary, curl the poids up as high as you can while squeezing the biceps. Expirez as you perform this portion of le mouvement. Conseil : Only the forearms should move. Do not swing the arms. 3. After a second contraction, Lentement, go back to the position de depart en inspirant. Conseil : Make sure that you go all of the way down. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curls_Lying_Against_An_Incline/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Deadlift', 'Bas du dos', 'Barre', '1. Stand in front of a loaded barre. 2. While keeping the back as straight as possible, bend your genoux, bend forward and grasp the bar using a medium (epaules width) prise en pronation. This will be the position de depart of the exercise. Conseil : If it is difficult to hold on to the bar with this grip, alternate your grip or use poignets straps. 3. While holding the bar, start the lift by pushing with vos jambes while simultaneously getting your torse to the upright position as you Expirez. In the upright position, stick your poitrine out and contract the back by bringing the omoplates back. Think of how the soldiers in the military look when they are in standing in attention. 4. Go back to the position de depart by bending at the genoux while simultaneously leaning the torse forward at the waist while keeping the back straight. When the poids on the bar touch le sol you are back at the position de depart and ready to perform another repetition. 5. Perform the amount of repetitions prescribed in the program.', 'Muscles secondaires : Mollets, Avant-bras, Fessiers, Ischio-jambiers, Dos, Milieu du dos, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Full Squat', 'Quadriceps', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above epaules level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your epaules (slightly below the neck) across it. 2. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Step away from the rack and position vos jambes using a epaules-width medium stance with the toes slightly pointed out. Keep your head up en permanence and maintain a straight back. Position de depart. 4. Begin to Lentement, lower the bar by bending the genoux and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your ischio-jambiers are on your mollets. Inhale as you perform this portion of le mouvement. 5. Begin to raise the bar en expirant by pushing le sol with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the position de depart. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Glute Bridge', 'Fessiers', 'Barre', '1. Begin seated on the ground with a loaded barre over vos jambes. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on le sol. 2. Begin le mouvement by driving through with your heels, extending your hips vertically through the bar. Your poids should be supported by your upper back and the heels of vos pieds. 3. Extend as far as possible, then reverse the motion to Revenez en position de depart.', 'Muscles secondaires : Mollets, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Guillotine Bench Press', 'Pectoraux', 'Barre', '1. Using a prise moyenne (a grip that creates a 90-degree angle in the middle of le mouvement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with vos bras locked. Position de depart. 2. As you Inspirez, bring the bar down Lentement, until it is about 1 inch from your neck. 3. Apres une pause, bring the bar back to the position de depart as you Expirez and push the bar using your poitrine muscles. Lock vos bras and squeeze your poitrine in the contracted position, Maintenez 1 seconde and then start coming down Lentement, again. It should take at least twice as long to go down than to come up. 4. Repetez le mouvement for the prescribed amount of repetitions. 5. When you are done, place the bar back in the rack.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Guillotine_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Hack Squat', 'Quadriceps', 'Barre', '1. Stand up straight while holding a barre behind you bras tendus and vos pieds at epaules width. Conseil : A epaules width grip is best with the palms of vos mains facing back. You can use poignets wraps for this exercise for a better grip. Position de depart. 2. While keeping your head and eyes up and back straight, squat until your upper cuisses are parallel to le sol. Inspirez as you Lentement, go down. 3. Pressing mainly with the heel of the foot and squeezing the cuisses, go back up as you Expirez. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Avant-bras, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hack_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Hip Thrust', 'Fessiers', 'Barre', '1. Begin seated on the ground with a banc directly behind you. Have a loaded barre over vos jambes. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. 2. Roll the bar so that it is directly above your hips, and lean back against the banc so that your omoplates are near the top of it. 3. Begin le mouvement by driving through vos pieds, extending your hips vertically through the bar. Your poids should be supported by your omoplates and vos pieds. Extend as far as possible, then reverse the motion to Revenez en position de depart.', 'Muscles secondaires : Mollets, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Incline Bench Press - Medium Grip', 'Pectoraux', 'Barre', '1. Allongez-vous au sol on an incline banc. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of le mouvement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with vos bras locked. Position de depart. 2. As you Inspirez, come down Lentement, until you feel the bar on you upper poitrine. 3. Apres une pause, bring the bar back to the position de depart as you Expirez and push the bar using your poitrine muscles. Lock vos bras in the contracted position, squeeze your poitrine, Maintenez 1 seconde and then start coming down Lentement, again. Conseil : it should take at least twice as long to go down than to come up. 4. Repetez le mouvement for the prescribed amount of repetitions. 5. When you are done, place the bar back in the rack.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Incline Shoulder Raise', 'Épaules', 'Barre', '1. Allongez-vous au sol on an Incline banc. Using a prise moyenne (a grip that is slightly wider than epaules width), lift the bar from the rack and hold it straight over you with vos bras straight. Position de depart. 2. While keeping the arms straight, lift the bar by protracting your omoplates, raising the epaules from the banc as you Expirez. 3. Bring back the bar to the position de depart as you Inspirez. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Pectoraux. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Shoulder_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Lunge', 'Quadriceps', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below epaules level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your epaules (slightly below the neck) across it. 2. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torse upright and maintaining balance. Inhale as you go down. Note: Do not allow your genoux to go forward beyond your toes as you come down, as this will put undue stress on the genoux joint. li> 4. Using mainly the heel of your foot, push up and go back to the position de depart en expirant. 5. Repetez le mouvement for the recommended amount of repetitions and then perform with the left leg.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Lunge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Rear Delt Row', 'Épaules', 'Barre', '1. Stand up straight while holding a barre using a wide (higher than epaules width) and overhand (palms facing votre corps) grip. 2. Bend genoux slightly and bend over as you keep the natural arch of votre dos. Let the arms hang in front of you as they hold the bar. Once your torse is parallel to le sol, flare the coudes out and away from votre corps. Conseil : Your torse and vos bras should resemble the letter "T". Now you are ready to begin the exercise. 3. While keeping the upper arms perpendicular to the torse, pull the barre up towards your upper poitrine as you squeeze the rear delts and you Expirez. Conseil : When performed correctly, this exercise should resemble a banc press in reverse. Also, refrain from using your biceps to do the work. Focus on targeting the rear delts; the arms should only act as hooks. 4. Lentement, go back to the initial position as you Inspirez. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Dos, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Rear_Delt_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Rollout from Bench', 'Abdominaux', 'Barre', '1. Place a loaded barre on the ground, near the end of a banc. Kneel with both legs on the banc, and take a medium to prise serree on the barre. Position de depart. 2. To begin, extend through the hips to Lentement, roll the bar forward. As you roll out, flex the epaules to roll the bar above your head. Ensure that vos bras remain extended throughout le mouvement. 3. When the bar has been moved as far forward as possible, Revenez en position de depart.', 'Muscles secondaires : Fessiers, Ischio-jambiers, Dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Rollout_from_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Seated Calf Raise', 'Mollets', 'Barre', '1. Place a block about 12 inches in front of a flat banc. 2. Sit on the banc and place the ball of vos pieds on the block. 3. Have someone place a barre over your upper cuisses about 3 inches above your genoux and hold it there. Position de depart. 4. Raise up on your toes as high as possible as you squeeze the mollets and as you Expirez. 5. After a second contraction, Lentement, go back to the position de depart. Conseil : To get maximum benefit stretch your mollets as far as you can. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Seated_Calf_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Shoulder Press', 'Épaules', 'Barre', '1. Asseyez-vous sur un banc with back support in a squat rack. Position a barre at a height that is just above your head. Grab the barre with a pronated grip (palms facing forward). 2. Once you pick up the barre with the correct grip width, lift the bar up over your head by locking vos bras. Hold at about epaules level and slightly in front of your head. Position de depart. 3. Lower the bar down to the epaules Lentement, en inspirant. 4. Lift the bar back up to the position de depart en expirant. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Pectoraux, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shoulder_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Shrug', 'Trapèzes', 'Barre', '1. Tenez-vous debout avec vos pieds at epaules width as you hold a barre with both hands in front of you using a pronated grip (palms facing the cuisses). Conseil : vos mains should be a little wider than epaules width apart. You can use poignets wraps for this exercise for a better grip. Position de depart. 2. Raise your epaules up as far as you can go as you Expirez and hold the contraction for a second. Conseil : Refrain from trying to lift the barre by using your biceps. 3. Lentement, Revenez en position de depart as you Inspirez. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shrug/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Shrug Behind The Back', 'Trapèzes', 'Barre', '1. Tenez-vous debout avec vos pieds at epaules width as you hold a barre with both hands behind votre dos using a pronated grip (palms facing back). Conseil : vos mains should be a little wider than epaules width apart. You can use poignets wraps for this exercise for better grip. Position de depart. 2. Raise your epaules up as far as you can go as you Expirez and hold the contraction for a second. Conseil : Refrain from trying to lift the barre by using your biceps. The arms should remain stretched out en permanence. 3. Lentement, Revenez en position de depart as you Inspirez. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shrug_Behind_The_Back/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Side Bend', 'Abdominaux', 'Barre', '1. Stand up straight while holding a barre placed on the back of your epaules (slightly below the neck). vos pieds should be epaules width apart. Position de depart. 2. While keeping votre dos straight and your head up, bend only at the waist to the right as far as possible. Inspirez as you bend to the side. Then Maintenez 1 seconde and come back up to the position de depart en expirant. Conseil : Keep the rest of the body stationary. 3. Now Repetez le mouvement but bending to the left instead. Maintenez 1 seconde and come back to the position de depart. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Side_Bend/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Side Split Squat', 'Quadriceps', 'Barre', '1. Stand up straight while holding a barre placed on the back of your epaules (slightly below the neck). vos pieds should be placed wide apart with the foot of the lead leg angled out to the side. Position de depart. 2. Lower votre corps towards the side of your angled foot by bending the genoux and hip of your lead leg and while keeping the opposite leg only slightly bent. Inspirez as you lower votre corps. 3. Revenez en position de depart by extending the hip and genoux of the lead leg. Expirez as you perform this movement. 4. After performing the recommended amount of reps, Repetez le mouvement with the opposite leg.', 'Muscles secondaires : Mollets, Ischio-jambiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Side_Split_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Squat', 'Quadriceps', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below epaules level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your epaules (slightly below the neck) across it. 2. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Step away from the rack and position vos jambes using a epaules width medium stance with the toes slightly pointed out. Keep your head up en permanence and also maintain a straight back. Position de depart. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section). 4. Begin to Lentement, lower the bar by bending the genoux and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the mollets becomes slightly less than 90-degrees. Inhale as you perform this portion of le mouvement. Conseil : If you performed the exercise correctly, the front of the genoux should make an imaginary straight line with the toes that is perpendicular to the front. If your genoux are past that imaginary line (if they are past your toes) then you are placing undue stress on the genoux and the exercise has been performed incorrectly. 5. Begin to raise the bar en expirant by pushing le sol with the heel of your foot as you straighten the legs again and go back to the position de depart. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Squat To A Bench', 'Quadriceps', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat banc or a box behind you. The flat banc is used to teach you to set your hips back and to hit depth. 2.  3. Then, set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your epaules (slightly below the neck) across it. 4. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 5. Step away from the rack and position vos jambes using a epaules width medium stance with the toes slightly pointed out. Keep your head up en permanence as looking down will get you off balance and also maintain a straight back. Position de depart. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section). 6. Begin to Lentement, lower the bar by bending the genoux and sitting your hips back as you maintain a straight posture with the head up. Continue down until you slightly touch the banc behind you. Inhale as you perform this portion of le mouvement. Conseil : If you performed the exercise correctly, the front of the genoux should make an imaginary straight line with the toes that is perpendicular to the front. If your genoux are past that imaginary line (if they are past your toes) then you are placing undue stress on the genoux and the exercise has been performed incorrectly. 7. Begin to raise the bar en expirant by pushing le sol with the heel of your foot as you straighten the legs and extend the hips to go back to the position de depart. 8. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Squat_To_A_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Step Ups', 'Quadriceps', 'Barre', '1. Stand up straight while holding a barre placed on the back of your epaules (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat banc). Position de depart. 2. Place the right foot on the elevated platform. Step on the platform by extending the hip and the genoux of your right leg. Use the heel mainly to lift the rest of votre corps up and place the foot of the left leg on the platform as well. Expirez as you execute the force required to come up. 3. Step down with the left leg by flexing the hip and genoux of the right leg en inspirant. Return to the original standing position by placing the right foot of to next to the left foot on the initial position. 4. Repetez with the right leg for the recommended amount of repetitions and then perform with the left leg.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Quadriceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Step_Ups/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Walking Lunge', 'Quadriceps', 'Barre', '1. Begin standing with vos pieds epaules width apart and a barre across your upper back. 2. Step forward with one leg, flexing the genoux to drop your hips. Descend until your rear genoux nearly touches the ground. Your posture should remain upright, and your front genoux should stay above the front foot. 3. Drive through the heel of your lead foot and extend both genoux to raise yourself back up. 4. Step forward with your rear foot, Repetezing the lunge on the opposite leg.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Walking_Lunge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Battling Ropes', 'Épaules', 'Autre', '1. For this exercise you will need a heavy rope anchored at its center 15-20 feet away. Standing in front of the rope, take an end in each hand with vos bras extended at your side. Position de depart. 2. Initiate le mouvement by rapidly raising one arm to epaules level as quickly as you can. 3. As you let that arm drop to the position de depart, raise the opposite side. 4. Continue alternating your left and right arms, whipping the ropes up and down as fast as you can.', 'Muscles secondaires : Pectoraux, Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Battling_Ropes/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bear Crawl Sled Drags', 'Quadriceps', 'Autre', '1. Wearing either a harness or a loose poids belt, attach the chain to the back so that you will be facing away from the sled. Bend down so that vos mains are on the ground. votre dos should be flat and genoux bent. Position de depart. 2. Begin by driving with legs, alternating left and right. Use vos mains to maintain balance and to help pull. Try to keep votre dos flat as you move over a given distance.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bear_Crawl_Sled_Drags/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Behind Head Chest Stretch', 'Pectoraux', 'Autre', '1. Sit upright on le sol with your partner behind you. 2. Place vos mains behind your hand, and push your coudes back as far as you can. Your partner should hold your coudes. Position de depart. 3. Gently attempt to pull your coudes forward with vos mains still behind your head for 10 or more seconds. Your partner should prevent your coudes from moving. 4. Now, relax your muscles and have your partner gently pull the coudes back as far as it comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury.', 'Muscles secondaires : Épaules. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Behind_Head_Chest_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bench Dips', 'Triceps', 'Poids de corps', '1. For this exercise you will need to place a banc behind votre dos. With the banc perpendicular to votre corps, and while looking away from it, hold on to the banc on its edge with the hands fully extended, separated at epaules width. The legs will be extended forward, bent at the waist and perpendicular to your torse. Position de depart. 2. Lentement, lower votre corps en inspirant by bending at the coudes until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Conseil : Keep the coudes as close as possible throughout le mouvement. Forearms should always be pointing down. 3. Using your triceps to bring your torse up again, lift yourself back to the position de depart. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Dips/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bench Jump', 'Quadriceps', 'Poids de corps', '1. Begin with a box or banc 1-2 feet in front of you. Tenez-vous debout avec vos pieds epaules width apart. Position de depart. 2. Perform a short squat in preparation for the jump; swing vos bras behind you. 3. Rebound out of this position, extending through the hips, genoux, and ankles to jump as high as possible. Swing vos bras forward and up. 4. Jump over the banc, landing with the genoux bent, absorbing the impact through the legs. 5. Turn around and face the opposite direction, then jump back over the banc.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Jump/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bench Press - Powerlifting', 'Triceps', 'Barre', '1. Begin by lying on the banc, getting your head beyond the bar if possible. Tuck vos pieds underneath you and arch votre dos. Using the bar to help support your poids, lift your epaules off the banc and retract them, squeezing the omoplates together. Use vos pieds to drive your traps into the banc. Maintain this tight body position throughout le mouvement. 2. However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your epaules. Focus on squeezing the bar and trying to pull it apart. 3. Lower the bar to your lower poitrine or upper stomach. The bar, poignets, and coudes should stay in line en permanence. 4. Pause when the barre touches your torse, and then drive the bar up with as much force as possible. The coudes should be tucked in until lockout.', 'Muscles secondaires : Pectoraux, Avant-bras, Dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_-_Powerlifting/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bench Press - With Bands', 'Pectoraux', 'Élastique', '1. Using a flat banc secure a band under the leg of the banc that is nearest to your head. 2. Once the band is secure, grab it by both handles and lie down on the banc. 3. Extend vos bras so that you are holding the band handles in front of you at epaules width. 4. Once at epaules width, rotate your poignets forward so that the palms of vos mains are facing away from you. Position de depart. 5. Bring down the handles Lentement, until your coudes forms a 90 degree angle. Keep full control en permanence. 6. As you Expirez, bring the handles up using your pectoral muscles. Lock vos bras in the contracted position, squeeze your poitrine, Maintenez 1 seconde and then start coming down slowly. Conseil : It should take at least twice as long to go down than to come up. 7. Repetez le mouvement for the prescribed amount of repetitions of your training program.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_-_With_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bench Press with Chains', 'Triceps', 'Barre', '1. Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar. 2. Lying on the banc, get your head beyond the bar if possible. Tuck vos pieds underneath you and arch votre dos. Using the bar to help support your poids, lift your epaules off the banc and retract them, squeezing the omoplates together. Use vos pieds to drive your traps into the banc. Maintain this tight body position throughout le mouvement. However wide your grip, it should cover the ring on the bar. 3. Pull the bar out of the rack without protracting your epaules. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower poitrine or upper stomach. The bar, poignets, and coudes should stay in line en permanence. 4. Pause when the barre touches your torse, and then drive the bar up with as much force as possible. The coudes should be tucked in until lockout.', 'Muscles secondaires : Pectoraux, Dos, Épaules. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_with_Chains/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bench Sprint', 'Quadriceps', 'Autre', '1. Stand on the ground with one foot resting on a banc or box with your heel close to the edge. 2. Push off with your foot on top of the banc, extending through the hip and genoux. 3. Land with the opposite foot on top of the box, returning your other foot back to the start position. 4. Continue alternating from one foot to another to complete the set.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Sprint/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent-Arm Barbell Pullover', 'Dos', 'Barre', '1. Allongez-vous sur un banc plat with a barre using a epaules grip width. 2. Hold the bar straight over your poitrine with a bend in vos bras. Position de depart. 3. While keeping vos bras in the bent arm position, lower the poids Lentement, in an arc behind your head while breathing in until you feel a stretch on the poitrine. 4. At that point, bring the barre back to the position de depart using the arc through which the poids was lowered and exhale as you perform this movement. 5. Hold the poids on the initial position for a second and Repetez the motion for the prescribed number of repetitions.', 'Muscles secondaires : Pectoraux, Dos, Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Arm_Barbell_Pullover/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent-Arm Dumbbell Pullover', 'Pectoraux', 'Haltères', '1. Place a halteres standing up on a flat banc. 2. Ensuring that the halteres stays securely placed at the top of the banc, lie perpendicular to the banc (torse across it as in forming a cross) with only your epaules lying on the surface. Hips should be below the banc and legs bent with feet firmly on le sol. The head will be off the banc as well. 3. Grasp the halteres with both hands and hold it straight over your poitrine with a bend in vos bras. Both palms should be pressing against the underside one of the sides of the halteres. Position de depart. Caution: Always ensure that the halteres used for this exercise is secure. Using a halteres with loose plates can result in the halteres falling apart and falling on your face. 4. While keeping vos bras locked in the bent arm position, lower the poids Lentement, in an arc behind your head while breathing in until you feel a stretch on the poitrine. 5. At that point, bring the halteres back to the position de depart using the arc through which the poids was lowered and exhale as you perform this movement. 6. Hold the poids on the initial position for a second and Repetez the motion for the prescribed number of repetitions.', 'Muscles secondaires : Dos, Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Arm_Dumbbell_Pullover/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent-Knee Hip Raise', 'Abdominaux', 'Poids de corps', '1. Lay flat on le sol with vos bras next to your sides. 2. Now bend your genoux at around a 75 degree angle and lift vos pieds off le sol by around 2 inches. 3. Using your lower abdominaux, bring your genoux in towards you as you maintain the 75 degree angle bend in vos jambes. Continue this movement until you raise your hips off of le sol by rolling your pelvis backward. Expirez as you perform this portion of le mouvement. Conseil : At the end of le mouvement your genoux will be over your poitrine. 4. Squeeze your abdominaux at the top of le mouvement for a second and then Revenez en position de depart Lentement, as you Inspirez. Conseil : Maintain a controlled motion en permanence. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Knee_Hip_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent Over Barbell Row', 'Milieu du dos', 'Barre', '1. Holding a barre with a pronated grip (palms facing down), bend your genoux slightly and bring your torse forward, by bending at the waist, while keeping the back straight until it is almost parallel to le sol. Conseil : Make sure that you keep the head up. The barre should hang directly in front of you as vos bras hang perpendicular to le sol and your torse. Position de depart. 2. Now, while keeping the torse stationary, Expirez and lift the barre to you. Keep the coudes close to the body and only use the forearms to hold the poids. At the top contracted position, squeeze the back muscles and hold for a brief pause. 3. Then inhale and Lentement, lower the barre back to the position de depart. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent Over Dumbbell Rear Delt Raise With Head On Bench', 'Épaules', 'Haltères', '1. Stand up straight while holding a halteres in each hand and with an incline banc in front of you. 2. While keeping votre dos straight and maintaining the natural arch of votre dos, lean forward until your forehead touches the banc in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of vos mains should be facing each other and your torse should be parallel to le sol. Position de depart. 3. Keeping your torse forward and stationary, and the arms straight with a slight bend at the coudes, lift the halteres straight to the side until both arms are parallel to le sol. Exhale as you lift the poids. Caution: avoid swinging the torse or bringing the arms back as opposed to the side. 4. After a one second contraction at the top, Lentement, lower the halteres back to the position de depart. 5. Repetez the recommended amount of repetitions.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent Over Low-Pulley Side Lateral', 'Épaules', 'Poulie', '1. Select a poids and hold the handle of the low pulley with your right hand. 2. Bend at the waist until your torse is nearly parallel to le sol. vos jambes should be slightly bent with your left hand placed on your lower left cuisses. Your right arm should be hanging from your epaules in front of you and with a slight bend at the coudes. Position de depart. 3. Raise your right arm, coudes slightly bent, to the side until the arm is parallel to le sol and in line with your right ear. Expirez as you perform this step. 4. Lentement, lower the poids back to the position de depart as you Inspirez. 5. Repetez selon le nombre souhaite. and Repetez le mouvement with the other arm.', 'Muscles secondaires : Bas du dos, Milieu du dos, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Low-Pulley_Side_Lateral/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent Over One-Arm Long Bar Row', 'Milieu du dos', 'Barre', '1. Put poids on one of the ends of an Olympic barre. Make sure that you either place the other end of the barre in the corner of two walls; or put a heavy object on the ground so the barre cannot slide backward. 2. Bend forward until your torse is as close to parallel with le sol as you can and keep your genoux slightly bent. 3. Now grab the bar with one arm just behind the plates on the side where the poids was placed and put your other hand on your genoux. Position de depart. 4. Pull the bar straight up with your coudes in (to maximize back stimulation) until the plates touch your lower poitrine. Squeeze the back muscles as you lift the poids up and Maintenez 1 seconde at the top of le mouvement. Expirez as you lift the poids. Conseil : Do not allow for any swinging of the torse. Only the arm should move. 5. Lentement, lower the bar to the position de depart getting a nice stretch on the lats. Conseil : Do not let the plates touch le sol. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones). 6. Repetez selon le nombre souhaite. and switch arms.', 'Muscles secondaires : Biceps, Dos, Bas du dos, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_One-Arm_Long_Bar_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent Over Two-Arm Long Bar Row', 'Milieu du dos', 'Barre', '1. Put poids on one of the ends of an Olympic barre. Make sure that you either place the other end of the barre in the corner of two walls; or put a heavy object on the ground so the barre cannot slide backward. 2. Bend forward until your torse is as close to parallel with le sol as you can and keep your genoux slightly bent. 3. Now grab the bar with both arms just behind the plates on the side where the poids was placed and put your other hand on your genoux. Position de depart. 4. Pull the bar straight up with your coudes in (to maximize back stimulation) until the plates touch your lower poitrine. Squeeze the back muscles as you lift the poids up and Maintenez 1 seconde at the top of le mouvement. Expirez as you lift the poids. Conseil : Use a stirrup or double handle cable attachment by hooking it under the end of the bar. 5. Lentement, lower the bar to the position de depart getting a nice stretch on the lats. Conseil : Do not let the plates touch le sol. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones). 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Two-Arm_Long_Bar_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent Over Two-Dumbbell Row', 'Milieu du dos', 'Haltères', '1. With a halteres in each hand (palms facing your torse), bend your genoux slightly and bring your torse forward by bending at the waist; as you bend make sure to keep votre dos straight until it is almost parallel to le sol. Conseil : Make sure that you keep the head up. The poids should hang directly in front of you as vos bras hang perpendicular to le sol and your torse. Position de depart. 2. While keeping the torse stationary, lift the halteres to your side (as you Expirez), keeping the coudes close to the body (do not exert any force with the forearm other than holding the poids). On the top contracted position, squeeze the back muscles and Maintenez 1 seconde. 3. Lentement, lower the poids again to the position de depart en inspirant. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Two-Dumbbell_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent Over Two-Dumbbell Row With Palms In', 'Milieu du dos', 'Haltères', '1. With a halteres in each hand (palms facing each other), bend your genoux slightly and bring your torse forward, by bending at the waist, while keeping the back straight until it is almost parallel to le sol. Conseil : Make sure that you keep the head up. The poids should hang directly in front of you as vos bras hang perpendicular to le sol and your torse. Position de depart. 2. While keeping the torse stationary, lift the halteres to your side as you Expirez, squeezing your omoplates together. On the top contracted position, squeeze the back muscles and Maintenez 1 seconde. 3. Lentement, lower the poids again to the position de depart en inspirant. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Two-Dumbbell_Row_With_Palms_In/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent Press', 'Abdominaux', 'Kettlebell', '1. Clean a kettlebells to your epaules. Clean the kettlebells to your epaules by extending through the legs and hips as you raise the kettlebells towards your epaules. The poignets should rotate as you do so. Position de depart. 2. Begin my leaning to the side opposite the kettlebells, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebells. As you do so, press the poids vertically be extending through the coudes, keeping your arm perpendicular to the ground. 3. Return to an upright position, with the kettlebells above your head. Return the kettlebells to the epaules and Repetez for the desired number of repetitions.', 'Muscles secondaires : Fessiers, Ischio-jambiers, Bas du dos, Quadriceps, Épaules, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bicycling', 'Quadriceps', 'Autre', '1. To begin, seat yourself on the bike and adjust the seat to your height.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bicycling, Stationary', 'Quadriceps', 'Machine', '1. To begin, seat yourself on the bike and adjust the seat to your height. 2. Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and poids to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Board Press', 'Triceps', 'Barre', '1. Begin by lying on the banc, getting your head beyond the bar if possible. One to five boards, made out of 2x6''s, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt. 2. Tuck vos pieds underneath you and arch votre dos. Using the bar to help support your poids, lift your epaules off the banc and retract them, squeezing the omoplates together. Use vos pieds to drive your traps into the banc. Maintain this tight body position throughout le mouvement. 3. You can take a standard banc grip, or epaules width to focus on the triceps. Pull the bar out of the rack without protracting your epaules. The bar, poignets, and coudes should stay in line en permanence. Focus on squeezing the bar and trying to pull it apart. 4. Lower the bar to the boards, and then drive the bar up with as much force as possible. The coudes should be tucked in until lockout.', 'Muscles secondaires : Pectoraux, Avant-bras, Dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Board_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Body-Up', 'Triceps', 'Poids de corps', '1. Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torse straight. Your forearms should be epaules-width apart. Position de depart. 2. Pressing your palms firmly into the ground, extend through the coudes to raise votre corps from the ground. Keep your torse rigid as you perform le mouvement. 3. Lentement, lower your forearms back to the ground by allowing the coudes to flex. 4. Repetez.', 'Muscles secondaires : Abdominaux, Avant-bras. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Body-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Body Tricep Press', 'Triceps', 'Poids de corps', '1. Position a bar in a rack at poitrine height. 2. Standing, take a epaules width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. Position de depart. 3. Begin by flexing the coudes, lowering yourself towards the bar. 4. Pause, and then reverse the motion by extending the coudes. 5. Progress from bodyweight by adding chains over your epaules.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Body_Tricep_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bodyweight Flyes', 'Pectoraux', 'Barre EZ', '1. Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll. 2. Assume a push-up position over the bars, supporting your poids on your toes and hands with vos bras extended and body straight. 3. Place vos mains on the bars. Position de depart. 4. Using a slow and controlled motion, move vos mains away from the midline of votre corps, rolling the bars apart. Inhale during this portion of the motion. 5. After moving the bars as far apart as you can, Revenez en position de depart by pulling them back together. Exhale as you perform this movement.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Flyes/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bodyweight Mid Row', 'Milieu du dos', 'Autre', '1. Begin by taking a medium to prise large on a pull-up apparatus with your palms facing away from you. From a hanging position, tuck your genoux to your poitrine, leaning back and getting vos jambes over your side of the pull-up apparatus. Position de depart. 2. Beginning with vos bras straight, flex the coudes and retract the omoplates to raise votre corps up until vos jambes contact the pull-up apparatus. 3. Apres une pause, Revenez en position de depart.', 'Muscles secondaires : Biceps, Dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Mid_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bodyweight Squat', 'Quadriceps', 'Poids de corps', '1. Tenez-vous debout avec vos pieds epaules width apart. You can place vos mains behind your head. Position de depart. 2. Begin le mouvement by flexing your genoux and hips, sitting back with your hips. 3. Continue down to full depth if you are able,and quickly reverse the motion until you Revenez en position de depart. As you squat, keep your head and poitrine up and push your genoux out.', 'Muscles secondaires : Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bodyweight Walking Lunge', 'Quadriceps', 'Autre', '1. Begin standing with vos pieds epaules width apart and vos mains on your hips. 2. Step forward with one leg, flexing the genoux to drop your hips. Descend until your rear genoux nearly touches the ground. Your posture should remain upright, and your front genoux should stay above the front foot. 3. Drive through the heel of your lead foot and extend both genoux to raise yourself back up. 4. Step forward with your rear foot, Repetezing the lunge on the opposite leg.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Walking_Lunge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bosu Ball Cable Crunch With Side Bends', 'Abdominaux', 'Poulie', '1. Connect a standard handle to each arm of a cable machine, and position them in the most downward position. 2. Grab a Bosu Ball and position it in front and center of the cable machine. 3. Lie down on the Bosu Ball with the small of votre dos arched around the ball. Your rear end should be close to le sol without touching it. 4. With both hands, reach back and grab the handle of each cable. 5. With vos pieds positioned in a wide stance, extend vos bras straight out in front of you and in between your genoux. vos mains should be at genoux level. 6. Keep vos bras straight and in-line with the upward angle of the cable. Elevate your torse in a crunching motion without dropping or bending vos bras. 7. Maintain the rigid position with vos bras. Lentement, descend back to the position de depart with votre dos arched around the Bosu Ball and your abdominals elongated. 8. Repetez the same series of movements to failure. 9. Once you reach failure, keep your abdominaux tight and raise your torse into plank position so votre dos is elevated off the Bosu Ball. 10. Lower vos bras down to your side; keep them straight. Start doing alternating side bends; reach for your heels! This finishing movement will focus on your obliques.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bottoms-Up Clean From The Hang Position', 'Avant-bras', 'Kettlebell', '1. Initiate the exercise by standing upright with a kettlebells in one hand. 2. Swing the kettlebells back forcefully and then reverse the motion forcefully. Crush the kettlebells handle as hard as possible and raise the kettlebells to your epaules.', 'Muscles secondaires : Biceps, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bottoms-Up_Clean_From_The_Hang_Position/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bottoms Up', 'Abdominaux', 'Poids de corps', '1. Begin by lying on votre dos on the ground. vos jambes should be straight and vos bras at your side. Position de depart. 2. To perform le mouvement, tuck the genoux toward your poitrine by flexing the hips and genoux. Following this, extend vos jambes directly above you so that they are perpendicular to the ground. Rotate and elevate your pelvis to raise your fessiers from le sol. 3. Apres une pause, Revenez en position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bottoms_Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Box Jump (Multiple Response)', 'Ischio-jambiers', 'Autre', '1. Assume a relaxed stance facing the box or platform approximately an arm''s length away. Arms should be down at the sides and legs slightly bent. 2. Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform. 3. Immediately drop or jump back down to the original starting place; then Repetez the sequence.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Jump_Multiple_Response/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Box Skip', 'Ischio-jambiers', 'Autre', '1. You will need several boxes lined up about 8 feet apart. 2. Begin facing the first box with one leg slightly behind the other. 3. Drive off the back leg, attempting to gain as much height with the hips as possible. 4. Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box. 5. Then, step to the next box and Repetez.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Skip/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Box Squat', 'Quadriceps', 'Barre', '1. The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired. 2. Begin by stepping under the bar and placing it across the back of the epaules. Squeeze your omoplates together and rotate your coudes forward, attempting to bend the bar across your epaules. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place vos pieds wider for more emphasis on the back, fessiers, adductors, and ischio-jambiers, or closer together for more quad development. Keep your head facing forward. 3. With votre dos, epaules, and sangle abdominale tight, push your genoux and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box. 4. Keeping the poids on your heels and pushing vos pieds and genoux out, drive upward off of the box as you lead le mouvement with your head. Continue upward, maintaining tightness head to toe.', 'Muscles secondaires : Adducteurs, Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Box Squat with Bands', 'Quadriceps', 'Barre', '1. Begin in a power rack with a box at the appropriate height behind you. Set up the bands on the sleeves, secured to either band pegs, the rack, or halteres so that there is appropriate tension. If halteres are used, secure them so that they don''t move. Also, ensure that the halteres you are using are heavy enough for the bands that you are using. Additional plates can be used to hold the halteres down. If more tension is needed, you can either widen the base on le sol or choke the bands. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired. 2. Begin by stepping under the bar and placing it across the back of the epaules. Squeeze your omoplates together and rotate your coudes forward, attempting to bend the bar across your epaules. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place vos pieds wider for more emphasis on the back, fessiers, adductors, and ischio-jambiers, or closer together for more quad development. Keep your head facing forward. 3. With votre dos, epaules, and sangle abdominale tight, push your genoux and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box. 4. Keeping the poids on your heels and pushing vos pieds and genoux out, drive upward off of the box as you lead le mouvement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barre to the rack.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Squat_with_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Box Squat with Chains', 'Quadriceps', 'Barre', '1. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired. 2. To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on le sol at the top of le mouvement. 3. Begin by stepping under the bar and placing it across the back of the epaules. Squeeze your omoplates together and rotate your coudes forward, attempting to bend the bar across your epaules. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place vos pieds wider for more emphasis on the back, fessiers, adductors, and ischio-jambiers, or closer together for more quad development. Keep your head facing forward. 4. With votre dos, epaules, and sangle abdominale tight, push your genoux and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box. 5. Keeping the poids on your heels and pushing vos pieds and genoux out, drive upward off of the box as you lead le mouvement with your head. Continue upward, maintaining tightness head to toe.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Squat_with_Chains/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Brachialis-SMR', 'Biceps', 'Foam roller', '1. Lie on your side, with your upper arm against the foam roller. The upper arm should be more or less aligned with votre corps, with the outside of the biceps pressed against the foam roller. 2. Raise your hips off of le sol, supporting your poids on your arm and on vos pieds. Hold for 10-30 seconds, and then switch sides.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Brachialis-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bradford/Rocky Presses', 'Épaules', 'Barre', '1. Sit on a Military Press banc with a bar at epaules level with a pronated grip (palms facing forward). Conseil : Your grip should be wider than epaules width and it should create a 90-degree angle between the forearm and the upper arm as the barre goes down. Position de depart. 2. Once you pick up the barre with the correct grip, lift the bar up over your head by locking vos bras. 3. Now lower the bar down to the back of the head Lentement, en inspirant. 4. Lift the bar back up to the position de depart en expirant. 5. Lower the bar down to the position de depart Lentement, en inspirant. This is one repetition. 6. Alternate in this manner until you complete the recommended amount of repetitions.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bradford_Rocky_Presses/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Butt-Ups', 'Abdominaux', 'Poids de corps', '1. Begin a pushup position but with your coudes on the ground and resting on your forearms. vos bras should be bent at a 90 degree angle. 2. Arch votre dos slightly out rather than keeping votre dos completely straight. 3. Raise your fessiers toward the ceiling, squeezing your abdominaux tightly to close the distance between your ribcage and hips. The end result will be that you''ll end up in a high bridge position. Exhale as you perform this portion of le mouvement. 4. Lower back down Lentement, to your position de depart as you Inspirez. Conseil : Don''t let votre dos sag downwards. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butt-Ups/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Butt Lift (Bridge)', 'Fessiers', 'Poids de corps', '1. Allongez-vous au sol on votre dos with the hands by your side and your genoux bent. vos pieds should be placed around epaules width. Position de depart. 2. Pushing mainly with your heels, lift your hips off le sol while keeping votre dos straight. Expirez as you perform this part of the motion and hold at the top for a second. 3. Lentement, go back to the position de depart as you Inspirez.', 'Muscles secondaires : Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butt_Lift_Bridge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Butterfly', 'Pectoraux', 'Machine', '1. Sit on the machine with votre dos flat on the pad. 2. Take hold of the handles. Conseil : Your upper arms should be positioned parallel to le sol; adjust the machine accordingly. Position de depart. 3. Push the handles together Lentement, as you squeeze your poitrine in the middle. Expirez during this part of the motion and hold the contraction for a second. 4. Return back to the position de depart Lentement, en inspirant until your poitrine muscles are fully stretched. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Chest Press', 'Pectoraux', 'Poulie', '1. Adjust the poids to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and poitrine up. The coudes should be bent to about 90 degrees. Position de depart. 2. Begin by extending through the coudes, pressing the handles together straight in front of you. Keep your omoplates retracted as you execute le mouvement. 3. After pausing at full extension, return to th position de depart, keeping tension on the cables. 4. You can also execute this movement with votre dos off the pad, at an incline or decline, or alternate hands.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Chest_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Crossover', 'Pectoraux', 'Poulie', '1. To get yourself into the position de depart, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand. 2. Step forward in front of an imaginary straight line between both pulleys while pulling vos bras together in front of you. Your torse should have a small forward bend from the waist. Position de depart. 3. With a slight bend on your coudes in order to prevent stress at the biceps tendon, extend vos bras to the side (straight out at both sides) in a wide arc until you feel a stretch on your poitrine. Inspirez as you perform this portion of le mouvement. Conseil : Keep in mind that throughout le mouvement, the arms and torse should remain stationary; le mouvement should only occur at the epaules joint. 4. Return vos bras back to the position de depart as you Expirez. Make sure to use the same arc of motion used to lower the poids. 5. Maintenez 1 seconde at the position de depart and Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Crossover/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Crunch', 'Abdominaux', 'Poulie', '1. Kneel below a high pulley that contains a rope attachment. 2. Grasp cable rope attachment and lower the rope until vos mains are placed next to your face. 3. Flex your hips slightly and allow the poids to hyperextend the lower back. Position de depart. 4. With the hips stationary, flex the waist as you contract the abdominaux so that the coudes travel towards the middle of the cuisses. Exhale as you perform this portion of le mouvement and hold the contraction for a second. 5. Lentement, Revenez en position de depart en inspirant. Conseil : Make sure that you keep constant tension on the abdominaux throughout le mouvement. Also, do not choose a poids so heavy that the lower back handles the brunt of the work. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Deadlifts', 'Quadriceps', 'Poulie', '1. Move the cables to the bottom of the towers and select an appropriate poids. Stand directly in between the uprights. 2. To begin, squat down be flexing your hips and genoux until you can reach the handles. 3. After grasping them, begin your ascent. Driving through your heels extend your hips and genoux keeping vos mains hanging at your side. Keep your head and poitrine up throughout le mouvement. 4. After reaching a full standing position, Revenez en position de depart and Repetez.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Deadlifts/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Hammer Curls - Rope Attachment', 'Biceps', 'Poulie', '1. Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it. 2. Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torse stationary. 3. Put your coudes in by your side and keep them there stationary during the entire movement. Conseil : Only the forearms should move; not your upper arms. Position de depart. 4. Using your biceps, pull vos bras up en expirant until your biceps touch your forearms. Conseil : Remember to keep the coudes in and your upper arms stationary. 5. After a 1 second contraction where you squeeze your biceps, Lentement, start to bring the poids back to the original position. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Hammer_Curls_-_Rope_Attachment/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Hip Adduction', 'Quadriceps', 'Poulie', '1. Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away. 2. Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley. 3. Now step out and away from the stack with a wide stance and grasp the bar of the pulley system. 4. Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. Position de depart. 5. Now perform le mouvement by moving the leg with the ankle cuff in front of the far leg by using the inner cuisses to abduct the hip. Expirez during this portion of le mouvement. 6. Lentement, Revenez en position de depart as you Inspirez. 7. Repetez selon le nombre souhaite. and then Repetez the same movement with the opposite leg.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Hip_Adduction/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Incline Pushdown', 'Dos', 'Poulie', '1. Lie on incline an banc facing away from a high pulley machine that has a straight bar attachment on it. 2. Grasp the straight bar attachment overhead with a pronated (overhand; palms down) epaules width grip and extend vos bras in front of you. The bar should be around 2 inches away from your upper cuisses. Position de depart. 3. Keeping the upper arms stationary, lift vos bras back in a semi circle until the bar is straight over your head. Inspirez during this portion of le mouvement. 4. Lentement, go back to the position de depart using your lats and hold the contraction once you reach the position de depart. Expirez during the execution of this movement. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Incline_Pushdown/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Incline Triceps Extension', 'Triceps', 'Poulie', '1. Lie on incline an banc facing away from a high pulley machine that has a straight bar attachment on it. 2. Grasp the straight bar attachment overhead with a pronated (overhand; palms down) prise serree (less than epaules width) and keep your coudes tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from le sol. 3. Keeping the upper arms stationary, extend the arms as you flex the triceps. Expirez during this portion of le mouvement and hold the contraction for a second. 4. Lentement, go back to the position de depart. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Incline_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Internal Rotation', 'Épaules', 'Poulie', '1. Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable. Conseil : If you can adjust the pulley''s height, you can use a flat banc to sit on instead. 2. Position the coudes against your side with the coudes bent at 90° and the arm pointing towards the pulley. Position de depart. 3. Pull the single hand cable attachment toward votre corps by internally rotating your epaules until your forearm is across your abdominaux. You will be creating an imaginary semi-circle. Conseil : The forearm should be perpendicular to your torse en permanence. 4. Lentement, go back to the initial position. 5. Repetez selon le nombre souhaite. and then Repetez le mouvement with the next arm.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Internal_Rotation/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Iron Cross', 'Pectoraux', 'Poulie', '1. Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand. 2. Stand directly between both pulleys with vos bras extended out to your sides. Your head and poitrine should be up while vos bras form a "T". Position de depart. 3. Keeping the coudes extended, pull vos bras straight to your sides. 4. Return vos bras back to the position de depart Apres une pause, at the peak contraction. 5. Continue le mouvement for the prescribed number of repetitions.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Iron_Cross/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Judo Flip', 'Abdominaux', 'Poulie', '1. Connect a rope attachment to a tower, and move the cable to the lowest pulley position. Tenez-vous debout avec your side to the cable with a wide stance, and grab the rope with both hands. 2. Twist votre corps away from the pulley as you bring the rope over your epaules like you''re performing a judo flip. 3. Shift your poids between vos pieds as you twist and crunch forward, pulling the cable downward. 4. Revenez en position de depart and Repetez until failure. 5. Then, reposition and Repetez the same series of movements on the opposite side.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Judo_Flip/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Lying Triceps Extension', 'Triceps', 'Poulie', '1. Allongez-vous sur un banc plat and grasp the straight bar attachment of a low pulley with a narrow prise en pronation. Conseil : The easiest way to do this is to have someone hand you the bar as you lay down. 2. With vos bras extended, position the bar over your torse. vos bras and your torse should create a 90-degree angle. Position de depart. 3. Lower the bar by bending at the coudes while keeping the upper arms stationary and coudes in. Go down until the bar lightly touches your forehead. Inspirez as you perform this portion of le mouvement. 4. Flex the triceps as you lift the bar back to its position de depart. Exhale as you perform this portion of le mouvement. 5. Maintenez 1 seconde at the contracted position and Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Lying_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable One Arm Tricep Extension', 'Triceps', 'Poulie', '1. With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the poids stack. 2. Now pull the handle down so that your upper arm and coudes are locked in to the side of votre corps. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. Position de depart. 3. As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Expirez as you perform this movement. Conseil : Only the forearms should move. Your upper arms should remain stationary en permanence. 4. Squeeze the triceps and Maintenez 1 seconde in this contracted position. 5. Lentement, return the handle to the position de depart. 6. Repetez selon le nombre souhaite. and then perform the same movement with the other arm.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_One_Arm_Tricep_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Preacher Curl', 'Biceps', 'Poulie', '1. Place a preacher banc about 2 feet in front of a pulley machine. 2. Attach a straight bar to the low pulley. 3. Sit at the preacher banc with your coudes and upper arms firmly on top of the banc pad and have someone hand you the bar from the low pulley. 4. Grab the bar and fully extend vos bras on top of the preacher banc pad. Position de depart. 5. Now start pilling the poids up towards your epaules and squeeze the biceps hard at the top of le mouvement. Exhale as you perform this motion. Also, Maintenez 1 seconde at the top. 6. Now Lentement, lower the poids to the position de depart. 7. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Preacher_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Rear Delt Fly', 'Épaules', 'Poulie', '1. Adjust the pulleys to the appropriate height and adjust the poids. The pulleys should be above your head. 2. Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. Position de depart. 3. Initiate le mouvement by moving vos bras back and outward, keeping vos bras straight as you execute le mouvement. 4. Pause at the end of the motion before returning the handles to the start position.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rear_Delt_Fly/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Reverse Crunch', 'Abdominaux', 'Poulie', '1. Connect an ankle strap attachment to a low pulley cable and position a mat on le sol in front of it. 2. Sit down with vos pieds toward the pulley and attach the cable to your ankles. 3. Lie down, elevate vos jambes and bend your genoux at a 90-degree angle. vos jambes and the cable should be aligned. If not, adjust the pulley up or down until they are. 4. With vos mains behind your head, bring your genoux inward to your torse and elevate your hips off le sol. 5. Pause for a moment and in a slow and controlled manner drop your hips and bring vos jambes back to the starting 90-degree angle. You should still have tension on your abdominaux in the resting position. 6. Repetez the same movement to failure.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Reverse_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Rope Overhead Triceps Extension', 'Triceps', 'Poulie', '1. Attach a rope to the bottom pulley of the pulley machine. 2. Grasping the rope with both hands, extend vos bras with vos mains directly above your head using a neutral grip (palms facing each other). Your coudes should be in close to your head and the arms should be perpendicular to le sol with the knuckles aimed at the ceiling. Position de depart. 3. Lentement, lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched. 4. Revenez en position de depart by flexing your triceps as you Expirez. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Overhead_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Rope Rear-Delt Rows', 'Épaules', 'Poulie', '1. Sit in the same position on a low pulley row station as you would if you were doing seated cable rows for the back. 2. Attach a rope to the pulley and grasp it with an prise en pronation. vos bras should be extended and parallel to le sol with the coudes flared out. 3. Keep your lower back upright and slide your hips back so that your genoux are slightly bent. Position de depart. 4. Pull the cable attachment towards your upper poitrine, just below the neck, as you keep your coudes up and out to the sides. Continue this motion en expirant until the coudes travel slightly behind the back. Conseil : Keep your upper arms horizontal, perpendicular to the torse and parallel to le sol throughout the motion. 5. Go back to the initial position where the arms are extended and the epaules are stretched forward. Inhale as you perform this portion of le mouvement. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Rear-Delt_Rows/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Russian Twists', 'Abdominaux', 'Poulie', '1. Connect a standard handle attachment, and position the cable to a middle pulley position. 2. Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm''s length away from the pulley, with the tension of the poids on the cable. 3. Grab the handle with both hands and fully extend vos bras above your poitrine. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are. 4. Keep your hips elevated and abdominaux engaged. Rotate your torse away from the pulley for a full-quarter rotation. votre corps should be flat from head to genoux. 5. Pause for a moment and in a slow and controlled manner reset to the position de depart. You should still have side tension on the cable in the resting position. 6. Repetez the same movement to failure. 7. Then, reposition and Repetez the same series of movements on the opposite side.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Russian_Twists/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Seated Crunch', 'Abdominaux', 'Poulie', '1. Seat on a flat banc with votre dos facing a high pulley. 2. Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place vos mains securely over both epaules. Conseil : Allow the poids to hyperextend the lower back slightly. Position de depart. 3. With the hips stationary, flex the waist so the coudes travel toward the hips. Expirez as you perform this step. 4. en inspirant, go back to the initial position slowly. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Seated Lateral Raise', 'Épaules', 'Poulie', '1. Stand in the middle of two low pulleys that are opposite to each other and place a flat banc right behind you (in perpendicular fashion to you; the narrow edge of the banc should be the one behind you). Select the poids to be used on each pulley. 2. Now sit at the edge of the flat banc behind you with vos pieds placed in front of your genoux. 3. Bend forward while keeping votre dos flat and rest your torse on the cuisses. 4. Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your poids. The pulleys should run under your genoux and vos bras will be extended with palms facing each other and a slight bend at the coudes. This will be the position de depart. 5. While keeping the arms stationary, raise the upper arms to the sides until they are parallel to le sol and at epaules height. Exhale during the execution of this movement and hold the contraction for a second. 6. Lentement, lower vos bras to the position de depart en inspirant. 7. Repetez selon le nombre souhaite. Conseil : Maintain upper arms perpendicular to torse and a fixed coudes position (10 degree to 30 degree angle) throughout exercise.', 'Muscles secondaires : Milieu du dos, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Shoulder Press', 'Épaules', 'Poulie', '1. Move the cables to the bottom of the towers and select an appropriate poids. 2. Stand directly in between the uprights. Grasp the cables and hold them at epaules height, palms facing forward. Position de depart. 3. Keeping your head and poitrine up, extend through the coudes to press the handles directly over head. 4. After pausing at the top, Revenez en position de depart and Repetez.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Shoulder_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Shrugs', 'Trapèzes', 'Poulie', '1. Grasp a cable bar attachment that is attached to a low pulley with a epaules width or slightly wider overhand (palms facing down) grip. 2. Stand erect close to the pulley with vos bras extended in front of you holding the bar. Position de depart. 3. Lift the bar by elevating the epaules as high as possible en expirant. Hold the contraction at the top for a second. Conseil : The arms should remain extended en permanence. Refrain from using the biceps to help lift the bar. Only the epaules should be moving up and down. 4. Lower the bar back to the original position. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Shrugs/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Wrist Curl', 'Avant-bras', 'Poulie', '1. Start out by placing a flat banc in front of a low pulley cable that has a straight bar attachment. 2. Use vos bras to grab the cable bar with a narrow to epaules width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your cuisses. Your poignets should be hanging just beyond your genoux. 3. Start out by curling your poignets upwards and exhaling. Keep the contraction for a second. 4. Lentement, lower your poignets back down to the position de depart while inhaling. 5. Your forearms should be stationary as your poignets is the only movement needed to perform this exercise. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Wrist_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Calf-Machine Shoulder Shrug', 'Trapèzes', 'Machine', '1. Position yourself on the calf machine so that the epaules pads are above your epaules. Your torse should be straight with the arms extended normally by your side. Position de depart. 2. Raise your epaules up towards your ears en expirant and hold the contraction for a full second. 3. Lentement, Revenez en position de depart en inspirant. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf-Machine_Shoulder_Shrug/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Calf Press', 'Mollets', 'Machine', '1. Adjust the seat so that vos jambes are only slightly bent in the start position. The balls of vos pieds should be firmly on the platform. 2. Select an appropriate poids, and grasp the handles. Position de depart. 3. Straighten the legs by extending the genoux, just barely lifting the poids from the stack. Your ankle should be fully flexed, toes pointing up. Execute le mouvement by pressing downward through the balls of vos pieds as far as possible. 4. Apres une pause, reverse the motion and Repetez.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Calf Press On The Leg Press Machine', 'Mollets', 'Machine', '1. Using a leg press machine, sit down on the machine and place vos jambes on the platform directly in front of you at a medium (epaules width) foot stance. 2. Lower the safety bars holding the weighted platform in place and press the platform all the way up until vos jambes are fully extended in front of you without locking your genoux. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torse and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of vos pieds on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. Position de depart. 3. Press on the platform by raising your heels as you Expirez by extending your ankles as high as possible and flexing your calf. Ensure that the genoux is kept stationary en permanence. There should be no bending at any time. Hold the contracted position by a second before you start to go back down. 4. Go back Lentement, to the position de depart as you Inspirez by lowering your heels as you bend the ankles until mollets are stretched. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Press_On_The_Leg_Press_Machine/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Calf Raise On A Dumbbell', 'Mollets', 'Haltères', '1. Hang on to a sturdy object for balance and stand on a halteres handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise. 2. Now roll your foot slightly forward so that you can get a nice stretch of the calf. Position de depart. 3. Lift the calf as you roll your foot over the top of the handle so that you get a full extension. Exhale during the execution of this movement. Contract the calf hard at the top and Maintenez 1 seconde. Conseil : As you come up, roll the halteres slightly backward. 4. Now inhale as you roll the halteres slightly forward as you come down to get a better stretch. 5. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Raise_On_A_Dumbbell/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Calf Raises - With Bands', 'Mollets', 'Élastique', '1. Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides. 2. While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a epaules press. The palms should be facing forward with the coudes bent and to the sides. This movement will create tension on the band. Position de depart. 3. Keeping the hands by your epaules, stand up on your toes en expirant and contract the mollets hard at the top of le mouvement. 4. After a one second contraction, Lentement, go back down to the position de depart. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Raises_-_With_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Calf Stretch Elbows Against Wall', 'Mollets', 'Autre', '1. Stand facing a wall from a couple feet away. 2. Lean against the wall, placing your poids on your forearms. 3. Attempt to keep your heels on the ground. Hold for 10-20 seconds. You may move further or closer the wall, making it more or less difficult, respectively.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Stretch_Elbows_Against_Wall/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Calf Stretch Hands Against Wall', 'Mollets', 'Autre', '1. Stand facing a wall from several feet away. Stagger your stance, placing one foot forward. 2. Lean forward and rest vos mains on the wall, keeping your heel, hip and head in a straight line. 3. Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Stretch_Hands_Against_Wall/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Calves-SMR', 'Mollets', 'Foam roller', '1. Begin seated on le sol. Place a foam roller underneath your lower leg. Your other leg can either be crossed over the opposite or be placed on le sol, supporting some of your poids. Position de depart. 2. Place vos mains to your side or just behind you, and press down to raise your hips off of le sol, placing much of your poids against your calf muscle. Roll from below the genoux to above the ankle, pausing at points of tension for 10-30 seconds. Repetez de l autre cote.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calves-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Car Deadlift', 'Quadriceps', 'Autre', '1. This event apparatus typically has neutral grip handles, however some have a straight bar that you can approach like a normal deadlift. The apparatus can be loaded with a vehicle or other heavy objects such as tractor tires or kegs. 2. Center yourself between the handles if you are a strong squatter, or back a couple inches if you are a strong deadlifter. You feet should be about hip width apart. Bend at the hip to grip the handles. With vos pieds and your grip set, take a big breath and then lower your hips and flex the genoux. 3. Look forward with your head, keep your poitrine up and votre dos arched, and begin driving through the heels to move the poids upward. As the poids comes up, pull your omoplates together as you drive your hips forward. 4. Lower the poids by bending at the hips and guiding it to le sol.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Car_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Car Drivers', 'Épaules', 'Barre', '1. While standing upright, hold a barre plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and vos bras should be extended straight out in front of you. Position de depart. 2. Initiate le mouvement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side. 3. Reverse the motion, turning it all the way to the opposite side. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Car_Drivers/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Carioca Quick Step', 'Adducteurs', 'Autre', '1. Begin with vos pieds a few inches apart and your left arm up in a relaxed, athletic position. 2. With your right foot, quick step behind and pull the genoux up. 3. Fire vos bras back up when you pull the right genoux, being sure that your genoux goes straight up and down. Avoid turning vos pieds as you move and continue to look forward as you move to the side.', 'Muscles secondaires : Abdominaux, Abducteurs, Mollets, Fessiers, Ischio-jambiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Carioca_Quick_Step/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cat Stretch', 'Bas du dos', 'Autre', '1. Position yourself on le sol on vos mains and genoux. 2. Pull your belly in and round your spine, lower back, epaules, and neck, letting your head drop. 3. Hold for 15 seconds.', 'Muscles secondaires : Milieu du dos, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cat_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Catch and Overhead Throw', 'Dos', 'Medecine ball', '1. Begin standing while facing a wall or a partner. 2. Using both hands, position the ball behind your head, stretching as much as possible, and forcefully throw the ball forward. 3. Ensure that you follow your throw through, being prepared to receive your rebound from your throw. If you are throwing against the wall, make sure that you stand close enough to the wall to receive the rebound, and aim a little higher than you would with a partner.', 'Muscles secondaires : Abdominaux, Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Catch_and_Overhead_Throw/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chain Handle Extension', 'Triceps', 'Autre', '1. You will need two cable handle attachments and a flat banc, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat banc. Your coudes should be pointing straight up. 2. Begin by extending through the coudes, keeping your upper arm still, with your poignets pronated. 3. Pause at the lockout, and reverse the motion to Revenez en position de depart.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chain_Handle_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chain Press', 'Pectoraux', 'Autre', '1. Begin by connecting the chains to the cable handle attachments. Position yourself on the flat banc in the same position as for a halteres press. Your poignets should be pronated and arms perpendicular to le sol. Position de depart. 2. Lower the chains by flexing the coudes, unloading some of the chain onto le sol. 3. Continue until your coudes forms a 90 degree angle, and then reverse the motion by extending through the coudes to lockout.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chain_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chair Leg Extended Stretch', 'Ischio-jambiers', 'Autre', '1. Sit upright in a chair and grip the seat on the sides. 2. Raise one leg, extending the genoux, flexing the ankle as you do so. 3. Lentement, move that leg outward as far as you can, and then back to the center and down. 4. Repetez for your other leg.', 'Muscles secondaires : Adducteurs. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chair_Leg_Extended_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chair Lower Back Stretch', 'Dos', 'Autre', '1. Sit upright on a chair. 2. Bend to one side with your arm over your head. You can hold onto the chair with your free hand. 3. Hold for 10 seconds, and Repetez for your other side.', 'Muscles secondaires : Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chair_Lower_Back_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chair Squat', 'Quadriceps', 'Machine', '1. To begin, first set the bar to a position that best matches your height. Once the bar is loaded, step under it and position it across the back of your epaules. 2. Take the bar with vos mains facing forward, unlock it and lift it off the rack by extending vos jambes. 3. Move vos pieds forward about 18 inches in front of the bar. Position vos jambes using a epaules width stance with the toes slightly pointed out. Look forward en permanence and maintain a neutral or slightly arched spine. Position de depart. 4. Lentement, lower the bar by bending the genoux as you maintain a straight posture with the head up. Continue down until the angle between the upper and lower leg breaks 90 degrees. 5. Begin to raise the bar en expirant by pushing le sol with the heels of vos pieds, extending the genoux and returning to the position de depart. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chair_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chair Upper Body Stretch', 'Épaules', 'Autre', '1. Sit on the edge of a chair, gripping the back of it. 2. Straighten vos bras, keeping votre dos straight, and pull your upper body forward so you feel a stretch. Hold for 20-30 seconds.', 'Muscles secondaires : Biceps, Pectoraux. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chair_Upper_Body_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chest And Front Of Shoulder Stretch', 'Pectoraux', 'Autre', '1. Start off by standing with vos jambes together, holding a bodybar or a broomstick. 2. Take a slightly wider than epaules width grip on the pole and hold it in front of you with your palms facing down. 3. Carefully lift the pole up and behind your head.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_And_Front_Of_Shoulder_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chest Push from 3 point stance', 'Pectoraux', 'Medecine ball', '1. Begin in a three point stance, squatted down with votre dos flat and one hand on the ground. Place the medicine ball directly in front of you. 2. To begin, take your first step as you pull the ball to your poitrine, positioning both hands to prepare for the throw. 3. As you execute the second step, explosively release the ball forward as hard as possible.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Push_from_3_point_stance/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chest Push (multiple response)', 'Pectoraux', 'Medecine ball', '1. Begin in a kneeling position facing a wall or utilize a partner. Hold the ball with both hands tight into the poitrine. 2. Execute the pass by exploding forward and outward with the hips while pushing the ball as hard as possible. 3. Follow through by falling forward, catching yourself with vos mains. 4. Immediately return to an upright position. Repetez for the desired number of repetitions.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Push_multiple_response/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chest Push (single response)', 'Pectoraux', 'Medecine ball', '1. Begin in a kneeling position holding the medicine ball with both hands tightly into the poitrine. 2. Execute the pass by exploding forward and outward with the hips while pushing the ball as far as possible. 3. Follow through by falling forward, catching yourself with vos mains.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Push_single_response/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chest Push with Run Release', 'Pectoraux', 'Medecine ball', '1. Begin in an athletic stance with the genoux bent, hips back, and back flat. Hold the medicine ball near vos jambes. Position de depart. 2. While taking your first step draw the medicine ball into your poitrine. 3. As you take the second step, explosively push the ball forward, immediately sprinting for 10 yards after the release. If you are really fast, you can catch your own pass!', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Push_with_Run_Release/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chest Stretch on Stability Ball', 'Pectoraux', 'Swiss ball', '1. Get on vos mains and genoux next to an exercise ball. 2. Place your coudes on top of the ball, keeping your arm out to your side. Position de depart. 3. Lower your torse towards le sol, keeping your coudes on top of the ball. Hold the stretch for 20-30 seconds, and Repetez with the other arm.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Stretch_on_Stability_Ball/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Child''s Pose', 'Bas du dos', 'Autre', '1. Get on vos mains and genoux, walk vos mains in front of you. 2. Lower your buttocks down to sit on your heels. Let vos bras drag along le sol as you sit back to stretch your entire spine. 3. Once you settle onto your heels, bring vos mains next to vos pieds and relax. "breathe" into votre dos. Rest your forehead on le sol. Avoid this position if you have genoux problems.', 'Muscles secondaires : Fessiers, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Childs_Pose/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chin-Up', 'Dos', 'Poids de corps', '1. Grab the pull-up bar with the palms facing your torse and a grip closer than the epaules width. 2. As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torse as straight as possible while creating a curvature on your lower back and sticking your poitrine out. Position de depart. Conseil : Keeping the torse as straight as possible maximizes biceps stimulation while minimizing back involvement. 3. As you Expirez, pull your torse up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform le mouvement. Keep the coudes close to votre corps. Conseil : The upper torse should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar. 4. After a second of squeezing the biceps in the contracted position, Lentement, lower your torse back to the position de depart; when vos bras are fully extended. Inspirez as you perform this portion of le mouvement. 5. Repetez this motion for the prescribed amount of repetitions.', 'Muscles secondaires : Biceps, Avant-bras, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chin To Chest Stretch', 'Cou', 'Autre', '1. Get into a seated position on le sol. 2. Place both hands at the rear of your head, fingers interlocked, thumbs pointing down and coudes pointing straight ahead. Lentement, pull your head down to your poitrine. Hold for 20-30 seconds.', 'Muscles secondaires : Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin_To_Chest_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Circus Bell', 'Épaules', 'Autre', '1. The circus bell is an oversized halteres with a thick handle. Begin with the halteres between vos pieds, and grip the handle with both hands. 2. Clean the halteres by extending through your hips and genoux to deliver the implement to the desired epaules, letting go with the extra hand. 3. Ensure that you get one of the halteres heads behind the epaules to keep from being thrown off balance. To raise it overhead, dip by flexing the genoux, and the drive upwards as you extend the halteres overhead, leaning slightly away from it as you do so. 4. Carefully guide the bell back to le sol, keeping it under control as much as possible. It is best to perform this event on a thick rubber mat to prevent damage to le sol.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Trapèzes, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Circus_Bell/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Clean', 'Ischio-jambiers', 'Barre', '1. With a barre on le sol close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the poids focused on the heels, back straight, head facing forward, poitrine up, with your epaules just in front of the bar. Position de depart. 2.  3. Begin the first pull by driving through the heels, extending your genoux. votre dos angle should stay the same, and vos bras should remain straight. Move the poids with control as you continue to above the genoux. 4. Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-cuisses position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, genoux, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the poids; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. 5. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the coudes up and out. At peak extension, aggressively pull yourself down, rotating your coudes under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted epaules, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery. 6. Immediately recover by driving through the heels, keeping the torse upright and coudes up. Continue until you have risen to a standing position.', 'Muscles secondaires : Mollets, Avant-bras, Fessiers, Bas du dos, Quadriceps, Épaules, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Clean Deadlift', 'Ischio-jambiers', 'Barre', '1. Begin standing with a barre close to your shins. vos pieds should be directly under your hips with vos pieds turned out slightly. Grip the bar with a double prise en pronation or hook grip, about epaules width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your epaules in front of the bar and votre dos as vertical as possible. 2. Begin by driving through le sol through the front of your heels. As the bar travels upward, maintain a constant back angle. Flare your genoux out to the side to help keep them out of the bar''s path. 3. After the bar crosses the genoux, complete the lift by driving the hips into the bar until your hips and genoux are extended.', 'Muscles secondaires : Avant-bras, Fessiers, Bas du dos, Milieu du dos, Quadriceps, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Clean Pull', 'Quadriceps', 'Barre', '1. With a barre on le sol close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the poids focused on the heels, back straight, head facing forward, poitrine up, with your epaules just in front of the bar. Position de depart. 2. Begin the first pull by driving through the heels, extending your genoux. votre dos angle should stay the same, and vos bras should remain straight and coudes out. Move the poids with control as you continue to above the genoux. 3. Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-cuisses position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, genoux, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the poids; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_Pull/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Clean Shrug', 'Trapèzes', 'Barre', '1. Begin with a epaules width, double overhand or hook grip, with the bar hanging at the mid cuisses position. votre dos should be straight and inclined slightly forward. 2. Shrug your epaules towards your ears. While this exercise can usually by loaded with heavier poids than a clean, avoid overloading to the point that the execution slows down.', 'Muscles secondaires : Avant-bras, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_Shrug/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Clean and Jerk', 'Épaules', 'Barre', '1. With a barre on le sol close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the poids focused on the heels, back straight, head facing forward, poitrine up, with your epaules just in front of the bar. Position de depart. 2. Begin the first pull by driving through the heels, extending your genoux. votre dos angle should stay the same, and vos bras should remain straight. Move the poids with control as you continue to above the genoux. 3. Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-cuisses position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, genoux, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the poids; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. 4. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the coudes up and out. At peak extension, aggressively pull yourself down, rotating your coudes under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted epaules, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery. 5. Immediately recover by driving through the heels, keeping the torse upright and coudes up. Continue until you have risen to a standing position. 6. The second phase is the jerk, which raises the poids overhead. Standing with the poids racked on the front of the epaules, begin with the dip. With vos pieds directly under your hips, flex the genoux without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. 7. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the epaules. 8. At this moment as the feet leave le sol, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be split, with one foot forward, and one foot back. Receive the bar with the arms locked out overhead. Return to a standing position.', 'Muscles secondaires : Abdominaux, Fessiers, Ischio-jambiers, Bas du dos, Quadriceps, Trapèzes, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_and_Jerk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Clean and Press', 'Épaules', 'Barre', '1. Assume a epaules-width stance, with genoux inside the arms. Now while keeping the back flat, bend at the genoux and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than epaules width. Point the coudes out to sides. The bar should be close to the shins. Position the epaules over or slightly ahead of the bar. Establish a flat back posture. Position de depart. 2. Begin to pull the bar by extending the genoux. Move your hips forward and raise the epaules at the same rate while keeping the angle of the back constant; continue to lift the bar straight up while keeping it close to votre corps. 3. As the bar passes the genoux, extend at the ankles, genoux, and hips forcefully, similar to a jumping motion. As you do so, continue to guide the bar with vos mains, shrugging your epaules and using the momentum from your movement to pull the bar as high as possible. The bar should travel close to votre corps, and you should keep your coudes out. 4. At maximum elevation, vos pieds should clear le sol and you should start to pull yourself under the bar. The mechanics of this could change slightly, depending on the poids used. You should descend into a squatting position as you pull yourself under the bar. 5. As the bar hits terminal height, rotate your coudes around and under the bar. Rack the bar across the front of the epaules while keeping the torse erect and flexing the hips and genoux to absorb the poids of the bar. 6. Stand to full height, holding the bar in the clean position. 7. Without moving vos pieds, press the bar overhead en expirant. Lower the bar under control .', 'Muscles secondaires : Abdominaux, Mollets, Fessiers, Ischio-jambiers, Bas du dos, Milieu du dos, Quadriceps, Épaules, Trapèzes, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_and_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Clean from Blocks', 'Quadriceps', 'Barre', '1. With a barre on boxes or stands of the desired height, take an overhand or hook grip just outside the legs. Lower your hips with the poids focused on the heels, back straight, head facing forward, poitrine up, with your epaules just in front of the bar. Position de depart. 2. Begin the first pull by driving through the heels, extending your genoux. votre dos angle should stay the same, and vos bras should remain straight with the coudes pointed out. 3. As full extension is achieved, transition into the receiving position by aggressively shrugging and flexing the arms with the coudes up and out. Aggressively pull yourself down, rotating your coudes under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted epaules, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery. 4. Immediately recover by driving through the heels, keeping the torse upright and coudes up. Continue until you have risen to a standing position. Return the poids to the boxes for the next rep.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Épaules, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_from_Blocks/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Clock Push-Up', 'Pectoraux', 'Poids de corps', '1. Move into a prone position on le sol, supporting your poids on vos mains and toes. 2. vos bras should be fully extended with the hands around epaules width. Keep votre corps straight throughout le mouvement. Position de depart. 3. Descend by flexing at the coudes, lowering your poitrine toward the ground. 4. At the bottom, reverse the motion by pushing yourself up through coudes extension as quickly as possible until you are air borne. Aim to "jump" 12-18 inches to one side. 5. As you accelerate up, move your outside foot away from your direction of travel. Leaving the ground, shift votre corps about 30 degrees for the next repetition. 6. Revenez en position de depart and Repetez the exercise, working all the way around until you are back where you started.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clock_Push-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Close-Grip Barbell Bench Press', 'Triceps', 'Barre', '1. Allongez-vous au sol on a flat banc. Using a close grip (around epaules width), lift the bar from the rack and hold it straight over you with vos bras locked. Position de depart. 2. As you Inspirez, come down Lentement, until you feel the bar on your middle poitrine. Conseil : Make sure that - as opposed to a regular banc press - you keep the coudes close to the torse en permanence in order to maximize triceps involvement. 3. Apres une pause, bring the bar back to the position de depart as you Expirez and push the bar using your triceps muscles. Lock vos bras in the contracted position, Maintenez 1 seconde and then start coming down Lentement, again. Conseil : It should take at least twice as long to go down than to come up. 4. Repetez le mouvement for the prescribed amount of repetitions. 5. When you are done, place the bar back in the rack.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Barbell_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Close-Grip Dumbbell Press', 'Triceps', 'Haltères', '1. Place a halteres standing up on a flat banc. 2. Ensuring that the halteres stays securely placed at the top of the banc, lie perpendicular to the banc with only your epaules lying on the surface. Hips should be below the banc and vos jambes bent with vos pieds firmly on le sol. 3. Grasp the halteres with both hands and hold it straight over your poitrine at arm''s length. Both palms should be pressing against the underside of the sides of the halteres. Position de depart. 4. Initiate le mouvement by lowering the halteres to your poitrine. 5. Revenez en position de depart by extending the coudes.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Dumbbell_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Close-Grip EZ-Bar Curl with Band', 'Biceps', 'Barre EZ', '1. Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The coudes should be close to the torse. Position de depart. 2. While keeping the upper arms in place, flex the coudes to execute the curl. Exhale as the poids is lifted. 3. Continue le mouvement until your biceps are entierement contracte and the bar is at epaules level. Maintenez 1 seconde and squeeze the biceps hard. 4. Lentement, begin to bring the bar back to position de depart as your Inspirez. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_EZ-Bar_Curl_with_Band/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Close-Grip EZ-Bar Press', 'Triceps', 'Barre EZ', '1. Allongez-vous sur un banc plat with an EZ bar loaded to an appropriate poids. 2. Using a prise serree lift the bar and hold it straight over your torse with your coudes in. The arms should be perpendicular to le sol. Position de depart. 3. Now lower the bar down to your lower poitrine as you Inspirez. Keep the coudes in as you perform this movement. 4. Using the triceps to push the bar back up, press it back to the position de depart by extending the coudes en expirant. 5. Repetez.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_EZ-Bar_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Close-Grip EZ Bar Curl', 'Biceps', 'Barre', '1. Tenez-vous debout avec your torse upright while holding an E-Z Curl Bar at the closer inner handle. The palm of vos mains should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The coudes should be close to the torse. Position de depart. 2. While holding the upper arms stationary, curl the poids forward while contracting the biceps as you Expirez. Conseil : Only the forearms should move. 3. Continue le mouvement until your biceps are entierement contracte and the bar is at epaules level. Maintenez 1 seconde and squeeze the biceps hard. 4. Lentement, begin to bring the bar back to position de depart as your Inspirez. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_EZ_Bar_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Close-Grip Front Lat Pulldown', 'Dos', 'Poulie', '1. Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the genoux pad of the machine to fit your height. These pads will prevent votre corps from being raised by the resistance attached to the bar. 2. Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a prise large, vos mains need to be spaced out at a distance wider than your epaules width. For a prise moyenne, vos mains need to be spaced out at a distance equal to your epaules width and for a close grip at a distance smaller than your epaules width. 3. As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torse back around 30 degrees or so while creating a curvature on your lower back and sticking your poitrine out. Position de depart. 4. As you Expirez, bring the bar down until it touches your upper poitrine by drawing the epaules and the upper arms down and back. Conseil : Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torse should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms. 5. After a second in the contracted position, while squeezing your omoplates together, Lentement, raise the bar back to the position de depart when vos bras are fully extended and the lats are fully stretched. Inhale during this portion of le mouvement. 6. 6. Repetez this motion for the prescribed amount of repetitions.', 'Muscles secondaires : Biceps, Milieu du dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Front_Lat_Pulldown/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Close-Grip Push-Up off of a Dumbbell', 'Triceps', 'Poids de corps', '1. Allongez-vous au sol and place vos mains on an upright halteres. Supporting your poids on your toes and hands, keep your torse rigid and your coudes in with vos bras straight. Position de depart. 2. Lower votre corps, allowing the coudes to flex while you inhale. Keep votre corps straight, not allowing your hips to rise or sag. 3. Press yourself back up to the position de depart by extending the coudes. Expirez as you perform this step. 4. Apres une pause, at the contracted position, Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Abdominaux, Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Push-Up_off_of_a_Dumbbell/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Close-Grip Standing Barbell Curl', 'Biceps', 'Barre', '1. Hold a barre with both hands, palms up and a few inches apart. 2. Tenez-vous debout avec your torse straight and your head up. vos pieds should be about epaules width and your coudes close to your torse. Position de depart. Conseil : You will keep your upper arms and coudes stationary throughout le mouvement. 3. Curl the bar up in a semicircular motion until the forearms touch your biceps. Exhale as you perform this portion of le mouvement and contract your biceps hard for a second at the top. Conseil : Avoid bending the back or using swinging motions as you lift the poids. Only the forearms should move. 4. Lentement, go back down to the position de depart en inspirant. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Standing_Barbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cocoons', 'Abdominaux', 'Poids de corps', '1. Begin by lying on votre dos on the ground. vos jambes should be straight and vos bras extended behind your head. Position de depart. 2. To perform le mouvement, tuck the genoux toward your poitrine, rotating your pelvis to lift your fessiers from le sol. As you do so, flex the spine, bringing vos bras back over your head to perform a simultaneous crunch motion. 3. Apres une pause, Revenez en position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cocoons/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Conan''s Wheel', 'Quadriceps', 'Autre', '1. With the poids loaded, take a zurcher hold on the end of the implement. Place the bar in the crook of the coudes and hold onto your poignets. Try to keep the poids off of the forearms. 2. Begin by lifting the poids from the ground. Keep a tight, upright posture as you being to walk, taking short, fast steps. Look up and away as you turn in a circle. Do not hold your breath during the event. Continue walking until you complete one or more complete turns.', 'Muscles secondaires : Abdominaux, Biceps, Mollets, Avant-bras, Bas du dos, Épaules, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Conans_Wheel/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Concentration Curls', 'Biceps', 'Haltères', '1. Sit down on a flat banc with one halteres in front of you between vos jambes. vos jambes should be spread with your genoux bent and feet on le sol. 2. Use your right arm to pick the halteres up. Place the back of your right upper arm on the top of your inner right cuisses. Rotate the palm of your hand until it is facing forward away from your cuisses. Conseil : Your arm should be extended and the halteres should be above le sol. Position de depart. 3. While holding the upper arm stationary, curl the poids forward while contracting the biceps as you Expirez. Only the forearms should move. Continue le mouvement until your biceps are entierement contracte and the halteres are at epaules level. Conseil : At the top of le mouvement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Maintenez 1 seconde as you squeeze the biceps. 4. Lentement, begin to bring the halteres back to position de depart as your Inspirez. Caution: Avoid swinging motions at any time. 5. Repetez selon le nombre souhaite. Then Repetez le mouvement with the left arm.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Concentration_Curls/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cross-Body Crunch', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol and bend your genoux about 60 degrees. 2. Keep vos pieds flat on le sol and place vos mains loosely behind your head. Position de depart. 3. Now curl up and bring your right coudes and epaules across votre corps while bring your left genoux in toward your left epaules at the same time. Reach with your coudes and try to touch your genoux. Exhale as you perform this movement. Conseil : Try to bring your epaules up towards your genoux rather than just your coudes and remember that the key is to contract the abdominaux as you perform le mouvement; not just to move the coudes. 4. Now go back down to the position de depart en inspirant and Repetez with the left coudes and the right genoux. 5. Continue alternating in this manner until all prescribed repetitions are done.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cross-Body_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cross Body Hammer Curl', 'Biceps', 'Haltères', '1. Tenez-vous debout avec a halteres in each hand. vos mains should be down at your side with your palms facing in. 2. While keeping your palms facing in and without twisting your arm, curl the halteres of the right arm up towards your left epaules en expirant. Touch the top of the halteres to your epaules and hold the contraction for a second. 3. Lentement, lower the halteres along the same path en inspirant and then Repetez the same movement for the left arm. 4. Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cross_Body_Hammer_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cross Over - With Bands', 'Pectoraux', 'Élastique', '1. Secure an exercise band around a stationary post. 2. While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band. 3. Raise vos bras to the sides, parallel to le sol, perpendicular to your torse (your torse and the arms should resemble the letter "T") and with the palms facing forward. Have them extended with a slight bend at the coudes. Position de depart. 4. While keeping vos bras straight, bring them across your poitrine in a semicircular motion to the front en expirant and flex your pecs. Hold the contraction for a second. 5. Lentement, Revenez en position de depart en inspirant. 6. Perform for the recommended amount of repetitions.', 'Muscles secondaires : Biceps, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cross_Over_-_With_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Crossover Reverse Lunge', 'Bas du dos', 'Autre', '1. Tenez-vous debout avec vos pieds epaules width apart. Position de depart. 2. Perform a rear lunge by stepping back with one foot and flexing the hips and front genoux. As you do so, rotate your torse across the front leg. 3. Apres une pause, Revenez en position de depart and Repetez de l autre cote, continuing in an alternating fashion.', 'Muscles secondaires : Abdominaux, Abducteurs, Fessiers, Ischio-jambiers, Quadriceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crossover_Reverse_Lunge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Crucifix', 'Épaules', 'Autre', '1. In the crucifix, you statically hold poids out to the side for time. While the event can be practiced using halteres, it is best to practice with one of the various implements used, such as axes and hammers, as it feels different. 2. Begin standing, and raise vos bras out to the side holding the implements. vos bras should be parallel to the ground. In competition, judges or sensors are used to let you know when you break parallel. Hold for as long as you can. Typically, the poids should be heavy enough that you fail in 30-60 seconds.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crucifix/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Crunch - Hands Overhead', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol with votre dos flat and genoux bent with around a 60-degree angle between the ischio-jambiers and the mollets. 2. Keep vos pieds flat on le sol and stretch vos bras overhead with your palms crossed. Position de depart. 3. Curl your upper body forward and bring your omoplates just off le sol. en permanence, keep vos bras aligned with your head, neck and epaules. Don''t move them forward from that position. Exhale as you perform this portion of le mouvement and hold the contraction for a second. 4. Lentement, lower down to the position de depart en inspirant. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunch_-_Hands_Overhead/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Crunch - Legs On Exercise Ball', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol with vos pieds resting on an exercise ball and your genoux bent at a 90 degree angle. 2. Place vos pieds three to four inches apart and point your toes inward so they touch. 3. Place vos mains lightly on either side of your head keeping your coudes in. Conseil : Don''t lock your fingers behind your head. 4. Push the small of votre dos down in le sol in order to better isolate your abdominal muscles. Position de depart. 5. Begin to roll your epaules off le sol and continue to push down as hard as you can with your lower back. Your epaules should come up off le sol only about four inches, and your lower back should remain on le sol. Expirez as you execute this portion of le mouvement. Squeeze your abdominals hard at the top of the contraction and Maintenez 1 seconde. Conseil : Focus on a slow, controlled movement. Refrain from using momentum at any time. 6. Lentement, go back down to the position de depart en inspirant. 7. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunch_-_Legs_On_Exercise_Ball/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Crunches', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol with vos pieds flat on the ground, or resting on a banc with your genoux bent at a 90 degree angle. If you are resting vos pieds on a banc, place them three to four inches apart and point your toes inward so they touch. 2. Now place vos mains lightly on either side of your head keeping your coudes in. Conseil : Don''t lock your fingers behind your head. 3. While pushing the small of votre dos down in le sol to better isolate your abdominal muscles, begin to roll your epaules off le sol. 4. Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your epaules should come up off le sol only about four inches, and your lower back should remain on le sol. At the top of le mouvement, contract your abdominals hard and keep the contraction for a second. Conseil : Focus on slow, controlled movement - don''t cheat yourself by using momentum. 5. After the one second contraction, begin to come down Lentement, again to the position de depart en inspirant. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunches/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cuban Press', 'Épaules', 'Haltères', '1. Take a halteres in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to le sol, allowing your lower arms to hang in the "scarecrow" position. Position de depart. 2. To initiate le mouvement, externally rotate the epaules to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the poignets are directly above the coudes, the forearms perpendicular to le sol. 3. Now press the halteres by extending at the coudes, straightening vos bras overhead. 4. Revenez en position de depart as you Inspirez by reversing the steps. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cuban_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dancer''s Stretch', 'Bas du dos', 'Autre', '1. Sit up on le sol. 2. Cross your right leg over your left, keeping the genoux bent. Your left leg is straight and down on le sol. 3. Place your left arm on your right leg and your right hand on le sol. 4. Rotate your upper body to the right, and hold for 10-20 seconds. Switch sides.', 'Muscles secondaires : Abducteurs, Fessiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dancers_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dead Bug', 'Abdominaux', 'Poids de corps', '1. Begin lying on votre dos with vos mains extended above you toward the ceiling. 2. Bring vos pieds, genoux, and hips up to 90 degrees. 3. Exhale hard to bring your ribcage down and flatten votre dos onto le sol, rotating your pelvis up and squeezing your fessiers. Hold this position throughout le mouvement. Position de depart. 4. Initiate the exercise by extending one leg, straightening the genoux and hip to bring the leg just above the ground. 5. Maintain the position of your lumbar and pelvis as you perform le mouvement, as votre dos is going to want to arch. 6. Stay tight and return the working leg to the position de depart. 7. Repetez de l autre cote, alternating until the set is complete.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dead_Bug/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Deadlift with Bands', 'Bas du dos', 'Barre', '1. To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. For long bands, they will need to be anchored to a secure base, such as heavy halteres or a rack. 2. With vos pieds, and your grip set, take a big breath and then lower your hips and bend the genoux until your shins contact the bar. Look forward with your head, keep your poitrine up and votre dos arched, and begin driving through the heels to move the poids upward. After the bar passes the genoux, aggressively pull the bar back, pulling your omoplates together as you drive your hips forward into the bar. 3. Lower the bar by bending at the hips and guiding it to le sol.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Milieu du dos, Quadriceps, Trapèzes. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Deadlift_with_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Deadlift with Chains', 'Bas du dos', 'Barre', '1. You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater poids increase as you lift. 2. Approach the bar so that it is centered over vos pieds. You feet should be about hip width apart. Bend at the hip to grip the bar at epaules width, allowing your omoplates to protract. Typically, you would use an prise en pronation or an over/under grip on heavier sets. With vos pieds, and your grip set, take a big breath and then lower your hips and bend the genoux until your shins contact the bar. 3. Look forward with your head, keep your poitrine up and votre dos arched, and begin driving through the heels to move the poids upward. After the bar passes the genoux, aggressively pull the bar back, pulling your omoplates together as you drive your hips forward into the bar. 4. Lower the bar by bending at the hips and guiding it to le sol.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Milieu du dos, Quadriceps, Trapèzes. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Deadlift_with_Chains/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Decline Barbell Bench Press', 'Pectoraux', 'Barre', '1. Secure vos jambes at the end of the decline banc and Lentement, lay down on the banc. 2. Using a prise moyenne (a grip that creates a 90-degree angle in the middle of le mouvement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with vos bras locked. The arms should be perpendicular to le sol. Position de depart. Conseil : In order to protect your rotator cuff, it is best if you have a spotter help you lift the barre off the rack. 3. As you Inspirez, come down Lentement, until you feel the bar on your lower poitrine. 4. Apres une pause, bring the bar back to the position de depart as you Expirez and push the bar using your poitrine muscles. Lock vos bras and squeeze your poitrine in the contracted position, Maintenez 1 seconde and then start coming down Lentement, again. Conseil : It should take at least twice as long to go down than to come up). 5. Repetez le mouvement for the prescribed amount of repetitions. 6. When you are done, place the bar back in the rack.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Barbell_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Decline Close-Grip Bench To Skull Crusher', 'Triceps', 'Barre', '1. Secure vos jambes at the end of the decline banc and Lentement, lay down on the banc. 2. Using a close grip (a grip that is slightly less than epaules width), lift the bar from the rack and hold it straight over you with vos bras locked and coudes in. The arms should be perpendicular to le sol. Position de depart. Conseil : In order to protect your rotator cuff, it is best if you have a spotter help you lift the barre off the rack. 3. Now lower the bar down to your lower poitrine as you Inspirez. Keep the coudes in as you perform this movement. 4. Using the triceps to push the bar back up, press it back to the position de depart en expirant. 5. As you Inspirez and you keep the upper arms stationary, bring the bar down Lentement, by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Inspirez as you perform this portion of le mouvement. 6. Lift the bar back to the position de depart by contracting the triceps and exhaling. 7. Repetez steps 3-6 until the recommended amount of repetitions is performed.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Close-Grip_Bench_To_Skull_Crusher/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Decline Crunch', 'Abdominaux', 'Poids de corps', '1. Secure vos jambes at the end of the decline banc and lie down. 2. Now place vos mains lightly on either side of your head keeping your coudes in. Conseil : Don''t lock your fingers behind your head. 3. While pushing the small of votre dos down in the banc to better isolate your abdominal muscles, begin to roll your epaules off it. 4. Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your epaules should come up off the banc only about four inches, and your lower back should remain on the banc. At the top of le mouvement, contract your abdominals hard and keep the contraction for a second. Conseil : Focus on slow, controlled movement - don''t cheat yourself by using momentum. 5. After the one second contraction, begin to come down Lentement, again to the position de depart en inspirant. 6. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Decline Dumbbell Bench Press', 'Pectoraux', 'Haltères', '1. Secure vos jambes at the end of the decline banc and lie down with a halteres on each hand on top of your cuisses. The palms of your hand will be facing each other. 2. Once you are laying down, move the halteres in front of you at epaules width. 3. Once at epaules width, rotate your poignets forward so that the palms of vos mains are facing away from you. Position de depart. 4. Bring down the poids Lentement, to your side as you Expirez. Keep full control of the halteres en permanence. Conseil : Throughout the motion, the forearms should always be perpendicular to le sol. 5. As you Expirez, push the halteres up using your pectoral muscles. Lock vos bras in the contracted position, squeeze your poitrine, Maintenez 1 seconde and then start coming down slowly. Conseil : It should take at least twice as long to go down than to come up.. 6. Repetez le mouvement for the prescribed amount of repetitions of your training program.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Decline Dumbbell Flyes', 'Pectoraux', 'Haltères', '1. Secure vos jambes at the end of the decline banc and lie down with a halteres on each hand on top of your cuisses. The palms of your hand will be facing each other. 2. Once you are laying down, move the halteres in front of you at epaules width. The palms of the hands should be facing each other and the arms should be perpendicular to le sol and fully extended. Position de depart. 3. With a slight bend on your coudes in order to prevent stress at the biceps tendon, lower vos bras out at both sides in a wide arc until you feel a stretch on your poitrine. Inspirez as you perform this portion of le mouvement. Conseil : Keep in mind that throughout le mouvement, the arms should remain stationary; le mouvement should only occur at the epaules joint. 4. Return vos bras back to the position de depart as you squeeze your poitrine muscles and Expirez. Conseil : Make sure to use the same arc of motion used to lower the poids. 5. Maintenez 1 seconde at the contracted position and Repetez le mouvement for the prescribed amount of repetitions.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Flyes/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Decline Dumbbell Triceps Extension', 'Triceps', 'Haltères', '1. Secure vos jambes at the end of the decline banc and lie down with a halteres on each hand on top of your cuisses. The palms of your hand will be facing each other. 2. Once you are laying down, move the halteres in front of you at epaules width. The palms of the hands should be facing each other and the arms should be perpendicular to le sol and fully extended. Position de depart. 3. As you Inspirez and you keep the upper arms stationary (and coudes in), bring the halteres down Lentement, by moving your forearms in a semicircular motion towards you until your thumbs are next to your ears. Inspirez as you perform this portion of le mouvement. 4. Lift the halteres back to the position de depart by contracting the triceps and exhaling. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Decline EZ Bar Triceps Extension', 'Triceps', 'Barre', '1. Secure vos jambes at the end of the decline banc and Lentement, lay down on the banc. 2. Using a close grip (a grip that is slightly less than epaules width), lift the EZ bar from the rack and hold it straight over you with vos bras locked and coudes in. The arms should be perpendicular to le sol. Position de depart. Conseil : In order to protect your rotator cuff, it is best if you have a spotter help you lift the barre off the rack. 3. As you Inspirez and you keep the upper arms stationary, bring the bar down Lentement, by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Inspirez as you perform this portion of le mouvement. 4. Lift the bar back to the position de depart by contracting the triceps and exhaling. 5. Repetez until the recommended amount of repetitions is performed.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_EZ_Bar_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Decline Oblique Crunch', 'Abdominaux', 'Poids de corps', '1. Secure vos jambes at the end of the decline banc and Lentement, lay down on the banc. 2. Raise your upper body off the banc until your torse is about 35-45 degrees if measured from le sol. 3. Put one hand beside your head and the other on your cuisses. Position de depart. 4. Raise your upper body Lentement, from the position de depart while turning your torse to the left. Continue crunching up en expirant until your right coudes touches your left genoux. Hold this contracted position for a second. Conseil : Focus on keeping your abdominaux tight and keeping le mouvement slow and controlled. 5. Lower votre corps back down Lentement, to the position de depart en inspirant. 6. After completing one set on the right for the recommended amount of repetitions, switch to your left side. Conseil : Focus on really twisting your torse and feeling the contraction when you are in the up position.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Oblique_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Decline Push-Up', 'Pectoraux', 'Autre', '1. Allongez-vous au sol face down and place vos mains about 36 inches apart while holding your torse up bras tendus. Move vos pieds up to a box or banc. Position de depart. 2. Next, lower yourself downward until your poitrine almost touches le sol en inspirant. 3. Now Expirez and press your upper body back up to the position de depart while squeezing your poitrine. 4. Apres une pause, at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Push-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Decline Reverse Crunch', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol on a decline banc and hold on to the top of the banc with both hands. Don''t let votre corps slip down from this position. 2. Hold vos jambes parallel to le sol using your abdominaux to hold them there while keeping your genoux and feet together. Conseil : vos jambes should be fully extended with a slight bend on the genoux. Position de depart. 3. While exhaling, move vos jambes towards the torse as you roll your pelvis backwards and you raise your hips off the banc. At the end of this movement your genoux will be touching your poitrine. 4. Hold the contraction for a second and move vos jambes back to the position de depart while inhaling. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Reverse_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Decline Smith Press', 'Pectoraux', 'Machine', '1. Place a decline banc underneath the Smith machine. Now place the barre at a height that you can reach when lying down and vos bras are almost fully extended. Using a pronated grip that is wider than epaules width, unlock the bar from the rack and hold it straight over you with vos bras extended. Position de depart. 2. en inspirant, lower the bar under control by allowing the coudes to flex, lightly contacting the torse. 3. Apres une pause, bring the bar back to the position de depart by extending the coudes, exhaling as you do so. 4. Repetez le mouvement for the prescribed amount of repetitions. 5. When the set is complete, lock the bar back in the rack.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Smith_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Deficit Deadlift', 'Bas du dos', 'Barre', '1. Begin by having a platform or poids plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over vos pieds. You feet should be about hip width apart. Bend at the hip to grip the bar at epaules width, allowing your omoplates to protract. Typically, you would use an prise en pronation or an over/under grip on heavier sets. 2. With vos pieds, and your grip set, take a big breath and then lower your hips and bend the genoux until your shins contact the bar. Look forward with your head, keep your poitrine up and votre dos arched, and begin driving through the heels to move the poids upward. After the bar passes the genoux, aggressively pull the bar back, pulling your omoplates together as you drive your hips forward into the bar. 3. Lower the bar by bending at the hips and guiding it to le sol.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Milieu du dos, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Deficit_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Depth Jump Leap', 'Quadriceps', 'Autre', '1. For this drill you will need two boxes or benches, one 12 to 16 inches high and the other 22 to 26 inches high. 2. Stand on one of the two boxes with arms at the sides; feet should be together and slightly off the edge as in the depth jump. Place the other box approximately two or three feet in front of and facing the performer. 3. Begin by dropping off the initial box, landing and simultaneously taking off with both feet. 4. Rebound by driving upward and outward as intensely as possible, using the arms and full extension of the body to jump onto the higher box. Again, allow the legs to absorb the impact.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Depth_Jump_Leap/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dip Machine', 'Triceps', 'Machine', '1. Sit securely in a dip machine, select the poids and firmly grasp the handles. 2. Now keep your coudes in at your sides in order to place emphasis on the triceps. The coudes should be bent at a 90 degree angle. 3. As you contract the triceps, extend vos bras downwards en expirant. Conseil : At the bottom of le mouvement, focus on keeping a little bend in vos bras to keep tension on the triceps muscle. 4. Now Lentement, let vos bras come back up to the position de depart en inspirant. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dip_Machine/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dips - Chest Version', 'Pectoraux', 'Autre', '1. For this exercise you will need access to parallel bars. To get yourself into the position de depart, hold votre corps bras tendus (arms locked) above the bars. 2. While breathing in, lower yourself Lentement, with your torse leaning forward around 30 degrees or so and your coudes flared out slightly until you feel a slight stretch in the poitrine. 3. Once you feel the stretch, use your poitrine to bring votre corps back to the position de depart as you Expirez. Conseil : Remember to squeeze the poitrine at the top of le mouvement for a second. 4. Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dips_-_Chest_Version/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dips - Triceps Version', 'Triceps', 'Poids de corps', '1. To get into the position de depart, hold votre corps at arm''s length with vos bras nearly locked above the bars. 2. Now, inhale and Lentement, lower yourself downward. Your torse should remain upright and your coudes should stay close to votre corps. This helps to better focus on triceps involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm. 3. Then, exhale and push your torse back up using your triceps to bring votre corps back to the position de depart. 4. Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dips_-_Triceps_Version/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Donkey Calf Raises', 'Mollets', 'Autre', '1. For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad. 2. Place both of vos bras on the side handles and place the balls of vos pieds on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the genoux without locking them. Position de depart. 3. Raise your heels as you Expirez by extending your ankles as high as possible and flexing your calf. Ensure that the genoux is kept stationary en permanence. There should be no bending at any time. Hold the contracted position by a second before you start to go back down. 4. Go back Lentement, to the position de depart as you Inspirez by lowering your heels as you bend the ankles until mollets are stretched. 5. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Donkey_Calf_Raises/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Double Kettlebell Alternating Hang Clean', 'Ischio-jambiers', 'Kettlebell', '1. Place two kettlebells between vos pieds. To get in the position de depart, push your butt back and look straight ahead. 2. Clean one kettlebells to your epaules and hold on to the other kettlebells. 3. With a fluid motion, lower the top kettlebells while driving the bottom kettlebells up.', 'Muscles secondaires : Biceps, Mollets, Avant-bras, Fessiers, Bas du dos, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Alternating_Hang_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Double Kettlebell Jerk', 'Épaules', 'Kettlebell', '1. Hold a kettlebells by the handle in each hand. 2. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so, so that the palms face forward. Position de depart. 3. Dip votre corps by bending the genoux, keeping your torse upright. 4. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. 5. As you do so, press the kettlebells overhead to lockout by extending the arms, using votre corps''s momentum to move the poids. 6. Return vos pieds to the ground in a split fashion, with one foot forward and one foot back. 7. Keeping the poids overhead, return to a standing position, bringing vos pieds together. Lower the poids to perform the next repetition.', 'Muscles secondaires : Mollets, Quadriceps, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Jerk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Double Kettlebell Push Press', 'Épaules', 'Kettlebell', '1. Clean two kettlebells to your epaules. 2. Squat down a few inches and reverse the motion rapidly. Use the momentum from the legs to drive the kettlebells overhead. 3. Once the kettlebells are locked out, lower the kettlebells to your epaules and Repetez.', 'Muscles secondaires : Mollets, Quadriceps, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Push_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Double Kettlebell Snatch', 'Épaules', 'Kettlebell', '1. Place two kettlebells behind vos pieds. Bend your genoux and sit back to pick up the kettlebells. 2. Swing the kettlebells between vos jambes forcefully and reverse the direction. 3. Drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.', 'Muscles secondaires : Fessiers, Ischio-jambiers, Quadriceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Snatch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Double Kettlebell Windmill', 'Abdominaux', 'Kettlebell', '1. Place a kettlebells in front of your front foot and clean and press a kettlebells overhead with your opposite arm. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so, so that the palm faces forward. 2. Keeping the kettlebells locked out en permanence, push your butt out in the direction of the locked out kettlebells. Turn vos pieds out at a forty-five degree angle from the arm with the locked out kettlebells. 3. Bending at the hip to one side, sticking your butt out, Lentement, lean until you can retrieve the kettlebells from le sol. Keep your eyes on the kettlebells that you hold over your head en permanence. 4. Pause for a second after retrieving the kettlebells from the ground and reverse the motion back to the position de depart.', 'Muscles secondaires : Fessiers, Ischio-jambiers, Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Kettlebell_Windmill/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Double Leg Butt Kick', 'Quadriceps', 'Poids de corps', '1. Begin standing with your genoux slightly bent. 2. Quickly squat a short distance, flexing the hips and genoux, and immediately extend to jump for maximum vertical height. 3. As you go up, tuck your heels by flexing the genoux, attempting to touch the buttocks. 4. Finish the motion by landing with the genoux only partially bent, using vos jambes to absorb the impact.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Double_Leg_Butt_Kick/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Downward Facing Balance', 'Fessiers', 'Swiss ball', '1. Lie facedown on top of an exercise ball. 2. While resting on your stomach on the ball, walk vos mains forward along le sol and lift vos jambes, extending your coudes and genoux.', 'Muscles secondaires : Abdominaux, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Downward_Facing_Balance/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Drag Curl', 'Biceps', 'Barre', '1. Grab a barre with a supinated grip (palms facing forward) and get your coudes close to your torse and back. Position de depart. 2. en expirant, curl the bar up while keeping the coudes to the back as you "Drag" the bar up by keeping it in contact with your torse. Conseil : As you can see, you will not be keeping the coudes pinned to your sides, but instead you will be bringing them back. Also, do not lift your epaules. 3. Lentement, go back to the position de depart as you keep the bar in contact with the torse en permanence. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Drag_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Drop Push', 'Pectoraux', 'Autre', '1. Position low boxes or other platforms 2-3 feet apart. 2. Move to a pushup position between them, supporting yourself by placing vos mains on the boxes. 3. With good posture, drop from the platforms by pressing up and moving vos mains to epaules width, cushioning your landing by absorbing the impact through the arm.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Drop_Push/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Alternate Bicep Curl', 'Biceps', 'Haltères', '1. Stand (torse upright) with a halteres in each hand held bras tendus. The coudes should be close to the torse and the palms of your hand should be facing your cuisses. 2. While holding the upper arm stationary, curl the right poids as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you Expirez until your biceps is entierement contracte and the halteres are at epaules level. Maintenez 1 seconde as you squeeze the biceps. Conseil : Only the forearms should move. 3. Lentement, begin to bring the halteres back to the position de depart as your Inspirez. Conseil : Remember to twist the palms back to the position de depart (facing your cuisses) as you come down. 4. Repetez le mouvement with the left hand. This equals one repetition. 5. Continue alternating in this manner for the recommended amount of repetitions.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Alternate_Bicep_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Bench Press', 'Pectoraux', 'Haltères', '1. Allongez-vous sur un banc plat with a halteres in each hand resting on top of your cuisses. The palms of vos mains will be facing each other. 2. Then, using your cuisses to help raise the halteres up, lift the halteres one at a time so that you can hold them in front of you at epaules width. 3. Once at epaules width, rotate your poignets forward so that the palms of vos mains are facing away from you. The halteres should be just to the sides of your poitrine, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the halteres en permanence. Position de depart. 4. Then, as you Expirez, use your poitrine to push the halteres up. Lock vos bras at the top of the lift and squeeze your poitrine, Maintenez 1 seconde and then begin coming down slowly. Conseil : Ideally, lowering the poids should take about twice as long as raising it. 5. Repetez le mouvement for the prescribed amount of repetitions of your training program.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Bench Press with Neutral Grip', 'Pectoraux', 'Haltères', '1. Take a halteres in each hand and lay back onto a flat banc. vos pieds should be flat on le sol and your omoplates retracted. 2. Maintaining a neutral grip, palms facing each other, begin with vos bras extended directly above you, perpendicular to le sol. Position de depart. 3. Begin le mouvement by flexing the coudes, lowering the upper arms to the side. Descend until the halteres are to your torse. 4. Pause, then extend the coudes and Revenez en position de depart.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bench_Press_with_Neutral_Grip/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Bicep Curl', 'Biceps', 'Haltères', '1. Tenez-vous debout avec a halteres in each hand at arm''s length. Keep your coudes close to your torse and rotate the palms of vos mains until they are facing forward. Position de depart. 2. Now, keeping the upper arms stationary, exhale and curl the poids while contracting your biceps. Continue to raise the poids until your biceps are entierement contracte and the halteres are at epaules level. Hold the contracted position for a brief pause as you squeeze your biceps. 3. Then, inhale and Lentement, begin to lower the halteres back to the position de depart. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Bicep_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Clean', 'Ischio-jambiers', 'Haltères', '1. Begin standing with a halteres in each hand with vos pieds epaules width apart. 2. Lower the poids to le sol by flexing at the hips and genoux, pushing your hips back until the halteres reach le sol. Position de depart. 3. To initiate le mouvement, violently jump upward by extending the hips, genoux, and ankles to acclerate the poids upward. Maintaining a neutral grip on the halteres, keep the arms straight until full extension is reached. 4. After full extension, rebend the hips and genoux to receive the poids in a squat position. Allow the arms to bend, guiding the halteres to your epaules. 5. Upon receiving the poids in the squat position, extend the hips and genoux to finish in a standing position with the poids on your epaules.', 'Muscles secondaires : Mollets, Avant-bras, Fessiers, Bas du dos, Quadriceps, Épaules, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Floor Press', 'Triceps', 'Haltères', '1. Lay on le sol holding halteres in vos mains. Your genoux can be bent. Begin with the poids fully extended above you. 2. Lower the poids until your upper arm comes in contact with le sol. You can tuck your coudes to emphasize triceps size and strength, or to focus on your poitrine angle vos bras to the side. 3. Pause at the bottom, and then bring the poids together at the top by extending through the coudes.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Floor_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Flyes', 'Pectoraux', 'Haltères', '1. Allongez-vous sur un banc plat with a halteres on each hand resting on top of your cuisses. The palms of your hand will be facing each other. 2. Then using your cuisses to help raise the halteres, lift the halteres one at a time so you can hold them in front of you at epaules width with the palms of vos mains facing each other. Raise the halteres up like you''re pressing them, but stop and hold just before you lock out. Position de depart. 3. With a slight bend on your coudes in order to prevent stress at the biceps tendon, lower vos bras out at both sides in a wide arc until you feel a stretch on your poitrine. Inspirez as you perform this portion of le mouvement. Conseil : Keep in mind that throughout le mouvement, the arms should remain stationary; le mouvement should only occur at the epaules joint. 4. Return vos bras back to the position de depart as you squeeze your poitrine muscles and Expirez. Conseil : Make sure to use the same arc of motion used to lower the poids. 5. Maintenez 1 seconde at the contracted position and Repetez le mouvement for the prescribed amount of repetitions.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Flyes/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Incline Row', 'Milieu du dos', 'Haltères', '1. Using a neutral grip, lean into an incline banc. 2. Take a halteres in each hand with a neutral grip, beginning with the arms straight. Position de depart. 3. Retract the omoplates and flex the coudes to row the halteres to your side. 4. Pause at the top of the motion, and then Revenez en position de depart.', 'Muscles secondaires : Biceps, Avant-bras, Dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Incline_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Incline Shoulder Raise', 'Épaules', 'Haltères', '1. Asseyez-vous sur un banc while holding a halteres on each hand on top of your cuisses. 2. Lift vos jambes up to kick the poids to your epaules and lean back. Position the halteres above your epaules with vos bras extended. The arms should be perpendicular to le sol with your palms facing forward and knuckles pointing towards the ceiling. Position de depart. 3. While keeping the arms straight and locked, lift the halteres by raising the epaules from the banc as you Expirez. 4. Bring back the halteres to the position de depart as you Inspirez. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Incline_Shoulder_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Lunges', 'Quadriceps', 'Haltères', '1. Tenez-vous debout avec your torse upright holding two halteres in vos mains by your sides. Position de depart. 2. Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torse upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your genoux to go forward beyond your toes as you come down, as this will put undue stress on the genoux joint. Make sure that you keep your front shin perpendicular to the ground. 3. Using mainly the heel of your foot, push up and go back to the position de depart en expirant. 4. Repetez le mouvement for the recommended amount of repetitions and then perform with the left leg.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lunges/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Lying One-Arm Rear Lateral Raise', 'Épaules', 'Haltères', '1. While holding a halteres in one hand, lay with your poitrine down on a slightly inclined (around 15 degrees when measured from le sol) adjustable banc. The other hand can be used to hold to the leg of the banc for stability. 2. Position the palm of the hand that is holding the halteres in a neutral manner (palms facing your torse) as you keep the arm extended with the coudes slightly bent. Position de depart. 3. Now raise the arm with the halteres to the side until your coudes is at epaules height and your arm is roughly parallel to le sol en expirant. Conseil : Maintain your arm perpendicular to the torse while keeping your arm extended throughout le mouvement. Also, keep the contraction at the top for a second. 4. Lentement, lower the halteres to the position de depart en inspirant. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Milieu du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Lying Pronation', 'Avant-bras', 'Haltères', '1. Allongez-vous sur un banc plat face down with one arm holding a halteres and the other hand on top of the banc folded so that you can rest your head on it. 2. Bend the coudes of the arm holding the halteres so that it creates a 90-degree angle between the upper arm and the forearm. 3. Now raise the upper arm so that the forearm is perpendicular to le sol and the upper arm is perpendicular to your torse. Conseil : The upper arm should be parallel to le sol and also creating a 90-degree angle with your torse. Position de depart. 4. As you Expirez, externally rotate your forearm so that the halteres is lifted forward as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is parallel to le sol. At this point you will hold the contraction for a second. 5. As you Inspirez, Lentement, go back to the position de depart. 6. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lying_Pronation/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Lying Rear Lateral Raise', 'Épaules', 'Haltères', '1. While holding a halteres in each hand, lay with your poitrine down on a slightly inclined (around 15 degrees when measured from le sol) adjustable banc. 2. Position the palms of the hands in a neutral manner (palms facing your torse) as you keep the arms extended with the coudes slightly bent. Position de depart. 3. Now raise the arms to the side until your coudes are at epaules height and vos bras are roughly parallel to le sol en expirant. Conseil : Maintain vos bras perpendicular to the torse while keeping them extended throughout le mouvement. Also, keep the contraction at the top for a second. 4. Lentement, lower the halteres to the position de depart en inspirant. 5. Repetez selon le nombre souhaite. and then switch to the other arm.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lying_Rear_Lateral_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Lying Supination', 'Avant-bras', 'Haltères', '1. Lie sideways on a flat banc with one arm holding a halteres and the other hand on top of the banc folded so that you can rest your head on it. 2. Bend the coudes of the arm holding the halteres so that it creates a 90-degree angle between the upper arm and the forearm. 3. Now raise the upper arm so that the forearm is parallel to le sol and perpendicular to your torse (Conseil : So the forearm will be directly in front of you). The upper arm will be stationary by your torse and should be parallel to le sol (aligned with your torse en permanence). Position de depart. 4. As you Expirez, externally rotate your forearm so that the halteres is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to le sol and the torse pointing towards the ceiling. At this point you will hold the contraction for a second. 5. As you Inspirez, Lentement, go back to the position de depart. 6. Repetez selon le nombre souhaite. and then switch to the other arm.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Lying_Supination/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell One-Arm Shoulder Press', 'Épaules', 'Haltères', '1. Grab a halteres and either sit on a military press banc or a utility banc that has a back support on it as you place the halteres upright on top of your cuisses or stand up straight. 2. Clean the halteres up to bring it to epaules height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. 3. Rotate the poignets so that the palm of your hand is facing forward. Position de depart. 4. en expirant, push the halteres up until your arm is fully extended. 5. Apres une pause, Lentement, come down back to the position de depart en inspirant. 6. Repetez selon le nombre souhaite. and then switch arms.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_One-Arm_Shoulder_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell One-Arm Triceps Extension', 'Triceps', 'Haltères', '1. Grab a halteres and either sit on a military press banc or a utility banc that has a back support on it as you place the halteres upright on top of your cuisses or stand up straight. 2. Clean the halteres up to bring it to epaules height and then extend the arm over your head so that the whole arm is perpendicular to le sol and next to your head. The halteres should be on top of you. The other hand can be kept fully extended to the side, by the waist, supporting the upper arm that has the halteres or grabbing a fixed surface. 3. Rotate the poignets so that the palm of your hand is facing forward and the pinkie is facing the ceiling. Position de depart. 4. Lentement, lower the halteres behind your head as you hold the upper arm stationary. Inhale as you perform this movement and pause when your triceps are fully stretched. 5. Revenez en position de depart by flexing your triceps as you Expirez. Conseil : It is imperative that only the forearm moves. The upper arm should remain en permanence stationary next to your head. 6. Repetez selon le nombre souhaite. and switch arms.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_One-Arm_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell One-Arm Upright Row', 'Épaules', 'Haltères', '1. Grab a halteres and Tenez-vous debout avec your arm extended in front of you with a slight bend at the coudes and votre dos straight. Position de depart. Conseil : The halteres should be resting on top of your cuisses with the palm of vos mains facing your cuisses. 2. Keep the other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. Position de depart. 3. Use your side epaules to lift the halteres en expirant. The halteres should be close to the body as you move it up. Continue to lift it until the halteres is nearly in line with your chin. Conseil : Your coudes should drive the motion. As you lift the halteres, your coudes should always be higher than your forearm. Also, keep your torse stationary and pause for a second at the top of le mouvement. 4. Lower the halteres back down Lentement, to the position de depart. Inhale as you perform this portion of le mouvement. 5. Repetez selon le nombre souhaite. and switch arms.', 'Muscles secondaires : Biceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_One-Arm_Upright_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Prone Incline Curl', 'Biceps', 'Haltères', '1. Grab a halteres on each hand and lie face down on an incline banc with your epaules near top of the incline. Your genoux can rest on the seat or vos jambes can be straddled to the sides (my preferred way). 2. Let vos bras extend and hang naturally in front of you so that they are perpendicular to le sol. 3. Now keep your coudes in by your side and face the palms forward. Position de depart. 4. Raise the halteres by contracting the biceps until vos bras are fully flexed. Exhale as you perform this portion of le mouvement and ensure that only the forearms move. The upper arms should remain stationary en permanence. 5. Lower the halteres until vos bras are fully extended. 6. Repetez for the recommended amount of times.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Prone_Incline_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Raise', 'Épaules', 'Haltères', '1. Grab a halteres in each arm and Tenez-vous debout avec vos bras extended by your sides with a slight bend at the coudes and votre dos straight. Position de depart. Conseil : The halteres should be next to your cuisses with the palm of vos mains facing back. 2. Use your side epaules to lift the halteres en expirant. The halteres should be to the side of the body as you move them up. Continue to lift it until the halteres are nearly in line with your chin. Conseil : Your coudes should drive the motion. As you lift the halteres, your coudes should always be higher than your forearm. Also, keep your torse stationary and pause for a second at the top of le mouvement. 3. Lower the halteres back down Lentement, to the position de depart. Inhale as you perform this portion of le mouvement. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Rear Lunge', 'Quadriceps', 'Haltères', '1. Tenez-vous debout avec your torse upright holding two halteres in vos mains by your sides. Position de depart. 2. Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torse upright and maintaining balance. Inhale as you go down. Conseil : As in the other exercises, do not allow your genoux to go forward beyond your toes as you come down, as this will put undue stress on the genoux joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torse upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps. 3. Push up and go back to the position de depart en expirant. Conseil : Use the ball of vos pieds to push in order to accentuate the quadriceps. To focus on the fessiers, press with your heels. 4. Now Repetez with the opposite leg.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Rear_Lunge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Scaption', 'Épaules', 'Haltères', '1. This corrective exercise strengthens the muscles that stabilize your omoplates. Hold a light poids in each hand, hanging at your sides. Your thumbs should pointing up. 2. Begin le mouvement raising vos bras out in front of you, about 30 degrees off center. vos bras should be fully extended as you perform le mouvement. 3. Continue until vos bras are parallel to the ground, and then Revenez en position de depart.', 'Muscles secondaires : Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Scaption/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Seated Box Jump', 'Quadriceps', 'Haltères', '1. Position a box a couple feet to the side of a banc. Hold a halteres to your poitrine with both hands and seat yourself on the banc facing the box. Position de depart. 2. Plant vos pieds firmly on the ground as you lean forward, extending through the hips and genoux to jump up and forward. 3. Land on the box with both feet, absorbing the impact by allowing the hips and genoux to bend. 4. Step down and Revenez en position de depart.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Seated_Box_Jump/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Seated One-Leg Calf Raise', 'Mollets', 'Haltères', '1. Place a block on le sol about 12 inches from a flat banc. 2. Sit on a flat banc and place a halteres on your upper left cuisses about 3 inches above your genoux. 3. Now place the ball of your left foot on the block. Position de depart. 4. Raise your toes up as high as possible en expirant and you contract your calf muscle. Hold the contraction for a second. 5. Lentement, Revenez en position de depart, stretching as far down as possible. 6. Repetez for your prescribed number of repetitions and then Repetez with the right leg.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Seated_One-Leg_Calf_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Shoulder Press', 'Épaules', 'Haltères', '1. While holding a halteres in each hand, sit on a military press banc or utility banc that has back support. Place the halteres upright on top of your cuisses. 2. Now raise the halteres to epaules height one at a time using your cuisses to help propel them up into position. 3. Make sure to rotate your poignets so that the palms of vos mains are facing forward. Position de depart. 4. Now, exhale and push the halteres upward until they touch at the top. 5. Then, Apres une pause, at the top contracted position, Lentement, lower the poids back down to the position de depart while inhaling. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shoulder_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Shrug', 'Trapèzes', 'Haltères', '1. Stand erect with a halteres on each hand (palms facing your torse), arms extended on the sides. 2. Lift the halteres by elevating the epaules as high as possible while you exhale. Hold the contraction at the top for a second. Conseil : The arms should remain extended en permanence. Refrain from using the biceps to help lift the halteres. Only the epaules should be moving up and down. 3. Lower the halteres back to the original position. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Shrug/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Side Bend', 'Abdominaux', 'Haltères', '1. Stand up straight while holding a halteres on the left hand (palms facing the torse) as you have the right hand holding your waist. vos pieds should be placed at epaules width. Position de depart. 2. While keeping votre dos straight and your head up, bend only at the waist to the right as far as possible. Inspirez as you bend to the side. Then Maintenez 1 seconde and come back up to the position de depart en expirant. Conseil : Keep the rest of the body stationary. 3. Now Repetez le mouvement but bending to the left instead. Maintenez 1 seconde and come back to the position de depart. 4. Repetez selon le nombre souhaite. and then change hands.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Side_Bend/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Squat', 'Quadriceps', 'Haltères', '1. Stand up straight while holding a halteres on each hand (palms facing the side of vos jambes). 2. Position vos jambes using a epaules width medium stance with the toes slightly pointed out. Keep your head up en permanence as looking down will get you off balance and also maintain a straight back. Position de depart. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section. 3. Begin to Lentement, lower your torse by bending the genoux as you maintain a straight posture with the head up. Continue down until your cuisses are parallel to le sol. Conseil : If you performed the exercise correctly, the front of the genoux should make an imaginary straight line with the toes that is perpendicular to the front. If your genoux are past that imaginary line (if they are past your toes) then you are placing undue stress on the genoux and the exercise has been performed incorrectly. 4. Begin to raise your torse en expirant by pushing le sol with the heel of your foot mainly as you straighten the legs again and go back to the position de depart. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Squat To A Bench', 'Quadriceps', 'Haltères', '1. Tenez-vous debout avec a flat banc behind you while holding a halteres on each hand (palms facing the side of vos jambes). 2. Position vos jambes using a epaules width medium stance with the toes slightly pointed out. Keep your head up en permanence as looking down will get you off balance and also maintain a straight back. Position de depart. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section. 3. Begin to Lentement, lower your torse by bending the genoux as you maintain a straight posture with the head up. Continue down until you slightly touch the banc behind you. Inhale as you perform this portion of le mouvement. Conseil : If you performed the exercise correctly, the front of the genoux should make an imaginary straight line with the toes that is perpendicular to the front. If your genoux are past that imaginary line (if they are past your toes) then you are placing undue stress on the genoux and the exercise has been performed incorrectly. 4. Begin to raise the bar en expirant by pushing le sol with the heel of your foot mainly as you straighten the legs again and go back to the position de depart. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Squat_To_A_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Step Ups', 'Quadriceps', 'Haltères', '1. Stand up straight while holding a halteres on each hand (palms facing the side of vos jambes). 2. Place the right foot on the elevated platform. Step on the platform by extending the hip and the genoux of your right leg. Use the heel mainly to lift the rest of votre corps up and place the foot of the left leg on the platform as well. Expirez as you execute the force required to come up. 3. Step down with the left leg by flexing the hip and genoux of the right leg en inspirant. Return to the original standing position by placing the right foot of to next to the left foot on the initial position. 4. Repetez with the right leg for the recommended amount of repetitions and then perform with the left leg.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Step_Ups/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dumbbell Tricep Extension -Pronated Grip', 'Triceps', 'Haltères', '1. Allongez-vous sur un banc plat holding two halteres directly above your epaules. vos bras should be fully extended and form a 90 degree angle from your torse and le sol. 2. The palms of vos mains should be facing forward, and your coudes should be tucked in. Position de depart. 3. Now, inhale and Lentement, lower the halteres until they are near your ears. Be sure to keep your upper arms stationary and your coudes tucked in. 4. Then, exhale and use your triceps to return the poids to the position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dumbbell_Tricep_Extension_-Pronated_Grip/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dynamic Back Stretch', 'Dos', 'Autre', '1. Tenez-vous debout avec vos pieds epaules width apart. Position de depart. 2. Keeping vos bras straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until vos bras are above your head.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dynamic_Back_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dynamic Chest Stretch', 'Pectoraux', 'Autre', '1. Tenez-vous debout avec vos mains together, arms extended directly in front of you. Position de depart. 2. Keeping vos bras straight, quickly move vos bras back as far as possible and back in again, similar to an exaggerated clapping motion. Repetez 5-10 times, increasing speed as you do so.', 'Muscles secondaires : Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dynamic_Chest_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('EZ-Bar Curl', 'Biceps', 'Barre EZ', '1. Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of vos mains should be facing forward and slightly tilted inward due to the shape of the bar. Keep your coudes close to your torse. Position de depart. 2. Now, while keeping your upper arms stationary, exhale and curl the poids forward while contracting the biceps. Focus on only moving your forearms. 3. Continue to raise the poids until your biceps are entierement contracte and the bar is at epaules level. Hold the top contracted position for a moment and squeeze the biceps. 4. Then inhale and Lentement, lower the bar back to the position de depart. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('EZ-Bar Skullcrusher', 'Triceps', 'Barre EZ', '1. Using a close grip, lift the EZ bar and hold it with your coudes in as you lie on the banc. vos bras should be perpendicular to le sol. Position de depart. 2. Keeping the upper arms stationary, lower the bar by allowing the coudes to flex. Inhale as you perform this portion of le mouvement. Pause once the bar is directly above the forehead. 3. Lift the bar back to the position de depart by extending the coudes and exhaling. 4. Repetez.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/EZ-Bar_Skullcrusher/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Elbow Circles', 'Épaules', 'Autre', '1. Sit or Tenez-vous debout avec vos pieds slightly apart. 2. Place vos mains on your epaules with your coudes at epaules level and pointing out. 3. Lentement, make a circle with your coudes. Expirez as you start the circle and Inspirez as you complete the circle.', 'Muscles secondaires : Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elbow_Circles/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Elbow to Knee', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol, crossing your right leg across your bent left genoux. Clasp vos mains behind your head, beginning with your omoplates on the ground. Position de depart. 2. Perform the motion by flexing the spine and rotating your torse to bring the left coudes to the right genoux. 3. Revenez en position de depart and Repetez le mouvement for the desired number of repetitions before switching sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elbow_to_Knee/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Elbows Back', 'Pectoraux', 'Autre', '1. Stand up straight. 2. Place both hands on your lower back, fingers pointing downward and coudes out. 3. Then gently pull your coudes back aiming to touch them together.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elbows_Back/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Elevated Back Lunge', 'Quadriceps', 'Barre', '1. Position a bar onto a rack at epaules height loaded to an appropriate poids. Place a short, raised platform behind you. 2. Rack the bar onto your upper back, keeping votre dos arched and tight. Step onto your raised platform with both feet. Position de depart. 3. Begin by stepping backwards with one leg. Descend by flexing your hips and genoux until your genoux touches le sol. 4. Pause, and extend through the hips and genoux to rise up, returning all the way to the position de depart before alternating.', 'Muscles secondaires : Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elevated_Back_Lunge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Elevated Cable Rows', 'Dos', 'Poulie', '1. Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height. 2. Place it on the seat of the cable row machine. 3. Sit down on the machine and place vos pieds on the front platform or crossbar provided making sure that your genoux are slightly bent and not locked. 4. Lean over as you keep the natural alignment of votre dos and grab the V-bar handles. 5. With vos bras extended pull back until your torse is at a 90-degree angle from vos jambes. votre dos should be slightly arched and your poitrine should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. Position de depart. of the exercise. 6. Keeping the torse stationary, pull the handles back towards your torse while keeping the arms close to it until you touch the abdominals. Expirez as you perform that movement. At that point you should be squeezing votre dos muscles hard. Hold that contraction for a second and Lentement, go back to the original position while breathing in. 7. Repetez selon le nombre souhaite.', 'Muscles secondaires : Milieu du dos, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elevated_Cable_Rows/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Elliptical Trainer', 'Quadriceps', 'Machine', '1. To begin, step onto the elliptical and select the desired option from the menu. Most ellipticals have a manual setting, or you can select a program to run. Typically, you can enter your age and poids to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout. 2. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Elliptical_Trainer/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Exercise Ball Crunch', 'Abdominaux', 'Swiss ball', '1. Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. vos pieds should be bent at the genoux and pressed firmly against le sol. The upper torse should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your poitrine as these positions avoid neck strains (as opposed to the hands behind the back of the head position). 2. Lower your torse into a stretch position keeping the neck stationary en permanence. Position de depart. 3. With the hips stationary, flex the waist by contracting the abdominals and curl the epaules and trunk upward until you feel a nice contraction on your abdominals. The arms should simply slide up the side of vos jambes if you have them at the side or just stay on top of your poitrine if you have them crossed. The lower back should always stay in contact with the ball. Exhale as you perform this movement and hold the contraction for a second. 4. en inspirant, go back to the position de depart. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Exercise_Ball_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Exercise Ball Pull-In', 'Abdominaux', 'Swiss ball', '1. Place an exercise ball nearby and lay on le sol in front of it with vos mains on le sol epaules width apart in a push-up position. 2. Now place your lower shins on top of an exercise ball. Conseil : At this point vos jambes should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. Position de depart. 3. While keeping votre dos completely straight and the upper body stationary, pull your genoux in towards your poitrine en expirant, allowing the ball to roll forward under your ankles. Squeeze your abdominaux and hold that position for a second. 4. Now Lentement, straighten vos jambes, rolling the ball back to the position de depart en inspirant. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Exercise_Ball_Pull-In/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Extended Range One-Arm Kettlebell Floor Press', 'Pectoraux', 'Kettlebell', '1. Allongez-vous au sol and position a kettlebells for one arm to press. The kettlebells should be held by the handle. The leg on the same side that you are pressing should be bent, with the genoux crossing over the midline of the body. 2. Press the kettlebells by extending the coudes and adducting the arm, pressing it above votre corps. Revenez en position de depart.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Extended_Range_One-Arm_Kettlebell_Floor_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('External Rotation', 'Épaules', 'Haltères', '1. Lie sideways on a flat banc with one arm holding a halteres and the other hand on top of the banc folded so that you can rest your head on it. 2. Bend the coudes of the arm holding the halteres so that it creates a 90-degree angle between the upper arm and the forearm. Conseil : Keep the arm parallel to your torse. 3. Now bend the coudes while keeping the upper arm stationary. In this manner, the forearm will be parallel to le sol and perpendicular to your torse (Conseil : So the forearm will be directly in front of you). The upper arm will be stationary by your torse and should be parallel to le sol (aligned with your torse en permanence). Position de depart. 4. As you Expirez, externally rotate your forearm so that the halteres is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to le sol and the torse pointing towards the ceiling. At this point you will hold the contraction for a second. 5. As you Inspirez, Lentement, go back to the position de depart. 6. Repetez selon le nombre souhaite. and then switch to the other arm.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/External_Rotation/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('External Rotation with Band', 'Épaules', 'Élastique', '1. Choke the band around a post. The band should be at the same height as your coudes. Tenez-vous debout avec your left side to the band a couple of feet away. 2. Grasp the end of the band with your right hand, and keep your coudes pressed firmly to your side. We recommend you hold a pad or foam roll in place with your coudes to keep it firmly in position. 3. With your upper arm in position, your coudes should be flexed to 90 degrees with your hand reaching across the front of your torse. Position de depart. 4. Execute le mouvement by rotating your arm in a backhand motion, keeping your coudes in place. 5. Continue as far as you are able, pause, and then Revenez en position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/External_Rotation_with_Band/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('External Rotation with Cable', 'Épaules', 'Poulie', '1. Adjust the cable to the same height as your coudes. Tenez-vous debout avec your left side to the band a couple of feet away. 2. Grasp the handle with your right hand, and keep your coudes pressed firmly to your side. We recommend you hold a pad or foam roll in place with your coudes to keep it firmly in position. 3. With your upper arm in position, your coudes should be flexed to 90 degrees with your hand reaching across the front of your torse. Position de depart. 4. Execute le mouvement by rotating your arm in a backhand motion, keeping your coudes in place.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/External_Rotation_with_Cable/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Face Pull', 'Épaules', 'Poulie', '1. Facing a high pulley with a rope or dual handles attached, pull the poids directly towards your face, separating vos mains as you do so. Keep your upper arms parallel to the ground.', 'Muscles secondaires : Milieu du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Face_Pull/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Farmer''s Walk', 'Avant-bras', 'Autre', '1. There are various implements that can be used for the farmers walk. These can also be performed with heavy halteres or short bars if these implements aren''t available. Begin by standing between the implements. 2. After gripping the handles, lift them up by driving through your heels, keeping votre dos straight and your head up. 3. Walk taking short, quick steps, and don''t forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible.', 'Muscles secondaires : Abdominaux, Fessiers, Ischio-jambiers, Bas du dos, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Farmers_Walk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Fast Skipping', 'Quadriceps', 'Poids de corps', '1. Start in a relaxed position with one leg slightly forward. Position de depart. 2. Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth. 3. Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Fast_Skipping/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Finger Curls', 'Avant-bras', 'Barre', '1. Hold a barre with both hands and your palms facing up; hands spaced about epaules width. 2. Place vos pieds flat on le sol, at a distance that is slightly wider than epaules width apart. Position de depart. 3. Lower the bar as far as possible by extending the fingers. Allowing the bar to roll down the hands, catch the bar with the final joint in the fingers. 4. Now curl bar up as high as possible by closing vos mains while exhaling. Hold the contraction at the top.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Finger_Curls/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Flat Bench Cable Flyes', 'Pectoraux', 'Poulie', '1. Position a flat banc between two low pulleys so that when you are laying on it, your poitrine will be lined up with the cable pulleys. 2. Lay flat on the banc and keep vos pieds on the ground. 3. Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip. 4. Extend vos bras by your side with a slight bend on your coudes. Conseil : You will keep this bend constant through the whole movement. vos bras should be parallel to le sol. Position de depart. 5. Now start lifting the arms in a semi-circle motion directly in front of you by pulling the cables together until both hands meet at the top of le mouvement. Squeeze your poitrine as you perform this motion and Expirez during this movement. Also, hold the contraction for a second at the top. Conseil : When performed correctly, at the top position of this movement, vos bras should be perpendicular to your torse and le sol touching above your poitrine. 6. Lentement, come back to the position de depart. 7. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Cable_Flyes/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Flat Bench Leg Pull-In', 'Abdominaux', 'Poids de corps', '1. Lie on an exercise mat or a flat banc with vos jambes off the end. 2. Place vos mains either under your fessiers with your palms down or by the sides holding on to the banc (or with palms down by the side on an exercise mat). Also extend vos jambes straight out. Position de depart. 3. Bend your genoux and pull your upper cuisses into your midsection as you Expirez. Continue this movement until your genoux are near your poitrine. Maintenez 1 seconde. 4. As you Inspirez, Lentement, Revenez en position de depart. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Leg_Pull-In/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Flat Bench Lying Leg Raise', 'Abdominaux', 'Poids de corps', '1. Lie with votre dos flat on a banc and vos jambes extended in front of you off the end. 2. Place vos mains either under your fessiers with your palms down or by the sides holding on to the banc. Position de depart. 3. As you keep vos jambes extended, straight as possible with your genoux slightly bent but locked raise vos jambes until they make a 90-degree angle with le sol. Exhale as you perform this portion of le mouvement and hold the contraction at the top for a second. 4. Now, en inspirant, Lentement, lower vos jambes back down to the position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Lying_Leg_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Flexor Incline Dumbbell Curls', 'Biceps', 'Haltères', '1. Hold the halteres towards the side farther from you so that you have more poids on the side closest to you. (This can be done for a good effect on all biceps halteres exercises). Now do a normal incline halteres curl, but keep your poignets as far back as possible so as to neutralize any stress that is placed on them. 2. Asseyez-vous sur un banc that is angled at 45-degrees while holding a halteres on each hand. 3. Let vos bras hang down on your sides, with the coudes in, and turn the palms of vos mains forward with the thumbs pointing away from the body. Conseil : You will keep this hand position throughout le mouvement as there should not be any twisting of the hands as they come up. Position de depart. 4. Curl up the two halteres at the same time until your biceps are entierement contracte and exhale. Conseil : Do not swing the arms or use momentum. Keep a controlled motion en permanence. Maintenez 1 seconde at the top. 5. en inspirant, Lentement, go back to the position de depart. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flexor_Incline_Dumbbell_Curls/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Floor Glute-Ham Raise', 'Ischio-jambiers', 'Autre', '1. You can use a partner for this exercise or brace vos pieds under something stable. 2. Begin on your genoux with your upper legs and torse upright. If using a partner, they will firmly hold vos pieds to keep you in position. Position de depart. 3. Lower yourself by extending at the genoux, taking care to NOT flex the hips as you go forward. 4. Place vos mains in front of you as you reach le sol. This movement is very difficult and you may be unable to do it unaided. Use vos bras to lightly push off le sol to aid your Revenez en position de depart.', 'Muscles secondaires : Mollets, Fessiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Floor_Glute-Ham_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Floor Press', 'Triceps', 'Barre', '1. Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on le sol with your head near the end of a power rack. Keeping your omoplates pulled together; pull the bar off of the hooks. 2. Lower the bar towards the bottom of your poitrine or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your coudes throughout le mouvement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the poids. 3. Press the bar back up as fast as you can, keeping the bar, your poignets, and coudes in line as you do so.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Floor_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Floor Press with Chains', 'Triceps', 'Barre', '1. Adjust the j-hooks so they are at the appropriate height to rack the bar. For this exercise, drape the chains directly over the end of the bar, trying to keep the ends away from the plates. 2. Begin lying on le sol with your head near the end of a power rack. Keeping your omoplates pulled together, pull the bar off of the hooks. 3. Lower the bar towards the bottom of your poitrine or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your coudes throughout le mouvement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the poids. 4. Press the bar back up as fast as you can, keeping the bar, your poignets, and coudes in line as you do so.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Floor_Press_with_Chains/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Flutter Kicks', 'Fessiers', 'Poids de corps', '1. On a flat banc lie facedown with the hips on the edge of the banc, the legs straight with toes high off le sol and with the arms on top of the banc holding on to the front edge. 2. Squeeze your fessiers and ischio-jambiers and straighten the legs until they are level with the hips. Position de depart. 3. Start le mouvement by lifting the left leg higher than the right leg. 4. Then lower the left leg as you lift the right leg. 5. Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement en permanence. Conseil : You will breathe normally as you perform this movement.', 'Muscles secondaires : Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flutter_Kicks/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Foot-SMR', 'Mollets', 'Autre', '1. This exercise stretches the fascia of the muscles in the feet. Start off seated with your shoes removed. Using a foot roller or a similar object, such as a small section of pvc pipe, place your foot against the roller across the arch of your foot. Position de depart. 2. Press down firmly, rolling across the arch of your foot. Hold for 10-30 seconds, and then switch feet.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Foot-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Forward Drag with Press', 'Pectoraux', 'Autre', '1. Attach a dual handled chain or rope attachment to the sled. You should be facing away from the sled, holding a handle in each hand. 2. Begin le mouvement by moving forward for one step. Leaning forward, extend through the legs and hips to move, pausing with each step to extend through the coudes, pressing vos mains forward. Step forward until you return to the start position prepared to press.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Quadriceps, Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Forward_Drag_with_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Frankenstein Squat', 'Quadriceps', 'Barre', '1. This drill teaches you the proper positioning of both the bar and votre corps during the clean and front squat. 2. Place the barre on the front of the epaules, releasing your grip and extending vos bras out in front of you. The epaules should be pushed forward to create a shelf, and the bar should be in contact with the throat. Ensure that you only move your omoplates forward; don''t round the thoracic spine. 3. Squat by flexing the genoux and hips, sitting in between vos jambes. Keep the torse upright, the arms up, and the epaules forward, and the bar should stay in place. Go to the bottom of the squat, until your ischio-jambiers contact your mollets. 4. Return to the upright position by driving through the front of the heel and extending the genoux and hips.', 'Muscles secondaires : Abdominaux, Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Frankenstein_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Freehand Jump Squat', 'Quadriceps', 'Poids de corps', '1. Cross vos bras over your poitrine. 2. With your head up and votre dos straight, position vos pieds at epaules width. 3. Keeping votre dos straight and poitrine up, squat down en inspirant until your upper cuisses are parallel, or lower, to le sol. 4. Now pressing mainly with the ball of vos pieds, jump straight up in the air as high as possible, using the cuisses like springs. Exhale during this portion of le mouvement. 5. When you touch le sol again, immediately squat down and jump again. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Freehand_Jump_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Frog Hops', 'Quadriceps', 'Autre', '1. Tenez-vous debout avec vos mains behind your head, and squat down keeping your torse upright and your head up. Position de depart. 2. Jump forward several feet, avoiding jumping unnecessarily high. As vos pieds contact the ground, absorb the impact through vos jambes, and jump again. Repetez this action 5-10 times.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Frog_Hops/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Frog Sit-Ups', 'Abdominaux', 'Poids de corps', '1. Lie with votre dos flat on le sol (or exercise mat) and vos jambes extended in front of you. 2. Now bend at the genoux and place your outer cuisses by le sol (or mat) as you make the soles of vos pieds touch each other. 3. Now try pushing both soles and bringing them up as near you as possible while you keep the outer cuisses on le sol (or at least almost touching it). Conseil : In this position vos jambes should create a diamond shape. 4. Now, cross vos bras in front of you by touching the opposite epaules. Position de depart. 5. en expirant flatten your lower back to le sol while curling the torse upwards. Conseil : This will be like performing the first 1/4 movement of a sit up. Hold at the top position for a second. 6. en inspirant, Lentement, lower back to the position de depart. 7. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Frog_Sit-Ups/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Front Barbell Squat', 'Quadriceps', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring vos bras up under the bar while keeping the coudes high and the upper arm slightly above parallel to le sol. Rest the bar on top of the deltoids and cross vos bras while grasping the bar for total control. 2. Lift the bar off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Step away from the rack and position vos jambes using a epaules width medium stance with the toes slightly pointed out. Keep your head up en permanence as looking down will get you off balance and also maintain a straight back. Position de depart. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section). 4. Begin to Lentement, lower the bar by bending the genoux as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the mollets becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to le sol). Inhale as you perform this portion of le mouvement. Conseil : If you performed the exercise correctly, the front of the genoux should make an imaginary straight line with the toes that is perpendicular to the front. If your genoux are past that imaginary line (if they are past your toes) then you are placing undue stress on the genoux and the exercise has been performed incorrectly. 5. Begin to raise the bar en expirant by pushing le sol mainly with the middle of your foot as you straighten the legs again and go back to the position de depart. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Barbell_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Front Barbell Squat To A Bench', 'Quadriceps', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first set a flat banc behind you and set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring vos bras up under the bar while keeping the coudes high and the upper arm slightly above parallel to le sol. Rest the bar on top of the deltoids and cross vos bras while grasping the bar for total control. 2. Lift the bar off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Step away from the rack and position vos jambes using a epaules width medium stance with the toes slightly pointed out. Keep your head up en permanence as looking down will get you off balance and also maintain a straight back. Position de depart. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section). 4. Begin to Lentement, lower the bar by bending the genoux as you maintain a straight posture with the head up. Continue down until you touch the banc with your fessiers. Inhale as you perform this portion of le mouvement. Conseil : If you performed the exercise correctly, the front of the genoux should make an imaginary straight line with the toes that is perpendicular to the front. If your genoux are past that imaginary line (if they are past your toes) then you are placing undue stress on the genoux and the exercise has been performed incorrectly. 5. Begin to raise the bar en expirant by pushing le sol mainly with the heel of your foot as you straighten the legs again and go back to the position de depart. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Barbell_Squat_To_A_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Front Box Jump', 'Ischio-jambiers', 'Autre', '1. Begin with a box of an appropriate height 1-2 feet in front of you. Tenez-vous debout avec vos pieds should width apart. Position de depart. 2. Perform a short squat in preparation for jumping, swinging vos bras behind you. 3. Rebound out of this position, extending through the hips, genoux, and ankles to jump as high as possible. Swing vos bras forward and up. 4. Land on the box with the genoux bent, absorbing the impact through the legs. You can jump from the box back to the ground, or preferably step down one leg at a time.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Box_Jump/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Front Cable Raise', 'Épaules', 'Poulie', '1. Select the poids on a low pulley machine and grasp the single hand cable attachment that is attached to the low pulley with your left hand. 2. Face away from the pulley and put your arm straight down with the hand cable attachment in front of your cuisses at arms'' length with the palms of the hand facing your cuisses. Position de depart. 3. While maintaining the torse stationary (no swinging), lift the left arm to the front with a slight bend on the coudes and the palms of the hand always faces down. Continue to go up until you arm is slightly above parallel to le sol. Exhale as you execute this portion of le mouvement and pause for a second at the top. 4. Now en inspirant lower the arm back down Lentement, to the position de depart. 5. Once all of the recommended amount of repetitions have been performed for this arm, switch arms and perform the exercise with the right one.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Cable_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Front Cone Hops (or hurdle hops)', 'Quadriceps', 'Autre', '1. Set up a row of cones or other small barriers, placing them a few feet apart. 2. Stand in front of the first cone with vos pieds epaules width apart. Position de depart. 3. Begin by jumping with both feet over the first cone, swinging both arms as you jump. 4. Absorb the impact of landing by bending the genoux, rebounding out of the first leap by jumping over the next cone. 5. Continue until you have jumped over all of the cones.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Cone_Hops_or_hurdle_hops/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Front Dumbbell Raise', 'Épaules', 'Haltères', '1. Pick a couple of halteres and Tenez-vous debout avec a straight torse and the halteres on front of your cuisses bras tendus with the palms of the hand facing your cuisses. Position de depart. 2. While maintaining the torse stationary (no swinging), lift the left halteres to the front with a slight bend on the coudes and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to le sol. Exhale as you execute this portion of le mouvement and pause for a second at the top. Inhale after the second pause. 3. Now lower the halteres back down Lentement, to the position de depart as you simultaneously lift the right halteres. 4. Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Dumbbell_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Front Incline Dumbbell Raise', 'Épaules', 'Haltères', '1. Asseyez-vous sur un banc with the incline set anywhere between 30 to 60 degrees while holding a halteres on each hand. Conseil : You can change the angle to hit the muscle a little differently each time. 2. Extend vos bras straight in front of you and have your palms facing down with the halteres raised about 1 inch above your cuisses. Position de depart. 3. Lentement, raise the halteres straight up until they are slightly above your epaules, while keeping your coudes locked. Squeeze at the top for a second and make sure you Expirez during this portion of le mouvement. Conseil : Keep your head resting down against the banc and vos jambes on le sol en permanence. 4. Lower the arms back to the position de depart en inspirant. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Incline_Dumbbell_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Front Leg Raises', 'Ischio-jambiers', 'Poids de corps', '1. Stand next to a chair or other support, holding on with one hand. 2. Swing your leg forward, keeping the leg straight. Continue with a downward swing, bringing the leg as far back as your flexibility allows. Repetez 5-10 times, and then switch legs.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Leg_Raises/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Front Plate Raise', 'Épaules', 'Autre', '1. While standing straight, hold a barre plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and vos bras should be extended and locked with a slight bend at the coudes and the plate should be down near your waist in front of you as far as you can go. Conseil : The arms will remain in this position throughout the exercise. Position de depart. 2. Lentement, raise the plate en expirant until it is a little above epaules level. Hold the contraction for a second. Conseil : make sure that you do not swing the poids or bend at the coudes. Your torse should remain stationary throughout le mouvement as well. 3. en inspirant, Lentement, lower the plate back down to the position de depart. 4. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Plate_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Front Raise And Pullover', 'Pectoraux', 'Barre', '1. Allongez-vous sur un banc plat while holding a barre using a palms down grip that is about 15 inches apart. 2. Place the bar on your upper cuisses, extend vos bras and lock them while keeping a slight bend on the coudes. Position de depart. 3. Now raise the poids using a semicircular motion and keeping vos bras straight en inspirant. Continue the same movement until the bar is on the other side above your head . (Conseil : the bar will travel approximately 180-degrees). At this point vos bras should be parallel to le sol with the palms of vos mains facing the ceiling. 4. Now return the barre to the position de depart by reversing the motion en expirant. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Dos, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Raise_And_Pullover/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Front Squat (Clean Grip)', 'Quadriceps', 'Barre', '1. To begin, first set the bar in a rack slightly below epaules level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. vos mains should be in a clean grip, touching the bar only with your fingers to help keep it in position. 2. Lift the bar off the rack by first pushing with vos jambes and at the same time straightening your torse. Step away from the rack and position vos jambes using a epaules width medium stance with the toes slightly pointed out. Keep your head and coudes up en permanence. Position de depart. 3. Bend at the genoux, sitting down between vos jambes. Continue down until your ischio-jambiers are on your mollets. Keep your genoux aligned with vos pieds by consciously using your abductors to push your genoux out as you squat. 4. Begin to raise the bar en expirant by pushing le sol mainly with the heel or middle of your foot as you straighten the legs again and Revenez en position de depart.', 'Muscles secondaires : Abdominaux, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Squat_Clean_Grip/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Front Squats With Two Kettlebells', 'Quadriceps', 'Kettlebell', '1. Clean two kettlebells to your epaules. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so. 2. Looking straight ahead en permanence, squat as low as you can and pause at the bottom. As you squat down, push your genoux out. You should squat between vos jambes, keeping an upright torse, with your head and poitrine up. 3. Rise back up by driving through your heels and Repetez.', 'Muscles secondaires : Mollets, Fessiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Squats_With_Two_Kettlebells/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Front Two-Dumbbell Raise', 'Épaules', 'Haltères', '1. Pick a couple of halteres and Tenez-vous debout avec a straight torse and the halteres on front of your cuisses bras tendus with the palms of the hand facing your cuisses. Position de depart. 2. While maintaining the torse stationary (no swinging), lift the halteres to the front with a slight bend on the coudes and the palms of the hands always facing down. Continue to go up until you arms are slightly above parallel to le sol. Exhale as you execute this portion of le mouvement and pause for a second at the top. 3. en inspirant, lower the halteres back down Lentement, to the position de depart. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Front_Two-Dumbbell_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Full Range-Of-Motion Lat Pulldown', 'Dos', 'Poulie', '1. Either standing or seated on a high banc, grasp two stirrup cables that are attached to the high pulleys. Grab with the opposing hand so vos bras are crisscrossed about you and your palms are facing forward. 2. Keeping your poitrine up and maintaining a slight arch in your lower back, pull the handles down as if you were doing a regular pulldown. The range of motion will be more of an arc. During le mouvement, rotate vos mains so that in the bottom position your palms face each other rather than forward. Return Lentement, to the position de depart and Repetez.', 'Muscles secondaires : Biceps, Milieu du dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Full_Range-Of-Motion_Lat_Pulldown/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Gironda Sternum Chins', 'Dos', 'Autre', '1. Grasp the pull-up bar with a epaules width prise en supination. 2. Now hang with vos bras fully extended and stick your poitrine out and lean back. Conseil : You will be leaning back throughout the entire movement. Position de depart. 3. Start pulling yourself towards the bar with your spine arched throughout le mouvement and your head leaning back as far away from the bar as possible. Exhale as you perform this portion of le mouvement. Conseil : At the upper end of le mouvement, your hips and legs will be at about a 45-degree angle to le sol. 4. Keep pulling until your collarbone passes the bar and your lower poitrine or sternum area touches it. Hold that contraction for a second. Conseil : By the time you''ve completed this portion of le mouvement; your head will be parallel to le sol. 5. Lentement, start going back to the position de depart en inspirant. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Milieu du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Gironda_Sternum_Chins/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Glute Ham Raise', 'Ischio-jambiers', 'Machine', '1. Begin by adjusting the equipment to fit votre corps. Place vos pieds against the footplate in between the rollers as you lie facedown. Your genoux should be just behind the pad. 2. Start from the bottom of le mouvement. Keep votre dos arched as you begin le mouvement by flexing the genoux. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until votre corps is upright. 3. Revenez en position de depart, keeping your descent under control.', 'Muscles secondaires : Mollets, Fessiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Glute_Ham_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Glute Kickback', 'Fessiers', 'Poids de corps', '1. Kneel on le sol or an exercise mat and bend at the waist with vos bras extended in front of you (perpendicular to the torse) in order to get into a kneeling push-up position but with the arms spaced at epaules width. Your head should be looking forward and the bend of the genoux should create a 90-degree angle between the ischio-jambiers and the mollets. Position de depart. 2. en expirant, lift up your right leg until the ischio-jambiers are in line with the back while maintaining the 90-degree angle bend. Contract the fessiers throughout this movement and hold the contraction at the top for a second. Conseil : At the end of le mouvement the upper leg should be parallel to le sol while the calf should be perpendicular to it. 3. Go back to the initial position en inspirant and now Repetez with the left leg. 4. Continue to alternate legs until all of the recommended repetitions have been performed.', 'Muscles secondaires : Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Glute_Kickback/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Goblet Squat', 'Quadriceps', 'Kettlebell', '1. Stand holding a light kettlebells by the horns close to your poitrine. Position de depart. 2. Squat down between vos jambes until your ischio-jambiers are on your mollets. Keep your poitrine and head up and votre dos straight. 3. At the bottom position, pause and use your coudes to push your genoux out. Revenez en position de depart, and Repetez for 10-20 repetitions.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Goblet_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Good Morning', 'Ischio-jambiers', 'Barre', '1. Begin with a bar on a rack at epaules height. Rack the bar across the rear of your epaules as you would a power squat, not on top of your epaules. Keep votre dos tight, omoplates pinched together, and your genoux slightly bent. Step back from the rack. 2. Begin by bending at the hips, moving them back as you bend over to near parallel. Keep votre dos arched and your cervical spine in proper alignment. 3. Reverse the motion by extending through the hips with your fessiers and ischio-jambiers. Continue until you have returned to the position de depart.', 'Muscles secondaires : Abdominaux, Fessiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Good_Morning/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Good Morning off Pins', 'Ischio-jambiers', 'Barre', '1. Begin with a bar on a rack at about the same height as your stomach. Bend over underneath the bar and rack the bar across the rear of your epaules as you would a power squat, not on top of your epaules. At the proper height, you should be near parallel to le sol when bent over. Keep votre dos tight, omoplates pinched together, and your genoux slightly bent. Keep votre dos arched and your cervical spine in proper alignment. 2. Begin the motion by extending through the hips with your fessiers and ischio-jambiers, and you are standing with the poids. Lentement, lower the poids back to the pins returning to the position de depart.', 'Muscles secondaires : Abdominaux, Fessiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Good_Morning_off_Pins/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Gorilla Chin/Crunch', 'Abdominaux', 'Poids de corps', '1. Hang from a chin-up bar using an prise en supination (palms facing you) that is slightly wider than epaules width. 2. Now bend your genoux at a 90 degree angle so that the mollets are parallel to le sol while the cuisses remain perpendicular to it. Position de depart. 3. en expirant, pull yourself up while crunching your genoux up at the same time until your genoux are at poitrine level. You will stop going up as soon as your nose is at the same level as the bar. Conseil : When you get to this point you should also be finishing the crunch at the same time. 4. Lentement, start to inhale as you Revenez en position de depart. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Gorilla_Chin_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Groin and Back Stretch', 'Adducteurs', 'Autre', '1. Sit on le sol with your genoux bent and feet together. 2. Interlock your fingers behind your head. Position de depart. 3. Curl downwards, bringing your coudes to the inside of your cuisses. Apres une pause, Revenez en position de depart with your head up and votre dos straight. Repetez for 10-20 repetitions.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Groin_and_Back_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Groiners', 'Adducteurs', 'Poids de corps', '1. Begin in a pushup position on le sol. Position de depart. 2. Using both legs, jump forward landing with vos pieds next to vos mains. Keep your head up as you do so. 3. Revenez en position de depart and immediately Repetez le mouvement, continuing for 10-20 repetitions.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Groiners/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hack Squat', 'Quadriceps', 'Machine', '1. Place the back of your torse against the back pad of the machine and hook your epaules under the epaules pads provided. 2. Position vos jambes in the platform using a epaules width medium stance with the toes slightly pointed out. Conseil : Keep your head up en permanence and also maintain the back on the pad en permanence. 3. Place vos bras on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position). 4. Now straighten vos jambes without locking the genoux. Position de depart. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section). 5. Begin to Lentement, lower the unit by bending the genoux as you maintain a straight posture with the head up (back on the pad en permanence). Continue down until the angle between the upper leg and the mollets becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to le sol). Inhale as you perform this portion of le mouvement. Conseil : If you performed the exercise correctly, the front of the genoux should make an imaginary straight line with the toes that is perpendicular to the front. If your genoux are past that imaginary line (if they are past your toes) then you are placing undue stress on the genoux and the exercise has been performed incorrectly. 6. Begin to raise the unit en expirant by pushing le sol with mainly with the heel of your foot as you straighten the legs again and go back to the position de depart. 7. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hack_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hammer Curls', 'Biceps', 'Haltères', '1. Tenez-vous debout avec your torse upright and a halteres on each hand being held bras tendus. The coudes should be close to the torse. 2. The palms of the hands should be facing your torse. Position de depart. 3. Now, while holding your upper arm stationary, exhale and curl the poids forward while contracting the biceps. Continue to raise the poids until the biceps are entierement contracte and the halteres is at epaules level. Hold the contracted position for a brief moment as you squeeze the biceps. Conseil : Focus on keeping the coudes stationary and only moving your forearm. 4. After the brief pause, inhale and Lentement, begin the lower the halteres back down to the position de depart. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hammer_Curls/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hammer Grip Incline DB Bench Press', 'Pectoraux', 'Haltères', '1. Allongez-vous au sol on an incline banc with a halteres on each hand on top of your cuisses. The palms of your hand will be facing each other. 2. By using your cuisses to help you get the halteres up, clean the halteres one arm at a time so that you can hold them at epaules width. 3. Once at epaules width, keep the palms of vos mains with a neutral grip (palms facing each other). Keep your coudes flared out with the upper arms in line with the epaules (perpendicular to the torse) and the coudes bent creating a 90-degree angle between the upper arm and the forearm. Position de depart. 4. Now bring down the poids Lentement, to your side as you Inspirez. Keep full control of the halteres en permanence. 5. As you Expirez, push the halteres up using your pectoral muscles. Lock vos bras in the contracted position, Maintenez 1 seconde and then start coming down slowly. Conseil : It should take at least twice as long to go down than to come up. 6. Repetez le mouvement for the prescribed amount of repetitions. 7. When you are done, place the halteres back in your cuisses and then on le sol. This is the safest manner to dispose of the halteres.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hammer_Grip_Incline_DB_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hamstring-SMR', 'Ischio-jambiers', 'Foam roller', '1. In a seated position, extend vos jambes over a foam roll so that it is position on the back of the upper legs. Place vos mains to the side or behind you to help support your poids. Position de depart. 2. Using vos mains, lift your hips off of le sol and shift your poids on the foam roll to one leg. Relax the ischio-jambiers of the leg you are stretching. 3. Roll over the foam from below the hip to above the back of the genoux, pausing at points of tension for 10-30 seconds. Repetez de l autre cote.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hamstring-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hamstring Stretch', 'Ischio-jambiers', 'Autre', '1. Allongez-vous au sol with one leg extended above you, with the hip at ninety degrees. Keep the other leg flat on le sol. 2. Loop a belt, band, or rope over the ball of your foot. Position de depart. 3. Pull on the belt to create tension in the mollets and ischio-jambiers. Hold this stretch for 10-30 seconds, and Repetez with the other leg.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hamstring_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Handstand Push-Ups', 'Épaules', 'Poids de corps', '1. With votre dos to the wall bend at the waist and place both hands on le sol at epaules width. 2. Kick yourself up against the wall with vos bras straight. votre corps should be upside down with the arms and legs fully extended. Keep your whole body as straight as possible. Conseil : If doing this for the first time, have a spotter help you. Also, make sure that you keep facing the wall with your head, rather than looking down. 3. Lentement, lower yourself to the ground en inspirant until your head almost touches le sol. Conseil : It is of utmost importance that you come down slow in order to avoid head injury. 4. Push yourself back up Lentement, en expirant until your coudes are nearly locked. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Handstand_Push-Ups/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hang Clean', 'Quadriceps', 'Barre', '1. Begin with a epaules width, double overhand or hook grip, with the bar hanging at the mid cuisses position. votre dos should be straight and inclined slightly forward. 2. Begin by aggressively extending through the hips, genoux and ankles, driving the poids upward. As you do so, shrug your epaules towards your ears. 3. Immediately recover by driving through the heels, keeping the torse upright and coudes up. Continue until you have risen to a standing position.', 'Muscles secondaires : Mollets, Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Épaules, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hang Clean - Below the Knees', 'Quadriceps', 'Barre', '1. Begin with a epaules width, double overhand or hook grip, with the bar hanging just below the genoux. votre dos should be straight and inclined slightly forward. 2. Begin by aggressively extending through the hips, genoux and ankles, driving the poids upward. As you do so, shrug your epaules towards your ears. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the coudes up and out. 3. At peak extension, aggressively pull yourself down, rotating your coudes under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted epaules, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery. 4. Immediately recover by driving through the heels, keeping the torse upright and coudes up. Continue until you have risen to a standing position.', 'Muscles secondaires : Mollets, Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Épaules, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Clean_-_Below_the_Knees/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hang Snatch', 'Ischio-jambiers', 'Barre', '1. Begin with a prise large on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your genoux should be slightly bent, and the torse inclined forward. The spine should be fully extended and the head facing forward. The bar should be at the hips. Position de depart. 2. Aggressively extend through the legs and hips. At peak extension, shrug the epaules and allow the coudes to flex to the side. 3. As you move vos pieds into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with votre corps as low as possible and the arms fully extended overhead. 4. Return to a standing position with the poids overhead. Follow by returning the poids to the ground under control.', 'Muscles secondaires : Abdominaux, Mollets, Avant-bras, Fessiers, Bas du dos, Quadriceps, Épaules, Trapèzes. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Snatch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hang Snatch - Below Knees', 'Ischio-jambiers', 'Barre', '1. Begin with a prise large on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your genoux should be slightly bent, and the torse inclined forward. The spine should be fully extended and the head facing forward. The bar should be just below the genoux. Position de depart. 2. Aggressively extend through the legs and hips. At peak extension, shrug the epaules and allow the coudes to flex to the side. 3. As you move vos pieds into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with votre corps as low as possible and the arms fully extended overhead. 4. Return to a standing position with the poids overhead, and then return the poids to le sol under control.', 'Muscles secondaires : Abdominaux, Mollets, Avant-bras, Fessiers, Bas du dos, Quadriceps, Épaules, Trapèzes. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hang_Snatch_-_Below_Knees/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hanging Bar Good Morning', 'Ischio-jambiers', 'Barre', '1. Begin with a bar on a rack at about the same height as your stomach. Suspend the bar using chains or suspension straps. 2. Bend over underneath the bar and rack the bar across the rear of your epaules as you would a power squat, not on top of your traps. At the proper height, you should be near parallel to le sol when bent over. Keep votre dos tight, omoplates pinched together, and your genoux slightly bent. Keep votre dos arched and your cervical spine in proper alignment. 3. Begin the motion by extending through the hips with your fessiers and ischio-jambiers, and you are standing with the poids. 4. Lentement, lower the poids back to the position de depart, where it is supported by the chains.', 'Muscles secondaires : Abdominaux, Fessiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Bar_Good_Morning/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hanging Leg Raise', 'Abdominaux', 'Poids de corps', '1. Hang from a chin-up bar with both arms extended bras tendus in top of you using either a prise large or a prise moyenne. The legs should be straight down with the pelvis rolled slightly backwards. Position de depart. 2. Raise vos jambes until the torse makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so. 3. Go back Lentement, to the position de depart as you Inspirez. 4. Repetez selon le nombre souhaite.', 'Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Leg_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hanging Pike', 'Abdominaux', 'Poids de corps', '1. Hang from a chin-up bar with vos jambes and feet together using an prise en pronation (palms facing away from you) that is slightly wider than epaules width. Conseil : You may use poignets wraps in order to facilitate holding on to the bar. 2. Now bend your genoux at a 90 degree angle and bring the upper legs forward so that the mollets are perpendicular to le sol while the cuisses remain parallel to it. Position de depart. 3. Pull vos jambes up en expirant until you almost touch your shins with the bar above you. Conseil : Try to straighten vos jambes as much as possible while at the top. 4. Lower vos jambes as Lentement, as possible until you reach the position de depart. Conseil : Avoid swinging and using momentum en permanence. 5. Repetez selon le nombre souhaite.', 'Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hanging_Pike/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Heaving Snatch Balance', 'Quadriceps', 'Barre', '1. This drill helps you learn the snatch. Begin by holding a light poids across the back of the epaules. vos pieds should be slightly wider than hip width apart with the feet turned out, the same position that you would perform a squat with. 2. Begin by dipping with the genoux slightly, and popping back up to briefly unload the bar. Drive yourself underneath the bar, elevating it overhead as you descend into a full squat. 3. Return to a standing position.', 'Muscles secondaires : Abdominaux, Avant-bras, Fessiers, Ischio-jambiers, Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Heaving_Snatch_Balance/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Heavy Bag Thrust', 'Pectoraux', 'Autre', '1. Utilize a heavy bag for this exercise. Assume an upright stance next to the bag, with vos pieds staggered, fairly wide apart. Place your hand on the bag at about poitrine height. Position de depart. 2. Begin by twisting at the waist, pushing the bag forward as hard as possible. Perform this move quickly, pushing the bag away from votre corps. 3. Receive the bag as it swings back by reversing these steps.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Heavy_Bag_Thrust/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('High Cable Curls', 'Biceps', 'Poulie', '1. Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to le sol with the palms of vos mains facing you. Position de depart. 2. Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Maintenez 1 seconde in the contracted position as you squeeze the biceps. 3. Lentement, bring back the arms to the position de depart. 4. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/High_Cable_Curls/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hip Circles (prone)', 'Abducteurs', 'Poids de corps', '1. Position yourself on vos mains and genoux on the ground. Maintaining good posture, raise one bent genoux off of the ground. Position de depart. 2. Keeping the genoux in a bent position, rotate the femur in an arc, attempting to make a big circle with your genoux. 3. Perform this Lentement, for a number of repetitions, and Repetez de l autre cote.', 'Muscles secondaires : Adducteurs. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hip_Circles_prone/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hip Extension with Bands', 'Fessiers', 'Élastique', '1. Secure one end of the band to the lower portion of a post and attach the other to one ankle. 2. Facing the attachment point of the band, hold on to the column to stabilize yourself. 3. Keeping your head and your poitrine up, move the resisted leg back as far as you can while keeping the genoux straight. 4. Return the leg to the position de depart.', 'Muscles secondaires : Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hip_Extension_with_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hip Flexion with Band', 'Quadriceps', 'Élastique', '1. Secure one end of the band to the lower portion of a post and attach the other to one ankle. 2. Face away from the attachment point of the band. 3. Keeping your head and your poitrine up, raise your genoux up to 90 degrees and pause. 4. Return the leg to the position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hip_Flexion_with_Band/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hip Lift with Band', 'Fessiers', 'Élastique', '1. After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn''t have pegs, the band can be secured using heavy halteres or similar objects, just ensure they won''t move. 2. Adjust your position so that the band is directly over your hips. Bend your genoux and place vos pieds flat on le sol. vos mains can be on le sol or holding the band in position. 3. Keeping your epaules on the ground, drive through your heels to raise your hips, pushing into the band as high as you can. 4. Pause at the top of the motion, and Revenez en position de depart.', 'Muscles secondaires : Mollets, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hip_Lift_with_Band/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hug A Ball', 'Bas du dos', 'Swiss ball', '1. Seat yourself on le sol. 2. Straddle an exercise ball between both legs and lower your hips down toward le sol. 3. Hug vos bras around the ball to support votre corps. Adjust vos jambes so that vos pieds are flat on le sol and your genoux line up over your ankles. Keep a good grip on the ball so it doesn''t roll away from you and send you back onto your buttocks.', 'Muscles secondaires : Mollets, Fessiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hug_A_Ball/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hug Knees To Chest', 'Bas du dos', 'Autre', '1. Allongez-vous au sol and pull both genoux up to your poitrine. 2. Hold vos bras under the genoux, not over (that would put to much pressure on your genoux joints). 3. Lentement, pull the genoux toward your epaules. This also stretches your buttocks muscles.', 'Muscles secondaires : Fessiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hug_Knees_To_Chest/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hurdle Hops', 'Ischio-jambiers', 'Autre', '1. Set up a row of hurdles or other small barriers, placing them a few feet apart. 2. Stand in front of the first hurdle with vos pieds epaules width apart. Position de depart. 3. Begin by jumping with both feet over the first hurdle, swinging both arms as you jump. 4. Absorb the impact of landing by bending the genoux, rebounding out of the first leap by jumping over the next hurdle. Continue until you have jumped over all of the hurdles.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hurdle_Hops/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hyperextensions (Back Extensions)', 'Bas du dos', 'Autre', '1. Lie face down on a hyperextension banc, tucking your ankles securely under the footpads. 2. Adjust the upper pad if possible so your upper cuisses lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction. 3. With votre corps straight, cross vos bras in front of you (my preference) or behind your head. Position de depart. Conseil : You can also hold a poids plate for extra resistance in front of you under your crossed arms. 4. Start bending forward Lentement, at the waist as far as you can while keeping votre dos flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the ischio-jambiers and you can no longer keep going without a rounding of the back. Conseil : Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as votre corps allows you to without rounding the back. 5. Lentement, raise your torse back to the initial position en inspirant. Conseil : Avoid the temptation to arch votre dos past a straight line. Also, do not swing the torse at any time in order to protect the back from injury. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hyperextensions_Back_Extensions/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Hyperextensions With No Hyperextension Bench', 'Bas du dos', 'Poids de corps', '1. With someone holding down vos jambes, slide yourself down to the edge a flat banc until your hips hang off the end of the banc. Conseil : Your entire upper body should be hanging down towards le sol. Also, you will be in the same position as if you were on a hyperextension banc but the range of motion will be shorter due to the height of the flat banc vs. that of the hyperextension banc. 2. With votre corps straight, cross vos bras in front of you (my preference) or behind your head. Position de depart. Conseil : You can also hold a poids plate for extra resistance in front of you under your crossed arms. 3. Start bending forward Lentement, at the waist as far as you can while keeping votre dos flat. Inhale as you perform this movement. Keep moving forward until you almost touch le sol or you feel a nice stretch on the ischio-jambiers (whichever comes first). Conseil : Never round the back as you perform this exercise. 4. Lentement, raise your torse back to the initial position en expirant. Conseil : Avoid the temptation to arch votre dos past a straight line. Also, do not swing the torse at any time in order to protect the back from injury. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hyperextensions_With_No_Hyperextension_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('IT Band and Glute Stretch', 'Abducteurs', 'Autre', '1. Loop a belt, rope, or band around one of vos pieds, and swing that leg across votre corps to the opposite side, keeping the leg extended as you lay on the ground. Position de depart. 2. Keeping your foot off of le sol, pull on the belt, using the tension to pull the toes up. Hold for 10-20 seconds, and Repetez de l autre cote.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/IT_Band_and_Glute_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Iliotibial Tract-SMR', 'Abducteurs', 'Foam roller', '1. Lay on your side, with the bottom leg placed onto a foam roller between the hip and the genoux. The other leg can be crossed in front of you. 2. Place as much of your poids as is tolerable onto your bottom leg; there is no need to keep your bottom leg in contact with the ground. Be sure to relax the muscles of the leg you are stretching. 3. Roll your leg over the foam from you hip to your genoux, pausing for 10-30 seconds at points of tension. Repetez with the opposite leg.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Iliotibial_Tract-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Inchworm', 'Ischio-jambiers', 'Poids de corps', '1. Tenez-vous debout avec vos pieds close together. Keeping vos jambes straight, stretch down and put vos mains on le sol directly in front of you. Position de depart. 2. Begin by walking vos mains forward slowly, alternating your left and your right. As you do so, bend only at the hip, keeping vos jambes straight. 3. Keep going until votre corps is parallel to the ground in a pushup position. 4. Now, keep vos mains in place and Lentement, take short steps with vos pieds, moving only a few inches at a time. 5. Continue walking until vos pieds are by hour hands, keeping vos jambes straight as you do so.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Inchworm/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Incline Barbell Triceps Extension', 'Triceps', 'Barre', '1. Hold a barre with an prise en pronation (palms down) that is a little closer together than epaules width. 2. Allongez-vous au sol on an incline banc set at any angle between 45-75-degrees. 3. Bring the bar overhead with vos bras extended and coudes in. The arms should be in line with the torse above the head. Position de depart. 4. Now lower the bar in a semicircular motion behind your head until your forearms touch your biceps. Inhale as you perform this movement. Conseil : Keep your upper arms stationary and close to your head en permanence. Only the forearms should move. 5. Revenez en position de depart as you Expirez and you contract the triceps. Hold the contraction for a second. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Barbell_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Incline Bench Pull', 'Milieu du dos', 'Barre', '1. Grab a halteres in each hand and lie face down on an incline banc that is set to an incline that is approximately 30 degrees. 2. Let the arms hang to your sides fully extended as they point to le sol. 3. Turn the poignets until vos mains have a pronated (palms down) grip. 4. Now flare the coudes out. Position de depart. 5. As you Expirez, start to pull the halteres up as if you are doing a reverse banc press. You will do this by bending at the coudes and bringing the upper arms up as you let the forearms hang. Continue this motion until the upper arms are at the same level as votre dos. Conseil : The coudes will come out to the side and your upper arms and torse should make the letter "T" at the top of le mouvement. Hold the contraction at the top for a second. 6. Lentement, go back down to the position de depart as you Inspirez. 7. Repetez selon le nombre souhaite.', 'Muscles secondaires : Dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Bench_Pull/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Incline Cable Chest Press', 'Pectoraux', 'Poulie', '1. Adjust the poids to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and poitrine up. The coudes should be bent to about 90 degrees. Position de depart. 2. Begin by extending through the coudes, pressing the handles together straight in front of you. Keep your omoplates retracted as you execute le mouvement. 3. After pausing at full extension, Revenez en position de depart, keeping tension on the cables.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Cable_Chest_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Incline Cable Flye', 'Pectoraux', 'Poulie', '1. To get yourself into the position de depart, set the pulleys at le sol level (lowest level possible on the machine that is below your torse). 2. Place an incline banc (set at 45 degrees) in between the pulleys, select a poids on each one and grab a pulley on each hand. 3. With a handle on each hand, Allongez-vous sur un banc incline and bring vos mains together bras tendus in front of your face. Position de depart. 4. With a slight bend of your coudes (in order to prevent stress at the biceps tendon), lower vos bras out at both sides in a wide arc until you feel a stretch on your poitrine. Inspirez as you perform this portion of le mouvement. Conseil : Keep in mind that throughout le mouvement, the arms should remain stationary. le mouvement should only occur at the epaules joint. 5. Return vos bras back to the position de depart as you squeeze your poitrine muscles and exhale. Maintenez 1 seconde. Conseil : Make sure to use the same arc of motion used to lower the poids. 6. Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Cable_Flye/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Incline Dumbbell Bench With Palms Facing In', 'Pectoraux', 'Haltères', '1. Allongez-vous au sol on an incline banc with a halteres on each hand on top of your cuisses. The palms of your hand will be facing each other. 2. By using your cuisses to help you get the halteres up, clean the halteres one arm at a time so that you can hold them at epaules width. 3. Once at epaules width, keep the palms of vos mains with a neutral grip (palms facing each other). Keep your coudes flared out with the upper arms in line with the epaules (perpendicular to the torse) and the coudes bent creating a 90-degree angle between the upper arm and the forearm. Position de depart. 4. Now bring down the poids Lentement, to your side as you Inspirez. Keep full control of the halteres en permanence. 5. As you Expirez, push the halteres up using your pectoral muscles. Lock vos bras in the contracted position, Maintenez 1 seconde and then start coming down slowly. Conseil : It should take at least twice as long to go down than to come up. 6. Repetez le mouvement for the prescribed amount of repetitions. 7. When you are done, place the halteres back in your cuisses and then on le sol. This is the safest manner to dispose of the halteres.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Bench_With_Palms_Facing_In/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Incline Dumbbell Curl', 'Biceps', 'Haltères', '1. Sit back on an incline banc with a halteres in each hand held bras tendus. Keep your coudes close to your torse and rotate the palms of vos mains until they are facing forward. Position de depart. 2. While holding the upper arm stationary, curl the poids forward while contracting the biceps as you Expirez. Only the forearms should move. Continue le mouvement until your biceps are entierement contracte and the halteres are at epaules level. Maintenez 1 seconde. 3. Lentement, begin to bring the halteres back to position de depart as your Inspirez. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Incline Dumbbell Flyes', 'Pectoraux', 'Haltères', '1. Hold a halteres on each hand and lie on an incline banc that is set to an incline angle of no more than 30 degrees. 2. Extend vos bras above you with a slight bend at the coudes. 3. Now rotate the poignets so that the palms of vos mains are facing you. Conseil : The pinky fingers should be next to each other. Position de depart. 4. As you Inspirez, start to Lentement, lower the arms to the side while keeping the arms extended and while rotating the poignets until the palms of the hand are facing each other. Conseil : At the end of le mouvement the arms will be by your side with the palms facing the ceiling. 5. en expirant start to bring the halteres back up to the position de depart by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Conseil : Keep in mind that le mouvement will only happen at the epaules joint and at the poignets. There is no motion that happens at the coudes joint. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Flyes/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Incline Dumbbell Flyes - With A Twist', 'Pectoraux', 'Haltères', '1. Hold a halteres in each hand and lie on an incline banc that is set to an incline angle of no more than 30 degrees. 2. Extend vos bras above you with a slight bend at the coudes. 3. Now rotate the poignets so that the palms of vos mains are facing you. Conseil : The pinky fingers should be next to each other. Position de depart. 4. As you Inspirez, start to Lentement, lower the arms to the side while keeping the arms extended and while rotating the poignets until the palms of the hand are facing each other. Conseil : At the end of le mouvement the arms will be by your side with the palms facing the ceiling. 5. en expirant start to bring the halteres back up to the position de depart by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Conseil : Keep in mind that le mouvement will only happen at the epaules joint and at the poignets. There is no motion that happens at the coudes joint. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Flyes_-_With_A_Twist/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Incline Dumbbell Press', 'Pectoraux', 'Haltères', '1. Allongez-vous au sol on an incline banc with a halteres in each hand atop your cuisses. The palms of vos mains will be facing each other. 2. Then, using your cuisses to help push the halteres up, lift the halteres one at a time so that you can hold them at epaules width. 3. Once you have the halteres raised to epaules width, rotate your poignets forward so that the palms of vos mains are facing away from you. Position de depart. 4. Be sure to keep full control of the halteres en permanence. Then Expirez and push the halteres up with your poitrine. 5. Lock vos bras at the top, Maintenez 1 seconde, and then start Lentement, lowering the poids. Tip Ideally, lowering the poids should take about twice as long as raising them. 6. Repetez le mouvement for the prescribed amount of repetitions. 7. When you are done, place the halteres back on your cuisses and then on le sol. This is the safest manner to release the halteres.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Dumbbell_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Incline Hammer Curls', 'Biceps', 'Haltères', '1. Seat yourself on an incline banc with a halteres in each hand. You should pressed firmly against he back with vos pieds together. Allow the halteres to hang straight down at your side, holding them with a neutral grip. Position de depart. 2. Initiate le mouvement by flexing at the coudes, attempting to keep the upper arm stationary. 3. Continue to the top of le mouvement and pause, then Lentement, return to the start position.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Hammer_Curls/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Incline Inner Biceps Curl', 'Biceps', 'Haltères', '1. Hold a halteres in each hand and Allongez-vous au sol on an incline banc. 2. The halteres should be at arm''s length hanging at your sides and your palms should be facing out. Position de depart. 3. Now en expirant curl the poids outward and up while keeping your forearms in line with your side deltoids. Continue the curl until the halteres are at epaules height and to the sides of your deltoids. Conseil : The end of le mouvement should look similar to a double biceps pose. 4. After a second contraction at the top of le mouvement, start to inhale and Lentement, lower the poids back to the position de depart using the same path used to bring them up. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Inner_Biceps_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Incline Push-Up', 'Pectoraux', 'Poids de corps', '1. Stand facing banc or sturdy elevated platform. Place hands on edge of banc or platform, slightly wider than epaules width. 2. Position forefoot back from banc or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower poitrine to edge of box or platform by bending arms. 3. Push body up until arms are extended. Repetez.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Incline Push-Up Close-Grip', 'Triceps', 'Poids de corps', '1. Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. 2. Place vos mains next to one another on the bar. 3. Position vos pieds back from the bar with arms and body straight. Position de depart. 4. Keeping votre corps straight, lower your poitrine to the bar by bending the arms. 5. Revenez en position de depart by extending the coudes, pressing yourself back up.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up_Close-Grip/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Incline Push-Up Depth Jump', 'Pectoraux', 'Autre', '1. For this drill you will need a box about 12 inches high, and two thick mats or aerobics steps. 2. Place the steps just outside of your epaules, and place vos pieds on top of the box so that you are in an incline pushup position, vos mains just inside the steps. Position de depart. 3. Begin by bending at the coudes to lower votre corps, quickly reversing position to push votre corps off of the ground. As you leave the ground, move vos mains onto the steps, bending your coudes to absorb the impact. 4. Repetez the motion to Revenez en position de depart.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up_Depth_Jump/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Incline Push-Up Medium', 'Pectoraux', 'Poids de corps', '1. Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. 2. Place vos mains on the bar, with vos mains about epaules width apart. 3. Position vos pieds back from the bar with arms and body straight. Position de depart. 4. Keeping votre corps straight, lower your poitrine to the bar by bending the arms. 5. Revenez en position de depart by extending the coudes, pressing yourself back up.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up_Medium/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Incline Push-Up Reverse Grip', 'Pectoraux', 'Poids de corps', '1. Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. 2. Place vos mains on the bar palms up, with vos mains about epaules width apart. 3. Position vos pieds back from the bar with arms and body straight. Position de depart. 4. Keeping votre corps straight, lower your poitrine to the bar by bending the arms. 5. Revenez en position de depart by extending the coudes, pressing yourself back up.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up_Reverse_Grip/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Incline Push-Up Wide', 'Pectoraux', 'Poids de corps', '1. Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. 2. Place vos mains on the bar, with vos mains wider than epaules width. 3. Position vos pieds back from the bar with arms and body straight. vos bras should be perpendicular to the body. Position de depart. 4. Keeping votre corps straight, lower your poitrine to the bar by bending the arms. 5. Revenez en position de depart by extending the coudes, pressing yourself back up.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Incline_Push-Up_Wide/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Intermediate Groin Stretch', 'Ischio-jambiers', 'Autre', '1. Allongez-vous au sol with vos jambes extended. Loop a belt, rope, or band around one of vos pieds, and swing that leg as far to the side as you can. Position de depart. 2. Pull gently on the belt to create tension in your groin and ischio-jambiers muscles. Hold for 10-20 seconds, and Repetez de l autre cote.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Intermediate_Groin_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Intermediate Hip Flexor and Quad Stretch', 'Quadriceps', 'Autre', '1. Lie face down on le sol, with a rope, belt, or band looped around one foot. 2. Flex the genoux and extend the hip of the leg to be stretched, using both hands to pull on the belt. Your genoux and your hip should come off of le sol, creating tension in the hip flexors and quadriceps. Hold the stretch for 10-20 seconds, and Repetez de l autre cote.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Intermediate_Hip_Flexor_and_Quad_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Internal Rotation with Band', 'Épaules', 'Élastique', '1. Choke the band around a post. The band should be at the same height as your coudes. Tenez-vous debout avec your right side to the band a couple of feet away. 2. Grasp the end of the band with your right hand, and keep your coudes pressed firmly to your side. We recommend you hold a pad or foam roll in place with your coudes to keep it firmly in position. 3. With your upper arm in position, your coudes should be flexed to 90 degrees with your hand reaching away from your torse. Position de depart. 4. Execute le mouvement by rotating your arm in a forehand motion, keeping your coudes in place. 5. Continue as far as you are able, pause, and then Revenez en position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Internal_Rotation_with_Band/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Inverted Row', 'Milieu du dos', 'Autre', '1. Position a bar in a rack to about waist height. You can also use a smith machine. 2. Take a wider than epaules width grip on the bar and position yourself hanging underneath the bar. votre corps should be straight with your heels on the ground with vos bras fully extended. Position de depart. 3. Begin by flexing the coudes, pulling your poitrine towards the bar. Retract your omoplates as you perform le mouvement. 4. Pause at the top of the motion, and return yourself to the start position. 5. Repetez for the desired number of repetitions.', 'Muscles secondaires : Dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Inverted_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Inverted Row with Straps', 'Milieu du dos', 'Autre', '1. Hang a rope or suspension straps from a rack or other stable object. Grasp the ends and position yourself in a supine position hanging from the ropes. votre corps should be straight with your heels on the ground with vos bras fully extended. Position de depart. 2. Begin by flexing the coudes, pulling your poitrine to vos mains. Retract your omoplates as you perform le mouvement. 3. Pause at the top of the motion, and return yourself to the start position. 4. Repetez for the desired number of repetitions.', 'Muscles secondaires : Biceps, Dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Inverted_Row_with_Straps/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Iron Cross', 'Épaules', 'Haltères', '', 'Muscles secondaires : Pectoraux, Fessiers, Ischio-jambiers, Bas du dos, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Iron_Cross/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Iron Crosses (stretch)', 'Quadriceps', 'Autre', '1. Lie face down on le sol, with vos bras extended out to your side, palms pressed to le sol. Position de depart. 2. To begin, flex one genoux and bring that leg across the back of votre corps, attempting to touch it to the ground near the opposite hand. 3. Promptly return the leg to the starting postion, and quickly Repetez with the other leg. Continue alternating for 10-20 repetitions.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Iron_Crosses_stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Isometric Chest Squeezes', 'Pectoraux', 'Poids de corps', '1. While either seating or standing, bend vos bras at a 90-degree angle and place the palms of vos mains together in front of your poitrine. Conseil : vos mains should be open with the palms together and fingers facing forward (perpendicular to your torse). 2. Push both hands against each other as you contract your poitrine. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction. 3. Hold for the recommended number of seconds. 4. Now release the tension slowly. 5. Rest for the recommended amount of time and Repetez.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Isometric_Chest_Squeezes/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Isometric Neck Exercise - Front And Back', 'Cou', 'Poids de corps', '1. With your head and neck in a neutral position (normal position with head erect facing forward), place both of vos mains on the front side of your head. 2. Now gently push forward as you contract the neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction. 3. Hold for the recommended number of seconds. 4. Now release the tension slowly. 5. Rest for the recommended amount of time and Repetez with vos mains placed on the back side of your head.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Isometric_Neck_Exercise_-_Front_And_Back/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Isometric Neck Exercise - Sides', 'Cou', 'Poids de corps', '1. With your head and neck in a neutral position (normal position with head erect facing forward), place your left hand on the left side of your head. 2. Now gently push towards the left as you contract the left neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction. 3. Hold for the recommended number of seconds. 4. Now release the tension slowly. 5. Rest for the recommended amount of time and Repetez with your right hand placed on the right side of your head.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Isometric_Neck_Exercise_-_Sides/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Isometric Wipers', 'Pectoraux', 'Poids de corps', '1. Assume a push-up position, supporting your poids on vos mains and toes while keeping votre corps straight. vos mains should be just outside of epaules width. Position de depart. 2. Begin by shifting votre corps poids as far to one side as possible, allowing the coudes on that side to flex as you lower votre corps. 3. Reverse the motion by extending the flexed arm, pushing yourself up and then dropping to the other side. 4. Repetez for the desired number of repetitions.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Isometric_Wipers/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('JM Press', 'Triceps', 'Barre', '1. Start the exercise the same way you would a close grip banc press. You will Allongez-vous sur un banc plat while holding a barre bras tendus (fully extended) with the coudes in. However, instead of having the arms perpendicular to the torse, make sure the bar is set in a direct line above the upper poitrine. Position de depart. 2. Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards vos jambes until they are perpendicular to the torse. Conseil : Keep the bend at the coudes constant as you bring the upper arms forward. 3. en expirant, press the bar back up by using the triceps to perform a close grip banc press. 4. Now go back to the position de depart and start over. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/JM_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Jackknife Sit-Up', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol (or exercise mat) on votre dos with vos bras extended straight back behind your head and vos jambes extended also. Position de depart. 2. en expirant, bend at the waist while simultaneously raising vos jambes and arms to meet in a jackknife position. Conseil : The legs should be extended and lifted at approximately a 35-45 degree angle from le sol and the arms should be extended and parallel to vos jambes. The upper torse should be off le sol. 3. While inhaling, lower vos bras and legs back to the position de depart. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jackknife_Sit-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Janda Sit-Up', 'Abdominaux', 'Poids de corps', '1. Position votre corps on le sol in the basic sit-up position; genoux to a ninety degree angle with feet flat on le sol and arms either crossed over your poitrine or to the sides. Position de depart. 2. As you strongly tighten your fessiers and ischio-jambiers, fill your lungs with air and in a slow (three to six second count) ascent, Lentement, exhale. Conseil : It is important to tighten the fessiers and ischio-jambiers as this will cause the hip flexors to be inactivated in a process called reciprocal inhibition, which basically means that opposite muscles to the contracted ones will relax. 3. en inspirant, Lentement, go back in a controlled manner to the position de depart. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Janda_Sit-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Jefferson Squats', 'Quadriceps', 'Barre', '1. Place a barre on le sol. 2. Stand in the middle of the bar length wise. 3. Bend down by bending at the genoux and keeping votre dos straight and grasp the front of the bar with your right hand. Your palm should be in (neutral grip) facing the left side. 4. Grasp the rear of the bar with your left hand. The palm of your hand should be in neutral grip alignment (palms facing the right side). Conseil : Ensure that your grip is even on the bar. Your torse should be positioned right in the middle of the bar and the distance between your torse and your right hand (which should be at the front) should be the same as the distance between your torse and your left hand (which should be to votre dos). 5. Now stand straight up with the poids. Conseil : vos pieds should be epaules width apart and your toes slightly pointed out. 6. Squat down by bending at the genoux and keeping votre dos straight until your upper cuisses are parallel with le sol. Conseil : Keep votre dos as vertical as possible with le sol and your head up. Also remember to not let your genoux go past your toes. Inhale during this portion of le mouvement. 7. Now drive yourself back up to the position de depart by pushing with the feet . Conseil : Keep the bar hanging at arm''s length and your coudes locked with a slight bend. The arms only serve as hooks. Avoid doing any lifting with them. Do the lifting with your cuisses; not vos bras.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jefferson_Squats/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Jerk Balance', 'Épaules', 'Barre', '1. This drill helps you learn to drive yourself low enough during the jerk and corrects those who move backward during le mouvement. Begin with the bar racked in the jerk position, with the epaules forward, torse upright, and the feet split slightly apart. 2. Initiate le mouvement as you would a normal jerk, dipping at the genoux while keeping your torse vertical, and driving back up forcefully, using momentum and not vos bras to elevate the poids. 3. Keep the rear foot in place, using it to drive votre corps forward into a full split as you jerk the poids. Recover by standing up with the poids overhead.', 'Muscles secondaires : Fessiers, Ischio-jambiers, Quadriceps, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jerk_Balance/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Jerk Dip Squat', 'Quadriceps', 'Barre', '1. This movement strengthens the dip portion of the jerk. Begin with the bar racked in the jerk position, with the epaules forward to create a shelf and the bar lightly contacting the throat. The feet should be directly under the hips, with the feet turned out as is comfortable. 2. Keeping the torse vertical, dip by flexing the genoux, allowing them to travel forward and without moving the hips to the rear. The dip should not be excessive. Return the poids to the position de depart by driving forcefully though the feet.', 'Muscles secondaires : Abdominaux, Mollets. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jerk_Dip_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Jogging, Treadmill', 'Quadriceps', 'Machine', '1. To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and poids to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout. 2. Treadmills offer convenience, cardiovascular benefits, and usually have less impact than jogging outside. A 150 lb person will burn almost 250 calories jogging for 30 minutes, compared to more than 450 calories running. Maintain proper posture as you jog, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.', 'Muscles secondaires : Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Jogging_Treadmill/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Keg Load', 'Bas du dos', 'Autre', '1. To load kegs, place the desired number a distance from the loading platform, typically 30-50 feet. 2. Begin by grabbing the close handle of the first keg, tilting it onto its side to grab the opposite edge of the bottom of the keg. Lift the keg up to your poitrine. 3. The higher you can place the keg, the faster you should be able to move to the platform. Shouldering is usually not allowed. Be sure to keep a firm hold on the keg. Move as quickly as possible to the platform, and load it, extending through your hips, genoux, and ankles to get it as high as possible. 4. Revenez en position de depart to retrieve the next keg, and Repetez until the event is completed.', 'Muscles secondaires : Abdominaux, Biceps, Mollets, Avant-bras, Fessiers, Ischio-jambiers, Milieu du dos, Quadriceps, Épaules, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Keg_Load/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kettlebell Arnold Press', 'Épaules', 'Kettlebell', '1. Clean a kettlebells to your epaules. Clean the kettlebells to your epaules by extending through the legs and hips as you raise the kettlebells towards your epaules. The palm should be facing inward. 2. Looking straight ahead, press the kettlebells out and overhead, rotating your poignets so that your palm faces forward at the top of the motion. 3. Return the kettlebells to the position de depart, with the palm facing in.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Arnold_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kettlebell Dead Clean', 'Ischio-jambiers', 'Kettlebell', '1. Place kettlebells between vos pieds. To get in the position de depart, push your butt back and look straight ahead. 2. Clean the kettlebells to your epaules. Clean the kettlebells to your epaules by extending through the legs and hips as you raise the kettlebells towards your epaules. The poignets should rotate as you do so. 3. Lower the kettlebells, keeping the ischio-jambiers loaded by keeping votre dos straight and your butt out.', 'Muscles secondaires : Mollets, Fessiers, Bas du dos, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Dead_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kettlebell Figure 8', 'Abdominaux', 'Kettlebell', '1. Place one kettlebells between vos jambes and take a wider than epaules width stance. Bend over by pushing your butt out and keeping votre dos flat. 2. Pick up a kettlebells and pass it to your other hand between vos jambes. The receiving hand should reach from behind the legs. Go back and forth for several repetitions.', 'Muscles secondaires : Ischio-jambiers, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Figure_8/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kettlebell Hang Clean', 'Ischio-jambiers', 'Kettlebell', '1. Place kettlebells between vos pieds. To get in the position de depart, push your butt back and look straight ahead. 2. Clean kettlebells to your epaules. Clean the kettlebells to your epaules by extending through the legs and hips as you raise the kettlebells towards your epaules. The poignets should rotate as you do so. 3. Lower kettlebells to a hanging position between vos jambes while keeping the ischio-jambiers loaded. Keep your head up en permanence.', 'Muscles secondaires : Mollets, Fessiers, Bas du dos, Épaules, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Hang_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kettlebell One-Legged Deadlift', 'Ischio-jambiers', 'Kettlebell', '1. Hold a kettlebells by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebells. 2. Keeping that genoux slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance. 3. Continue lowering the kettlebells until you are parallel to the ground, and then return to the upright position.', 'Muscles secondaires : Fessiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_One-Legged_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kettlebell Pass Between The Legs', 'Abdominaux', 'Kettlebell', '1. Place one kettlebells between vos jambes and take a comfortable stance. Bend over by pushing your butt out and keeping votre dos flat. 2. Pick up a kettlebells and pass it to your other hand between vos jambes, in the fashion of a "W". Go back and forth for several repetitions.', 'Muscles secondaires : Fessiers, Ischio-jambiers, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Pass_Between_The_Legs/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kettlebell Pirate Ships', 'Épaules', 'Kettlebell', '1. With a wide stance, hold a kettlebells with both hands. Allow it to hang at waist level with vos bras extended. Position de depart. 2. Initiate le mouvement by turning to one side, swinging the kettlebells to head height. Briefly pause at the top of the motion. 3. Allow the bell to drop as you rotate to the opposite side, again raising the kettlebells to head height. 4. Repetez for the desired amount of repetitions.', 'Muscles secondaires : Abdominaux. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Pirate_Ships/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kettlebell Pistol Squat', 'Quadriceps', 'Kettlebell', '1. Pick up a kettlebells with two hands and hold it by the horns. Hold one leg off of le sol and squat down on the other. 2. Squat down by flexing the genoux and sitting back with the hips, holding the kettlebells up in front of you. 3. Hold the bottom position for a second and then reverse the motion, driving through the heel and keeping your head and poitrine up. 4. Lower yourself again and Repetez.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Épaules. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Pistol_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kettlebell Seated Press', 'Épaules', 'Kettlebell', '1. Sit on le sol and spread vos jambes out comfortably. 2. Clean one kettlebells to your epaules. 3. Press the kettlebells up and out until it is locked out overhead. Revenez en position de depart.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Seated_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kettlebell Seesaw Press', 'Épaules', 'Kettlebell', '1. Clean two kettlebells two your epaules. 2. Press one kettlebells. 3. Lower the kettlebells and immediately press the other kettlebells. Make sure to do the same amount of reps on both sides.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Seesaw_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kettlebell Sumo High Pull', 'Trapèzes', 'Kettlebell', '1. Place a kettlebells on the ground between vos pieds. Position vos pieds in a wide stance, and grasp the kettlebells with two hands. Set your hips back as far as possible, with your genoux bent. Keep your poitrine and head up. Position de depart. 2. Begin by extending the hips and genoux, simultaneously pulling the kettlebells to your epaules, raising your coudes as you do so. Reverse the motion to Revenez en position de depart.', 'Muscles secondaires : Adducteurs, Fessiers, Ischio-jambiers, Quadriceps, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Sumo_High_Pull/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kettlebell Thruster', 'Épaules', 'Kettlebell', '1. Clean two kettlebells to your epaules. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so. Position de depart. 2. Begin to squat by flexing your hips and genoux, lowering your hips between vos jambes. Maintain an upright, straight back as you descend as low as you can. 3. At the bottom, reverse direction and squat by extending your genoux and hips, driving through your heels. As you do so, press both kettlebells overhead by extending vos bras straight up, using the momentum from the squat to help drive the poids upward. 4. As you begin the next repetition, return the poids to the epaules.', 'Muscles secondaires : Quadriceps, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Thruster/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kettlebell Turkish Get-Up (Lunge style)', 'Épaules', 'Kettlebell', '1. Allongez-vous au sol on le sol and press a kettlebells to the top position by extending the coudes. Bend the genoux on the same side as the kettlebells. 2. Keeping the kettlebells locked out en permanence, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to one genoux. 3. While looking up at the kettlebells, Lentement, stand up. Reverse the motion back to the position de depart and Repetez.', 'Muscles secondaires : Abdominaux, Ischio-jambiers, Quadriceps, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Turkish_Get-Up_Lunge_style/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kettlebell Turkish Get-Up (Squat style)', 'Épaules', 'Kettlebell', '1. Allongez-vous au sol on le sol and press a kettlebells to the top position by extending the coudes. Bend the genoux on the same side as the kettlebells. 2. Keeping the kettlebells locked out en permanence, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. 3. Using your free hand, push yourself to a seated position, then progressing to vos pieds. While looking up at the kettlebells, Lentement, stand up. Reverse the motion back to the position de depart and Repetez.', 'Muscles secondaires : Abdominaux, Mollets, Ischio-jambiers, Quadriceps, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Turkish_Get-Up_Squat_style/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kettlebell Windmill', 'Abdominaux', 'Kettlebell', '1. Place a kettlebells in front of your lead foot and clean and press it overhead with your opposite arm. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so, so that the palm faces forward. Press it overhead by extending the coudes. 2. Keeping the kettlebells locked out en permanence, push your butt out in the direction of the locked out kettlebells. Turn vos pieds out at a forty-five degree angle from the arm with the locked out kettlebells. Bending at the hip to one side, sticking your butt out, Lentement, lean until you can touch le sol with your free hand. Keep your eyes on the kettlebells that you hold over your head en permanence. 3. Pause for a second after reaching the ground and reverse the motion back to the position de depart.', 'Muscles secondaires : Fessiers, Ischio-jambiers, Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kettlebell_Windmill/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kipping Muscle Up', 'Dos', 'Autre', '1. Grip the rings using a false grip, with the base of your palms on top of the rings. 2. Begin with a movement swinging vos jambes backward slightly. 3. Counter that movement by swinging vos jambes forward and up, jerking your chin and poitrine back, pulling yourself up with both arms as you do so. As you reach the top position of the pull-up, pull the rings to your armpits as you roll your epaules forward, allowing your coudes to move straight back behind you. This puts you into the proper position to continue into the dip portion of le mouvement. 4. Maintaining control and stability, extend through the coudes to complete the motion. 5. Use care when lowering yourself to the ground.', 'Muscles secondaires : Abdominaux, Biceps, Avant-bras, Milieu du dos, Épaules, Trapèzes, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kipping_Muscle_Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Knee Across The Body', 'Fessiers', 'Autre', '1. Allongez-vous au sol with your right leg straight. Bend your left leg and lower it across votre corps, holding the genoux down toward le sol with your right hand. (The genoux doesn''t need to touch le sol if you''re tight.) 2. Place your left arm comfortably beside you and turn your head to the left. Imagine you have a poids tied to your tailbone. let your tailbone fall back toward le sol as your poitrine reaches in the opposite direction to stretch your lower back. Switch sides.', 'Muscles secondaires : Abducteurs, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Knee_Across_The_Body/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Knee Circles', 'Mollets', 'Poids de corps', '1. Tenez-vous debout avec vos jambes together and hands by your waist. 2. Now move your genoux in a circular motion as you breathe normally. 3. Repetez selon le nombre souhaite.', 'Muscles secondaires : Ischio-jambiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Knee_Circles/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Knee/Hip Raise On Parallel Bars', 'Abdominaux', 'Autre', '1. Position votre corps on the vertical leg raise banc so that your forearms are resting on the pads next to the torse and holding on to the handles. vos bras will be bent at a 90 degree angle. 2. The torse should be straight with the lower back pressed against the pad of the machine and the legs extended pointing towards le sol. Position de depart. 3. Now as you Expirez, lift vos jambes up as you keep them extended. Continue this movement until vos jambes are roughly parallel to le sol and then hold the contraction for a second. Conseil : Do not use any momentum or swinging as you perform this exercise. 4. Lentement, go back to the position de depart as you Inspirez. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Knee_Hip_Raise_On_Parallel_Bars/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Knee Tuck Jump', 'Ischio-jambiers', 'Poids de corps', '1. Begin in a comfortable standing position with your genoux slightly bent. Hold vos mains in front of you, palms down with your fingertips together at poitrine height. Position de depart. 2. Rapidly dip down into a quarter squat and immediately explode upward. Drive the genoux towards the poitrine, attempting to touch them to the palms of the hands. 3. Jump as high as you can, raising your genoux up, and then ensure a good land be re-extending vos jambes, absorbing impact through be allowing the genoux to rebend.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Knee_Tuck_Jump/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kneeling Arm Drill', 'Épaules', 'Autre', '1. This drill helps increase arm efficiency during the run. Begin kneeling, left foot in front, right genoux down. Apply pressure through the front heel to keep your fessiers and ischio-jambiers activated. 2. Begin by blocking the arms in long, pendulum like swings. Close the arm angle, blocking with the arms as you would when jogging, progressing to a run and finally a sprint. 3. As soon as vos mains pass the hip, accelerate them forward during the sprinting motion to move them as quickly as possible. 4. Switch genoux and Repetez.', 'Muscles secondaires : Abdominaux. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Arm_Drill/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kneeling Cable Crunch With Alternating Oblique Twists', 'Abdominaux', 'Poulie', '1. Connect a rope attachment to a high pulley cable and position a mat on le sol in front of it. 2. Grab the rope with both hands and kneel approximately two feet back from the tower. 3. Position the rope behind your head with vos mains by your ears. 4. Keep vos mains in the same place, contract your abdominaux and pull downward on the rope in a crunching movement until your coudes reach your genoux. 5. Pause briefly at the bottom and rise up in a slow and controlled manner until you reach the position de depart. 6. Repetez the same downward movement until you''re halfway down, at which time you''ll begin rotating one of your coudes to the opposite genoux. 7. Again, pause briefly at the bottom and rise up in a slow and controlled manner until you reach the position de depart. 8. Repetez the same movement as before, but alternate the other coudes to the opposite genoux. 9. Continue this series of movements to failure.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kneeling Cable Triceps Extension', 'Triceps', 'Poulie', '1. Place a banc sideways in front of a high pulley machine. 2. Hold a straight bar attachment above your head with vos mains about 6 inches apart with your palms facing down. 3. Face away from the machine and kneel. 4. Place your head and the back of your upper arms on the banc. Your coudes should be bent with the forearms pointing towards the high pulley. Position de depart. 5. While keeping your upper arms close to your head en permanence with the coudes in, press the bar out in a semicircular motion until the coudes are locked and vos bras are parallel to le sol. Contract the triceps hard and keep this position for a second. Exhale as you perform this movement. 6. Lentement, Revenez en position de depart as you Inspirez. 7. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Cable_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kneeling Forearm Stretch', 'Avant-bras', 'Autre', '1. Start by kneeling on a mat with your palms flat and your fingers pointing back toward your genoux. 2. Lentement, lean back keeping your palms flat on le sol until you feel a stretch in your poignets and forearms. Hold for 20-30 seconds.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Forearm_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kneeling High Pulley Row', 'Dos', 'Poulie', '1. Select the appropriate poids using a pulley that is above your head. Attach a rope to the cable and kneel a couple of feet away, holding the rope out in front of you with both arms extended. Position de depart. 2. Initiate le mouvement by flexing the coudes and fully retracting your epaules, pulling the rope toward your upper poitrine with your coudes out. 3. After pausing briefly, Lentement, Revenez en position de depart.', 'Muscles secondaires : Biceps, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_High_Pulley_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kneeling Hip Flexor', 'Quadriceps', 'Autre', '1. Kneel on a mat and bring your right genoux up so the bottom of your foot is on le sol and extend your left leg out behind you so the top of your foot is on le sol. 2. Shift your poids forward until you feel a stretch in your hip. Hold for 15 seconds, then Repetez for your other side.', 'Muscles secondaires : Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Hip_Flexor/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kneeling Jump Squat', 'Fessiers', 'Barre', '1. Begin kneeling on le sol with a barre racked across the back of your epaules, or you can use votre corps poids for this exercise. This can be done inside of a power rack to make unracking easier. 2. Sit back with your hips until your fessiers touch vos pieds, keeping your head and poitrine up. 3. Explode up with your hips, generating enough power to land with vos pieds flat on le sol. 4. Continue with the squat by driving through your heels and extending the genoux to come to a standing position.', 'Muscles secondaires : Mollets, Ischio-jambiers, Quadriceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Jump_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kneeling Single-Arm High Pulley Row', 'Dos', 'Poulie', '1. Attach a single handle to a high pulley and make your poids selection. 2. Kneel in front of the cable tower, taking the cable with one hand with your arm extended. Position de depart. 3. Starting with your palm facing forward, pull the poids down to your torse by flexing the coudes and retract the omoplates. As you do so, rotate the poignets so that at the completion of le mouvement, your palm is now facing you. 4. Apres une pause, Revenez en position de depart.', 'Muscles secondaires : Biceps, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Single-Arm_High_Pulley_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Kneeling Squat', 'Fessiers', 'Barre', '1. Set the bar to the proper height in a power rack. Kneel behind the bar; it may be beneficial to put a mat down to pad your genoux. Slide under the bar, racking it across the back of your epaules. Your omoplates should be retracted and the bar tight across votre dos. Unrack the poids. 2. With your head looking forward, sit back with your butt until you touch your mollets. 3. Reverse the motion, returning the torse to an upright position.', 'Muscles secondaires : Abdominaux, Ischio-jambiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Kneeling_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Landmine 180''s', 'Abdominaux', 'Barre', '1. Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate poids. 2. Raise the bar from le sol, taking it to epaules height with both hands with vos bras extended in front of you. Adopt a wide stance. Position de depart. 3. Perform le mouvement by rotating the trunk and hips as you swing the poids all the way down to one side. Keep vos bras extended throughout the exercise. 4. Reverse the motion to swing the poids all the way to the opposite side. 5. Continue alternating le mouvement until the set is complete.', 'Muscles secondaires : Fessiers, Bas du dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Landmine_180s/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Landmine Linear Jammer', 'Épaules', 'Barre', '1. Position a bar into landmine or, lacking one, securely anchor it in a corner. Load the bar to an appropriate poids and position the handle attachment on the bar. 2. Raise the bar from le sol, taking the handles to your epaules. Position de depart. 3. In an athletic stance, squat by flexing your hips and setting your hips back, keeping vos bras flexed. 4. Reverse the motion by powerfully extending through the hips, genoux, and ankles, while also extending the coudes to straighten the arms. This movement should be done explosively, coming out of the squat to full extension as powerfully as possible. 5. Revenez en position de depart.', 'Muscles secondaires : Abdominaux, Mollets, Pectoraux, Ischio-jambiers, Quadriceps, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Landmine_Linear_Jammer/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lateral Bound', 'Adducteurs', 'Poids de corps', '1. Assume a half squat position facing 90 degrees from your direction of travel. Position de depart. 2. Allow your lead leg to do a countermovement inward as you shift your poids to the outside leg. 3. Immediately push off and extend, attempting to bound to the side as far as possible. 4. Upon landing, immediately push off in the opposite direction, returning to your original start position. 5. Continue back and forth for several repetitions.', 'Muscles secondaires : Abducteurs, Mollets, Fessiers, Ischio-jambiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Bound/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lateral Box Jump', 'Adducteurs', 'Autre', '1. Assume a comfortable standing position, with a short box positioned next to you. Position de depart. 2. Quickly dip into a quarter squat to initiate the stretch reflex, and immediately reverse direction to jump up and to the side. 3. Bring your genoux high enough to ensure vos pieds have good clearance over the box. 4. Land on the center of the box, using vos jambes to absorb the impact. 5. Carefully jump down to the other side of the box, and continue going back and forth for several repetitions.', 'Muscles secondaires : Abducteurs, Mollets, Fessiers, Ischio-jambiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Box_Jump/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lateral Cone Hops', 'Adducteurs', 'Autre', '1. Position a number of cones in a row several feet apart. 2. Stand next to the end of the cones, facing 90 degrees to the direction of travel. Position de depart. 3. Begin the jump by dipping with the genoux to initiate a stretch reflex, and immediately reverse direction to push off the ground, jumping up and sideways over the cone. 4. Use vos jambes to absorb impact upon landing, and rebound into the next jump, continuing down the row of cones.', 'Muscles secondaires : Abducteurs, Mollets, Fessiers, Ischio-jambiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Cone_Hops/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lateral Raise - With Bands', 'Épaules', 'Élastique', '1. To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your cuisses) grip that is slightly less than epaules width. The handles should be resting on the sides of your cuisses. vos bras should be extended with a slight bend at the coudes and votre dos should be straight. Position de depart. 2. Use your side epaules to lift the handles to the sides en expirant. Continue to lift the handles until they are slightly above parallel. Conseil : As you lift the handles, slightly tilt the hand as if you were pouring water and keep vos bras extended. Also, keep your torse stationary and pause for a second at the top of le mouvement. 3. Lower the handles back down Lentement, to the position de depart. Inhale as you perform this portion of le mouvement. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lateral_Raise_-_With_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Latissimus Dorsi-SMR', 'Dos', 'Foam roller', '1. While lying on le sol, place a foam roll under votre dos and to one side, just behind your arm pit. Position de depart. 2. Keep the arm of the side being stretched behind and to the side of you as you shift your poids onto your lats, keeping your upper body off of the ground. Hold for 10-30 seconds, and switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Latissimus_Dorsi-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leg-Over Floor Press', 'Pectoraux', 'Kettlebell', '1. Allongez-vous au sol with one kettlebells in place on your poitrine, holding it by the handle. Extend leg on working side over leg on non-working side.Your free arm can be extended out to your side for support. 2. Press the kettlebll into a locked out position. 3. Lower the poids until the coudes touches the ground, keeping the kettlebells above the coudes. Repetez for the desired number of repetitions.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg-Over_Floor_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leg-Up Hamstring Stretch', 'Ischio-jambiers', 'Autre', '1. Allongez-vous au sol, bend one genoux, and put that foot flat on le sol to stabilize your spine. 2. Extend the other leg in the air. If you''re tight, you wont be able to straighten it. That''s okay. Extend the genoux so that the sole of the lifted foot faces the ceiling (or as close as you can get it). 3. Lentement, straighten the legs as much as possible and then pull the leg toward your nose. Switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg-Up_Hamstring_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leg Extensions', 'Quadriceps', 'Machine', '1. For this exercise you will need to use a leg extension machine. First choose your poids and sit on the machine with vos jambes under the pad (feet pointed forward) and the hands holding the side bars. Position de depart. Conseil : You will need to adjust the pad so that it falls on top of your lower leg (just above vos pieds). Also, make sure that vos jambes form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the genoux is over the toes which in turn creates undue stress at the genoux joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle. 2. Using your quadriceps, extend vos jambes to the maximum en expirant. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position. 3. Lentement, lower the poids back to the original position en inspirant, ensuring that you do not go past the 90-degree angle limit. 4. Repetez for the recommended amount of times.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Extensions/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leg Lift', 'Fessiers', 'Poids de corps', '1. While standing up straight with both feet next to each other at around epaules width, grab a sturdy surface such as the sides of a squat rack or the top of a chair to brace yourself and keep balance. 2. With or without an ankle poids, lift one leg behind you as if performing a leg curl but standing up while keeping the other leg straight. Expirez as you perform this movement. 3. Lentement, bring the raised leg back to le sol as you Inspirez. 4. Repetez selon le nombre souhaite. 5. Repetez le mouvement with the opposite leg.', 'Muscles secondaires : Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Lift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leg Press', 'Quadriceps', 'Machine', '1. Using a leg press machine, sit down on the machine and place vos jambes on the platform directly in front of you at a medium (epaules width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section). 2. Lower the safety bars holding the weighted platform in place and press the platform all the way up until vos jambes are fully extended in front of you. Conseil : Make sure that you do not lock your genoux. Your torse and the legs should make a perfect 90-degree angle. Position de depart. 3. en inspirant, Lentement, lower the platform until your upper and lower legs make a 90-degree angle. 4. Pushing mainly with the heels of vos pieds and using the quadriceps go back to the position de depart en expirant. 5. Repetez selon le nombre souhaite. and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leg Pull-In', 'Abdominaux', 'Poids de corps', '1. Lie on an exercise mat with vos jambes extended and vos mains either palms facing down next to you or under your fessiers. Conseil : My preference is with the hands next to me. Position de depart. 2. Bend your genoux and pull your upper cuisses into your midsection as you Expirez. Continue the motion until your genoux are around poitrine level. Contract your abdominaux as you execute this movement and Maintenez 1 seconde at the top. Conseil : As you perform the motion, the lower legs (mollets) should always remain parallel to le sol. 3. Revenez en position de depart en inspirant. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leg_Pull-In/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leverage Chest Press', 'Pectoraux', 'Machine', '1. Load an appropriate poids onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion. 2. Your poitrine and head should be up and your omoplates retracted. Position de depart. 3. Press the handles forward by extending through the coudes. 4. Apres une pause, at the top, return the poids just above the start position, keeping tension on the muscles by not returning the poids to the stops until the set is complete.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Chest_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leverage Deadlift', 'Quadriceps', 'Machine', '1. Load the pins to an appropriate poids. Position yourself directly between the handles. Grasp the bottom handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your poitrine up. Position de depart. 2. Return the poids to the position de depart.', 'Muscles secondaires : Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leverage Decline Chest Press', 'Pectoraux', 'Machine', '1. Load an appropriate poids onto the pins and adjust the seat for your height. The handles should be near the bottom of the pectorals at the beginning of the motion. Your poitrine and head should be up and your omoplates retracted. Position de depart. 2. Press the handles forward by extending through the coudes. 3. Apres une pause, at the top, return the poids just above the start position, keeping tension on the muscles by not returning the poids to the stops until the set is complete.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Decline_Chest_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leverage High Row', 'Milieu du dos', 'Machine', '1. Load an appropriate poids onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the genoux pad to help keep you down. Grasp the handles with a pronated grip. Position de depart. 2. Pull the handles towards your torse, retracting your omoplates as you flex the coudes. 3. Pause at the bottom of the motion, and then Lentement, return the handles to the position de depart. 4. For multiple repetitions, avoid completely returning the poids to the stops to keep tension on the muscles being worked.', 'Muscles secondaires : Dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_High_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leverage Incline Chest Press', 'Pectoraux', 'Machine', '1. Load an appropriate poids onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your poitrine and head should be up and your omoplates retracted. Position de depart. 2. Press the handles forward by extending through the coudes. 3. Apres une pause, at the top, return the poids just above the start position, keeping tension on the muscles by not returning the poids to the stops until the set is complete.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Incline_Chest_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leverage Iso Row', 'Dos', 'Machine', '1. Load an appropriate poids onto the pins and adjust the seat height so that the handles are at poitrine level. Grasp the handles with either a neutral or pronated grip. Position de depart. 2. Pull the handles towards your torse, retracting your omoplates as you flex the coudes. 3. Pause at the bottom of the motion, and then Lentement, return the handles to the position de depart. For multiple repetitions, avoid completely returning the poids to the stops to keep tension on the muscles being worked.', 'Muscles secondaires : Biceps, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Iso_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leverage Shoulder Press', 'Épaules', 'Machine', '1. Load an appropriate poids onto the pins and adjust the seat for your height. The handles should be near the top of the epaules at the beginning of the motion. Your poitrine and head should be up and handles held with a pronated grip. Position de depart. 2. Press the handles upward by extending through the coudes. 3. Apres une pause, at the top, return the poids to just above the start position, keeping tension on the muscles by not returning the poids to the stops until the set is complete.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Shoulder_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Leverage Shrug', 'Trapèzes', 'Machine', '1. Load the pins to an appropriate poids. Position yourself directly between the handles. 2. Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your poitrine up. 3. Drive through le sol with your heels, extending your hips and genoux as you rise to a standing position. Keep vos bras straight throughout le mouvement, finishing with your epaules back. Position de depart. 4. Raise the poids by shrugging the epaules towards your ears, moving straight up and down. 5. Pause at the top of the motion, and then return the poids to the position de depart.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Leverage_Shrug/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Linear 3-Part Start Technique', 'Ischio-jambiers', 'Autre', '1. This drill helps you accelerate as quickly as possible into a sprint from a dead stop. It helps to use a line to start from. Begin with two feet on the line. Place your left foot with the toe next to your right ankle. Place your right foot 4-6 inches behind the left. 2. Place your right hand onto the line, and thing bring your nose close to your left genoux. 3. Squat down as you lean foward, your head being lower than your hips and your poids loaded onto the left leg. Position de depart. 4. Take your left hand up so that it is parallel to the ground, pointing behind you, and explode out when ready.', 'Muscles secondaires : Mollets, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Linear_3-Part_Start_Technique/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Linear Acceleration Wall Drill', 'Ischio-jambiers', 'Autre', '1. Lean at around 45 degrees against a wall. vos pieds should be together, fessiers contracted. 2. Begin by lifting your right genoux quickly, pausing, and then driving it straight down into the ground. 3. Switch legs, raising the opposite genoux, and then attacking the ground straight down. 4. Repetez once more with your right leg, and as soon as the right foot strikes the ground hammer them out rapidly, alternating left and right as fast as you can.', 'Muscles secondaires : Mollets, Fessiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Linear_Acceleration_Wall_Drill/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Linear Depth Jump', 'Quadriceps', 'Autre', '1. You will need two boxes or benches spaced a few feet away from each other. Begin by standing on one box facing towards the other platform. 2. To initiate le mouvement, gently drop down to the ground between your platforms, allowing the genoux and hips to flex. 3. Reverse the motion by exploding, extending through the hips, genoux, and ankles to jump onto the other platform. 4. Land softly, asborbing the impact through the legs.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Linear_Depth_Jump/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Log Lift', 'Épaules', 'Autre', '1. Begin standing with the log in front of you. Grasp the handles, and begin to clean the log. As you are bent over to start the clean, attempt to get the log as high as possible, pulling it into your poitrine. Extend through the hips and genoux to bring it up to complete the clean. 2. Push your head back and look up, creating a shelf on your poitrine to rest the log. Begin the press by dipping, flexing slightly through the genoux and reversing the motion. This push press will generate momentum to start the log moving vertically. Continue by extending through the coudes to press the log above your head. There are no strict rules on form, so use whatever techniques you are most efficient with. As the log is pressed, ensure that you push your head through on each repetition, looking forward. 3. Repetez as many times as possible. Attempt to control the descent of the log as it is returned to the ground.', 'Muscles secondaires : Abdominaux, Pectoraux, Fessiers, Ischio-jambiers, Bas du dos, Milieu du dos, Quadriceps, Trapèzes, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Log_Lift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('London Bridges', 'Dos', 'Autre', '1. Attach a climbing rope to a high beam or cross member. Below it, ensure that the smith machine bar is locked in place with the safeties and cannot move. Alternatively, a secure box could also be utilized. 2. Stand on the bar, using the rope to balance yourself. Position de depart. 3. Keeping votre corps straight, lean back and lower votre corps by Lentement, going hand over hand with the rope. Continue until you are perpendicular to the ground. 4. Keeping votre corps straight, reverse the motion, going hand over hand back to the position de depart.', 'Muscles secondaires : Biceps, Avant-bras, Milieu du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/London_Bridges/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Looking At Ceiling', 'Quadriceps', 'Autre', '1. Kneel on le sol, holding your heels with both hands. 2. Lift your buttocks up and forward while bringing your head back to look up at the ceiling, to give an arch in votre dos.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Looking_At_Ceiling/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Low Cable Crossover', 'Pectoraux', 'Poulie', '1. To move into the position de depart, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand. 2. Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and vos bras straight. Position de depart. 3. With a slight bend in vos bras, draw vos mains upward and toward the midline of votre corps. vos mains should come together in front of your poitrine, palms facing up. 4. Return vos bras back to the position de depart Apres une pause, .', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Low_Cable_Crossover/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Low Cable Triceps Extension', 'Triceps', 'Poulie', '1. Select the desired poids and lay down face up on the banc of a seated row machine that has a rope attached to it. Your head should be pointing towards the attachment. 2. Grab the outside of the rope ends with your palms facing each other (neutral grip). 3. Position your coudes so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torse. Conseil : Keep the coudes in and make sure that the upper arms point to the ceiling while your forearms point towards the pulley above your head. Position de depart. 4. As you Expirez, extend your lower arms until they are straight and vertical. The upper arms and coudes remain stationary throughout le mouvement. Only the forearms should move. Contract the triceps hard for a second. 5. As you Inspirez Lentement, Revenez en position de depart. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Low_Cable_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Low Pulley Row To Neck', 'Épaules', 'Poulie', '1. Sit on a low pulley row machine with a rope attachment. 2. Grab the ends of the rope using a palms-down grip and sit with votre dos straight and your genoux slightly bent. Conseil : Keep votre dos almost completely vertical and vos bras fully extended in front of you. Position de depart. 3. While keeping your torse stationary, lift your coudes and start bending them as you pull the rope towards your neck while exhaling. Throughout le mouvement your upper arms should remain parallel to le sol. Conseil : Continue this motion until vos mains are almost next to your ears (the forearms will not be parallel to le sol at the end of le mouvement as they will be angled a bit upwards) and your coudes are out away from your sides. 4. After holding for a second or so at the contracted position, come back Lentement, to the position de depart en inspirant. Conseil : Again, during no part of le mouvement should the torse move. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Milieu du dos, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Low_Pulley_Row_To_Neck/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lower Back-SMR', 'Bas du dos', 'Foam roller', '1. In a seated position, place a foam roll under your lower back. Cross vos bras in front of you and protract your epaules. Position de depart. 2. Raise your hips off of le sol and lean back, keeping your poids on your lower back. Now shift your poids slightly to one side, keeping your poids off of the spine and on the muscles to the side of it. Roll over your lower back, holding points of tension for 10-30 seconds. Repetez de l autre cote.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lower_Back-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lower Back Curl', 'Abdominaux', 'Poids de corps', '1. Lie on your stomach with vos bras out to your sides. Position de depart. 2. Using your lower back muscles, extend your spine lifting your poitrine off of the ground. Do not use vos bras to push yourself up. Keep your head up during le mouvement. Repetez for 10-20 repetitions.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lower_Back_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lunge Pass Through', 'Ischio-jambiers', 'Kettlebell', '1. Tenez-vous debout avec your torse upright holding a kettlebells in your right hand. Position de depart. 2. Step forward with your left foot and lower your upper body down by flexing the hip and the genoux, keeping the torse upright. Lower votre dos genoux until it nearly touches the ground. 3. As you lunge, pass the kettlebells under your front leg to your opposite hand. 4. Pressing through the heel of your foot, Revenez en position de depart. 5. Repetez le mouvement for the recommended amount of repetitions, alternating legs.', 'Muscles secondaires : Mollets, Fessiers, Quadriceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lunge_Pass_Through/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lunge Sprint', 'Quadriceps', 'Machine', '1. Adjust a bar in a Smith machine to an appropriate height. Position yourself under the bar, racking it across the back of your epaules. Unrack the bar, and then split vos pieds, moving one foot forward and one foot back. Position de depart. 2. Lower votre dos genoux nearly to the ground, flexing the genoux and lowering your hips as you do so. 3. At the bottom of the descent, immediately reverse direction. Explosively drive through the heel of your front foot with light pressure from votre dos foot. Jump up and reverse the position of vos jambes. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lunge_Sprint/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Bent Leg Groin', 'Adducteurs', 'Autre', '1. Allongez-vous au sol with your genoux bent and the soles of the feet pressed together. Have your partner hold your genoux. Position de depart. 2. Attempt to squeeze your genoux together, while your partner prevents any movement from occurring. 3. After 10-20 seconds, relax your muscles as your partner gently pushes your genoux towards le sol. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching.', 'Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Bent_Leg_Groin/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Cable Curl', 'Biceps', 'Poulie', '1. Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) epaules-width grip. 2. Allongez-vous au sol on top of an exercise mat in front of the poids stack with vos pieds flat against the frame of the pulley machine and vos jambes straight. 3. With vos bras extended and your coudes close to votre corps slightly bend vos bras. Position de depart. 4. While keeping your upper arms stationary and the coudes close to votre corps, curl the bar up Lentement, toward your poitrine as you Expirez and you squeeze the biceps. 5. After a second squeeze at the top of le mouvement, Lentement, Revenez en position de depart. 6. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Cable_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Cambered Barbell Row', 'Milieu du dos', 'Barre', '1. Place a cambered bar underneath an exercise banc. 2. Lie face down on the exercise banc and grab the bar using a palms down (pronated grip) that is wider than epaules width. Position de depart. 3. en expirant row the bar up as you keep the coudes close to votre corps to either your poitrine, in order to target the upper mid back, or to your stomach if targeting the lats is your goal. 4. After a second hold at the top, lower back down to the position de depart Lentement, en inspirant.', 'Muscles secondaires : Biceps, Dos, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Cambered_Barbell_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Close-Grip Bar Curl On High Pulley', 'Biceps', 'Poulie', '1. Place a flat banc in front of a high pulley or lat pulldown machine. 2. Hold the straight bar attachment using an prise en supination (palms up) that is about epaules width. 3. Allongez-vous au sol with your head over the end of the banc. 4. Now extend vos bras straight above your epaules. Your torse and vos bras should make a 90-degree angle and the coudes should be in. Position de depart. 5. As you Expirez, curl the bar down in a semicircular motion until it touches your chin. Squeeze the biceps for a second at the top contracted position. Conseil : As you execute this motion only the forearms should move. At no time should the upper arms be moving at all. They are to remain perpendicular throughout le mouvement. 6. Revenez en position de depart slowly. 7. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Close-Grip_Bar_Curl_On_High_Pulley/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Close-Grip Barbell Triceps Extension Behind The Head', 'Triceps', 'Barre', '1. While holding a barre or EZ Curl bar with a pronated grip (palms facing forward), Allongez-vous au sol on a flat banc with your head close to the end of the banc. Conseil : If you are holding a barre grab it using a epaules-width grip and if you are using an E-Z Bar grab it on the inner handles. 2. Extend vos bras in front of you and Lentement, bring the bar back in a semi circular motion (while keeping the arms extended) to a position over your head. At the end of this step vos bras should be overhead and parallel to le sol. Position de depart. Conseil : Keep your coudes in en permanence. 3. en inspirant, lower the bar by bending at the coudes and while keeping the upper arm stationary. Keep lowering the bar until your forearms are perpendicular to le sol. 4. en expirant bring the bar back up to the position de depart by pushing the bar up in a semi-circular motion until the lower arms are also parallel to le sol. Contract the triceps hard at the top of le mouvement for a second. Conseil : Again, only the forearms should move. The upper arms should remain stationary en permanence. 5. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Close-Grip Barbell Triceps Press To Chin', 'Triceps', 'Barre EZ', '1. While holding a barre or EZ Curl bar with a pronated grip (palms facing forward), Allongez-vous au sol on a flat banc with your head off the end of the banc. Conseil : If you are holding a barre grab it using a epaules-width grip and if you are using an E-Z Bar grab it on the inner handles. 2. Extend vos bras in front of you as you hold the barre over your poitrine. The arms should be perpendicular to your torse (90-degree angle). Position de depart. 3. en inspirant, lower the bar in a semi-circular motion by bending at the coudes and while keeping the upper arm stationary and coudes in. Keep lowering the bar until it lightly touches your chin. 4. en expirant bring the bar back up to the position de depart by pushing the bar up in a semi-circular motion. Contract the triceps hard at the top of le mouvement for a second. Conseil : Again, only the forearms should move. The upper arms should remain stationary en permanence. 5. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Crossover', 'Abducteurs', 'Poids de corps', '1. Allongez-vous au sol with vos jambes extended. 2. Cross one leg over votre corps with the genoux bent, attempting to touch the genoux to the ground. Your partner should kneel beside you, holding your epaules down with one hand and controlling the crossed leg with the other. Position de depart. 3. Attempt to raise the bent genoux off of the ground as your partner prevents any actual movement. 4. After 10-20 seconds, relax the leg as your partner gently presses the genoux towards le sol. Repetez with the other side.', 'Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Crossover/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Dumbbell Tricep Extension', 'Triceps', 'Haltères', '1. Allongez-vous sur un banc plat while holding two halteres directly in front of you. vos bras should be fully extended at a 90-degree angle from your torse and le sol. The palms should be facing in and the coudes should be tucked in. Position de depart. 2. As you Inspirez and you keep the upper arms stationary with the coudes in, Lentement, lower the poids until the halteres are near your ears. 3. At that point, while keeping the coudes in and the upper arms stationary, use the triceps to bring the poids back up to the position de depart as you Expirez. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Dumbbell_Tricep_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Face Down Plate Neck Resistance', 'Cou', 'Autre', '1. Lie face down with your whole body straight on a flat banc while holding a poids plate behind your head. Conseil : You will need to position yourself so that your epaules are slightly above the end of a flat banc in order for the upper poitrine, neck and face to be off the banc. Position de depart. 2. While keeping the plate secure on the back of your head Lentement, lower your head (as in saying "yes") as you Inspirez. 3. Raise your head back up to the position de depart in a semi-circular motion as you Expirez. Hold the contraction for a second. 4. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Face_Down_Plate_Neck_Resistance/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Face Up Plate Neck Resistance', 'Cou', 'Autre', '1. Lie face up with your whole body straight on a flat banc while holding a poids plate on top of your forehead. Conseil : You will need to position yourself so that your epaules are slightly above the end of a flat banc in order for the traps, neck and head to be off the banc. Position de depart. 2. While keeping the plate secure on your forehead Lentement, lower your head back in a semi-circular motion as you Inspirez. 3. Raise your head back up to the position de depart in a semi-circular motion as you Expirez. Hold the contraction for a second. 4. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Face_Up_Plate_Neck_Resistance/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Glute', 'Fessiers', 'Poids de corps', '1. Allongez-vous au sol with your partner kneeling beside you. 2. Flex the hip of one leg, raising it off of le sol. Rotate the leg so the foot is over the opposite hip, the lower leg perpendicular to votre corps. Your partner should hold the genoux and ankle in place. Position de depart. 3. Attempt to push your leg towards your partner, who should be preventing any actual movement of the leg. 4. After 10-20 seconds, completely relax as your partner gently pushes the ankle and genoux towards your poitrine. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching.', 'Muscles secondaires : Abducteurs. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Glute/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Hamstring', 'Ischio-jambiers', 'Autre', '1. Allongez-vous au sol with vos jambes extended. Your partner should be kneeling beside you. Raise one leg up towards the ceiling and have your partner hold the ankle. Your partner can use their epaules to brace your leg if necessary. Position de depart. 2. With your partner holding your leg in place, attempt to flex the genoux, contracting the ischio-jambiers for 10-20 seconds. 3. Then relax your leg, allowing your partner to gently push the leg towards your head. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching. Switch sides once complete.', 'Muscles secondaires : Mollets. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Hamstring/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying High Bench Barbell Curl', 'Biceps', 'Barre', '1. Lie face forward on a tall flat banc while holding a barre with a supinated grip (palms facing up). Conseil : If you are holding a barre grab it using a epaules-width grip and if you are using an E-Z Bar grab it on the inner handles. Your upper body should be positioned in a way that the upper poitrine is over the end of the banc and the barre is hanging in front of you with the arms extended and perpendicular to le sol. Position de depart. 2. While keeping the coudes in and the upper arms stationary, curl the poids up in a semi-circular motion as you contract the biceps and exhale. Hold at the top of le mouvement for a second. 3. en inspirant, Lentement, go back to the position de depart. Conseil : Maintain full control of the poids en permanence and avoid any swinging. Remember, only the forearms should move throughout le mouvement. 4. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_High_Bench_Barbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Leg Curls', 'Ischio-jambiers', 'Machine', '1. Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of vos jambes (just a few inches under the mollets). Conseil : Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for ischio-jambiers recruitment. 2. Keeping the torse flat on the banc, ensure vos jambes are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). Position de depart. 3. en expirant, curl vos jambes up as far as possible without lifting the upper legs from the pad. Once you hit the entierement contracte position, hold it for a second. 4. en inspirant, bring the legs back to the initial position. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Leg_Curls/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Machine Squat', 'Quadriceps', 'Machine', '1. Adjust the leg machine to a height that will allow you to get inside it with your genoux bent and the cuisses slightly below parallel. 2. Once you select the poids, position yourself inside the machine face up with the genoux bent and cuisses slightly below parallel to the platform. Make sure that the genoux do not go past the toes. The angle created between the ischio-jambiers and the mollets should be one that is slightly less than 90 degrees (since your position de depart requires you to start slightly below parallel). votre dos and your head should be resting on the machine while your epaules are pressed under the epaules pads. 3. Place vos mains by the handles and position vos pieds slightly pointing out at a epaules width position. Position de depart. 4. While pressing with the balls of the feet as you Expirez, make your whole body erect as you squeeze the quads. Maintenez 1 seconde. Conseil : Since you are starting below parallel, you can opt to use vos mains to help you up by pressing on your cuisses only on the first repetition. 5. Lentement, squat down en inspirant but instead of going all the way down to the position de depart, just stop once your cuisses are parallel to the platform. The angle between your ischio-jambiers and mollets should be a 90-degree angle. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Machine_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying One-Arm Lateral Raise', 'Épaules', 'Haltères', '1. While holding a halteres in one hand, lay with your poitrine down on a flat banc. The other hand can be used to hold to the leg of the banc for stability. 2. Position the palm of the hand that is holding the halteres in a neutral manner (palms facing your torse) as you keep the arm extended with the coudes slightly bent. Position de depart. 3. Now raise the arm with the halteres to the side until your coudes is at epaules height and your arm is roughly parallel to le sol en expirant. Conseil : Maintain your arm perpendicular to the torse while keeping your arm extended throughout le mouvement. Also, keep the contraction at the top for a second. 4. Lentement, lower the halteres to the position de depart en inspirant. 5. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_One-Arm_Lateral_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Prone Quadriceps', 'Quadriceps', 'Poids de corps', '1. Lay face down on le sol with your partner kneeling beside you. Flex one genoux and raise that leg off the ground, attempting to touch your fessiers with your foot. Your partner should hold the genoux and ankle. Position de depart. 2. Attempt to extend your genoux while your partner prevents any actual movement. 3. After 10-20 seconds, relax your muscles as your partner gently pushes the foot towards your fessiers, further stretching the quadriceps and hip flexors. 4. After 10-20 seconds, switch sides.', 'Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Prone_Quadriceps/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Rear Delt Raise', 'Épaules', 'Haltères', '1. While holding a halteres in each hand, lay with your poitrine down on a flat banc. 2. Position the palms of the hands in a neutral manner (palms facing your torse) as you keep the arms extended with the coudes slightly bent. Position de depart. 3. Now raise the arms to the side until your coudes are at epaules height and vos bras are roughly parallel to le sol en expirant. Conseil : Maintain vos bras perpendicular to the torse while keeping them extended throughout le mouvement. Also, keep the contraction at the top for a second. 4. Lentement, lower the halteres to the position de depart en inspirant. 5. Repetez selon le nombre souhaite. and then switch to the other arm.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Rear_Delt_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Supine Dumbbell Curl', 'Biceps', 'Haltères', '1. Allongez-vous sur un banc plat face up while holding a halteres in each arm on top of your cuisses. 2. Bring the halteres to the sides with the arms extended and the palms of the hands facing your cuisses (neutral grip). 3. While keeping the arms close to your torse and coudes in, Lentement, lower vos bras (as you keep them extended with a slight bend at the coudes) as far down towards le sol as you can go. Once you cannot go down any further, lock your upper arms in that position and that will be your position de depart. 4. As you Expirez, Lentement, begin to curl the poids up as you simultaneously rotate your poignets so that the palms of the hands face up. Continue curling the poids until your biceps are entierement contracte and squeeze hard at the top position for a second. Conseil : Only the forearms should move. Upper arms should remain stationary and coudes should stay in throughout le mouvement. 5. Return back to the position de depart very slowly.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Supine_Dumbbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying T-Bar Row', 'Milieu du dos', 'Machine', '1. Load up the T-bar Row Machine with the desired poids and adjust the leg height so that your upper poitrine is at the top of the pad. Conseil : In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper poitrine at the top of the pad. 2. Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of votre dos you want to emphasize. 3. Lift the bar off the rack and extend vos bras in front of you. Position de depart. 4. en expirant Lentement, pull the poids up and squeeze votre dos at the top of le mouvement. Conseil : Keep the upper arms as close to the torse as possible throughout le mouvement in order to better engage the back muscles. Also, do not lift votre corps off of the pad at any time and refrain from using the biceps to lift the poids. 5. After a second contraction at the top of le mouvement, en inspirant, Lentement, go back down to the position de depart. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_T-Bar_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Lying Triceps Press', 'Triceps', 'Barre EZ', '1. Allongez-vous sur un banc plat with either an e-z bar (my preference) or a straight bar placed on le sol behind your head and vos pieds on le sol. 2. Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you bras tendus. Conseil : The arms should be perpendicular to the torse and le sol. The coudes should be tucked in. Position de depart. 3. As you Inspirez, Lentement, lower the poids until the bar lightly touches your forehead while keeping the upper arms and coudes stationary. 4. At that point, use the triceps to bring the poids back up to the position de depart as you Expirez. 5. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Lying_Triceps_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Machine Bench Press', 'Pectoraux', 'Machine', '1. Sit down on the poitrine Press Machine and select the poids. 2. Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms. 3. Grab the handles with a palms-down grip and lift your coudes so that your upper arms are parallel to le sol to the sides of your torse. Conseil : Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the position de depart. 4. Now bring the handles back towards you as you Inspirez. 5. Push the handles away from you as you flex your pecs and you Expirez. Hold the contraction for a second before going back to the position de depart. 6. Repetez for the recommended amount of reps. 7. When finished step on the lever again and Lentement, get the handles back to their original place.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Machine Bicep Curl', 'Biceps', 'Machine', '1. Adjust the seat to the appropriate height and make your poids selection. Place your upper arms against the pads and grasp the handles. Position de depart. 2. Perform le mouvement by flexing the coudes, pulling your lower arm towards your upper arm. 3. Pause at the top of le mouvement, and then Lentement, return the poids to the position de depart. 4. Avoid returning the poids all the way to the stops until the set is complete to keep tension on the muscles being worked.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Bicep_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Machine Preacher Curls', 'Biceps', 'Machine', '1. Sit down on the Preacher Curl Machine and select the poids. 2. Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an prise en supination (palms facing up). Conseil : Make sure that when you place the arms on the pad you keep the coudes in. Position de depart. 3. Now lift the handles en expirant and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Conseil : Only the forearms should move. The upper arms should remain stationary and on the pad en permanence. 4. Lower the handles Lentement, back to the position de depart en inspirant. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Preacher_Curls/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Machine Shoulder (Military) Press', 'Épaules', 'Machine', '1. Sit down on the epaules Press Machine and select the poids. 2. Grab the handles to your sides as you keep the coudes bent and in line with your torse. Position de depart. 3. Now lift the handles en expirant and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second. 4. Lower the handles Lentement, back to the position de depart en inspirant. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Shoulder_Military_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Machine Triceps Extension', 'Triceps', 'Machine', '1. Adjust the seat to the appropriate height and make your poids selection. Place your upper arms against the pads and grasp the handles. Position de depart. 2. Perform le mouvement by extending the coudes, pulling your lower arm away from your upper arm. 3. Pause at the completion of le mouvement, and then Lentement, return the poids to the position de depart. 4. Avoid returning the poids all the way to the stops until the set is complete to keep tension on the muscles being worked.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Machine_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Medicine Ball Chest Pass', 'Pectoraux', 'Medecine ball', '1. You will need a partner for this exercise. Lacking one, this movement can be performed against a wall. 2. Begin facing your partner holding the medicine ball at your torse with both hands. 3. Pull the ball to your poitrine, and reverse the motion by extending through the coudes. For sports applications, you can take a step as you throw. 4. Your partner should catch the ball, and throw it back to you. 5. Receive the throw with both hands at poitrine height.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Medicine_Ball_Chest_Pass/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Medicine Ball Full Twist', 'Abdominaux', 'Medecine ball', '1. For this exercise you will need a medicine ball and a partner. Stand back to back with your partner, spaced 2-3 feet apart. Position de depart. 2. Hold the ball in front of the trunk. Open the hips and turn the epaules at the same time as your partner. 3. For full rotation, you and your partner should twist in the same direction, i.e. counter-clockwise. 4. Pass the ball to your partner, and both of you can now twist in the opposite direction to Repetez the procedure.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Medicine_Ball_Full_Twist/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Medicine Ball Scoop Throw', 'Épaules', 'Medecine ball', '1. Assume a semisquat stance with a medicine ball in vos mains. vos bras should hang so the ball is near vos pieds. 2. Begin by thrusting the hips forward as you extend through the legs, jumping up. 3. As you do, swing vos bras up and over your head, keeping them extended, releasing the ball at the peak of your movement. The goal is to throw the ball the greatest distance behind you.', 'Muscles secondaires : Abdominaux, Ischio-jambiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Medicine_Ball_Scoop_Throw/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Middle Back Shrug', 'Milieu du dos', 'Haltères', '1. Lie facedown on an incline banc while holding a halteres in each hand. vos bras should be fully extended hanging down and pointing towards le sol. The palms of vos mains should be facing each other. Position de depart. 2. en expirant, squeeze your omoplates together and hold the contraction for a full second. Conseil : This movement is just like the reverse action of a hug, or trying to perform rear laterals as if you had no arms. 3. en inspirant go back to the position de depart. 4. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Middle_Back_Shrug/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Middle Back Stretch', 'Milieu du dos', 'Autre', '1. Stand so vos pieds are epaules width apart and vos mains are on your hips. 2. Twist at your waist until you feel a stretch. Hold for 10 to 15 seconds, then twist to the other side.', 'Muscles secondaires : Abdominaux, Dos, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Middle_Back_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Mixed Grip Chin', 'Milieu du dos', 'Autre', '1. Using a spacing that is just about 1 inch wider than epaules width, grab a pull-up bar with the palms of one hand facing forward and the palms of the other hand facing towards you. Position de depart. 2. Now start to pull yourself up en expirant. Conseil : With the arm that has the palms facing up concentrate on using the back muscles in order to perform le mouvement. The coudes of that arm should remain close to the torse. With the other arm that has the palms facing forward, the coudes will be away but in line with the torse. You will concentrate on using the lats to pull votre corps up. 3. After a second contraction at the top, start to Lentement, come down en inspirant. 4. Repetez selon le nombre souhaite. 5. On the following set, switch grips; so if you had the right hand with the palms facing you and the left one with the palms facing forward, on the next set you will have the palms facing forward for the right hand and facing you for the left.', 'Muscles secondaires : Biceps, Dos. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Mixed_Grip_Chin/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Monster Walk', 'Abducteurs', 'Élastique', '1. Place a band around both ankles and another around both genoux. There should be enough tension that they are tight when vos pieds are epaules width apart. 2. To begin, take short steps forward alternating your left and right foot. 3. After several steps, do just the opposite and walk backward to where you started.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Monster_Walk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Mountain Climbers', 'Quadriceps', 'Autre', '1. Begin in a pushup position, with your poids supported by vos mains and toes. Flexing the genoux and hip, bring one leg until the genoux is approximately under the hip. Position de depart. 2. Explosively reverse the positions of vos jambes, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and genoux flexed. Repetez in an alternating fashion for 20-30 seconds.', 'Muscles secondaires : Pectoraux, Ischio-jambiers, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Mountain_Climbers/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Moving Claw Series', 'Ischio-jambiers', 'Autre', '1. This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the genoux, aiming to kick your fessiers as the hip extends. 2. Reload the quad as the leg moves back forward, attacking the ground on the next step. 3. Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion.', 'Muscles secondaires : Mollets, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Moving_Claw_Series/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Muscle Snatch', 'Ischio-jambiers', 'Barre', '1. Begin with a loaded barre held at the mid cuisses position with a prise large. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the poitrine up and the head looking forward. The epaules should be just in front of the bar. This will be the position de depart. 2. Begin the pull by driving through the front of the heels, raising the bar. Transition into the second pull by extending through the hips genoux and ankles, driving the bar up as quickly as possible. The bar should be close to the body. 3. Continue raising the bar to the overhead position, without rebending the genoux.', 'Muscles secondaires : Fessiers, Bas du dos, Quadriceps, Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Muscle_Snatch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Muscle Up', 'Dos', 'Autre', '1. Grip the rings using a false grip, with the base of your palms on top of the rings. Initiate a pull up by pulling the coudes down to your side, flexing the coudes. 2. As you reach the top position of the pull-up, pull the rings to your armpits as you roll your epaules forward, allowing your coudes to move straight back behind you. This puts you into the proper position to continue into the dip portion of le mouvement. 3. Maintaining control and stability, extend through the coudes to complete the motion. 4. Use care when lowering yourself to the ground.', 'Muscles secondaires : Abdominaux, Biceps, Avant-bras, Milieu du dos, Épaules, Trapèzes, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Muscle_Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Narrow Stance Hack Squats', 'Quadriceps', 'Machine', '1. Place the back of your torse against the back pad of the machine and hook your epaules under the epaules pads provided. 2. Position vos jambes in the platform using a less than epaules width narrow stance with the toes slightly pointed out. vos pieds should be around 3 inches or less apart. Conseil : Keep your head up en permanence and also maintain the back on the pad en permanence. 3. Place vos bras on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position). 4. Now straighten vos jambes without locking the genoux. Position de depart. 5. Begin to Lentement, lower the unit by bending the genoux as you maintain a straight posture with the head up (back on the pad en permanence). Continue down until the angle between the upper leg and the mollets becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to le sol). Inhale as you perform this portion of le mouvement. 6. Begin to raise the unit en expirant by pushing le sol with mainly with the heels of vos pieds as you straighten the legs again and go back to the position de depart. 7. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Narrow_Stance_Hack_Squats/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Narrow Stance Leg Press', 'Quadriceps', 'Machine', '1. Using a leg press machine, sit down on the machine and place vos jambes on the platform directly in front of you at a less-than-epaules-width narrow stance with the toes slightly pointed out. vos pieds should be around 3 inches or less apart. Conseil : Keep your head up en permanence and also maintain the back on the pad en permanence. 2. Lower the safety bars holding the weighted platform in place and press the platform all the way up until vos jambes are fully extended in front of you. Conseil : Make sure that you do not lock your genoux. Your torse and the legs should make a perfect 90-degree angle. Position de depart. 3. en inspirant, Lentement, lower the platform until your upper and lower legs make a 90-degree angle. 4. Pushing mainly with the heels of vos pieds and using the quadriceps go back to the position de depart en expirant. 5. Repetez selon le nombre souhaite. and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Narrow_Stance_Leg_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Narrow Stance Squats', 'Quadriceps', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your epaules (slightly below the neck) across it. 2. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Step away from the rack and position vos jambes using a less-than-epaules-width narrow stance with the toes slightly pointed out. Feet should be around 3-6 inches apart. Keep your head up en permanence (looking down will get you off balance) and maintain a straight back. Position de depart. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section). 4. Begin to Lentement, lower the bar by bending the genoux as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the mollets becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to le sol). Inhale as you perform this portion of le mouvement. Conseil : If you performed the exercise correctly, the front of the genoux should make an imaginary straight line with the toes that is perpendicular to the front. If your genoux are past that imaginary line (if they are past your toes) then you are placing undue stress on the genoux and the exercise has been performed incorrectly. 5. Begin to raise the bar en expirant by pushing le sol with the heel of your foot mainly as you straighten the legs again and go back to the position de depart. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Narrow_Stance_Squats/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Natural Glute Ham Raise', 'Ischio-jambiers', 'Poids de corps', '1. Using the leg pad of a lat pulldown machine or a preacher banc, position yourself so that your ankles are under the pads, genoux on the seat, and you are facing away from the machine. You should be upright and maintaining good posture. 2. Position de depart. Lower yourself under control until your genoux are almost completely straight. 3. Remaining in control, raise yourself back up to the position de depart. 4. If you are unable to complete a rep, use a band, a partner, or push off of a box to aid in completing a repetition.', 'Muscles secondaires : Mollets, Fessiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Natural_Glute_Ham_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Neck-SMR', 'Cou', 'Autre', '1. Using a muscle roller or a rolling pin, place the roller behind your head and against your neck. Make sure that you do not place the roller directly against the spine, but turned slightly so that the roller is pressed against the muscles to either side of the spine. Position de depart. 2. Starting at the top of your neck, Lentement, roll down the muscles of your neck, pausing at points of tension for 10-30 seconds.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Neck-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Neck Press', 'Pectoraux', 'Barre', '1. Allongez-vous au sol on a flat banc. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of le mouvement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with vos bras locked. Position de depart. 2. As you Inspirez, come down Lentement, until you feel the bar on your neck. 3. Apres une pause, bring the bar back to the position de depart as you Expirez and push the bar using your poitrine muscles. Lock vos bras and squeeze your poitrine in the contracted position, Maintenez 1 seconde and then start coming down Lentement, again. Conseil : It should take at least twice as long to go down than to come up). 4. Repetez le mouvement for the prescribed amount of repetitions. 5. When you are done, place the bar back in the rack.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Neck_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Oblique Crunches', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against le sol. 2. Make sure vos pieds are elevated and resting on a flat surface. 3. Now lift the epaules in which your hand is touching your head. 4. Simply elevate your epaules and body upward until you touch your genoux. For example, if you have your right hand besides your head, then you want to elevate votre corps upwards until your right coudes touches your left genoux. The same variation can be applied doing the inverse and using your left coudes to touch your right genoux. 5. After your genoux touches your coudes, lower votre corps until you have reached the position de depart. 6. Remember to Inspirez during the eccentric (lowering) part of the exercise and to Expirez during the concentric (upward) part of the exercise. 7. Continue alternating in this manner until all of the recommended repetitions for each side have been completed.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Oblique_Crunches/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Oblique Crunches - On The Floor', 'Abdominaux', 'Poids de corps', '1. Start out by lying on your right side with vos jambes lying on top of each other. Make sure your genoux are bent a little bit. 2. Place your left hand behind your head. 3. Once you are in this set position, begin by moving your left coudes up as you would perform a normal crunch except this time the main emphasis is on your obliques. 4. Crunch as high as you can, hold the contraction for a second and then Lentement, drop back down into the position de depart. 5. Remember to Inspirez during the eccentric (lowering) part of the exercise and to Expirez during the concentric (elevation) part of the exercise.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Oblique_Crunches_-_On_The_Floor/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Olympic Squat', 'Quadriceps', 'Barre', '1. Begin with a barre supported on top of the traps. The poitrine should be up, and the head facing forward. Adopt a hip width stance with the feet turned out as needed. 2. Descend by flexing the genoux, refraining from moving the hips back as much as possible. This requires that the genoux travel forward; ensure that they stay aligned with the feet. The goal is to keep the torse as upright as possible. Continue all the way down, keeping the poids on the front of the heel. 3. At the moment the upper legs contact the lower, reverse the motion, driving the poids upward.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Olympic_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('On-Your-Back Quad Stretch', 'Quadriceps', 'Autre', '1. Allongez-vous sur un banc plat or step, and hang one leg and arm over the side. 2. Bend the genoux and hold the top of the foot. As you do this, be careful not to arch your lower back. 3. Pull the belly button to the spine to stay in neutral. Press your foot down and into your hand. To add the hip stretch, lift the hip of the leg you''re holding up toward the ceiling. 4. Switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/On-Your-Back_Quad_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('On Your Side Quad Stretch', 'Quadriceps', 'Autre', '1. Start off by lying on your right side, with your right genoux bent at a 90-degree angle resting on le sol in front of you (this stabilizes the torse). 2. Bend your left genoux behind you and hold your left foot with your left hand. To stretch your hip flexor, press your left hip forward as you push your left foot back into your hand. Switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/On_Your_Side_Quad_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Dumbbell Row', 'Milieu du dos', 'Haltères', '1. Choose a flat banc and place a halteres on each side of it. 2. Place the right leg on top of the end of the banc, bend your torse forward from the waist until your upper body is parallel to le sol, and place your right hand on the other end of the banc for support. 3. Use the left hand to pick up the halteres on le sol and hold the poids while keeping your lower back straight. The palm of the hand should be facing your torse. Position de depart. 4. Pull the resistance straight up to the side of your poitrine, keeping your upper arm close to your side and keeping the torse stationary. Expirez as you perform this step. Conseil : Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torse should remain stationary and only the arms should move. The forearms should do no other work except for holding the halteres; therefore do not try to pull the halteres up using the forearms. 5. Lower the resistance straight down to the position de depart. Inspirez as you perform this step. 6. Repetez le mouvement for the specified amount of repetitions. 7. Switch sides and Repetez again with the other arm.', 'Muscles secondaires : Biceps, Dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Dumbbell_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Flat Bench Dumbbell Flye', 'Pectoraux', 'Haltères', '1. Allongez-vous sur un banc plat with a halteres in one hand resting on top of your cuisses. The palm of your hand with the halteres in it should be at a neutral grip. 2. By using your cuisses to help you get the halteres up, clean the halteres so that you can hold it in front of you with your lifting arm being fully extended. Remember to maintain a neutral grip with this exercise. Your non lifting hand should be to the side holding the flat banc for better support. Position de depart. 3. Your arm with the poids should have a slight bend on your coudes in order to prevent stress at the biceps tendon. Begin by lowering your arm with the poids in it out in a wide arc until you feel a stretch on your poitrine. Inspirez as you perform this portion of le mouvement. Conseil : Keep in mind that throughout le mouvement, your lifting arm should remain stationary; le mouvement should only occur at the epaules joint. 4. Return your lifting arm back to the position de depart as you squeeze your poitrine muscles and Expirez. Conseil : Make sure to use the same arc of motion used to lower the poids. 5. Maintenez 1 seconde at the contracted position and Repetez le mouvement for the prescribed amount of repetitions. 6. Switch arms and Repetez the exercise.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Flat_Bench_Dumbbell_Flye/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm High-Pulley Cable Side Bends', 'Abdominaux', 'Poulie', '1. Connect a standard handle to a tower. Move cable to highest pulley position. 2. Tenez-vous debout avec side to cable. With one hand, reach up and grab handle with prise en supination. 3. Pull down cable until coudes touches your side and the handle is by your epaules. 4. Position feet hip-width apart. Place free hand on hip to help gauge pivot point. 5. Keep arm in static position. Contract oblique to bring the poids down in a side crunch. 6. Once you reach maximum contraction, Lentement, release the poids to the position de depart. The poids stack should never be unloaded in a resting position. The aim is constant tension during the set. 7. Repetez to failure. 8. Then, reposition and Repetez the same series of movements on the opposite side.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_High-Pulley_Cable_Side_Bends/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Incline Lateral Raise', 'Épaules', 'Haltères', '1. Lie down sideways on an incline banc press with a halteres in the hand. Make sure the epaules is pressing against the incline banc and the arm is lying across votre corps with the palm around your navel. 2. Hold a halteres in your uppermost arm while keeping it extended in front of you parallel to le sol. Position de depart. 3. While keeping the halteres parallel to le sol en permanence, perform a lateral raise. Your arm should travel straight up until it is pointing at the ceiling. Conseil : Exhale as you perform this movement. Hold the halteres in the position and feel the contraction in the epaules for a second. 4. While inhaling lower the poids across votre corps back into the position de depart. 5. Repetez le mouvement for the prescribed amount of repetitions. 6. Switch arms and Repetez le mouvement.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Incline_Lateral_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Clean', 'Ischio-jambiers', 'Kettlebell', '1. Place a kettlebells between vos pieds. As you bend down to grab the kettlebells, push your butt back and keep your eyes looking forward. 2. Clean the kettlebells to your epaules by extending through the legs and hips as you raise the kettlebells towards your epaules. The poignets should rotate as you do so. 3. Return the poids to the position de depart.', 'Muscles secondaires : Fessiers, Bas du dos, Épaules, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Clean and Jerk', 'Épaules', 'Kettlebell', '1. Hold a kettlebells by the handle. 2. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so, so that the palm faces forward. 3. Dip votre corps by bending the genoux, keeping your torse upright. 4. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebells overhead to lockout by extending the arms, using votre corps''s momentum to move the poids. 5. Receive the poids overhead by returning to a squat position underneath the poids. 6. Keeping the poids overhead, return to a standing position. Lower the poids to le sol to perform the next repetition.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Clean_and_Jerk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Floor Press', 'Pectoraux', 'Kettlebell', '1. Allongez-vous au sol holding a kettlebells with one hand, with your upper arm supported by le sol. The palm should be facing in. 2. Press the kettlebells straight up toward the ceiling, rotating your poignets. 3. Lower the kettlebells back to the position de depart and Repetez.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Floor_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Jerk', 'Épaules', 'Kettlebell', '1. Hold a kettlebells by the handle. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so, so that the palm faces forward. Position de depart. 2. Dip votre corps by bending the genoux, keeping your torse upright. 3. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebells overhead to lockout by extending the arms, using votre corps''s momentum to move the poids. Receive the poids overhead by returning to a squat position underneath the poids. Keeping the poids overhead, return to a standing position. 4. Lower the poids to perform the next repetition.', 'Muscles secondaires : Mollets, Quadriceps, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Jerk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Military Press To The Side', 'Épaules', 'Kettlebell', '1. Clean a kettlebells to your epaules. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so, so that the palm faces inward. Position de depart. 2. Look at the kettlebells and press it up and out until it is locked out overhead. 3. Lower the kettlebells back to your epaules under control and Repetez. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Military_Press_To_The_Side/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Para Press', 'Épaules', 'Kettlebell', '1. Clean a kettlebells to your epaules. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so, so that the palm faces forward. Position de depart. 2. Hold the kettlebells with the coudes out to the side, and press it up and out until it is locked out overhead. 3. Lower the kettlebells back to your epaules under control and Repetez. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Para_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Push Press', 'Épaules', 'Kettlebell', '1. Hold a kettlebells by the handle. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so, so that the palm faces forward. Position de depart. 2. Dip votre corps by bending the genoux, keeping your torse upright. 3. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebells overhead to lockout by extending the arms, using votre corps''s momentum to move the poids. Lower the poids to perform the next repetition.', 'Muscles secondaires : Mollets, Quadriceps, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Push_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Row', 'Milieu du dos', 'Kettlebell', '1. Place a kettlebells in front of vos pieds. Bend your genoux slightly and then push your butt out as much as possible as you bend over to get in the position de depart. Grab the kettlebells and pull it to your stomach, retracting your omoplates and flexing the coudes. Keep votre dos straight. Lower and Repetez.', 'Muscles secondaires : Biceps, Dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Snatch', 'Épaules', 'Kettlebell', '1. Place a kettlebells between vos pieds. Bend your genoux and push your butt back to get in the proper position de depart. 2. Look straight ahead and swing the kettlebells back between vos jambes. 3. Immediately reverse the direction and drive through with your hips and genoux, accelerating the kettlebells upward. As the kettlebells rises to your epaules rotate your hand and punch straight up, using momentum to receive the poids locked out overhead.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos, Trapèzes, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Snatch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Split Jerk', 'Épaules', 'Kettlebell', '1. Hold a kettlebells by the handle. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so, so that the palm faces forward. Position de depart. 2. Dip votre corps by bending the genoux, keeping your torse upright. 3. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebells overhead to lockout by extending the arms, using votre corps''s momentum to move the poids. 4. Receive the poids overhead by returning to a squat position underneath the poids, positioning one leg in front of you and one leg behind you. 5. Keeping the poids overhead, return to a standing position and bring vos pieds together. Lower the poids to perform the next repetition.', 'Muscles secondaires : Fessiers, Ischio-jambiers, Quadriceps, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Split_Jerk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Split Snatch', 'Épaules', 'Kettlebell', '1. Hold a kettlebells in one hand by the handle. 2. Squat towards le sol, and then reverse the motion, extending the hips, genoux, and finally the ankles, to raise the kettlebells overhead. 3. After fully extending the body, descend into a lunge position to receive the poids overhead, one leg forward and one leg back. Ensure you drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion. 4. Return to a standing position, holding the poids overhead, and bring the feet together. Lower the poids to Revenez en position de depart.', 'Muscles secondaires : Ischio-jambiers, Quadriceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Split_Snatch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Kettlebell Swings', 'Ischio-jambiers', 'Kettlebell', '', 'Muscles secondaires : Mollets, Fessiers, Bas du dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Kettlebell_Swings/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Long Bar Row', 'Milieu du dos', 'Barre', '1. Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate poids onto your end. 2. Stand next to the bar, and take a grip with one hand close to the collar. Using your hips and legs, rise to a standing position. 3. Assume a bent-genoux stance with your hips back and your poitrine up. Your arm should be extended. Position de depart. 4. Pull the poids to your side by retracting the epaules and flexing the coudes. Do not jerk the poids or cheat during le mouvement. 5. Apres une pause, Revenez en position de depart.', 'Muscles secondaires : Biceps, Dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Long_Bar_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Medicine Ball Slam', 'Abdominaux', 'Medecine ball', '1. Start in a standing position with a staggered, athletic stance. Hold a medicine ball in one hand, on the same side as votre dos leg. Position de depart. 2. Begin by winding the arm, raising the medicine ball above your head. As you do so, extend through the hips, genoux, and ankles to load up for the slam. 3. At peak extension, flex the epaules, spine, and hips to throw the ball hard into the ground directly in front of you. 4. Catch the ball on the bounce and continue for the desired number of repetitions.', 'Muscles secondaires : Dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Medicine_Ball_Slam/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Open Palm Kettlebell Clean', 'Ischio-jambiers', 'Kettlebell', '1. Place one kettlebells between vos pieds. 2. Grab the handle with one hand and raise the kettlebells rapidly, let it flip so that the ball of the kettlebells lands in the palm of your hand. 3. Throw the kettlebells out in front of you and catch the handle with one hand. 4. Take the kettlebells to le sol and Repetez. Make sure to work both arms.', 'Muscles secondaires : Avant-bras, Fessiers, Bas du dos, Quadriceps, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Open_Palm_Kettlebell_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Overhead Kettlebell Squats', 'Quadriceps', 'Kettlebell', '1. Clean and press a kettlebells with one arm. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so. Press the poids overhead by extending through the coudes.Position de depart. 2. Looking straight ahead and keeping a kettlebells locked out above you, flex the genoux and hips and lower your torse between vos jambes, keeping your head and poitrine up. 3. Pause at the bottom position for a second before rising back to the top, driving through the heels of vos pieds.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Épaules. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Overhead_Kettlebell_Squats/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Side Deadlift', 'Quadriceps', 'Barre', '1. Stand to the side of a barre next to its center. Bend your genoux and lower votre corps until you are able to reach the barre. 2. Grasp the bar as if you were grabbing a briefcase (palms facing you since the bar is sideways). You may need a poignets wrap if you are using a significant amount of poids. Position de depart. 3. Use vos jambes to help lift the barre up while exhaling. vos bras should extend fully as bring the barre up until you are in a standing position. 4. Lentement, bring the barre back down while inhaling. Conseil : Make sure to bend your genoux while lowering the poids to avoid any injury from occurring. 5. Repetez selon le nombre souhaite. 6. Switch arms and Repetez le mouvement.', 'Muscles secondaires : Abdominaux, Mollets, Fessiers, Ischio-jambiers, Bas du dos, Trapèzes. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Side_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Arm Side Laterals', 'Épaules', 'Haltères', '1. Pick a halteres and place it in one of vos mains. Your non lifting hand should be used to grab something steady such as an incline banc press. Lean towards your lifting arm and away from the hand that is gripping the incline banc as this will allow you to keep your balance. 2. Tenez-vous debout avec a straight torse and have the halteres by your side at arm''s length with the palm of the hand facing you. Position de depart. 3. While maintaining the torse stationary (no swinging), lift the halteres to your side with a slight bend on the coudes and your hand slightly tilted forward as if pouring water in a glass. Continue to go up until you arm is parallel to le sol. Exhale as you execute this movement and pause for a second at the top. 4. Lower the halteres back down Lentement, to the position de depart en inspirant. 5. Repetez selon le nombre souhaite. 6. Switch arms and Repetez the exercise.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Arm_Side_Laterals/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One-Legged Cable Kickback', 'Fessiers', 'Poulie', '1. Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle. 2. Face the poids stack from a distance of about two feet, grasping the steel frame for support. 3. While keeping your genoux and hips bent slightly and your abdominaux tight, contract your fessiers to Lentement, "kick" the working leg back in a semicircular arc as high as it will comfortably go as you Expirez. Conseil : At full extension, squeeze your fessiers for a second in order to achieve a peak contraction. 4. Now Lentement, bring your working leg forward, resisting the pull of the cable until you reach the position de depart. 5. Repetez selon le nombre souhaite. 6. Switch legs and Repetez le mouvement for the other side.', 'Muscles secondaires : Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One-Legged_Cable_Kickback/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Arm Against Wall', 'Dos', 'Autre', '1. From a standing position, place a bent arm against a wall or doorway. 2. Lentement, lean toward your arm until you feel a stretch in your lats.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Against_Wall/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Arm Chin-Up', 'Milieu du dos', 'Autre', '1. For this exercise, start out by placing a towel around a chin up bar. 2. Grab the chin-up bar with your palm facing you. One hand will be grabbing the chin-up bar and the other will be grabbing the towel. 3. Bring your torse back around 30 degrees or so while creating a curvature on your lower back and sticking your poitrine out. Position de depart.v 4. Pull your torse up until the bar touches your upper poitrine by drawing the epaules and the upper arms down and back. Exhale as you perform this portion of le mouvement. Conseil : Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torse should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar. 5. After a second on the contracted position, start to inhale and Lentement, lower your torse back to the position de depart when vos bras are fully extended and the lats are fully stretched. 6. Repetez this motion for the prescribed amount of repetitions. 7. Switch arms and Repetez le mouvement.', 'Muscles secondaires : Biceps, Avant-bras, Dos. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Chin-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Arm Dumbbell Bench Press', 'Pectoraux', 'Haltères', '1. Allongez-vous sur un banc plat with a halteres in one hand on top of your cuisses. 2. By using your cuisses to help you get the halteres up, clean the halteres up so that you can hold it in front of you at epaules width. Use the hand you are not lifting with to help position the halteres over you properly. 3. Once at epaules width, rotate your poignets forward so that the palm of your hand is facing away from you. Position de depart. 4. Bring down the poids Lentement, to your side as you Inspirez. Keep full control of the halteres en permanence. Conseil : Use the hand that you are not lifting with to help keep the halteres balance as you may struggle a bit at first. Only use your non-lifting hand if it is needed. Otherwise, keep it resting to the side. 5. As you Expirez, push the halteres up using your pectoral muscles. Lock vos bras in the contracted position, squeeze your poitrine, Maintenez 1 seconde and then start coming down slowly. Conseil : It should take at least twice as long to go down than to come up. 6. Repetez le mouvement for the prescribed amount of repetitions of your training program. 7. Switch arms and Repetez le mouvement.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Dumbbell_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Arm Dumbbell Preacher Curl', 'Biceps', 'Haltères', '1. Grab a halteres with the right arm and place the upper arm on top of the preacher banc or the incline banc. The halteres should be held at epaules length. Position de depart. 2. As you Inspirez, Lentement, lower the halteres until your upper arm is extended and the biceps is fully stretched. 3. en expirant, use the biceps to curl the poids up until your biceps is entierement contracte and the halteres is at epaules height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb. 4. Squeeze the biceps hard for a second at the contracted position and Repetez selon le nombre souhaite. 5. Switch arms and Repetez le mouvement.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Dumbbell_Preacher_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Arm Floor Press', 'Triceps', 'Barre', '1. Lie down on a flat surface with votre dos pressing against le sol or an exercise mat. Make sure your genoux are bent. 2. Have a partner hand you the bar on one hand. When starting, your arm should be just about fully extended, similar to the position de depart of a barre banc press. However, this time your grip will be neutral (palms facing your torse). 3. Make sure the hand you are not using to lift the poids is placed by your side. 4. Begin the exercise by lowering the barre until your coudes touches the ground. Make sure to Inspirez as this is the eccentric (lowering part of the exercise). 5. Then start lifting the barre back up to the original position de depart. Remember to Expirez during the concentric (lifting part of the exercise). 6. Repetez until you have performed your recommended repetitions. 7. Switch arms and Repetez le mouvement.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Floor_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Arm Lat Pulldown', 'Dos', 'Poulie', '1. Select an appropriate poids and adjust the genoux pad to help keep you down. Grasp the handle with a pronated grip. Position de depart. 2. Pull the handle down, squeezing your coudes to your side as you flex the coudes. 3. Pause at the bottom of the motion, and then Lentement, return the handle to the position de depart. 4. For multiple repetitions, avoid completely returning the poids to keep tension on the muscles being worked.', 'Muscles secondaires : Biceps, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Lat_Pulldown/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Arm Pronated Dumbbell Triceps Extension', 'Triceps', 'Haltères', '1. Lie flat on a banc while holding a halteres bras tendus. Your arm should be perpendicular to votre corps. The palm of your hand should be facing towards vos pieds as a pronated grip is required to perform this exercise. 2. Place your non lifting hand on your biceps for support. 3. Lentement, begin to lower the halteres down as you Inspirez. 4. Then, begin lifting the halteres upward as you contract the triceps. Remember to Expirez during the concentric (lifting part of the exercise). 5. Repetez until you have performed your set repetitions. 6. Switch arms and Repetez le mouvement.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Pronated_Dumbbell_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Arm Supinated Dumbbell Triceps Extension', 'Triceps', 'Haltères', '1. Lie flat on a banc while holding a halteres bras tendus. Your arm should be perpendicular to votre corps. The palm of your hand should be facing towards your face as a supinated grip is required to perform this exercise. 2. Place your non lifting hand on your biceps for support. 3. Lentement, begin to lower the halteres down as you Inspirez. 4. Then, begin lifting the halteres upward as you contract the triceps. Remember to Expirez during the concentric (lifting part of the exercise). 5. Repetez until you have performed your set repetitions. 6. Switch arms and Repetez le mouvement. 7. Switch arms again and Repetez le mouvement.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Arm_Supinated_Dumbbell_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Half Locust', 'Quadriceps', 'Autre', '1. Lie facedown on le sol. 2. Put your left hand under your left hipbone to pad your hip and pubic bone. 3. Bend your right genoux so you can hold the foot in your right hand. 4. Lift the foot in the air and simultaneously lift your epaules off le sol. This also stretches the right hip flexor and the poitrine and epaules. Switch sides. If it doesn''t bother votre dos, you can try it with both arms and legs at the same time.', 'Muscles secondaires : Abdominaux, Biceps, Pectoraux. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Half_Locust/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Handed Hang', 'Dos', 'Autre', '1. Grab onto a chinup bar with one hand, using a pronated grip. Keep vos pieds on le sol or a step. Allow the majority of your poids to hang from that hand, while keeping vos pieds on the ground. Hold for 10-20 seconds and switch sides.', 'Muscles secondaires : Biceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Handed_Hang/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Knee To Chest', 'Fessiers', 'Autre', '1. Start off by lying on le sol. 2. Extend one leg straight and pull the other genoux to your poitrine. Hold under the genoux joint to protect the kneecap. 3. Gently tug that genoux toward your nose. 4. Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg.', 'Muscles secondaires : Ischio-jambiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Knee_To_Chest/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('One Leg Barbell Squat', 'Quadriceps', 'Barre', '1. Start by standing about 2 to 3 feet in front of a flat banc with votre dos facing the banc. Have a barre in front of you on le sol. Conseil : vos pieds should be epaules width apart from each other. 2. Bend the genoux and use a pronated grip with vos mains being wider than epaules width apart from each other to lift the barre up until you can rest it on your poitrine. 3. Then lift the barre over your head and rest it on the base of your neck. Move one foot back so that your toe is resting on the flat banc. Your other foot should be stationary in front of you. Keep your head up en permanence as looking down will get you off balance and also maintain a straight back. Conseil : Make sure votre dos is straight and poitrine is out while performing this exercise. 4. en inspirant, Lentement, lower your leg until your cuisses is parallel to le sol. At this point, your genoux should be over your toes. Your poitrine should be directly above the middle of your cuisses. 5. Leading with the poitrine and hips and contracting the quadriceps, elevate your leg back to the position de depart en expirant. 6. Repetez selon le nombre souhaite. 7. Switch legs and Repetez le mouvement.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/One_Leg_Barbell_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Open Palm Kettlebell Clean', 'Ischio-jambiers', 'Kettlebell', '1. Place one kettlebells between vos pieds. Clean the kettlebells by extending through the legs and hips as you raise the kettlebells towards your epaules. 2. Release the kettlebells as it comes up, and let it flip so that the ball of the kettlebells lands in the palms of vos mains. 3. Release the kettlebells out in front of you and catch the handle with both hands. Lower the kettlebells to the position de depart and Repetez.', 'Muscles secondaires : Fessiers, Bas du dos, Quadriceps, Épaules. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Open_Palm_Kettlebell_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Otis-Up', 'Abdominaux', 'Autre', '1. Secure vos pieds and lay back on le sol. Your genoux should be bent. Hold a poids with both hands to your poitrine. Position de depart. 2. Initiate le mouvement by flexing the hips and spine to raise your torse up from the ground. 3. As you move up, press the poids up so that it is above your head at the top of le mouvement. 4. Return the poids to your poitrine as you reverse the sit-up motion, ensuring not to go all the way down to le sol.', 'Muscles secondaires : Pectoraux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Otis-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Overhead Cable Curl', 'Biceps', 'Poulie', '1. To begin, set a poids that is comfortable on each side of the pulley machine. Note: Make sure that the amount of poids selected is the same on each side. 2. Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your epaules. 3. Stand in the middle of both sides and use an prise en supination (palms facing towards the ceiling) to grab each handle. vos bras should be fully extended and parallel to le sol with vos pieds positioned epaules width apart from each other. votre corps should be evenly aligned the handles. Position de depart. 4. While exhaling, Lentement, squeeze the biceps on each side until your forearms and biceps touch. 5. While inhaling, move your forearms back to the position de depart. Note: Your entire body is stationary during this exercise except for the forearms. 6. Repetez selon le nombre souhaite. prescribed in your program.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Cable_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Overhead Lat', 'Dos', 'Autre', '1. Sit upright on le sol with your partner behind you. Raise one arm straight up, and flex the coudes, attempting to touch your hand to votre dos. Your parner should hold your triceps and poignets. Position de depart. 2. Attempt to pull your upper arm to your side as your partner prevents you from doing actually doing so. 3. After 10-20 seconds, relax the arm and allow your partner to further stretch the lat by applying gentle pressure to the triceps. Hold for 10-20 seconds, and then switch sides.', 'Muscles secondaires : Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Lat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Overhead Slam', 'Dos', 'Medecine ball', '1. Hold a medine ball with both hands and Tenez-vous debout avec vos pieds at epaules width. Position de depart. 2. Initiate the countermovement by raising the ball above your head and fully extending votre corps. 3. Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can. 4. Receive the ball with both hands on the bounce and Repetez le mouvement.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Slam/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Overhead Squat', 'Quadriceps', 'Barre', '1. Start out by having a barre in front of you on le sol. vos pieds should be wider than epaules width apart from each other. 2. Bend the genoux and use a pronated grip (palms facing you) to grab the barre. vos mains should be at a wider than epaules width apart from each other before lifting. Once you are positioned, lift the barre up until you can rest it on your poitrine. 3. Move the barre over and slightly behind your head and make sure vos bras are fully extended. Keep your head up en permanence and also maintain a straight back. Retract your omoplates. Position de depart. 4. Lentement, lower the poids by bending your genoux until your cuisses are parallel to the ground while inhaling. Conseil : Keep votre dos straight while performing this exercise to avoid any injuries and vos bras should remain extended and over your head en permanence. 5. Now use vos pieds and legs to help bring the poids back up to the position de depart while exhaling. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Abdominaux, Mollets, Fessiers, Ischio-jambiers, Bas du dos, Épaules, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Overhead Stretch', 'Abdominaux', 'Autre', '1. Standing straight up, lace your fingers together and open your palms to the ceiling. Keep your epaules down as you extend vos bras up. 2. To create a full torse stretch, pull your tailbone down and stabilize your torse as you do this. Stretch the muscles on both the front and the back of the torse.', 'Muscles secondaires : Pectoraux, Avant-bras, Dos, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Overhead Triceps', 'Triceps', 'Poids de corps', '1. Sit upright on le sol with your partner behind you. Raise one arm straight up, and flex the coudes, attempting to touch your hand to votre dos. Your parner should hold your coudes and poignets. Position de depart. 2. Attempt to extend the arm straight into the air as your partner prevents you from doing actually doing so. 3. After 10-20 seconds, relax the arm and allow your partner to further stretch the triceps by applying gentle pressure to the poignets. Hold for 10-20 seconds, and then switch sides.', 'Muscles secondaires : Dos. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Overhead_Triceps/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pallof Press', 'Abdominaux', 'Poulie', '1. Connect a standard handle to a tower, and—if possible—position the cable to epaules height. If not, a low pulley will suffice. 2. With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the poids on the cable. 3. With vos pieds positioned hip-width apart and genoux slightly bent, hold the cable to the middle of your poitrine. Position de depart. 4. Press the cable away from your poitrine, fully extending both arms. You sangle abdominale should be tight and engaged. 5. Hold the repetition for several seconds before returning to the position de depart. 6. At the conclusion of the set, Repetez facing the other direction.', 'Muscles secondaires : Pectoraux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pallof_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pallof Press With Rotation', 'Abdominaux', 'Poulie', '1. Connect a standard handle to a tower, and position the cable to epaules height. 2. With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the poids on the cable. Align outstretched arm with cable. 3. With vos pieds positioned hip-width apart, pull the cable into your poitrine and grab the handle with your other hand. Both hands should be on the handle at this time. 4. Facing forward, press the cable away from your poitrine. You sangle abdominale should be tight and engaged. 5. Keeping your hips straight, twist your torse away from the pulley until you get a full quarter rotation. 6. Maintain your rigid stance and straight arms. Return to the neutral position in a slow and controlled manner. vos bras should be extended in front of you. 7. With the side tension still engaging your sangle abdominale, bring vos mains to your poitrine and immediately press outward to a fully extended position. This constitutes one rep. 8. Repetez to failure. 9. Then, reposition and Repetez the same series of movements on the opposite side.', 'Muscles secondaires : Pectoraux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pallof_Press_With_Rotation/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Palms-Down Dumbbell Wrist Curl Over A Bench', 'Avant-bras', 'Haltères', '1. Start out by placing two halteres on one side of a flat banc. 2. Kneel down on both of your genoux so that votre corps is facing the flat banc. 3. Use vos bras to grab both of the halteres with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat banc. Your poignets should be hanging over the edge. 4. Start out by curling your poignets upwards and exhaling. 5. Lentement, lower your poignets back down to the position de depart while inhaling. 6. Your forearms should be stationary as your poignets is the only movement needed to perform this exercise. 7. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Palms-Down Wrist Curl Over A Bench', 'Avant-bras', 'Barre', '1. Start out by placing a barre on one side of a flat banc. 2. Kneel down on both of your genoux so that votre corps is facing the flat banc. 3. Use vos bras to grab the barre with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat banc. Your poignets should be hanging over the edge. 4. Start out by curling your poignets upwards and exhaling. 5. Lentement, lower your poignets back down to the position de depart while inhaling. 6. Your forearms should be stationary as your poignets is the only movement needed to perform this exercise. 7. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Palms-Up Barbell Wrist Curl Over A Bench', 'Avant-bras', 'Barre', '1. Start out by placing a barre on one side of a flat banc. 2. Kneel down on both of your genoux so that votre corps is facing the flat banc. 3. Use vos bras to grab the barre with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat banc. Your poignets should be hanging over the edge. 4. Start out by curling your poignets upwards and exhaling. 5. Lentement, lower your poignets back down to the position de depart while inhaling. 6. Your forearms should be stationary as your poignets is the only movement needed to perform this exercise. 7. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Palms-Up Dumbbell Wrist Curl Over A Bench', 'Avant-bras', 'Haltères', '1. Start out by placing two halteres on one side of a flat banc. 2. Kneel down on both of your genoux so that votre corps is facing the flat banc. 3. Use vos bras to grab both of the halteres with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat banc. Your poignets should be hanging over the edge. 4. Start out by curling your poignets upwards and exhaling. 5. Lentement, lower your poignets back down to the position de depart while inhaling. Make sure to inhale during this part of the exercise. 6. Your forearms should be stationary as your poignets is the only movement needed to perform this exercise. 7. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Parallel Bar Dip', 'Triceps', 'Autre', '1. Stand between a set of parallel bars. Place a hand on each bar, and then take a small jump to help you get into the position de depart with vos bras locked out. 2. Begin by flexing the coudes, lowering votre corps until vos bras break 90 degrees. Avoid swinging, and maintain good posture throughout the descent. 3. Reverse the motion by extending the coudes, pushing yourself back up into the position de depart. 4. Repetez for the desired number of repetitions.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Parallel_Bar_Dip/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pelvic Tilt Into Bridge', 'Bas du dos', 'Autre', '1. Lie down with vos pieds on le sol, heels directly under your genoux. 2. Lift only your tailbone to the ceiling to stretch your lower back. (Don''t lift the entire spine yet.) Pull in your stomach. 3. To go into a bridge, lift the entire spine except the neck.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pelvic_Tilt_Into_Bridge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Peroneals-SMR', 'Mollets', 'Foam roller', '1. Lay on your side, supporting your poids on your forearm and on a foam roller placed on the outside of your lower leg. Your upper leg can either be on top of your lower leg, or you can cross it in front of you. Position de depart. 2. Raise your hips off of the ground and begin to roll from below the genoux to above the ankle on the side of your leg, pausing at points of tension for 10-30 seconds. Repetez de l autre cote.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Peroneals-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Peroneals Stretch', 'Mollets', 'Autre', '1. In a seated position, loop a belt, rope, or band around one foot. Position de depart. 2. With the leg extended and the heel off of the ground, pull on the belt so that the foot is inverted, with the inside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Peroneals_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Physioball Hip Bridge', 'Fessiers', 'Swiss ball', '1. Lay on a ball so that your upper back is on the ball with your hips unsupported. Both feet should be flat on le sol, hip width apart or wider. Position de depart. 2. Begin by extending the hips using your fessiers and ischio-jambiers, raising your hips upward as you bridge. 3. Pause at the top of the motion and Revenez en position de depart.', 'Muscles secondaires : Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Physioball_Hip_Bridge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pin Presses', 'Triceps', 'Barre', '1. Pin presses remove the eccentric phase of the banc press, developing starting strength. They also allow you to train a desired range of motion. 2. The banc should be set up in a power rack. Set the pins to the desired point in your range of motion, whether it just be lockout or an inch off of your poitrine. The bar should be moved to the pins and prepared for lifting. 3. Begin by lying on the banc, with the bar directly above the contact point during your regular banc. Tuck vos pieds underneath you and arch votre dos. Using the bar to help support your poids, lift your epaules off the banc and retract them, squeezing the omoplates together. Use vos pieds to drive your traps into the banc. Maintain this tight body position throughout le mouvement. 4. You can take a standard banc grip, or epaules width to focus on the triceps. The bar, poignets, and coudes should stay in line en permanence. Focus on squeezing the bar and trying to pull it apart. 5. Drive the bar up with as much force as possible. The coudes should be tucked in until lockout. 6. Return the bar to the pins, pausing before beginning the next repetition.', 'Muscles secondaires : Pectoraux, Avant-bras, Dos, Milieu du dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pin_Presses/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Piriformis-SMR', 'Fessiers', 'Foam roller', '1. Sit with your buttocks on top of a foam roll. Bend your genoux, and then cross one leg so that the ankle is over the genoux. Position de depart. 2. Shift your poids to the side of the crossed leg, rolling over the buttocks until you feel tension in your upper fessiers. You may assist the stretch by using one hand to pull the bent genoux towards your poitrine. Hold this position for 10-30 seconds, and then switch sides.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Piriformis-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Plank', 'Abdominaux', 'Poids de corps', '1. Get into a prone position on le sol, supporting your poids on your toes and your forearms. vos bras are bent and directly below the epaules. 2. Keep votre corps straight en permanence, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plank/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Plate Pinch', 'Avant-bras', 'Autre', '1. Grab two wide-rimmed plates and put them together with the smooth sides facing outward 2. Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. Position de depart. 3. Squeeze the plate with your fingers and thumb. Hold this position for as long as you can. 4. Repetez for the recommended amount of sets prescribed in your program. 5. Switch arms and Repetez le mouvements.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plate_Pinch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Plate Twist', 'Abdominaux', 'Autre', '1. Allongez-vous au sol or an exercise mat with vos jambes fully extended and your upper body upright. Grab the plate by its sides with both hands out in front of your abdominals with vos bras slightly bent. 2. Lentement, cross vos jambes near your ankles and lift them up off the ground. Your genoux should also be bent slightly. Note: Move your upper body back slightly to help keep you balanced turning this exercise. Position de depart. 3. Move the plate to the left side and touch le sol with it. Expirez as you perform that movement. 4. Come back to the position de depart as you Inspirez and then Repetez le mouvement but this time to the right side of the body. Conseil : Use a slow controlled movement en permanence. Jerking motions can injure the back. 5. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plate_Twist/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Platform Hamstring Slides', 'Ischio-jambiers', 'Autre', '1. For this movement a wooden floor or similar is needed. Lay on votre dos with vos jambes extended. Place a gym towel or a light poids underneath your heel. Position de depart. 2. Begin le mouvement by flexing the genoux, keeping your other leg straight. 3. Continue bringing the heel closer to you, sliding it on le sol. 4. At full genoux flexion, reverse le mouvement to Revenez en position de depart.', 'Muscles secondaires : Fessiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Platform_Hamstring_Slides/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Plie Dumbbell Squat', 'Quadriceps', 'Haltères', '1. Hold a halteres at the base with both hands and stand straight up. Move vos jambes so that they are wider than epaules width apart from each other with your genoux slightly bent. 2. Your toes should be facing out. Note: vos bras should be stationary while performing the exercise. Position de depart. 3. Lentement, bend the genoux and lower vos jambes until your cuisses are parallel to le sol. Make sure to inhale as this is the eccentric part of the exercise. 4. Press mainly with the heel of the foot to bring the body back to the position de depart while exhaling. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Abdominaux, Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plie_Dumbbell_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Plyo Kettlebell Pushups', 'Pectoraux', 'Kettlebell', '1. Place a kettlebells on le sol. Place yourself in a pushup position, on your toes with one hand on the ground and one hand holding the kettlebells, with your coudes extended. Position de depart. 2. Begin by lowering yourself as low as you can, keeping votre dos straight. 3. Quickly and forcefully reverse direction, pushing yourself up to the other side of the kettlebells, switching hands as you do so. Continue le mouvement by descending and Repetezing le mouvement back and forth.', 'Muscles secondaires : Épaules, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plyo_Kettlebell_Pushups/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Plyo Push-up', 'Pectoraux', 'Poids de corps', '1. Move into a prone position on le sol, supporting your poids on vos mains and toes. 2. vos bras should be fully extended with the hands around epaules width. Keep votre corps straight throughout le mouvement. Position de depart. 3. Descend by flexing at the coudes, lowering your poitrine towards the ground. 4. At the bottom, reverse the motion by pushing yourself up through coudes extension as quickly as possible. Attempt to push your upper body up until vos mains leave the ground. 5. Revenez en position de depart and Repetez the exercise. 6. For added difficulty, add claps into le mouvement while you are air borne.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Plyo_Push-up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Posterior Tibialis Stretch', 'Mollets', 'Autre', '1. In a seated position, loop a belt, rope, or band around one foot. Position de depart. 2. With the leg extended and the heel off of the ground, pull on the belt so that the foot is everted, with the outside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Posterior_Tibialis_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Power Clean', 'Ischio-jambiers', 'Barre', '1. Tenez-vous debout avec vos pieds slightly wider than epaules width apart and toes pointing out slightly. 2. Squat down and grasp bar with a closed, pronated grip. vos mains should be slightly wider than epaules width apart outside genoux with coudes fully extended. 3. Place the bar about 1 inch in front of your shins and over the balls of vos pieds. 4. votre dos should be flat or slightly arched, your poitrine held up and out and your omoplates should be retracted. 5. Keep your head in a neutral position (in line with vertebral column and not tilted or rotated) with your eyes focused straight ahead. Inhale during this phase. 6. Lift the bar from le sol by forcefully extending the hips and the genoux en expirant. Conseil : The upper torse should maintain the same angle. Do not bend at the waist yet and do not let the hips rise before the epaules (this would have the effect of pushing the fessiers in the air and stretching the ischio-jambiers. 7. Keep coudes fully extended with the head in a neutral position and the epaules over the bar. 8. As the bar raises keep it as close to the shins as possible. 9. As the bar passes the genoux, thrust your hips forward and slightly bend the genoux to avoid locking them. Conseil : At this point your cuisses should be against the bar. 10. Keep the back flat or slightly arched, coudes fully extended and your head neutral. Conseil : You will hold your breath until the next phase. 11. Inhale and then forcefully and quickly extend your hips and genoux and stand on your toes. 12. Keep the bar as close to votre corps as possible. Conseil : votre dos should be flat with the coudes pointed out to the sides and your head in a neutral position. Also, keep your epaules over the bar and arms straight as long as possible. 13. When your lower body joints are fully extended, shrug the epaules upward rapidly without letting the coudes flex yet. Exhale during this portion of le mouvement. 14. As the epaules reach their highest elevation flex your coudes to begin pulling votre corps under the bar. 15. Continue to pull the arms as high and as long as possible. Conseil : Due to the explosive nature of this phase, your torse will be erect or with an arched back, your head will be tilted back slightly and vos pieds may lose contact with le sol. 16. After the lower body has fully extended and the bar reaches near maximal height, pull votre corps under the bar and rotate the arms around and under the bar. 17. Simultaneously, flex the hips and genoux into a quarter squat position. 18. Once the arms are under the bar, inhale and then lift your coudes to position the upper arms parallel to le sol. Rack the bar across the front of your collar bones and front epaules muscles. 19. Catch the bar with an erect and tight torse, a neutral head position and flat feet. Exhale during this movement. 20. Stand up by extending the hips and genoux to a fully erect position. 21. Lower the bar by gradually reducing the muscular tension of the arms to allow a controlled descent of the bar to the cuisses. Inhale during this movement. 22. Simultaneously flex the hips and genoux to cushion the impact of the bar on the cuisses. 23. Squat down with the coudes fully extended until the bar touches le sol. 24. Start over at Phase 1 and Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Avant-bras, Fessiers, Bas du dos, Milieu du dos, Quadriceps, Épaules, Trapèzes, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Power Clean from Blocks', 'Ischio-jambiers', 'Barre', '1. With a barre on boxes of the desired height, take a grip just outside the legs. Lower your hips with the poids focused on the heels, back straight, head facing forward, poitrine up, with your epaules just in front of the bar. Position de depart. 2. Begin the first pull by driving through the heels, extending your genoux. votre dos angle should stay the same, and vos bras should remain straight. As the bar approaches the mid-cuisses position, begin extending through the hips. 3. In a jumping motion, accelerate by extending the hips, genoux, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the poids. At the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. 4. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the coudes up and out. At peak extension, pull yourself under the bar far enough that it can be racked onto the epaules, rotating your coudes under the bar as you do so. The bar should be racked onto the protracted epaules, lightly touching the throat with the hands relaxed. 5. Immediately recover by driving through the heels, keeping the torse upright and coudes up. Continue until you have risen to a standing position, and complete the repetition by returning the poids to the boxes.', 'Muscles secondaires : Quadriceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Clean_from_Blocks/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Power Jerk', 'Quadriceps', 'Barre', '1. Standing with the poids racked on the front of the epaules, begin with the dip. With vos pieds directly under your hips, flex the genoux without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. 2. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the epaules. 3. At this moment as the feet leave le sol, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be moved to a slightly wider stance, with the genoux partially bent. 4. Receive the bar with the arms locked out overhead. 5. Return to a standing position.', 'Muscles secondaires : Abdominaux, Mollets, Fessiers, Ischio-jambiers, Épaules, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Jerk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Power Partials', 'Épaules', 'Haltères', '1. Tenez-vous debout avec your torse upright and a halteres on each hand being held bras tendus. The coudes should be close to the torse. 2. The palms of the hands should be facing your torse. vos pieds should be about epaules width apart. Position de depart. 3. Keeping vos bras straight and the torse stationary, lift the poids out to your sides until they are about epaules level height while exhaling. 4. Feel the contraction for a second and begin to lower the poids back down to the position de depart while inhaling. Conseil : Keep the palms facing down with the little finger slightly higher while lifting and lowering the poids as it will concentrate the stress on your epaules mainly. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Partials/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Power Snatch', 'Ischio-jambiers', 'Barre', '1. Begin with a loaded barre on le sol. The bar should be close to or touching the shins, and a prise large should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the poitrine up and the head looking forward. The epaules should be just in front of the bar. This will be the position de depart. 2. Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the genoux. 3. Transition into the second pull by extending through the hips genoux and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the epaules and allow the coudes to flex to the side. 4. As you move vos pieds into the receiving position, a slightly wider position, pull yourself below the bar as you elevate the bar overhead. The bar should be received in a partial squat. Continue raising the bar to the overhead position, receiving the bar locked out overhead. 5. Return to a standing position with the poids over head.', 'Muscles secondaires : Mollets, Fessiers, Bas du dos, Quadriceps, Épaules, Trapèzes, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Snatch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Power Snatch from Blocks', 'Quadriceps', 'Barre', '1. Begin with a loaded barre on boxes or stands of the desired height. A prise large should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the poitrine up and the head looking forward. The epaules should be just in front of the bar, with the coudes pointed out. This will be the position de depart. 2. Begin the first pull by driving through the front of the heels, raising the bar from the boxes. 3. Transition into the second pull by extending through the hips genoux and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the epaules and allow the coudes to flex to the side. 4. As you move vos pieds into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar above a full squat and with the arms fully extended overhead. 5. Keeping the bar aligned over the front of the heels, your head and poitrine up, drive through heels of the feet to move to a standing position. Carefully return the poids to the boxes.', 'Muscles secondaires : Mollets, Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Épaules, Trapèzes, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Snatch_from_Blocks/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Power Stairs', 'Ischio-jambiers', 'Autre', '1. In the power stairs, implements are moved up a staircase. For training purposes, these can be performed with a tire or box. 2. Begin by taking the implement with both hands. Set vos pieds wide, with your head and poitrine up. Drive through the ground with your heels, extending your genoux and hips to raise the poids from the ground. 3. As you lean back, attempt to swing the poids onto the stairs, which are usually around 16-18" high. You can use vos jambes to help push the poids onto the stair. 4. Repetez for 3-5 repetitions, and continue with a heavier poids, moving as fast as possible.', 'Muscles secondaires : Adducteurs, Mollets, Fessiers, Bas du dos, Quadriceps, Épaules, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Power_Stairs/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Preacher Curl', 'Biceps', 'Barre', '1. To perform this movement you will need a preacher banc and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of vos mains should be facing forward and they should be slightly tilted inwards due to the shape of the bar. 2. With the upper arms positioned against the preacher banc pad and the poitrine against it, hold the E-Z Curl Bar at epaules length. Position de depart. 3. As you Inspirez, Lentement, lower the bar until your upper arm is extended and the biceps is fully stretched. 4. en expirant, use the biceps to curl the poids up until your biceps is entierement contracte and the bar is at epaules height. Squeeze the biceps hard and hold this position for a second. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Preacher Hammer Dumbbell Curl', 'Biceps', 'Haltères', '1. Place the upper part of both arms on top of the preacher banc as you hold a halteres in each hand with the palms facing each other (neutral grip). 2. As you Inspirez, Lentement, lower the halteres until your upper arm is extended and the biceps is fully stretched. 3. en expirant, use the biceps to curl the poids up until your biceps is entierement contracte and the halteres are at epaules height. 4. Squeeze the biceps hard for a second at the contracted position and Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Preacher_Hammer_Dumbbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Press Sit-Up', 'Abdominaux', 'Barre', '1. To begin, lie down on a banc with a barre resting on your poitrine. Position vos jambes so they are secure on the extension of the abdominal banc. Position de depart. 2. While inhaling, tighten your abdominals and fessiers. Simultaneously curl your torse as you do when performing a sit-up and press the barre to an overhead position while exhaling. Conseil : Use vos bras to push the barre out as you perform this exercise while still focusing on the abdominal muscles. 3. Lower your upper body back down to the position de depart while bringing the barre back down to your torse. Remember to Inspirez while lowering the body. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Pectoraux, Épaules, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Press_Sit-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Prone Manual Hamstring', 'Ischio-jambiers', 'Autre', '1. You will need a partner for this exercise. Lay face down with vos jambes straight. Your assistant will place their hand on your heel. 2. To begin, flex the genoux to curl your leg up. Your partner should provide resistance, starting light and increasing the pressure as le mouvement is completed. Communicate with your partner to monitor appropriate resistance levels. 3. Pause at the top, returning the leg to the position de depart as your partner provides resistance going the other direction.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Prone_Manual_Hamstring/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Prowler Sprint', 'Ischio-jambiers', 'Autre', '1. Place your sled on an appropriate surface, loaded to a suitable poids. The sled should provide enough resistance to require effort, but not so heavy that you are significantly slowed down. 2. You may use the upright or the low handles for this exercise. Place vos mains on the handles with vos bras extended, leaning into the implement. 3. With good posture, drive through the ground with alternating, short steps. Move as fast as you can for a short distance.', 'Muscles secondaires : Mollets, Pectoraux, Fessiers, Quadriceps, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Prowler_Sprint/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pull Through', 'Fessiers', 'Poulie', '1. Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with vos pieds set wide apart. 2. Begin le mouvement by reaching through vos jambes as far as possible, bending at the hips. Keep your genoux slightly bent. Keeping vos bras straight, extend through the hip to stand straight up. Avoid pulling upward through the epaules; all of the motion should originate through the hips.', 'Muscles secondaires : Ischio-jambiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pull_Through/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pullups', 'Dos', 'Poids de corps', '1. Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a prise large, vos mains need to be spaced out at a distance wider than your epaules width. For a prise moyenne, vos mains need to be spaced out at a distance equal to your epaules width and for a close grip at a distance smaller than your epaules width. 2. As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torse back around 30 degrees or so while creating a curvature on your lower back and sticking your poitrine out. Position de depart. 3. Pull your torse up until the bar touches your upper poitrine by drawing the epaules and the upper arms down and back. Exhale as you perform this portion of le mouvement. Conseil : Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torse should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar. 4. After a second on the contracted position, start to inhale and Lentement, lower your torse back to the position de depart when vos bras are fully extended and the lats are fully stretched. 5. Repetez this motion for the prescribed amount of repetitions.', 'Muscles secondaires : Biceps, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Push-Up Wide', 'Pectoraux', 'Poids de corps', '1. With vos mains wide apart, support votre corps on your toes and hands in a plank position. Your coudes should be extended and votre corps straight. Do not allow your hips to sag. Position de depart. 2. To begin, allow the coudes to flex, lowering your poitrine to le sol en inspirant. 3. Using your pectoral muscles, press your upper body back up to the position de depart by extending the coudes. Exhale as you perform this step. 4. After pausing at the contracted position, Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Up_Wide/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Push-Ups - Close Triceps Position', 'Triceps', 'Poids de corps', '1. Allongez-vous au sol face down and place vos mains closer than epaules width for a close hand position. Make sure that you are holding your torse up at arms'' length. 2. Lower yourself until your poitrine almost touches le sol en inspirant. 3. Using your triceps and some of your pectoral muscles, press your upper body back up to the position de depart and squeeze your poitrine. Expirez as you perform this step. 4. Apres une pause, at the contracted position, Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Ups_-_Close_Triceps_Position/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Push-Ups With Feet Elevated', 'Pectoraux', 'Poids de corps', '1. Allongez-vous au sol face down and place vos mains about 36 inches apart from each other holding your torse up bras tendus. 2. Place your toes on top of a flat banc. This will allow votre corps to be elevated. Note: The higher the elevation of the flat banc, the higher the resistance of the exercise is. 3. Lower yourself until your poitrine almost touches le sol en inspirant. 4. Using your pectoral muscles, press your upper body back up to the position de depart and squeeze your poitrine. Expirez as you perform this step. 5. Apres une pause, at the contracted position, Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Ups_With_Feet_Elevated/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Push-Ups With Feet On An Exercise Ball', 'Pectoraux', 'Swiss ball', '1. Allongez-vous au sol face down and place vos mains about 36 inches apart from each other holding your torse up bras tendus. 2. Place your toes on top of an exercise ball. This will allow votre corps to be elevated. 3. Lower yourself until your poitrine almost touches le sol en inspirant. 4. Using your pectoral muscles, press your upper body back up to the position de depart and squeeze your poitrine. Expirez as you perform this step. 5. Apres une pause, at the contracted position, Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push-Ups_With_Feet_On_An_Exercise_Ball/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Push Press', 'Épaules', 'Barre', '', 'Muscles secondaires : Quadriceps, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Push Press - Behind the Neck', 'Épaules', 'Barre', '1. Standing with the poids racked on the back of the epaules, begin with the dip. With vos pieds directly under your hips, flex the genoux without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, moving the bar in a vertical path. 2. Using the momentum generated, finish pressing the poids overhead be extending through the arms. 3. Revenez en position de depart, using vos jambes to absorb the impact.', 'Muscles secondaires : Mollets, Quadriceps, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push_Press_-_Behind_the_Neck/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Push Up to Side Plank', 'Pectoraux', 'Poids de corps', '1. Get into pushup position on the toes with vos mains just outside of epaules width. 2. Perform a pushup by allowing the coudes to flex. As you descend, keep votre corps straight. 3. Do one pushup and as you come up, shift your poids on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank. 4. Lower the arm back to le sol for another pushup and then twist to the other side. 5. Repetez the series, alternating each side, for 10 or more reps.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Push_Up_to_Side_Plank/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pushups', 'Pectoraux', 'Poids de corps', '1. Allongez-vous au sol face down and place vos mains about 36 inches apart while holding your torse up bras tendus. 2. Next, lower yourself downward until your poitrine almost touches le sol en inspirant. 3. Now Expirez and press your upper body back up to the position de depart while squeezing your poitrine. 4. Apres une pause, at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pushups/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pushups (Close and Wide Hand Positions)', 'Pectoraux', 'Poids de corps', '1. Allongez-vous au sol face down and body straight with your toes on le sol and the hands wider than epaules width for a wide hand position and closer than epaules width for a close hand position. Make sure you are holding your torse up bras tendus. 2. Lower yourself until your poitrine almost touches le sol en inspirant. 3. Using your pectoral muscles, press your upper body back up to the position de depart and squeeze your poitrine. Expirez as you perform this step. 4. Apres une pause, at the contracted position, Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pushups_Close_and_Wide_Hand_Positions/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Pyramid', 'Bas du dos', 'Swiss ball', '1. Start off by rolling your torse forward onto the ball so your hips rest on top of the ball and become the highest point of votre corps. 2. Rest vos mains and feet on le sol. vos bras and legs can be slightly bent or straight, depending on the size of the ball, your flexibility, and the length of your limbs. This also helps develop stabilizing strength in your torse and epaules.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pyramid/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Quad Stretch', 'Quadriceps', 'Autre', '1. Lay on your side. Loop a belt, rope, or band around your top foot. Flex the genoux and extend your hip, attempting to touch your fessiers with your foot, and holding the belt with vos mains. Position de depart. 2. With the belt being held over the epaules or overhead, gently pull to increase the stretch in the quadriceps. Hold for 10-20 seconds, and then switch sides.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Quad_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Quadriceps-SMR', 'Quadriceps', 'Foam roller', '1. Lay facedown on le sol with your poids supported by vos mains or forearms. Place a foam roll underneath one leg on the quadriceps, and keep the foot off of the ground. Make sure to relax the leg as much as possible. Position de depart. 2. Shifting as much poids onto the leg to be stretched as is tolerable, roll over the foam from above the genoux to below the hip, holding points of tension for 10-30 seconds. Switch sides.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Quadriceps-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Quick Leap', 'Quadriceps', 'Autre', '1. You will need a box for this exerise. 2. Begin facing the box standing 1-2 feet from its edge. 3. By utilizing your hips, hop onto the box, landing on both legs. Ensure that you land with vos jambes bent and vos pieds flat. 4. Immediately upon landing, fully extend through the entire body and swing vos bras overhead to explode off of the box. Use vos jambes to absorb the impact of landing.', 'Muscles secondaires : Mollets, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Quick_Leap/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rack Delivery', 'Épaules', 'Barre', '1. This drill teaches the delivery of the barre to the rack position on the epaules. Begin holding a bar in the scarecrow position, with the upper arms parallel to le sol, and the forearms hanging down. Use a hook grip, with your fingers wrapped over your thumbs. 2. Begin by rotating the coudes around the bar, delivering the bar to the epaules. As your coudes come forward, relax your grip. The epaules should be protracted, providing a shelf for the bar, which should lightly contact the throat. 3. It is important that the bar stay close to the body en permanence, as with a heavier load any distance will result in an unwanted collision. As le mouvement becomes smoother, speed and load can be increased before progressing further.', 'Muscles secondaires : Avant-bras, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rack_Delivery/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rack Pull with Bands', 'Bas du dos', 'Barre', '1. Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the genoux, just above, or in the mid cuisses position. Attach bands to the base of the rack, or secure them with halteres. Attach the other end to the bar. You may need to choke the bands to provide tension. 2. Position yourself against the bar in proper deadlifting position. vos pieds should be under your hips, your grip epaules width, back arched, and hips back to engage the ischio-jambiers. Since the poids is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the poids. 3. With your head looking forward, extend through the hips and genoux, pulling the poids up and back until lockout. Be sure to pull your epaules back as you complete le mouvement. Return the poids to the pins and Repetez.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rack_Pull_with_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rack Pulls', 'Bas du dos', 'Barre', '1. Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the genoux, just above, or in the mid cuisses position. Position yourself against the bar in proper deadlifting position. vos pieds should be under your hips, your grip epaules width, back arched, and hips back to engage the ischio-jambiers. Since the poids is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the poids. 2. With your head looking forward, extend through the hips and genoux, pulling the poids up and back until lockout. Be sure to pull your epaules back as you complete le mouvement. 3. Return the poids to the pins and Repetez.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rack_Pulls/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rear Leg Raises', 'Quadriceps', 'Poids de corps', '1. Place yourself on vos mains genoux on an exercise mat. Your head should be looking forward and the bend of the genoux should create a 90-degree angle between the ischio-jambiers and the mollets. Position de depart. 2. Extend one leg up and behind you. The genoux and hip should both extend. Repetez for 5-10 repetitions, and then switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rear_Leg_Raises/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Recumbent Bike', 'Quadriceps', 'Machine', '1. To begin, seat yourself on the bike and adjust the seat to your height. 2. Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and poids to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity. 3. Recumbent bikes offer convenience, cardiovascular benefits, and have less impact than other activities. A 150 lb person will burn about 230 calories cycling at a moderate rate for 30 minutes, compared to 450 calories or more running.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Recumbent_Bike/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Return Push from Stance', 'Épaules', 'Medecine ball', '1. You will need a partner for this drill. 2. Begin in an athletic 2 or 3 point stance. 3. At the signal, move into a position to receive the pass from your partner. 4. Catch the medicine ball with both hands and immediately throw it back to your partner. 5. You can modify this drill by running different routes.', 'Muscles secondaires : Pectoraux, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Return_Push_from_Stance/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Band Bench Press', 'Triceps', 'Barre', '1. Position a banc inside a power rack, with the bar set to the correct height. Begin by anchoring bands either to band pegs or to the top of the rack. Ensure that you will be position properly under the bands. Attach the other end to the barre. 2. Lie on the banc, tuck vos pieds underneath you and arch votre dos. Using the bar to help support your poids, lift your epaules off the banc and retract them, squeezing the omoplates together. Use vos pieds to drive your traps into the banc. Maintain this tight body position throughout le mouvement. However wide your grip, it should cover the ring on the bar. 3. Pull the bar out of the rack without protracting your epaules. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower poitrine or upper stomach. The bar, poignets, and coudes should stay in line en permanence. 4. Pause when the barre touches your torse, and then drive the bar up with as much force as possible. The coudes should be tucked in until lockout.', 'Muscles secondaires : Pectoraux, Avant-bras, Dos, Milieu du dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Band Box Squat', 'Quadriceps', 'Barre', '1. Begin in a power rack with a box at the appropriate height behind you. Set up the bands either on band pegs or attached to the top of the rack, ensuring they will be directly above the bar during the squat. Attach the other end to the bar. 2. Begin by stepping under the bar and placing it across the back of the epaules. Squeeze your omoplates together and rotate your coudes forward, attempting to bend the bar across your epaules. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place vos pieds wider for more emphasis on the back, fessiers, adductors, and ischio-jambiers, or closer together for more quad development. Keep your head facing forward. 3. With votre dos, epaules, and sangle abdominale tight, push your genoux and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box. 4. Keeping the poids on your heels and pushing vos pieds and genoux out, drive upward off of the box as you lead le mouvement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barre to the rack.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Avant-bras, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Box_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Band Deadlift', 'Bas du dos', 'Barre', '1. Set the bar up in a power rack. Attach bands to the top of the rack, using either bands pegs or the frame itself. Attach the other end of the bands to the bar. 2. Approach the bar so that it is centered over vos pieds. You feet should be about hip width apart. Bend at the hip to grip the bar at epaules width, allowing your omoplates to protract. Typically, you would use an prise en pronation or an over/under grip on heavier sets. 3. With vos pieds, and your grip set, take a big breath and then lower your hips and bend the genoux until your shins contact the bar. Look forward with your head, keep your poitrine up and votre dos arched, and begin driving through the heels to move the poids upward. 4. After the bar passes the genoux, aggressively pull the bar back, pulling your omoplates together as you drive your hips forward into the bar. 5. Lower the bar by bending at the hips and guiding it to le sol.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers, Quadriceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Band Power Squat', 'Quadriceps', 'Barre', '1. Begin in a power rack with the pins and bar set at the appropriate height. After loading the bar, attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end of the bands to the bar. 2. Begin by stepping under the bar and placing it across the back of the epaules. Squeeze your omoplates together and rotate your coudes forward, attempting to bend the bar across your epaules. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place vos pieds wide for more emphasis on the back, fessiers, adductors, and ischio-jambiers. 3. Keep your head facing forward. With votre dos, epaules, and sangle abdominale tight, push your genoux and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torse lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the genoux. 4. Keeping the poids on your heels and pushing vos pieds and genoux out, drive upward as you lead le mouvement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the position de depart.', 'Muscles secondaires : Adducteurs, Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Power_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Band Sumo Deadlift', 'Ischio-jambiers', 'Barre', '1. Begin with a bar loaded on le sol inside of a power rack. Attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end to the barre. 2. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the epaules, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the epaules, which in effect lengthens vos bras. 3. Take a breath, and then lower your hips, looking forward with your head with your poitrine up. Drive through le sol, spreading vos pieds apart, with your poids on the back half of vos pieds. Extend through the hips and genoux. 4. As the bar passes through the genoux, lean back and drive the hips into the bar, pulling your omoplates together. 5. Return the poids to the ground by bending at the hips and controlling the poids on the way down.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Avant-bras, Fessiers, Bas du dos, Quadriceps, Trapèzes. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Band_Sumo_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Barbell Curl', 'Biceps', 'Barre', '1. Tenez-vous debout avec your torse upright while holding a barre at epaules width with the coudes close to the torse. The palm of vos mains should be facing down (pronated grip). Position de depart. 2. While holding the upper arms stationary, curl the poids while contracting the biceps as you Expirez. Only the forearms should move. Continue le mouvement until your biceps are entierement contracte and the bar is at epaules level. Maintenez 1 seconde as you squeeze the muscle. 3. Lentement, begin to bring the bar back to position de depart as your Inspirez. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Barbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Barbell Preacher Curls', 'Biceps', 'Barre EZ', '1. Grab an EZ-bar using a epaules width and palms down (pronated) grip. 2. Now place the upper part of both arms on top of the preacher banc and have vos bras extended. Position de depart. 3. en expirant, use the biceps to curl the poids up until your biceps are entierement contracte and the barre is at epaules height. Squeeze the biceps hard for a second at the contracted position. 4. As you Inspirez, Lentement, lower the barre until your upper arms are extended and the biceps is fully stretched. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Barbell_Preacher_Curls/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Cable Curl', 'Biceps', 'Poulie', '1. Tenez-vous debout avec your torse upright while holding a bar attachment that is attached to a low pulley using a pronated (palms down) and epaules width grip. Make sure also that you keep the coudes close to the torse. Position de depart. 2. While holding the upper arms stationary, curl the poids while contracting the biceps as you Expirez. Only the forearms should move. Continue le mouvement until your biceps are entierement contracte and the bar is at epaules level. Maintenez 1 seconde as you squeeze the muscle. 3. Lentement, begin to bring the bar back to position de depart as your Inspirez. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Cable_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Crunch', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol with vos jambes fully extended and arms to the side of your torse with the palms on le sol. vos bras should be stationary for the entire exercise. 2. Move vos jambes up so that your cuisses are perpendicular to le sol and feet are together and parallel to le sol. Position de depart. 3. While inhaling, move vos jambes towards the torse as you roll your pelvis backwards and you raise your hips off le sol. At the end of this movement your genoux will be touching your poitrine. 4. Hold the contraction for a second and move vos jambes back to the position de depart while exhaling. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Flyes', 'Épaules', 'Haltères', '1. To begin, lie down on an incline banc with the poitrine and stomach pressing against the incline. Have the halteres in each hand with the palms facing each other (neutral grip). 2. Extend the arms in front of you so that they are perpendicular to the angle of the banc. The legs should be stationary while applying pressure with the ball of your toes. Position de depart. 3. Maintaining the slight bend of the coudes, move the poids out and away from each other (to the side) in an arc motion while exhaling. Conseil : Try to squeeze your omoplates together to get the best results from this exercise. 4. The arms should be elevated until they are parallel to le sol. 5. Feel the contraction and Lentement, lower the poids back down to the position de depart while inhaling. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Flyes/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Flyes With External Rotation', 'Épaules', 'Haltères', '1. To begin, lie down on an incline banc set at a 30-degree angle with the poitrine and stomach pressing against the incline. 2. Have the halteres in each hand with the palms facing down to le sol. vos bras should be in front of you so that they are perpendicular to the angle of the banc. Conseil : Your coudes should have a slight bend. The legs should be stationary while applying pressure with the ball of your toes (your heels should not be touching le sol). Position de depart. 3. Maintaining the slight bend of the coudes, move the poids out and away from each other in an arc motion while exhaling. 4. As you lift the poids, your poignets should externally rotate by 90-degrees so that you go from a palms down (pronated) grip to a palms facing each other (neutral) grip. Conseil : Try to squeeze your omoplates together to get the best results from this exercise. 5. The arms should be elevated until they are level with the head. 6. Feel the contraction and Lentement, lower the poids back down to the position de depart while inhaling. 7. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Flyes_With_External_Rotation/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Grip Bent-Over Rows', 'Milieu du dos', 'Barre', '1. Stand erect while holding a barre with a supinated grip (palms facing up). 2. Bend your genoux slightly and bring your torse forward, by bending at the waist, while keeping the back straight until it is almost parallel to le sol. Conseil : Make sure that you keep the head up. The barre should hang directly in front of you as vos bras hang perpendicular to le sol and your torse. Position de depart. 3. While keeping the torse stationary, lift the barre as you Expirez, keeping the coudes close to the body and not doing any force with the forearm other than holding the poids. On the top contracted position, squeeze the back muscles and Maintenez 1 seconde. 4. Lentement, lower the poids again to the position de depart en inspirant. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Grip_Bent-Over_Rows/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Grip Triceps Pushdown', 'Triceps', 'Poulie', '1. Start by setting a bar attachment (straight or e-z) on a high pulley machine. 2. Facing the bar attachment, grab it with the palms facing up (supinated grip) at epaules width. Lower the bar by using your lats until vos bras are fully extended by your sides. Conseil : coudes should be in by your sides and vos pieds should be epaules width apart from each other. Position de depart. 3. Lentement, elevate the bar attachment up en inspirant so it is aligned with your poitrine. Only the forearms should move and the coudes/upper arms should be stationary by your side en permanence. 4. Then begin to lower the cable bar back down to the original staring position while exhaling and contracting the triceps hard. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Grip_Triceps_Pushdown/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Hyperextension', 'Ischio-jambiers', 'Machine', '1. Place vos pieds between the pads after loading an appropriate poids. Lay on the top pad, allowing your hips to hang off the back, while grasping the handles to hold your position. 2. To begin le mouvement, flex the hips, pulling the legs forward. 3. Reverse the motion by extending the hips, kicking the leg back. It is very important not to over-extend the hip on this movement, stopping short of your full range of motion. 4. Return by again flexing the hip, pulling the carriage forward as far as you can. 5. Repetez for the desired number of repetitions.', 'Muscles secondaires : Mollets, Fessiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Hyperextension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Machine Flyes', 'Épaules', 'Machine', '1. Adjust the handles so that they are fully to the rear. Make an appropriate poids selection and adjust the seat height so the handles are at epaules level. Grasp the handles with vos mains facing inwards. Position de depart. 2. In a semicircular motion, pull vos mains out to your side and back, contracting your rear delts. 3. Keep vos bras slightly bent throughout le mouvement, with all of the motion occurring at the epaules joint. 4. Pause at the rear of le mouvement, and Lentement, return the poids to the position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Machine_Flyes/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Plate Curls', 'Biceps', 'Autre', '1. Start by standing straight with a weighted plate held by both hands and arms fully extended. Use a pronated grip (palms facing down) and make sure your fingers grab the rough side of the plate while your thumb grabs the smooth side. Note: For the best results, grab the weighted plate at an 11:00 and 1:00 o''clock position. 2. vos pieds should be epaules width apart from each other and the weighted plate should be near the groin area. Position de depart. 3. Lentement, lift the plate up while keeping the coudes in and the upper arms stationary until your biceps and forearms touch while exhaling. The plate should be evenly aligned with your torse at this point. 4. Feel the contraction for a second and begin to lower the poids back down to the position de depart while inhaling 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Plate_Curls/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Reverse Triceps Bench Press', 'Triceps', 'Barre', '1. Allongez-vous au sol on a flat banc. Using a close, supinated grip (around epaules width), lift the bar from the rack and hold it straight over you with vos bras locked extended in front of you and perpendicular to le sol. Position de depart. 2. As you Inspirez, come down Lentement, until you feel the bar on your middle poitrine. Conseil : Make sure that as opposed to a regular banc press, you keep the coudes close to the torse en permanence in order to maximize triceps involvement. 3. Apres une pause, bring the bar back to the position de depart as you Expirez and push the bar using your triceps muscles. Lock vos bras in the contracted position, Maintenez 1 seconde and then start coming down Lentement, again. Conseil : It should take at least twice as long to go down than to come up. 4. Repetez le mouvement for the prescribed amount of repetitions. 5. When you are done, place the bar back in the rack.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Reverse_Triceps_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rhomboids-SMR', 'Milieu du dos', 'Foam roller', '1. Lay down with votre dos on le sol. Place a foam roll underneath your upper back, and cross vos bras in front of you, protracting your epaules. Position de depart. 2. Raise your hips off of the ground, placing your poids onto the foam roll. Shift your poids to one side at a time, rolling over your middle and upper back. Pause at points of tension for 10-30 seconds.', 'Muscles secondaires : Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rhomboids-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rickshaw Carry', 'Avant-bras', 'Autre', '1. Position the frame at the starting point, and load with the appropriate poids. Standing in the center of the frame, begin by gripping the handles and driving through your heels to lift the frame. Ensure your poitrine and head are up and votre dos is straight. 2. Immediately begin walking briskly with quick, controlled steps. Keep your poitrine up and head forward, and make sure you continue breathing. Bring the frame to the ground after you have reached the end point.', 'Muscles secondaires : Abdominaux, Mollets, Fessiers, Ischio-jambiers, Bas du dos, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rickshaw_Carry/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rickshaw Deadlift', 'Quadriceps', 'Autre', '1. Load the frame with the desired poids. Center yourself between the handles. You feet should be about hip width apart. Bend at the hips to grip the handles, allowing your omoplates to protract. 2. With vos pieds and your grip set, take a big breath and then lower your hips and flex the genoux. Look forward with your head, keep your poitrine up and votre dos arched, and begin driving through the heels to move the poids upward. As the poids comes up, pull your omoplates together as you drive your hips forward. 3. Lower the poids by bending at the hips and guiding it to the ground.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rickshaw_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Ring Dips', 'Triceps', 'Autre', '1. Grip a ring in each hand, and then take a small jump to help you get into the position de depart with vos bras locked out. 2. Begin by flexing the coudes, lowering votre corps until vos bras break 90 degrees. Avoid swinging, and maintain good posture throughout the descent. 3. Reverse the motion by extending the coudes, pushing yourself back up into the position de depart. 4. Repetez for the desired number of repetitions.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ring_Dips/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rocket Jump', 'Quadriceps', 'Poids de corps', '1. Begin in a relaxed stance with vos pieds epaules width apart and hold vos bras close to the body. 2. To initiate the move, squat down halfway and explode back up as high as possible. 3. Fully extend your entire body, reaching overhead as far as possible. As you land, absorb your impact through the legs.', 'Muscles secondaires : Mollets, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rocket_Jump/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rocking Standing Calf Raise', 'Mollets', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place it on the back of your epaules (slightly below the neck). 2. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Step away from the rack and position vos jambes using a epaules width medium stance with the toes slightly pointed out. Keep your head up en permanence as looking down will get you off balance. Also maintain a straight back and keep the genoux with a slight bend; never locked. Position de depart. 4. Raise your heels as you Expirez by extending your ankles as high as possible and flexing your calf. Ensure that the genoux is kept stationary en permanence. There should be no bending (other than the slight initial bend we created during positioning) at any time. Hold the contracted position by a second before you start to go back down. 5. Go back Lentement, to the position de depart as you Inspirez by lowering your heels as you bend the ankles until mollets are stretched. 6. Now lift your toes by contracting the tibia muscles in the front of the mollets as you Expirez. 7. Maintenez 1 seconde and bring them back down as you Inspirez. 8. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rocking_Standing_Calf_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rocky Pull-Ups/Pulldowns', 'Dos', 'Autre', '1. Grab the pull-up bar with the palms facing forward using a prise large. 2. As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torse back around 30 degrees or so while creating a curvature on your lower back and sticking your poitrine out. Position de depart. 3. Pull your torse up until the bar touches your upper poitrine by drawing the epaules and the upper arms down and back. Exhale as you perform this portion of le mouvement. Conseil : Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torse should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar. 4. After a second on the contracted position, start to inhale and Lentement, lower your torse back to the position de depart when vos bras are fully extended and the lats are fully stretched. 5. Now Repetez the same movements as described above except this time your torse will remain straight as you go up and the bar will touch the back of the neck instead of the upper poitrine. Conseil : Use the head to lean forward slightly as it will help you properly execute this portion of the exercise. 6. Once you have lowered yourself back down to the position de depart, Repetez the exercise for the prescribed amount of repetitions in your program.', 'Muscles secondaires : Biceps, Milieu du dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rocky_Pull-Ups_Pulldowns/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Romanian Deadlift', 'Ischio-jambiers', 'Barre', '1. Put a barre in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than epaules width. Conseil : Depending on the poids used, you may need poignets wraps to perform the exercise and also a raised platform in order to allow for better range of motion. 2. Bend the genoux slightly and keep the shins vertical, hips back and back straight. Position de depart. 3. Keeping votre dos and arms completely straight en permanence, use your hips to lift the bar en expirant. Conseil : le mouvement should not be fast but steady and under control. 4. Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the genoux, unlike when squatting. Conseil : Take a deep breath at the start of le mouvement and keep your poitrine up. Hold your breath as you lower and exhale as you complete le mouvement. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Romanian Deadlift from Deficit', 'Ischio-jambiers', 'Barre', '1. Begin standing while holding a bar at arm''s length in front of you. You can stand on a raised platform to increase the range of motion. 2. Begin by flexing the genoux slightly, and then flex at the hip, moving your butt back as far as possible, lowering the torse as far as flexibility allows. The back should remain in absolute extension en permanence, and the bar should remain in contact with the legs. If done properly, there should be heavy tension felt in the ischio-jambiers. 3. Reverse the motion to Revenez en position de depart.', 'Muscles secondaires : Avant-bras, Fessiers, Bas du dos, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Romanian_Deadlift_from_Deficit/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rope Climb', 'Dos', 'Autre', '1. Grab the rope with both hands above your head. Pull down on the rope as you take a small jump. 2. Wrap the rope around one leg, using vos pieds to pinch the rope. Reach up as high as possible with vos bras, gripping the rope tightly. 3. Release the rope from vos pieds as you pull yourself up with vos bras, bringing your genoux towards your poitrine. 4. Resecure vos pieds on the rope, and then stand up to take another high hold on the rope. Continue until you reach the top of the rope. 5. To lower yourself, loosen the grip of vos pieds on the rope as you slide down using a hand over hand motion.', 'Muscles secondaires : Biceps, Avant-bras, Milieu du dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Climb/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rope Crunch', 'Abdominaux', 'Poulie', '1. Kneel 1-2 feet in front of a cable system with a rope attached. 2. After selecting an appropriate poids, grasp the rope with both hands reaching overhead. Your torse should be upright in the position de depart. 3. To begin, flex at the spine, attempting to bring your rib cage to vos jambes as you pull the cable down. 4. Pause at the bottom of the motion, and then Lentement, Revenez en position de depart. 5. These can be done with twists or to the side to hit the obliques.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rope Jumping', 'Quadriceps', 'Autre', '1. Hold an end of the rope in each hand. Position the rope behind you on the ground. Raise vos bras up and turn the rope over your head bringing it down in front of you. When it reaches the ground, jump over it. Find a good turning pace that can be maintained. Different speeds and techniques can be used to introduce variation. 2. Rope jumping is exciting, challenges your coordination, and requires a lot of energy. A 150 lb person will burn about 350 calories jumping rope for 30 minutes, compared to over 450 calories running.', 'Muscles secondaires : Mollets, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Jumping/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rope Straight-Arm Pulldown', 'Dos', 'Poulie', '1. Attach a rope to a high pulley and make your poids selection. Stand a couple feet back from the pulley with vos pieds staggered and take the rope with both hands. Lean forward from the hip, keeping votre dos straight, with vos bras extended up in front of you. Position de depart. 2. Keeping vos bras straight, extend the epaules to pull the rope down to your cuisses. 3. Pause at the bottom of the motion, squeezing your lats. 4. Revenez en position de depart without allowing the poids to fully rest on the stack.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rope_Straight-Arm_Pulldown/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Round The World Shoulder Stretch', 'Épaules', 'Autre', '1. Tenez-vous debout avec vos jambes together, holding a bodybar or broomstick. 2. Hold the pole behind your hips with a wider than epaules width grip. Your palms should be down and your thumbs facing out. 3. Lentement, lift vos bras up behind your head. Don''t force it if it gets hard to lift further.', 'Muscles secondaires : Biceps, Pectoraux. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Round_The_World_Shoulder_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Rowing, Stationary', 'Quadriceps', 'Machine', '1. To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips. 2. There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your genoux are bent and against your poitrine. Your upper body is leaning slightly forward while still maintaining good posture. Next, push against the foot pedals and extend vos jambes while bringing vos mains to your upper abdominal area, squeezing your epaules back as you do so. To avoid straining votre dos, use primarily your leg and hip muscles. 3. The recovery phase simply involves straightening vos bras, bending the genoux, and bringing votre corps forward again as you transition back into the first phase.', 'Muscles secondaires : Biceps, Mollets, Fessiers, Ischio-jambiers, Bas du dos, Milieu du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Rowing_Stationary/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Runner''s Stretch', 'Ischio-jambiers', 'Autre', '1. It''s easiest to get into this stretch if you start standing up, put one leg behind you, and Lentement, lower your torse down to le sol. 2. Keep the front heel on le sol (if it lifts up, scoot your other leg further back). 3. Place vos mains on either side of your front leg. To get more out of this stretch, push your butt up toward the ceiling, and then gradually lower it back toward le sol. You''ll Stretch the hip flexor of the back leg and the ischio-jambiers and buttocks of the front.', 'Muscles secondaires : Mollets. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Runners_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Running, Treadmill', 'Quadriceps', 'Machine', '1. To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and poids to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout. 2. Treadmills offer convenience, cardiovascular benefits, and usually have less impact than running outside. A 150 lb person will burn over 450 calories running 8 miles per hour for 30 minutes. Maintain proper posture as you run, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Running_Treadmill/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Russian Twist', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol placing vos pieds either under something that will not move or by having a partner hold them. vos jambes should be bent at the genoux. 2. Elevate your upper body so that it creates an imaginary V-shape with your cuisses. vos bras should be fully extended in front of you perpendicular to your torse and with the hands clasped. Position de depart. 3. Twist your torse to the right side until vos bras are parallel with le sol while breathing out. 4. Hold the contraction for a second and move back to the position de depart while breathing out. Now move to the opposite side performing the same techniques you applied to the right side. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Russian_Twist/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Sandbag Load', 'Quadriceps', 'Autre', '1. To load sandbags or other objects, begin with the implements placed a distance from the loading platform, typically 50 feet. 2. Begin by lifting the sandbag. Sandbags are extremely awkward, and the manner of lifting them can vary depending on the particular sandbag used. Reach as far around it as possible, extending through the hips and genoux to pull it up high. Shouldering is usually not allowed. 3. Move as quickly as possible to the platform, and load it, extending through your hips, genoux, and ankles to get it as high as possible. Place it onto the platform, ensuring it doesn''t fall off. 4. Revenez en position de depart to retrieve the next sandbag, and Repetez until the event is completed.', 'Muscles secondaires : Abdominaux, Biceps, Mollets, Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Milieu du dos, Épaules, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sandbag_Load/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Scapular Pull-Up', 'Trapèzes', 'Autre', '1. Take a pronated grip on a pull-up bar. 2. From a hanging position, raise yourself a few inches without using vos bras. Do this by depressing your epaules girdle in a reverse shrugging motion. 3. Pause at the completion of le mouvement, and then Lentement, Revenez en position de depart before performing more repetitions.', 'Muscles secondaires : Dos, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Scapular_Pull-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Scissor Kick', 'Abdominaux', 'Poids de corps', '1. To begin, lie down with votre dos pressed against le sol or on an exercise mat (optional). vos bras should be fully extended to the sides with your palms facing down. Note: The arms should be stationary the entire time. 2. With a slight bend at the genoux, lift vos jambes up so that your heels are about 6 inches off the ground. Position de depart. 3. Now lift your left leg up to about a 45 degree angle while your right leg is lowered until the heel is about 2-3 inches from the ground. 4. Switch movements by raising your right leg up and lowering your left leg. Remember to breathe while performing this exercise. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Scissor_Kick/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Scissors Jump', 'Quadriceps', 'Poids de corps', '1. Assume a lunge stance position with one foot forward with the genoux bent, and the rear genoux nearly touching the ground. 2. Ensure that the front genoux is over the midline of the foot. Extending through both legs, jump as high as possible, swinging vos bras to gain lift. 3. As you jump as high as you can, switch the position of vos jambes, moving your front leg to the back and the rear leg to the front. 4. As you land, absorb the impact through the legs by adopting the lunge position, and Repetez.', 'Muscles secondaires : Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Scissors_Jump/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Band Hamstring Curl', 'Ischio-jambiers', 'Autre', '1. Secure a band close to the ground and place a banc a couple feet away from it. 2. Seat yourself on the banc and secure the band behind your ankles, beginning with vos jambes straight. Position de depart. 3. Flex the genoux, bringing vos pieds towards the banc. You may need to lean back slightly to keep vos pieds from striking le sol. 4. Pause at the completion of le mouvement, and then Lentement, Revenez en position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Band_Hamstring_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Barbell Military Press', 'Épaules', 'Barre', '1. Sit on a Military Press banc with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward). Conseil : Your grip should be wider than epaules width and it should create a 90-degree angle between the forearm and the upper arm as the barre goes down. 2. Once you pick up the barre with the correct grip length, lift the bar up over your head by locking vos bras. Hold at about epaules level and slightly in front of your head. Position de depart. 3. Lower the bar down to the collarbone Lentement, en inspirant. 4. Lift the bar back up to the position de depart en expirant. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Barbell_Military_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Barbell Twist', 'Abdominaux', 'Barre', '1. Start out by sitting at the end of a flat banc with a barre placed on top of your cuisses. vos pieds should be epaules width apart from each other. 2. Grip the bar with your palms facing down and make sure vos mains are wider than epaules width apart from each other. Begin to lift the barre up over your head until vos bras are fully extended. 3. Now lower the barre behind your head until it is resting along the base of your neck. Position de depart. 4. While keeping vos pieds and head stationary, move your waist from side to side so that your oblique muscles feel the contraction. Only move from side to side as far as your waist will allow you to go. Stretching or moving too far can cause an injury to occur. Conseil : Use a slow and controlled motion. 5. Remember to Expirez while twisting votre corps to the side and in when moving back to the position de depart. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Barbell_Twist/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Bent-Over One-Arm Dumbbell Triceps Extension', 'Triceps', 'Haltères', '1. Sit down at the end of a flat banc with a halteres in one arm using a neutral grip (palms of the hand facing you). 2. Bend your genoux slightly and bring your torse forward, by bending at the waist, while keeping the back straight until it is almost parallel to le sol. Make sure that you keep the head up. 3. The upper arm with the halteres should be close to the torse and aligned with it (lifted up until it is parallel to le sol while the forearms are pointing towards le sol as the hands hold the poids). Conseil : There should be a 90-degree angle between the forearms and the upper arm. Position de depart. 4. Keeping the upper arm stationary, use the triceps to lift the poids en expirant until the forearm is parallel to le sol and the whole arm is extended. Like many other arm exercises, only the forearm moves. 5. After a second contraction at the top, Lentement, lower the halteres back to the position de depart en inspirant. 6. Repetez le mouvement for the prescribed amount of repetitions. 7. Switch arms and Repetez the exercise.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Bent-Over Rear Delt Raise', 'Épaules', 'Haltères', '1. Place a couple of halteres looking forward in front of a flat banc. 2. Sit on the end of the banc with vos jambes together and the halteres behind your mollets. 3. Bend at the waist while keeping the back straight in order to pick up the halteres. The palms of vos mains should be facing each other as you pick them. Position de depart. 4. Keeping your torse forward and stationary, and the arms slightly bent at the coudes, lift the halteres straight to the side until both arms are parallel to le sol. Exhale as you lift the poids. (Note: avoid swinging the torse or bringing the arms back as opposed to the side.) 5. After a one second contraction at the top, Lentement, lower the halteres back to the position de depart. 6. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_Rear_Delt_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Bent-Over Two-Arm Dumbbell Triceps Extension', 'Triceps', 'Haltères', '1. Sit down at the end of a flat banc with a halteres in both arms using a neutral grip (palms of the hand facing you). 2. Bend your genoux slightly and bring your torse forward, by bending at the waist, while keeping the back straight until it is almost parallel to le sol. Make sure that you keep the head up. 3. The upper arms with the halteres should be close to the torse and aligned with it (lifted up until they are parallel to le sol while the forearms are pointing towards le sol as the hands hold the poids). Conseil : There should be a 90-degree angle between the forearms and the upper arm. Position de depart. 4. Keeping the upper arms stationary, use the triceps to lift the poids en expirant until the forearms are parallel to le sol and the whole arm is extended. Like many other arm exercises, only the forearm moves. 5. After a second contraction at the top, Lentement, lower the halteres back to the position de depart en inspirant. 6. Repetez le mouvement for the prescribed amount of repetitions.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Biceps', 'Biceps', 'Poids de corps', '1. Sit on le sol with your genoux bent and your partner standing behind you. Extend vos bras straight behind you with your palms facing each other. Your partner will hold your poignets for you. This will be the position de depart. 2. Attempt to flex your coudes, while your partner prevents any actual movement. 3. After 10-20 seconds, relax vos bras while your partner gently pulls your poignets up to stretch your biceps. Be sure to let your partner know when the stretch is appropriate to prevent injury or overstretching.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Biceps/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Cable Rows', 'Milieu du dos', 'Poulie', '1. For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of vos mains face each other. To get into the position de depart, first sit down on the machine and place vos pieds on the front platform or crossbar provided making sure that your genoux are slightly bent and not locked. 2. Lean over as you keep the natural alignment of votre dos and grab the V-bar handles. 3. With vos bras extended pull back until your torse is at a 90-degree angle from vos jambes. votre dos should be slightly arched and your poitrine should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. Position de depart. of the exercise. 4. Keeping the torse stationary, pull the handles back towards your torse while keeping the arms close to it until you touch the abdominals. Expirez as you perform that movement. At that point you should be squeezing votre dos muscles hard. Hold that contraction for a second and Lentement, go back to the original position while breathing in. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Rows/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Cable Shoulder Press', 'Épaules', 'Poulie', '1. Adjust the poids to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 90 degrees to the body, with your head and poitrine up. The coudes should also be bent to about 90 degrees. Position de depart. 2. Begin by extending through the coudes, pressing the handles together above your head. 3. After pausing at the top, return the handles to the position de depart. Ensure that you maintain tension on the cables. 4. You can also execute this movement with votre dos off the pad and alternate hands.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Cable_Shoulder_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Calf Raise', 'Mollets', 'Machine', '1. Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter. 2. Place your lower cuisses under the lever pad, which will need to be adjusted according to the height of your cuisses. Now place vos mains on top of the lever pad in order to prevent it from slipping forward. 3. Lift the lever slightly by pushing your heels up and release the safety bar. Position de depart. 4. Lentement, lower your heels by bending at the ankles until the mollets are fully stretched. Inhale as you perform this movement. 5. Raise the heels by extending the ankles as high as possible as you contract the mollets and Expirez. Hold the top contraction for a second. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Calf_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Calf Stretch', 'Mollets', 'Autre', '1. Sit up straight on an exercise mat. 2. Bend one genoux and put that foot on le sol to stabilize the torse. 3. Straighten your other leg and flex your ankle. 4. Using a band, towel, or your hand if you can reach, pull the toes toward you. Hold for 10 to 20 seconds, then switch sides.', 'Muscles secondaires : Ischio-jambiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Calf_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Close-Grip Concentration Barbell Curl', 'Biceps', 'Barre', '1. Sit down on a flat banc with a barre or E-Z Bar in front of you in between vos jambes. vos jambes should be spread with the genoux bent and the feet on le sol. 2. Use vos bras to pick the barre up and place the back of your upper arms on top of your inner cuisses (around three and a half inches away from the front of the genoux). A supinated grip closer than epaules width is needed to perform this exercise. Conseil : Your arm should be extended bras tendus and the barre should be above le sol. Position de depart. 3. While holding the upper arms stationary, curl the poids forward while contracting the biceps as you Expirez. Only the forearms should move. Continue le mouvement until your biceps are entierement contracte and the halteres are at epaules level. Maintenez 1 seconde as you squeeze the biceps. 4. Lentement, begin to bring the barre back to position de depart as your Inspirez. Conseil : Avoid swinging motions at any time. 5. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Close-Grip_Concentration_Barbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Dumbbell Curl', 'Biceps', 'Haltères', '1. Sit on a flat banc with a halteres on each hand being held bras tendus. The coudes should be close to the torse. 2. Rotate the palms of the hands so that they are facing your torse. Position de depart. 3. While holding the upper arm stationary, curl the poids and start twisting the poignets once the halteres pass your cuisses so that the palms of vos mains face forward at the end of le mouvement. Make sure that you contract the biceps as you Expirez and make sure that only the forearms move. Continue le mouvement until your biceps are entierement contracte and the halteres are at epaules level. Maintenez 1 seconde as you squeeze the biceps. 4. Lentement, begin to bring the halteres back to the position de depart as your Inspirez and as you rotate the poignets back to a neutral grip. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Dumbbell Inner Biceps Curl', 'Biceps', 'Haltères', '1. Sit on the end of a flat banc with a halteres in each hand being held bras tendus. The coudes should be close to the torse. 2. Rotate the palms of the hands so that they are facing inward in a neutral position. Position de depart. 3. While holding the upper arms stationary, curl the halteres out and up, turning the palms out as you lift and keeping your forearms in line with your outer deltoids. Tips: 4. Only the forearms should move. Continue le mouvement until your biceps are entierement contracte and the halteres are at epaules level. Maintenez 1 seconde as you squeeze the biceps. 5. Lentement, begin to bring the halteres back to the position de depart as your Inspirez. Remember to rotate vos bras as you lower the halteres so that you can switch back to a neutral grip. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Inner_Biceps_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Dumbbell Palms-Down Wrist Curl', 'Avant-bras', 'Haltères', '1. Start out by placing two halteres on le sol in front of a flat banc. 2. Sit down on the edge of the flat banc with vos jambes at about epaules width apart. Make sure to keep vos pieds on le sol. 3. Use vos bras to grab both of the halteres and bring them up so that your forearms are resting against your cuisses with the palms of the hands facing down. Your poignets should be hanging over the edge of your cuisses. 4. Start out by curling your poignets upwards and exhaling. 5. Lentement, lower your poignets back down to the position de depart while inhaling. Make sure to inhale during this part of the exercise. Conseil : Your forearms should be stationary as your poignets is the only movement needed to perform this exercise. 6. Repetez selon le nombre souhaite. 7. When finished, simply lower the halteres to le sol.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Palms-Down_Wrist_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Dumbbell Palms-Up Wrist Curl', 'Avant-bras', 'Haltères', '1. Start out by placing two halteres on le sol in front of a flat banc. 2. Sit down on the edge of the flat banc with vos jambes at about epaules width apart. Make sure to keep vos pieds on le sol. 3. Use vos bras to grab both of the halteres and bring them up so that your forearms are resting against your cuisses with the palms of the hands facing up. Your poignets should be hanging over the edge of your cuisses. 4. Start out by curling your poignets upwards and exhaling. 5. Lentement, lower your poignets back down to the position de depart while inhaling. Make sure to inhale during this part of the exercise. Conseil : Your forearms should be stationary as your poignets is the only movement needed to perform this exercise. 6. Repetez selon le nombre souhaite. 7. When finished, simply lower the halteres to le sol.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Palms-Up_Wrist_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Dumbbell Press', 'Épaules', 'Haltères', '1. Grab a couple of halteres and sit on a military press banc or a utility banc that has a back support on it as you place the halteres upright on top of your cuisses. 2. Clean the halteres up one at a time by using your cuisses to bring the halteres up to epaules height at each side. 3. Rotate the poignets so that the palms of vos mains are facing forward. Position de depart. 4. en expirant, push the halteres up until they touch at the top. 5. Apres une pause, Lentement, come down back to the position de depart en inspirant. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Dumbbell_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Flat Bench Leg Pull-In', 'Abdominaux', 'Poids de corps', '1. Asseyez-vous sur un banc with the legs stretched out in front of you slightly below parallel and vos bras holding on to the sides of the banc. Your torse should be leaning backwards around a 45-degree angle from the banc. Position de depart. 2. Bring the genoux in toward you as you move your torse closer to them at the same time. Expirez as you perform this movement. 3. Apres une pause, go back to the position de depart en inspirant. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Flat_Bench_Leg_Pull-In/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Floor Hamstring Stretch', 'Ischio-jambiers', 'Autre', '1. Sit on a mat with your right leg extended in front of you and your left leg bent with your foot against your right inner cuisses. 2. Lean forward from your hips and reach for your ankle until you feel a stretch in your ischio-jambiers. Hold for 15 seconds, then Repetez for your other side.', 'Muscles secondaires : Mollets. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Floor_Hamstring_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Front Deltoid', 'Épaules', 'Poids de corps', '1. Sit upright on le sol with vos jambes bent, your partner standing behind you. Stick vos bras straight out to your sides, with your palms facing the ground. Attempt to move them as far behind you as possible, as your assistant holds your poignets. Position de depart. 2. Keeping your coudes straight, attempt to move vos bras to the front, with your partner gently restraining you to prevent any actual movement for 10-20 seconds. 3. Now, relax your muscles and allow your partner to gently increase the stretch on the epaules and poitrine. Hold for 10 to 20 seconds.', 'Muscles secondaires : Pectoraux. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Front_Deltoid/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Glute', 'Fessiers', 'Poids de corps', '1. In a seated position with your genoux bent, cross one ankle over the opposite genoux. Your partner will stand behind you. Now, lean forward as your partner braces your epaules with their hands. Position de depart. 2. Attempt to push your torse back for 10-20 seconds, as your partner prevents any actual movement of your torse. 3. Now relax your muscles as your partner increases the stretch by gently pushing your torse forward for 10-20 seconds.', 'Muscles secondaires : Adducteurs. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Glute/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Good Mornings', 'Bas du dos', 'Barre', '1. Set up a box in a power rack. The pins should be set at an appropriate height. Begin by stepping under the bar and placing it across the back of the epaules, not on top of your traps. Squeeze your omoplates together and rotate your coudes forward, attempting to bend the bar across your epaules. 2. Remove the bar from the rack, creating a tight arch in your lower back. Keep your head facing forward. With votre dos, epaules, and sangle abdominale tight, push your genoux and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Position de depart. 3. Keeping the bar tight, bend forward at the hips as much as possible. If you set the pins to what would be parallel, you not only have a safety if you fail, but know when to stop. 4. Pause just above the pins and reverse the motion until your torse it upright.', 'Muscles secondaires : Fessiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Good_Mornings/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Hamstring', 'Ischio-jambiers', 'Autre', '1. In a seated position with vos jambes extended, have your partner stand behind you. Now, lean forward as your partner braces your epaules with their hands. Position de depart. 2. Attempt to push your torse back for 10-20 seconds, as your partner prevents any actual movement of your torse. 3. Now relax your muscles as your partner increases the stretch by gently pushing your torse forward for 10-20 seconds.', 'Muscles secondaires : Mollets. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Hamstring/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Hamstring and Calf Stretch', 'Ischio-jambiers', 'Autre', '1. Loop a belt, rope, or band around one foot. Sit down with both legs extended . Position de depart. 2. Leaning forward slightly, pull on the belt to draw the toes of your foot back. Hold this position for 10-20 seconds and then Repetez with the other leg.', 'Muscles secondaires : Mollets. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Hamstring_and_Calf_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Head Harness Neck Resistance', 'Cou', 'Autre', '1. Place a neck strap on le sol at the end of a flat banc. Once you have selected the poids, sit at the end of the flat banc with vos pieds wider than epaules width apart from each other. Your toes should be pointed out. 2. Lentement, move your torse forward until it is almost parallel with le sol. Using both hands, securely position the neck strap around your head. Conseil : Make sure the poids are still lying on le sol to prevent any strain on the neck. Now grab the poids with both hands while elevating your torse back until it is almost perpendicular to le sol. Note: Your head and torse needs to be slightly tilted forward to perform this exercise. 3. Now place both hands on top of your genoux. Position de depart. 4. Lentement, lower your neck down until your chin touches the upper part of your poitrine while breathing in. 5. While exhaling, bring your neck back to the position de depart. 6. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Head_Harness_Neck_Resistance/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Leg Curl', 'Ischio-jambiers', 'Machine', '1. Adjust the machine lever to fit your height and sit on the machine with votre dos against the back support pad. 2. Place the back of lower leg on top of padded lever (just a few inches under the mollets) and secure the lap pad against your cuisses, just above the genoux. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. Position de depart. 3. en expirant, pull the machine lever as far as possible to the back of your cuisses by flexing at the genoux. Keep your torse stationary en permanence. Maintenez 1 seconde. 4. Lentement, Revenez en position de depart as you Inspirez. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Leg_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Leg Tucks', 'Abdominaux', 'Poids de corps', '1. Asseyez-vous sur un banc with the legs stretched out in front of you slightly below parallel and vos bras holding on to the sides of the banc. Your torse should be leaning backwards around a 45-degree angle from the banc. Position de depart. 2. Bring the genoux in toward you as you move your torse closer to them at the same time. Expirez as you perform this movement. 3. Apres une pause, go back to the position de depart en inspirant. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Leg_Tucks/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated One-Arm Dumbbell Palms-Down Wrist Curl', 'Avant-bras', 'Haltères', '1. Sit on a flat banc with a halteres in your right hand. 2. Place vos pieds flat on le sol, at a distance that is slightly wider than epaules width apart. 3. Lean forward and place your right forearm on top of your upper right cuisses with your palm down. Conseil : Make sure that the back of the poignets lies on top of your genoux. Position de depart. 4. Lower the halteres as far as possible as you keep a tight grip on the halteres. Inhale as you perform this movement. 5. Now curl the halteres as high as possible as you contract the forearms and en expirant. Keep the contraction for a second before you lower again. Conseil : The only movement should happen at the poignets. 6. Perform for the recommended amount of repetitions, switch arms and Repetez le mouvement.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated One-Arm Dumbbell Palms-Up Wrist Curl', 'Avant-bras', 'Haltères', '1. Sit on a flat banc with a halteres in your right hand. 2. Place vos pieds flat on le sol, at a distance that is slightly wider than epaules width apart. 3. Lean forward and place your right forearm on top of your upper right cuisses with your palm up. Conseil : Make sure that the front of the poignets lies on top of your genoux. Position de depart. 4. Lower the halteres as far as possible as you keep a tight grip on the halteres. Inhale as you perform this movement. 5. Now curl the halteres as high as possible as you contract the forearms and en expirant. Keep the contraction for a second before you lower again. Conseil : The only movement should happen at the poignets. 6. Perform for the recommended amount of repetitions, switch arms and Repetez le mouvement.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated One-arm Cable Pulley Rows', 'Milieu du dos', 'Poulie', '1. To get into the position de depart, first sit down on the machine and place vos pieds on the front platform or crossbar provided making sure that your genoux are slightly bent and not locked. 2. Lean over as you keep the natural alignment of votre dos and grab the single handle attachment with your left arm using a palms-down grip. 3. With your arm extended pull back until your torse is at a 90-degree angle from vos jambes. votre dos should be slightly arched and your poitrine should be sticking out. You should be feeling a nice stretch on your lat as you hold the bar in front of you. The right arm can be kept by the waist. Position de depart. of the exercise. 4. Keeping the torse stationary, pull the handles back towards your torse while keeping the arms close to it as you rotate the poignets, so that by the time your hand is by your abdominals it is in a neutral position (palms facing the torse). Expirez as you perform that movement. At that point you should be squeezing votre dos muscles hard. 5. Hold that contraction for a second and Lentement, go back to the original position while breathing in. Conseil : Remember to rotate the poignets as you go back to the position de depart so that the palms are facing down again. 6. Repetez selon le nombre souhaite. and then perform the same movement with the right hand.', 'Muscles secondaires : Biceps, Dos, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_One-arm_Cable_Pulley_Rows/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Overhead Stretch', 'Abdominaux', 'Autre', '1. Sit up straight on an exercise mat. 2. Touch the soles of vos pieds together with vos pieds six to eight inches in front of your hips. 3. Place one hand on le sol beside you and your other hand behind your head. 4. Lift your coudes to the ceiling as you incline your torse to the other side. Hold for 10 to 20 seconds, then switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Overhead_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Palm-Up Barbell Wrist Curl', 'Avant-bras', 'Barre', '1. Hold a barre with both hands and your palms facing up; hands spaced about epaules width. 2. Place vos pieds flat on le sol, at a distance that is slightly wider than epaules width apart. 3. Lean forward and place your forearms on top of your upper cuisses with your palms up. Conseil : Make sure that the front of the poignets lay on top of your genoux. Position de depart. 4. Lower the bar as far as possible while inhaling and keeping a tight grip. 5. Now curl bar up as high as possible while flexing the forearms and exhaling. Hold the contraction at the top for a second and Conseil : Only the poignets should move.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Palm-Up_Barbell_Wrist_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Palms-Down Barbell Wrist Curl', 'Avant-bras', 'Barre', '1. Hold a barre with both hands and your palms facing down; hands spaced about epaules width. 2. Place vos pieds flat on le sol, at a distance that is slightly wider than epaules width apart. 3. Lean forward and place your forearms on top of your upper cuisses with your palms down. Conseil : Make sure that the back of the poignets lay on top of your genoux. Position de depart. 4. Lower the bar as far as possible while inhaling and keeping a tight grip. 5. Now curl bar up as high as possible while flexing the forearms and exhaling. Hold the contraction at the top for a second and Conseil : Only the poignets should move.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Palms-Down_Barbell_Wrist_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Side Lateral Raise', 'Épaules', 'Haltères', '1. Pick a couple of halteres and sit at the end of a flat banc with vos pieds firmly on le sol. Hold the halteres with your palms facing in and vos bras straight down at your sides at arms'' length. Position de depart. 2. While maintaining the torse stationary (no swinging), lift the halteres to your side with a slight bend on the coudes and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to le sol. Exhale as you execute this movement and pause for a second at the top. 3. Lower the halteres back down Lentement, to the position de depart en inspirant. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Side_Lateral_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Triceps Press', 'Triceps', 'Haltères', '1. Asseyez-vous sur un banc with back support and grasp a halteres with both hands and hold it overhead at arm''s length. Conseil : a better way is to have somebody hand it to you especially if it is very heavy. The resistance should be resting in the palms of vos mains with your thumbs around it. The palm of the hand should be facing inward. Position de depart. 2. Keeping your upper arms close to your head (coudes in) and perpendicular to le sol, lower the resistance in a semi-circular motion behind your head until your forearms touch your biceps. Conseil : The upper arms should remain stationary and only the forearms should move. Inspirez as you perform this step. 3. Go back to the position de depart by using the triceps to raise the halteres. Expirez as you perform this step. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Triceps_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Seated Two-Arm Palms-Up Low-Pulley Wrist Curl', 'Avant-bras', 'Poulie', '1. Put a banc in front of a low pulley machine that has a barre or EZ Curl attachment on it. 2. Move the banc far enough away so that when you bring the handle to the top of your cuisses tension is created on the cable due to the poids stack being moved up. 3. Now hold the handle with both hands, palms up, using a epaules-width grip. 4. Step back and sit on the banc with vos pieds about epaules width apart, firmly on le sol. 5. Lean forward and place the forearms on your cuisses with the back of your poignets over your genoux. Position de depart. 6. Lower the bar as far as possible, while inhaling and keeping a tight grip. 7. Now curl the bar up as high as possible while contracting the forearms. Conseil : Only the poignets should move; not the forearms. 8. After a second contraction at the top go back to the position de depart en inspirant. 9. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('See-Saw Press (Alternating Side Press)', 'Épaules', 'Haltères', '1. Grab a halteres with each hand and stand up erect. 2. Clean (lift) the halteres to the poitrine/epaules level and then rotate your poignets so that your palms are facing towards you as if you were getting ready to perform an Arnold Press. Position de depart. 3. Now start extending your left arm overhead as you rotate the poignets so that the palm of your hand faces forward as you go up. Your coudes should come out also as you lift the poids. Simultaneously, you will also be bending from your hip to your opposite side. Conseil : If you perform the exercise correctly, is should look as if you are trying to reach for something overhead on the right hand side of votre corps, but with your left arm. Expirez as you perform this movement. 4. Once you reach the top position Inspirez. Then, with the poids fully extended overhead and you bent over to your right hand side, begin le mouvement to the left side. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Abdominaux, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/See-Saw_Press_Alternating_Side_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Shotgun Row', 'Dos', 'Poulie', '1. Attach a single handle to a low cable. 2. After selecting the correct poids, stand a couple feet back with a wide-split stance. Your arm should be extended and your epaules forward. Position de depart. 3. Perform le mouvement by retracting the epaules and flexing the coudes. As you pull, supinate the poignets, turning the palm upward as you go. 4. Apres une pause, Revenez en position de depart.', 'Muscles secondaires : Biceps, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Shotgun_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Shoulder Circles', 'Épaules', 'Autre', '1. With epaules relaxed and arms resting loosely at your sides (or in your lap if you''re seated), gently roll your epaules forward, up, back, and down. 2. Reverse direction. You can do this exercise alternating epaules or both at the same time.', 'Muscles secondaires : Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Shoulder_Circles/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Shoulder Press - With Bands', 'Épaules', 'Élastique', '1. To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles and lift them so that the hands are at epaules height at each side. 2. Rotate the poignets so that the palms of vos mains are facing forward. Your coudes should be bent, with the upper arms and forearms in line to the torse. Position de depart. 3. en expirant, lift the handles up until vos bras are fully extended overhead.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Shoulder_Press_-_With_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Shoulder Raise', 'Épaules', 'Autre', '1. Relax vos bras to your sides and raise your epaules up toward your ears, then back down.', 'Muscles secondaires : Dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Shoulder_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Shoulder Stretch', 'Épaules', 'Autre', '1. Reach your left arm across votre corps and hold it straight.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Shoulder_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Side-Lying Floor Stretch', 'Dos', 'Autre', '1. First lie on your left side, bending your left genoux in front of you to stabilize your torse (use your abdominal muscles as well to hold you upright). 2. Straighten your right leg and rest the right foot on le sol behind your left. Straighten your right arm over your head and gently pull on your right poignets to stretch the entire right side of the body. Switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side-Lying_Floor_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Side Bridge', 'Abdominaux', 'Poids de corps', '', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Bridge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Side Hop-Sprint', 'Quadriceps', 'Autre', '1. Stand to the side of a cone or hurdle. 2. Begin this drill by hopping sideways over the obstacle, rebounding out of your landing to hop back to where you started. 3. Hop for a prescribed number or repetitions as quickly as possible, and finish this drill by sprinting a short distance upon landing the last hop.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Hop-Sprint/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Side Jackknife', 'Abdominaux', 'Poids de corps', '', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Jackknife/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Side Lateral Raise', 'Épaules', 'Haltères', '1. Pick a couple of halteres and Tenez-vous debout avec a straight torse and the halteres by your side bras tendus with the palms of the hand facing you. Position de depart. 2. While maintaining the torse in a stationary position (no swinging), lift the halteres to your side with a slight bend on the coudes and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to le sol. Exhale as you execute this movement and pause for a second at the top. 3. Lower the halteres back down Lentement, to the position de depart en inspirant. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lateral_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Side Laterals to Front Raise', 'Épaules', 'Haltères', '1. In a standing position, hold a pair of halteres at your side. Position de depart. 2. Keeping your coudes slightly bent, raise the poids directly in front of you to epaules height, avoiding any swinging or cheating. 3. At the top of the exercise move the poids out in front of you, keeping vos bras extended. 4. Lower the poids with a controlled motion. 5. On the next repetition, raise the poids in front of you to epaules height before moving the poids laterally to your sides. 6. Lower the poids to the position de depart.', 'Muscles secondaires : Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Laterals_to_Front_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Side Leg Raises', 'Adducteurs', 'Poids de corps', '1. Stand next to a chair, which you may hold onto as a support. Stand on one leg. Position de depart. 2. Keeping your leg straight, raise it as far out to the side as possible, and swing it back down, allowing it to cross the opposite leg. 3. Repetez this swinging motion 5-10 times, increasing the range of motion as you do so.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Leg_Raises/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Side Lying Groin Stretch', 'Adducteurs', 'Autre', '1. Start off by lying on your right side and bend your right genoux in front of you to stabilize the torse. 2. Rest your head on your right hand or epaules. Lift your left leg upward and hold it by the back of the genoux (easier) or the foot (harder). 3. Pull your left genoux in toward your left epaules and simultaneously press your foot or genoux down to le sol. To intensify this stretch, straighten your left leg. Switch sides.', 'Muscles secondaires : Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Lying_Groin_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Side Neck Stretch', 'Cou', 'Autre', '1. Start with your epaules relaxed, gently tilt your head towards your epaules. 2. Assist stretch with a gentle pull on the side of the head.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Neck_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Side Standing Long Jump', 'Quadriceps', 'Autre', '1. Begin standing with vos pieds hip width apart in an athletic stance. Your head and poitrine should be up, genoux and hips slightly bent. Position de depart. 2. Leaning to your right, extend through your hips, genoux, and ankles to jump into the air. Block with the arms to lead le mouvement, jumping as far to your right as you can. 3. Land facing the same direction with vos pieds hip width apart, absorbing the impact through your lower body.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Standing_Long_Jump/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Side To Side Chins', 'Dos', 'Autre', '1. Grab the pull-up bar with the palms facing forward using a prise large. 2. As you have both arms extended in front of you holding the bar at a prise large, bring your torse back around 30 degrees or so while creating a curvature on your lower back and sticking your poitrine out. Position de depart. 3. Pull your torse up while leaning to the left hand side until the bar almost touches your upper poitrine by drawing the epaules and the upper arms down and back. Exhale as you perform this portion of le mouvement. Conseil : Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torse should remain stationary as it moves through space (no swinging) and only the arms should move. The forearms should do no other work other than hold the bar. 4. After a second of contraction, inhale as you go back to the position de depart. 5. Now, pull your torse up while leaning to the right hand side until the bar almost touches your upper poitrine by drawing the epaules and the upper arms down and back. Exhale as you perform this portion of le mouvement. Conseil : Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torse should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar. 6. After a second of contraction, inhale as you go back to the position de depart. 7. Repetez steps 3-6 until you have performed the prescribed amount of repetitions for each side.', 'Muscles secondaires : Biceps, Avant-bras, Milieu du dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_To_Side_Chins/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Side Wrist Pull', 'Épaules', 'Autre', '1. This stretch works best standing. Cross your left arm over the midline of votre corps and hold the left poignets in your right hand down at the level of your hips. Start the stretch with a bent left arm. 2. Lentement, straighten, pull, and lift it up to epaules height, as pictured. Feel this stretch originate in votre dos, not your epaules, and don''t pull too hard on the epaules joint. Switch sides.', 'Muscles secondaires : Avant-bras, Dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_Wrist_Pull/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Side to Side Box Shuffle', 'Quadriceps', 'Autre', '1. Stand to one side of the box with your left foot resting on the middle of it. 2. To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on le sol. Swing vos bras to aid your movement. 3. Continue shuffling back and forth across the box.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Side_to_Side_Box_Shuffle/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Single-Arm Cable Crossover', 'Pectoraux', 'Poulie', '1. Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand. 2. Step forward in front of both pulleys with vos bras extended in front of you, bringing vos mains together. Your head and poitrine should be up as you lean forward, while vos pieds should be staggered. Position de depart. 3. Keeping your left arm in place, allow your right arm to extend out to the side, maintaining a slight bend at the coudes. The right arm should be perpendicular to the body at approximately epaules level. 4. Return your arm back to the position de depart by pulling your hand back to the midline of the body. 5. Maintenez 1 seconde at the position de depart and Repetez le mouvement on the opposite side. Continue alternating back and forth for the prescribed number of repetitions.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Arm_Cable_Crossover/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Single-Arm Linear Jammer', 'Épaules', 'Barre', '1. Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate poids. 2. Raise the bar from le sol, taking it to your epaules with one or both hands. Adopt a wide stance. Position de depart. 3. Perform le mouvement by extending the coudes, pressing the poids up. Move explosively, extending the hips and genoux fully to produce maximal force. 4. Revenez en position de depart.', 'Muscles secondaires : Pectoraux, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Arm_Linear_Jammer/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Single-Arm Push-Up', 'Pectoraux', 'Poids de corps', '1. Begin laying prone on the ground. Move yourself into a position supporting your poids on your toes and one arm. Your working arm should be placed directly under the epaules, fully extended. vos jambes should be extended, and for this movement you may need a wider base, placing vos pieds further apart than in a normal push-up. 2. Maintain good posture, and place your free hand behind votre dos. Position de depart. 3. Lower yourself by allowing the coudes to flex until you touch the ground. 4. Descend slowly, and reverse direction be extending the arm to Revenez en position de depart.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Arm_Push-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Single-Cone Sprint Drill', 'Quadriceps', 'Autre', '1. This drill teaches quick foot action. You need a single cone. Begin standing next to the cone with one arm back and one arm forward. 2. Chop the feet as quickly as possible, blocking with the arms. Circle the cone, keep your genoux up, with violent foot action. 3. Rest after three trips around the cone.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Cone_Sprint_Drill/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Single-Leg High Box Squat', 'Quadriceps', 'Autre', '1. Position a box in a rack. Secure a band or rope in place above the box. 2. Standing in front of it, step onto the box to a full standing position, letting your other leg remain unsupported. Hold onto the band for balance 3. . Continue stepping up and down on the same leg before switching to the opposite side.', 'Muscles secondaires : Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Leg_High_Box_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Single-Leg Hop Progression', 'Quadriceps', 'Autre', '1. Arrange a line of cones in front of you. Assume a relaxed standing position, balanced on one leg. Raise the genoux of your opposite leg. Position de depart. 2. Hop forward, jumping and landing with the same leg over the cone. 3. Use a countermovement jump to hop from cone to cone. 4. At the end, turn around and go back on the other leg.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Leg_Hop_Progression/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Single-Leg Lateral Hop', 'Quadriceps', 'Autre', '1. Stand to the side of a cone or hurdle. To get into the start position, stand on one leg with your genoux slightly bent. 2. To begin, execute a counterjump to hop sideways over the cone. 3. Land on your jumping leg, and immediately rebound out of it by jumping back to the start position. 4. Continue hopping back and forth.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Leg_Lateral_Hop/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Single-Leg Leg Extension', 'Quadriceps', 'Machine', '1. Seat yourself in the machine and adjust it so that you are positioned properly. The pad should be against the lower part of the shin but not in contact with the ankle. Adjust the seat so that the pivot point is in line with your genoux. Select a poids appropriate for your abilities. 2. Maintaining good posture, fully extend one leg, pausing at the top of the motion. 3. Revenez en position de depart without letting the poids stop, keeping tension on the muscle. 4. Repetez for the desired number of repetitions.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Leg_Leg_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Single-Leg Stride Jump', 'Quadriceps', 'Autre', '1. Stand to the side of a box with your inside foot on top of it, close to the edge. 2. Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite genoux upward. 3. Land in the same position that you started, using your inside leg to decelerate the impact.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single-Leg_Stride_Jump/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Single Dumbbell Raise', 'Épaules', 'Haltères', '1. With a wide stance, hold a dumbell with both hands, grasping the head of the halteres instead of the handle. vos bras should be extended and hanging at the waist. Position de depart. 2. Raise the poids until it is above epaules level, keeping vos bras extended. Your torse and hips should remain stationary throughout le mouvement. 3. Revenez en position de depart and Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Dumbbell_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Single Leg Butt Kick', 'Quadriceps', 'Poids de corps', '1. Begin by standing on one leg, with the bent genoux raised. This will be your start position. 2. Using a countermovement jump, take off upward by extending the hip, genoux, and ankle of the grounded leg. 3. Immediately flex the genoux and attempt to touch your butt with the heel of your jumping leg. 4. Return the leg to a partially bent position underneath the hips and land. Your opposite leg should stay in relatively the same position throughout the drill.', 'Muscles secondaires : Mollets, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Butt_Kick/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Single Leg Glute Bridge', 'Fessiers', 'Poids de corps', '1. Lay on le sol with vos pieds flat and genoux bent. 2. Raise one leg off of the ground, pulling the genoux to your poitrine. Position de depart. 3. Execute le mouvement by driving through the heel, extending your hip upward and raising your fessiers off of the ground. 4. Extend as far as possible, pause and then Revenez en position de depart.', 'Muscles secondaires : Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Glute_Bridge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Single Leg Push-off', 'Quadriceps', 'Autre', '1. Stand on the ground with one foot resting on the box, heel close to the edge. 2. Push off with your foot on top of the box, trying to gain as much height as possible by extending through the hip and genoux. 3. Land with the same foot on top of the box, returning your other foot back to the start position.', 'Muscles secondaires : Mollets, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Single_Leg_Push-off/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Sit-Up', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol placing vos pieds either under something that will not move or by having a partner hold them. vos jambes should be bent at the genoux. 2. Place vos mains behind your head and lock them together by clasping your fingers. Position de depart. 3. Elevate your upper body so that it creates an imaginary V-shape with your cuisses. Expirez when performing this part of the exercise. 4. Once you feel the contraction for a second, lower your upper body back down to the position de depart while inhaling. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sit-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Sit Squats', 'Quadriceps', 'Autre', '1. Tenez-vous debout avec vos pieds epaules width apart. Position de depart. 2. Begin le mouvement by flexing your genoux and hips, sitting back with your hips. 3. Continue until you have squatted a portion of the way down, but are above parallel, and quickly reverse the motion until you Revenez en position de depart. Repetez for 5-10 repetitions.', 'Muscles secondaires : Abducteurs, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sit_Squats/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Skating', 'Quadriceps', 'Autre', '1. Roller skating is a fun activity which can be effective in improving cardiorespiratory fitness and muscular endurance. It requires relatively good balance and coordination. It is necessary to learn the basics of skating including turning and stopping and to wear protective gear to avoid possible injury. 2. You can skate at a comfortable pace for 30 minutes straight. If you want a cardio challenge, do interval skating — speed skate two minutes of every five minutes, using the remaining three minutes to recover. A 150 lb person will typically burn about 175 calories in 30 minutes skating at a comfortable pace, similar to brisk walking.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Skating/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Sled Drag - Harness', 'Quadriceps', 'Autre', '1. To begin, load the sled with the desired poids and attach the pulling strap. You can pull with handles, use a harness, or attach the pulling strap to a poids belt. 2. Whether pulling forwards or backwards, lean in the direction of travel and progress by extending through the hips and genoux.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sled_Drag_-_Harness/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Sled Overhead Backward Walk', 'Épaules', 'Autre', '1. Attach dual handles to a sled connected by a rope or chain. Load the sled to a light poids. 2. Face the sled, backing up until there is some tension in the line. Hold vos mains directly above your head with your coudes extended. Position de depart. 3. Walk backwards, keeping vos bras raised above your head. Avoid jerky movements.', 'Muscles secondaires : Mollets, Milieu du dos, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sled_Overhead_Backward_Walk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Sled Overhead Triceps Extension', 'Triceps', 'Autre', '1. Attach dual handles to a sled using a chain or rope. Load the sled to an appropriate load. 2. Facing away from the sled, step away until there is tension in the line. Raise vos mains above your head, keeping them together, palms facing each other. Your coudes should be pointed upward with the coudes flexed. Position de depart. 3. Extend through the coudes to straighten the arm. Ensure that your upper arm stays in position to isolate the triceps. 4. Upon full extension, step forward to take the slack out of the line. You may keep vos pieds staggered for more stability.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sled_Overhead_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Sled Push', 'Quadriceps', 'Autre', '1. Load your pushing sled with the desired poids. 2. Take an athletic posture, leaning into the sled with vos bras fully extended, grasping the handles. Push the sled as fast as possible, focusing on extending your hips and genoux to strengthen your posterior chain.', 'Muscles secondaires : Mollets, Pectoraux, Fessiers, Ischio-jambiers, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sled_Push/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Sled Reverse Flye', 'Épaules', 'Autre', '1. Attach dual handles to a sled connected by a rope or chain. Load the sled to a light poids. 2. Face the sled, backing up until there is some tension in the line. Take both handles bras tendus at about waist level. Bend the genoux slightly and keep your poitrine and head up. Position de depart. 3. Without flexing the coudes, pull the handles upward and apart, performing a reverse fly with some external rotation. Your palms should be facing forward as you do this. 4. Revenez en position de depart, taking a couple steps back to take the slack out of the line.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sled_Reverse_Flye/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Sled Row', 'Milieu du dos', 'Autre', '1. Attach dual handles to a sled connected by a rope or chain. Load the sled to an appropriate poids. Face the sled, backing up until there is some tension in the line. 2. With a handle in each hand, bend the genoux slightly, keep your head and poitrine up, and begin with vos bras extended. 3. To initiate le mouvement, flex the coudes as you retract your omoplates, pulling the sled towards you. 4. Take a step or two back to get tension in the line and Repetez.', 'Muscles secondaires : Biceps, Dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sled_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Sledgehammer Swings', 'Abdominaux', 'Autre', '1. You will need a tire and a sledgehammer for this exercise. Stand in front of the tire about two feet away from it with a staggered stance. Grip the sledgehammer. 2. If you are right handed, your left hand should be at the bottom of the handle, and your right hand should be choking up closer to the head. 3. As you bring the sledge up, your right hand slides toward the head; as you swing down, your right hand will slide down to join your left hand. Slam it down as hard as you can against the tire. Control the bounce of the hammer off of the tire. 4. Repetez de l autre cote.', 'Muscles secondaires : Mollets, Avant-bras, Dos, Milieu du dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sledgehammer_Swings/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Incline Shoulder Raise', 'Épaules', 'Barre', '1. Place an incline banc underneath the smith machine. Place the barre at a height that you can reach when lying down and vos bras are almost fully extended. Once the poids you need is selected, Allongez-vous sur un banc incline and make sure your epaules are aligned right under the barre. 2. Using a epaules width pronated (palms forward) grip, lift the bar from the rack and hold it straight over you with a slight bend at the coudes. Position de depart. 3. As you Expirez, lift the bar up until vos bras are fully extended. Note: The contraction should be felt around the epaules. 4. Apres une pause, bring the bar back down to the position de depart as you Inspirez. 5. Repetez le mouvement for the prescribed amount of repetitions. 6. When you are done, place the bar back in the rack.', 'Muscles secondaires : Pectoraux. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Incline_Shoulder_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Machine Behind the Back Shrug', 'Trapèzes', 'Machine', '1. With the bar at cuisses level, load an appropriate poids. 2. Tenez-vous debout avec the bar behind you, taking a epaules-width, pronated grip on the bar and unhook the poids. You should be standing up straight with your head and poitrine up and vos bras extended. Position de depart. 3. Initiate le mouvement by shrugging your epaules straight up. Do not flex the arms or poignets during le mouvement. 4. Apres une pause, return the poids to the position de depart. 5. Repetez for the desired number of repetitions before engaging the hooks to rack the poids.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Behind_the_Back_Shrug/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Machine Bench Press', 'Pectoraux', 'Machine', '1. Place a flat banc underneath the smith machine. Now place the barre at a height that you can reach when lying down and vos bras are almost fully extended. Once the poids you need is selected, Allongez-vous sur un banc plat. Using a pronated grip that is wider than epaules width, unlock the bar from the rack and hold it straight over you with vos bras locked. Position de depart. 2. As you Inspirez, come down Lentement, until you feel the bar on your middle poitrine. 3. Apres une pause, bring the bar back to the position de depart as you Expirez and push the bar using your poitrine muscles. Lock vos bras in the contracted position, Maintenez 1 seconde and then start coming down Lentement, again. Conseil : It should take at least twice as long to go down than to come up. 4. Repetez le mouvement for the prescribed amount of repetitions. 5. When you are done, lock the bar back in the rack.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Machine Bent Over Row', 'Milieu du dos', 'Machine', '1. Set the barre attached to the smith machine to a height that is about 2 inches below your genoux. 2. Bend your genoux slightly and bring your torse forward, by bending at the waist, while keeping the back straight until it is almost parallel to le sol. Conseil : Make sure that you keep the head up. 3. Now grasp the barre using an overhand (pronated) grip and unlock it from the smith machine rack. Then let it hang directly in front of you as vos bras hang extended perpendicular to le sol and your torse. Position de depart. 4. While keeping the torse stationary, lift the barre as you Expirez, keeping the coudes close to the body and not doing any force with the forearm other than holding the poids. On the top contracted position, squeeze the back muscles and Maintenez 1 seconde. 5. Lentement, lower the poids again to the position de depart en inspirant. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Bent_Over_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Machine Calf Raise', 'Mollets', 'Machine', '1. Place a block or poids plate below the bar on the Smith machine. Set the bar to a position that best matches your height. Once the correct height is chosen and the bar is loaded, step onto the plates with the balls of vos pieds and place the bar on the back of your epaules. 2. Take the bar with both hands facing forward. Rotate the bar to unrack it. Position de depart. 3. Raise your heels as high as possible by pushing off of the balls of vos pieds, flexing your calf at the top of the contraction. Your genoux should remain extended. Maintenez 1 seconde before you start to go back down. 4. Return Lentement, to the position de depart as you Inspirez while lowering your heels. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Calf_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Machine Close-Grip Bench Press', 'Triceps', 'Machine', '1. Place a flat banc underneath the smith machine. Place the barre at a height that you can reach when lying down and vos bras are almost fully extended. Once the poids you need is selected, Allongez-vous sur un banc plat. Using a close and pronated grip (palms facing forward) that is around epaules width, unlock the bar from the rack and hold it straight over you with vos bras locked. Position de depart. 2. As you Inspirez, come down Lentement, until you feel the bar on your middle poitrine. Conseil : Make sure that as opposed to a regular banc press, you keep the coudes close to the torse en permanence in order to maximize triceps involvement. 3. Apres une pause, bring the bar back to the position de depart as you Expirez and push the bar using your triceps muscles. Lock vos bras in the contracted position, Maintenez 1 seconde and then start coming down Lentement, again. Conseil : It should take at least twice as long to go down than to come up. 4. Repetez le mouvement for the prescribed amount of repetitions. 5. When you are done, lock the bar back in the rack.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Close-Grip_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Machine Decline Press', 'Pectoraux', 'Machine', '1. Position a decline banc in the rack so that the bar will be above your poitrine. Load an appropriate poids and take your place on the banc. 2. Rotate the bar to unhook it from the rack and fully extend vos bras. votre dos should be slightly arched and your omoplates retracted. Position de depart. 3. Begin le mouvement by flexing vos bras, lowering the bar to your poitrine. 4. Pause briefly, and then extend vos bras to push the poids back to the position de depart. 5. After completing the desired number of repetitions, rotate the bar to rack the poids.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Decline_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Machine Hang Power Clean', 'Ischio-jambiers', 'Machine', '1. Position the bar at genoux height and load it to an appropriate poids. 2. Take a pronated grip on the bar outside of epaules width and unhook the bar from the machine. vos bras should be fully extended with your head and poitrine up. Your coudes should be pointed out with your epaules back and down. Your hips should be back, loading the tension into the ischio-jambiers. Position de depart. 3. Initate le mouvement by forcefully extending the hips and genoux, accelerating into the bar. Ensure that you keep vos bras straight during this part of the motion. 4. Upon full extension, rebend the hips and genoux to lower your receiving position. 5. Allow the arms to flex at this point, rotating the coudes around the bar to receive it on your epaules. 6. Extend through the hips and genoux to come to a standing position with the bar racked on your epaules to complete le mouvement.', 'Muscles secondaires : Fessiers, Bas du dos, Quadriceps, Épaules, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Hang_Power_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Machine Hip Raise', 'Abdominaux', 'Machine', '1. Position a banc in the rack and load the bar to an appropriate poids. Lie down on the banc, placing the bottom of vos pieds against the bar. Unlock the bar and extend vos jambes. You may need to use vos mains to assist you. For added stability grasp the sides of the Smith Machine. Position de depart. 2. Initiate le mouvement by rotating your pelvis, flexing your spine to raise your hips off of the banc. Maintain a slight bend in the genoux throughout the motion. 3. Apres une pause, return the hips to the banc. 4. Repetez for the desired number of repetitions.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Hip_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Machine Incline Bench Press', 'Pectoraux', 'Machine', '1. Place an incline banc underneath the smith machine. Place the barre at a height that you can reach when lying down and vos bras are almost fully extended. Once the poids you need is selected, Allongez-vous sur un banc incline and make sure your upper poitrine is aligned with the barre. Using a pronated grip (palms facing forward) that is wider than epaules width, unlock the bar from the rack and hold it straight over you with vos bras locked. Position de depart. 2. As you Inspirez, come down Lentement, until you feel the bar on your upper poitrine. 3. Apres une pause, bring the bar back to the position de depart as you Expirez and push the bar using your poitrine muscles. Lock vos bras in the contracted position, Maintenez 1 seconde and then start coming down Lentement, again. Conseil : It should take at least twice as long to go down than to come up. 4. Repetez le mouvement for the prescribed amount of repetitions. 5. When you are done, place the bar back in the rack.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Incline_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Machine Leg Press', 'Quadriceps', 'Machine', '1. Position a Smith machine bar a couple feet off of the ground. Ensure that it is resting on the safeties. After loading the bar to an appropriate poids, lie underneath the bar. Place the middle of vos pieds on the bar, tucking your genoux to your poitrine. Position de depart. 2. Begin le mouvement by driving through vos pieds to move the bar upward, extending the hips and genoux. Do not lock out your genoux. 3. At the top of the motion, pause briefly before returning to the position de depart.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Leg_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Machine One-Arm Upright Row', 'Épaules', 'Machine', '1. With the bar at cuisses level, load an appropriate poids. 2. Take a prise large on the bar and unhook the poids, removing your off hand from the bar. Your arm should be extended as you Tenez-vous debout avec your head and poitrine up. Position de depart. 3. Begin le mouvement by flexing the coudes, raising the upper arm with the coudes pointed out. Continue until your upper arm is parallel to le sol. 4. Apres une pause, return the poids to the position de depart. 5. Repetez for the desired number of repetitions before engaging the hooks to rack the poids.', 'Muscles secondaires : Biceps, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_One-Arm_Upright_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Machine Overhead Shoulder Press', 'Épaules', 'Machine', '1. To begin, place a flat banc (or preferably one with back support) underneath a smith machine. Position the barre at a height so that when seated on the flat banc, the arms must be almost fully extended to reach the barre. 2. Once you have the correct height, sit slightly in behind the barre so that there is an imaginary straight line from the tip of your nose to the barre. vos pieds should be stationary. Grab the barre with the palms facing forward, unlock it and lift it up so that vos bras are fully extended. Position de depart. 3. Lentement, begin to lower the barre until it is level with your chin while inhaling. 4. Then lift the barre back to the position de depart using your epaules while exhaling. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Overhead_Shoulder_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Machine Pistol Squat', 'Quadriceps', 'Machine', '1. To begin, first set the bar to a position that best matches your height. Step under it and position the bar across the back of your epaules. 2. Take the bar with vos mains facing forward, unlock it and lift it off the rack by extending vos jambes. 3 3. Move one foot forward about 12 inches in front of the bar. Extend the other leg out in front of you, holding it off the ground. Look forward en permanence and maintain a neutral or slightly arched spine. Position de depart. 4. Maintaining good posture, lower yourself by flexing the genoux and hip, going down as far as flexibility allows. 5. Pause briefly at the bottom and then Revenez en position de depart by driving through the heel of your foot, extending the genoux and hip.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Pistol_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Machine Reverse Calf Raises', 'Mollets', 'Machine', '1. Adjust the barre on the smith machine to fit your height and align a raised platform right under the bar. 2. Stand on the platform with the heels of vos pieds secured on top of it with the balls of vos pieds extending off it. Position your toes facing forward with a epaules width stance. 3. Now, place your epaules under the barre while maintaining the foot positioning described and push the barre up by extending your hips and genoux until your torse is standing erect. The genoux should be kept with a slight bend; never locked. Position de depart. Conseil : The barre on votre dos is only for balance purposes. 4. Raise the balls of vos pieds as you Expirez by extending your toes as high as possible and flexing your calf. Ensure that the genoux is kept stationary en permanence. There should be no bending at any time. Maintenez 1 seconde before you start to go back down. 5. Lentement, go back down to the position de depart as you Inspirez by lowering the balls of vos pieds and toes. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Reverse_Calf_Raises/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Machine Squat', 'Quadriceps', 'Machine', '1. To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your epaules (slightly below the neck) across it. 2. Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Position vos jambes using a epaules width medium stance with the toes slightly pointed out. Keep your head up en permanence and also maintain a straight back. Position de depart. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section). 4. Begin to Lentement, lower the bar by bending the genoux as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the mollets becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to le sol). Inhale as you perform this portion of le mouvement. Conseil : If you performed the exercise correctly, the front of the genoux should make an imaginary straight line with the toes that is perpendicular to the front. If your genoux are past that imaginary line (if they are past your toes) then you are placing undue stress on the genoux and the exercise has been performed incorrectly. 5. Begin to raise the bar en expirant by pushing le sol with the heel of your foot as you straighten the legs again and go back to the position de depart. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Machine Stiff-Legged Deadlift', 'Ischio-jambiers', 'Machine', '1. To begin, set the bar on the smith machine to a height that is around the middle of your cuisses. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is epaules width apart. You may need some poignets wraps if using a significant amount of poids. 2. Lift the bar up by fully extending vos bras while keeping votre dos straight. Tenez-vous debout avec your torse straight and vos jambes spaced using a epaules width or narrower stance. The genoux should be slightly bent. Position de depart. 3. Keeping the genoux stationary, lower the barre to over the top of vos pieds by bending at the waist while keeping votre dos straight. Keep moving forward as if you were going to pick something from le sol until you feel a stretch on the ischio-jambiers. Exhale as you perform this movement 4. Start bringing your torse up straight again as soon as you feel the ischio-jambiers stretch by extending your hips and waist until you are back at the position de depart. Inhale as you perform this movement. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Fessiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Stiff-Legged_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Machine Upright Row', 'Trapèzes', 'Machine', '1. To begin, set the bar on the smith machine to a height that is around the middle of your cuisses. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is epaules width apart. You may need some poignets wraps if using a significant amount of poids. 2. Lift the barre up and fully extend vos bras with votre dos straight. There should be a slight bend at the coudes. Position de depart. 3. Use your side epaules to lift the bar en expirant. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Conseil : Your coudes should drive the motion. As you lift the bar, your coudes should always be higher than your forearms. Also, keep your torse stationary and pause for a second at the top of le mouvement. 4. Lower the bar back down Lentement, to the position de depart. Inhale as you perform this portion of le mouvement. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Milieu du dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Machine_Upright_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Smith Single-Leg Split Squat', 'Quadriceps', 'Machine', '1. To begin, place a flat banc 2-3 feet behind the smith machine. Then, set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your epaules (slightly below the neck) across it. 2. Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Position vos jambes by placing one foot slightly forward under the bar and extending your other leg back and place the top of your foot on the banc. Position de depart. 4. Begin to Lentement, lower the bar by bending the genoux as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calf becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to le sol). Inhale as you perform this portion of le mouvement. Conseil : If you performed the exercise correctly, the front of the genoux should make an imaginary straight line with the toes that is perpendicular to the front. If your genoux is past that imaginary line (if it is past your toes) then you are placing undue stress on the genoux and the exercise has been performed incorrectly. 5. Begin to raise the bar en expirant by pushing le sol with the heel of your foot mainly as you straighten your leg again and go back to the position de depart. 6. Repetez selon le nombre souhaite. 7. Switch legs and Repetez le mouvement.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Smith_Single-Leg_Split_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Snatch', 'Quadriceps', 'Barre', '1. Place vos pieds at a epaules width stance with the barre resting right above the connection between the toes and the rest of the foot. 2. With a palms facing down grip, bend at the genoux and keeping the back flat grab the bar using a wider than epaules width grip. Bring the hips down and make sure that votre corps drops as if you were going to sit on a chair. Position de depart. 3. Start pushing le sol as if it were a moving platform with vos pieds and simultaneously start lifting the barre keeping it close to vos jambes. 4. As the bar reaches the middle of your cuisses, push le sol with vos jambes and lift votre corps to a complete extension in an explosive motion. 5. Lift your epaules back in a shrugging movement as you bring the bar up while lifting your coudes out to the side and keeping them above the bar for as long as possible. 6. Now in a very quick but powerful motion, you have to get votre corps under the barre when it has reached a high enough point where it can be controlled and drop while locking vos bras and holding the barre overhead as you assume a squat position. 7. Finalize le mouvement by rising up out of the squat position to finish the lift. At the end of the lift both feet should be on line and the arms fully extended holding the barre overhead.', 'Muscles secondaires : Biceps, Fessiers, Ischio-jambiers, Bas du dos, Épaules, Trapèzes, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Snatch Balance', 'Quadriceps', 'Barre', '1. Begin with the feet in the pulling position, the bar racked across the back of the epaules, and the hands placed in a wide snatch grip. 2. Pop the bar with an abrupt dip and drive of the genoux, and aggressively drive under the bar, transitioning the feet into the receiving position. 3. Receive the bar locked out overhead near the bottom of the squat. The torse should remain vertical, lowering the hips between the legs. 4. Continue to descend to full depth, and return to a standing position. Carefully lower the poids.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_Balance/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Snatch Deadlift', 'Ischio-jambiers', 'Barre', '1. The snatch deadlift strengthens the first pull of the snatch. Begin with a wide snatch grip with the barre placed on the platform. The feet should be directly under the hips, with the feet turned out. Squat down to the bar, keeping the back in absolute extension with the head facing forward. 2. Initiate le mouvement by driving through the heels, raising the hips. The back angle should remain the same until the bar passes the genoux. 3. At that point, drive your hips through the bar as you lay back. Return the bar to the platform by reversing the motion.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Snatch Pull', 'Ischio-jambiers', 'Barre', '1. With a barre on le sol close to the shins, take a wide snatch grip. Lower your hips with the poids focused on the heels, back straight, head facing forward, poitrine up, with your epaules just in front of the bar. Position de depart. 2. Begin the first pull by driving through the heels, extending your genoux. votre dos angle should stay the same, and vos bras should remain straight. Move the poids with control as you continue to above the genoux. 3. Next comes the second pull, the main source of acceleration for the pull. As the bar approaches the mid-cuisses position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, genoux, and ankles, using speed to move the bar upward. 4. There should be no need to actively pull through the arms to accelerate the poids; at the end of the second pull, the body should be fully extended, leaning slightly back. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary.', 'Muscles secondaires : Mollets, Fessiers, Bas du dos, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_Pull/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Snatch Shrug', 'Trapèzes', 'Barre', '1. Begin with a prise large, with the bar hanging at the mid cuisses position. You can use a hook or prise en pronation. votre dos should be straight and inclined slightly forward. 2. Shrug your epaules towards your ears. While this exercise can usually by loaded with heavier poids than a snatch, avoid overloading to the point that the execution slows down.', 'Muscles secondaires : Avant-bras, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_Shrug/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Snatch from Blocks', 'Quadriceps', 'Barre', '1. Begin with a loaded barre on boxes or stands of the desired height. A prise large should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the poitrine up and the head looking forward. The epaules should be just in front of the bar, with the coudes pointed out. This will be the position de depart. 2. Begin the first pull by driving through the front of the heels, raising the bar from the boxes. 3. Transition into the second pull by extending through the hips genoux and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the epaules and allow the coudes to flex to the side. 4. As you move vos pieds into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar with votre corps as low as possible and the arms fully extended overhead. 5. Keeping the bar aligned over the front of the heels, your head and poitrine up, drive through heels of the feet to move to a standing position. Carefully return the poids to the boxes.', 'Muscles secondaires : Mollets, Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Épaules, Trapèzes, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Snatch_from_Blocks/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Speed Band Overhead Triceps', 'Triceps', 'Élastique', '1. For this exercise anchor a band to the ground. We used an incline banc and anchored the band to the base, standing over the banc. Alternatively, this could be performed standing on the band. 2. To begin, pull the band behind your head, holding it with a pronated grip and your coudes up. Position de depart. 3. To perform le mouvement, extend through the coudes to to straighten vos bras, ensuring that you keep your upper arm in place. 4. Pause, and then Revenez en position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Speed_Band_Overhead_Triceps/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Speed Box Squat', 'Quadriceps', 'Barre', '1. Attach bands to the bar that are securely anchored near the ground. You may need to choke the bands to get adequate tension. 2. Use a box of an appropriate height for this exercise. Load the bar to a poids that still requires effort, but isn''t so heavy that speed is compromised. Typically, that will be between 50-70% of your one rep max. 3. Position the bar on your upper back, omoplates retracted, back arched and everything tight head to toe. This will be the position de depart. 4. Unrack the bar and position yourself in front of the box. Sit back with your hips until you are seated on the box, ensuring that you descend under control and don''t crash onto the surface. 5. Pause briefly, and explode off of the box, extending through the hips and genoux.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Speed_Box_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Speed Squats', 'Quadriceps', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your epaules (slightly below the neck) across it. 2. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Step away from the rack and position vos jambes using a epaules width medium stance with the toes slightly pointed out. Keep your head up en permanence as looking down will get you off balance and also maintain a straight back. Position de depart. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section). 4. Begin to lower the bar by bending the genoux as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the mollets becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to le sol). Inhale as you perform this portion of le mouvement. Conseil : If you performed the exercise correctly, the front of the genoux should make an imaginary straight line with the toes that is perpendicular to the front. If your genoux are past that imaginary line (if they are past your toes) then you are placing undue stress on the genoux and the exercise has been performed incorrectly. 5. Begin to raise the bar as fast as possible without involving momentum en expirant by pushing le sol with the heel of your foot mainly as you straighten the legs again and go back to the position de depart. Note: You should perform these exercises as fast as possible but without breaking perfect form and without involving momentum. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Speed_Squats/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Spell Caster', 'Abdominaux', 'Haltères', '1. Hold a halteres in each hand with a pronated grip. vos pieds should be wide with your hips and genoux extended. Position de depart. 2. Begin le mouvement by pulling both of the halteres to one side next to your hip, rotating your torse. 3. Keeping vos bras straight and the halteres parallel to the ground, rotate your torse to swing the poids to your opposite side. 4. Continue alternating, rotating from one side to the other until the set is complete.', 'Muscles secondaires : Fessiers, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spell_Caster/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Spider Crawl', 'Abdominaux', 'Poids de corps', '1. Begin in a prone position on le sol. Support your poids on vos mains and toes, with vos pieds together and votre corps straight. vos bras should be bent to 90 degrees. Position de depart. 2. Initiate le mouvement by raising one foot off of the ground. Externally rotate the leg and bring the genoux toward your coudes, as far forward as possible. 3. Return this leg to the position de depart and Repetez de l autre cote.', 'Muscles secondaires : Pectoraux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spider_Crawl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Spider Curl', 'Biceps', 'Barre EZ', '1. Start out by setting the bar on the part of the preacher banc that you would normally sit on. Make sure to align the barre properly so that it is balanced and will not fall off. 2. Move to the front side of the preacher banc (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torse and stomach pressed against the front side of the preacher banc. 3. Make sure that vos pieds (especially the toes) are well positioned on le sol and place your upper arms on top of the pad located on the inside part of the preacher banc. 4. Use vos bras to grab the barre with a supinated grip (palms facing up) at about epaules width apart or slightly closer from each other. 5. Lentement, begin to lift the barre upwards and exhale. Maintenez 1 seconde as you squeeze the biceps. 6. Lentement, begin to bring the barre back to the position de depart as your Inspirez. . 7. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spider_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Spinal Stretch', 'Milieu du dos', 'Autre', '1. Sit in a chair so votre dos is straight and vos pieds planted on le sol. 2. Interlace your fingers behind your head, coudes out and your chin down. 3. Twist your upper body to one side about 3 times as far as you can. Then lean forward and twist your torse to reach your coudes to le sol on the inside of your genoux. 4. Return to upright position and then Repetez for your other side.', 'Muscles secondaires : Dos, Bas du dos, Cou, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Spinal_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Split Clean', 'Quadriceps', 'Barre', '1. With a barre on le sol close to the shins, take an prise en pronation just outside the legs. Lower your hips with the poids focused on the heels, back straight, head facing forward, poitrine up, with your epaules just in front of the bar. Position de depart. 2. Begin the first pull by driving through the heels, extending your genoux. votre dos angle should stay the same, and vos bras should remain straight. Move the poids with control as you continue to above the genoux. 3. Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-cuisses position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, genoux, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the poids; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. 4. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the coudes up and out. At peak extension, aggressively pull yourself down, rotating your coudes under the bar as you do so. 5. Receive the bar with the feet split, aggressively moving one foot forward and one foot back. The bar should be racked onto the protracted epaules, lightly touching the throat with the hands relaxed. Continue to descend to the bottom position, which will help in the recovery. 6. Immediately recover by driving through the heels, keeping the torse upright and coudes up. Bring the feet together as you stand up.', 'Muscles secondaires : Mollets, Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Épaules, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Split Jerk', 'Quadriceps', 'Barre', '1. Standing with the poids racked on the front of the epaules, begin with the dip. With vos pieds directly under your hips, flex the genoux without moving the hips backward. 2. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the epaules. At this moment as the feet leave le sol, the feet must be placed into the receiving position as quickly as possible. 3. In the brief moment the feet are not actively driving against the platform, the athlete''s effort to push the bar up will drive them down. The feet should be moved to a split stance, one foot forward, one foot back, with the genoux partially bent. Receive the bar with the arms locked out overhead. 4. Return to a standing position, bringing the feet together.', 'Muscles secondaires : Fessiers, Ischio-jambiers, Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Jerk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Split Jump', 'Quadriceps', 'Poids de corps', '1. Assume a lunge stance position with one foot forward with the genoux bent, and the rear genoux nearly touching the ground. 2. Ensure that the front genoux is over the midline of the foot. 3. Extending through both legs, jump as high as possible, swinging vos bras to gain lift. 4. As you jump, bring vos pieds together, and move them back to their initial positions as you land. 5. Absorb the impact by reverting back to the position de depart.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Jump/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Split Snatch', 'Ischio-jambiers', 'Barre', '1. Begin with a loaded barre on le sol. The bar should be close to or touching the shins, and a prise large should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the poitrine up and the head looking forward. The epaules should be just in front of the bar. This will be the position de depart. 2. Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the genoux. 3. Transition into the second pull by extending through the hips genoux and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the epaules and allow the coudes to flex to the side. 4. As you move vos pieds into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move forcefully to a split position, one foot forward one foot back. Receive the bar with votre corps as low as possible and the arms fully extended overhead. 5. Keeping the bar aligned over the front of the heels, your head and poitrine up, drive through heels of the feet to move to a standing position, bringing vos pieds together. 6. Carefully return the poids to floor.', 'Muscles secondaires : Mollets, Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Quadriceps, Épaules, Trapèzes, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Snatch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Split Squat with Dumbbells', 'Quadriceps', 'Haltères', '1. Position yourself into a staggered stance with the rear foot elevated and front foot forward. 2. Hold a halteres in each hand, letting them hang at the sides. Position de depart. 3. Begin by descending, flexing your genoux and hip to lower votre corps down. Maintain good posture througout le mouvement. Keep the front genoux in line with the foot as you perform the exercise. 4. At the bottom of le mouvement, drive through the heel to extend the genoux and hip to Revenez en position de depart.', 'Muscles secondaires : Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Squat_with_Dumbbells/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Split Squats', 'Ischio-jambiers', 'Autre', '1. Being in a standing position. Jump into a split leg position, with one leg forward and one leg back, flexing the genoux and lowering your hips slightly as you do so. 2. As you descend, immediately reverse direction, standing back up and jumping, reversing the position of vos jambes. Repetez 5-10 times on each leg.', 'Muscles secondaires : Mollets, Fessiers, Quadriceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Split_Squats/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Squat Jerk', 'Quadriceps', 'Barre', '1. Standing with the poids racked on the front of the epaules, begin with the dip. With vos pieds directly under your hips, flex the genoux without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the epaules. 2. At this moment as the feet leave le sol, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athlete''s effort to push the bar up will drive them down. The feet should move forcefully to just outside the hips, turned out as necessary. Receive the bar with votre corps in a full squat and the arms fully extended overhead. 3. Keeping the bar aligned over the front of the heels, your head and poitrine up, drive throught heels of the feet to move to a standing position. Carefully return the poids to floor.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Épaules, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squat_Jerk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Squat with Bands', 'Quadriceps', 'Barre', '1. Set up the bands on the sleeves, secured to either band pegs, the rack, or halteres so that there is appropriate tension. 2. Begin by stepping under the bar and placing it across the back of the epaules. Squeeze your omoplates together and rotate your coudes forward, attempting to bend the bar across your epaules. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place vos pieds wide for more emphasis on the back, fessiers, adductors, and ischio-jambiers. Keep your head facing forward. 3. With votre dos, epaules, and sangle abdominale tight, push your genoux and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torse lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the genoux. 4. Keeping the poids on your heels and pushing vos pieds and genoux out, drive upward as you lead le mouvement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the position de depart.', 'Muscles secondaires : Adducteurs, Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squat_with_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Squat with Chains', 'Quadriceps', 'Barre', '1. To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on le sol at the top of le mouvement. 2. Begin by stepping under the bar and placing it across the back of the epaules. Squeeze your omoplates together and rotate your coudes forward, attempting to bend the bar across your epaules. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place vos pieds wide for more emphasis on the back, fessiers, adductors, and ischio-jambiers. Keep your head facing forward. 3. With votre dos, epaules, and sangle abdominale tight, push your genoux and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torse lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the genoux. 4. Keeping the poids on your heels and pushing vos pieds and genoux out, drive upward as you lead le mouvement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the position de depart.', 'Muscles secondaires : Adducteurs, Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squat_with_Chains/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Squat with Plate Movers', 'Quadriceps', 'Barre', '1. To begin, first set the bar on a rack to just below epaules level. Position a poids plate on the ground a couple feet back from the rack. Once the bar is loaded, step under it and place the back of your epaules across it. 2. Hold on to the bar with both hands and lift it off the rack by first pushing with vos jambes and at the same time straighten your torse. 3. Step away from the rack and adopt a wide stance with the toes slightly pointed out, with one foot on the poids plate. Keep your head up en permanence. Position de depart. 4. Begin to Lentement, lower the bar by bending the genoux and hips. Continue down until the angle between the upper leg and the mollets becomes slightly less than 90-degrees. 5. Raise the bar en expirant by pushing le sol with the heels of vos pieds as you extend the hips and genoux. 6. At the top of le mouvement, side step, bringing vos pieds together on the opposite side of the plate. 7. Using your inside foot, push the poids plate, sliding it across le sol to where you were just standing. 8. Place your inside foot on the poids plate, adopting a wide stance for the next repetition.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squat_with_Plate_Movers/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Squats - With Bands', 'Quadriceps', 'Élastique', '1. To start out, make sure that the exercise band is at an even split between both the left and right side of the body. To do this, use vos mains to grab both sides of the band and place both feet in the middle of the band. vos pieds should be epaules width apart from each other. 2. When holding the bands, they should be the same height on each side. You should be using a pronated grip (palms facing forward) and have the handles of the bands next to your face for this exercise. Position de depart. 3. Lentement, start to bend the genoux and lower the legs so that your cuisses are parallel to le sol while exhaling. 4. Use the heel of vos pieds to push votre corps up to the position de depart en expirant. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Squats_-_With_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Stairmaster', 'Quadriceps', 'Machine', '1. To begin, step onto the stairmaster and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and poids to estimate the amount of calories burned during exercise. 2. Pump vos jambes up and down in an established rhythm, driving the pedals down but not all the way to le sol. It is recommended that you maintain your grip on the handles so that you don''t fall. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity. 3. Stairmasters offer convenience, cardiovascular benefits, and usually have less impact than running outside. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stairmaster/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Alternating Dumbbell Press', 'Épaules', 'Haltères', '1. Tenez-vous debout avec a halteres in each hand. Raise the halteres to your epaules with your palms facing forward and your coudes pointed out. Position de depart. 2. Extend one arm to press the halteres straight up, keeping your off hand in place. Do not lean or jerk the poids during le mouvement. 3. Apres une pause, return the poids to the position de depart. 4. Repetez de l autre cote, continuing to alternate between arms.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Alternating_Dumbbell_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Barbell Calf Raise', 'Mollets', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the bar on the back of your epaules (slightly below the neck). 2. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Step away from the rack and position vos jambes using a epaules width medium stance with the toes slightly pointed out. Keep your head up en permanence as looking down will get you off balance and also maintain a straight back. The genoux should be kept with a slight bend; never locked. Position de depart. Conseil : For better range of motion you may also place the ball of vos pieds on a wooden block but be careful as this option requires more balance and a sturdy block. 4. Raise your heels as you Expirez by extending your ankles as high as possible and flexing your calf. Ensure that the genoux is kept stationary en permanence. There should be no bending at any time. Hold the contracted position by a second before you start to go back down. 5. Go back Lentement, to the position de depart as you Inspirez by lowering your heels as you bend the ankles until mollets are stretched. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Barbell_Calf_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Barbell Press Behind Neck', 'Épaules', 'Barre', '1. This exercise is best performed inside a squat rack for easier pick up of the bar. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your epaules (slightly below the neck) across it. 2. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Step away from the rack and position vos jambes using a epaules width medium stance with the toes slightly pointed out. votre dos should be kept straight while performing this exercise. Position de depart. 4. Elevate the barre overhead by fully extending vos bras while breathing out. 5. Hold the contraction for a second and lower the barre back down to the position de depart by inhaling. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Barbell_Press_Behind_Neck/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Bent-Over One-Arm Dumbbell Triceps Extension', 'Triceps', 'Haltères', '1. With a halteres in one hand and the palm facing your torse, bend your genoux slightly and bring your torse forward, by bending at the waist, while keeping the back straight until it is almost parallel to le sol. Make sure that you keep the head up. 2. The upper arm should be close to the torse and parallel to le sol while the forearm is pointing towards le sol as the hand holds the poids. Conseil : There should be a 90-degree angle between the forearm and the upper arm. Position de depart. 3. Keeping the upper arms stationary, use the triceps to lift the poids en expirant until the forearms are parallel to le sol and the whole arm is extended. Like many other arm exercises, only the forearm moves. 4. After a second contraction at the top, Lentement, lower the halteres back to the position de depart en inspirant. 5. Repetez le mouvement for the prescribed amount of repetitions. 6. Switch arms and Repetez the exercise.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Bent-Over Two-Arm Dumbbell Triceps Extension', 'Triceps', 'Haltères', '1. With a halteres in each hand and the palms facing your torse, bend your genoux slightly and bring your torse forward, by bending at the waist, while keeping the back straight until it is almost parallel to le sol. Make sure that you keep the head up. The upper arms should be close to the torse and parallel to le sol while the forearms are pointing towards le sol as the hands hold the poids. Conseil : There should be a 90-degree angle between the forearms and the upper arm. Position de depart. 2. Keeping the upper arms stationary, use the triceps to lift the poids en expirant until the forearms are parallel to le sol and the whole arms are extended. Like many other arm exercises, only the forearm moves. 3. After a second contraction at the top, Lentement, lower the halteres back to their position de depart en inspirant. 4. Repetez le mouvement for the prescribed amount of repetitions.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Biceps Cable Curl', 'Biceps', 'Poulie', '1. Tenez-vous debout avec your torse upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at epaules width and keep the coudes close to the torse. The palm of vos mains should be facing up (supinated grip). Position de depart. 2. While holding the upper arms stationary, curl the poids while contracting the biceps as you Expirez. Only the forearms should move. Continue le mouvement until your biceps are entierement contracte and the bar is at epaules level. Maintenez 1 seconde as you squeeze the muscle. 3. Lentement, begin to bring the curl bar back to position de depart as your Inspirez. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Biceps_Cable_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Biceps Stretch', 'Biceps', 'Autre', '1. Clasp vos mains behind votre dos with your palms together, straighten arms and then rotate them so your palms face downward. 2. Raise vos bras up and hold until you feel a stretch in your biceps.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Biceps_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Bradford Press', 'Épaules', 'Barre', '1. Place a loaded bar at epaules level in a rack. With a pronated grip at epaules width, begin with the bar racked across the front of your epaules. Position de depart. 2. Initiate the lift by extending the coudes to press the bar overhead. Avoid locking out the coudes as you move the poids behind your head. 3. Lower the bar down to the back of the head until your coudes forms a right angle. 4. Lift the bar back over your head by extending the coudes 5. Lower the bar down to the position de depart. 6. Alternate in this manner until you complete the recommended amount of repetitions.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Bradford_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Cable Chest Press', 'Pectoraux', 'Poulie', '1. Position dual pulleys to poitrine height and select an appropriate poids. Stand a foot or two in front of the cables, holding one in each hand. You can stagger your stance for better stability. 2. Position the upper arm at a 90 degree angle with the omoplates together. Position de depart. 3. Keeping the rest of the body stationary, extend through the coudes to press the handles forward, drawing them together in front of you. 4. Pause at the top of the motion, and Revenez en position de depart.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Cable_Chest_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Cable Lift', 'Abdominaux', 'Poulie', '1. Connect a standard handle on a tower, and move the cable to the lowest pulley position. 2. With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the poids on the cable. Your outstretched arm should be aligned with the cable. 3. With vos pieds positioned epaules width apart, squat down and grab the handle with both hands. vos bras should still be fully extended. 4. In one motion, pull the handle up and across votre corps until vos bras are in a fully-extended position above your head. 5. Keep votre dos straight and vos bras close to votre corps as you pivot votre dos foot and straighten vos jambes to get a full range of motion. 6. Retract vos bras and then votre corps. Return to the neutral position in a slow and controlled manner. 7. Repetez to failure. 8. Then, reposition and Repetez the same series of movements on the opposite side.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Cable_Lift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Cable Wood Chop', 'Abdominaux', 'Poulie', '1. Connect a standard handle to a tower, and move the cable to the highest pulley position. 2. With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the poids on the cable. Your outstretched arm should be aligned with the cable. 3. With vos pieds positioned epaules width apart, reach upward with your other hand and grab the handle with both hands. vos bras should still be fully extended. 4. In one motion, pull the handle down and across votre corps to your front genoux while rotating your torse. 5. Keep votre dos and arms straight and sangle abdominale tight while you pivot votre dos foot and bend your genoux to get a full range of motion. 6. Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner. 7. Repetez to failure. 8. Then, reposition and Repetez the same series of movements on the opposite side.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Cable_Wood_Chop/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Calf Raises', 'Mollets', 'Machine', '1. Adjust the padded lever of the calf raise machine to fit your height. 2. Place your epaules under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of vos pieds should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and genoux until your torse is standing erect. The genoux should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. Position de depart. 3. Raise your heels as you Expirez by extending your ankles as high as possible and flexing your calf. Ensure that the genoux is kept stationary en permanence. There should be no bending at any time. Hold the contracted position by a second before you start to go back down. 4. Go back Lentement, to the position de depart as you Inspirez by lowering your heels as you bend the ankles until mollets are stretched. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Calf_Raises/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Concentration Curl', 'Biceps', 'Haltères', '1. Taking a halteres in your working hand, lean forward. Allow your working arm to hang perpendicular to the ground with the coudes pointing out. Position de depart. 2. Flex the coudes to curl the poids, keeping the upper arm stationary. At the top of the repetition, flex the biceps and pause. 3. Lower the halteres back to the position de depart. 4. Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Concentration_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Dumbbell Calf Raise', 'Mollets', 'Haltères', '1. Tenez-vous debout avec your torse upright holding two halteres in vos mains by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch le sol. Position de depart. 2. With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off le sol en expirant by contracting the mollets. Hold the top contraction for a second. 3. en inspirant, go back to the position de depart by Lentement, lowering the heels. 4. Repetez for the recommended amount of times.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Calf_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Dumbbell Press', 'Épaules', 'Haltères', '1. Standing with vos pieds epaules width apart, take a halteres in each hand. Raise the halteres to head height, the coudes out and about 90 degrees. Position de depart. 2. Maintaining strict technique with no leg drive or leaning back, extend through the coudes to raise the poids together directly above your head. 3. Pause, and Lentement, return the poids to the position de depart.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Dumbbell Reverse Curl', 'Biceps', 'Haltères', '1. To begin, Tenez-vous debout avec a halteres in each hand using a pronated grip (palms facing down). vos bras should be fully extended while vos pieds are epaules width apart from each other. Position de depart. 2. While holding the upper arms stationary, curl the poids while contracting the biceps as you Expirez. Only the forearms should move. Continue le mouvement until your biceps are entierement contracte and the halteres are at epaules level. Maintenez 1 seconde as you squeeze the muscle. 3. Lentement, begin to bring the halteres back to position de depart as your Inspirez. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Reverse_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Dumbbell Straight-Arm Front Delt Raise Above Head', 'Épaules', 'Haltères', '1. Hold the halteres in front of your cuisses, palms facing your cuisses. 2. Keep vos bras straight with a slight bend at the coudes but keep them locked. Position de depart. 3. Raise the halteres in a semicircular motion to arm''s length overhead en expirant. 4. Lentement, Revenez en position de depart using the same path en inspirant. 5. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Dumbbell Triceps Extension', 'Triceps', 'Haltères', '1. To begin, Tenez-vous debout avec a halteres held by both hands. vos pieds should be about epaules width apart from each other. Lentement, use both hands to grab the halteres and lift it over your head until both arms are fully extended. 2. The resistance should be resting in the palms of vos mains with your thumbs around it. The palm of the hands should be facing up towards the ceiling. Position de depart. 3. Keeping your upper arms close to your head with coudes in and perpendicular to le sol, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Conseil : The upper arms should remain stationary and only the forearms should move. Inspirez as you perform this step. 4. Go back to the position de depart by using the triceps to raise the halteres. Expirez as you perform this step. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Dumbbell Upright Row', 'Trapèzes', 'Haltères', '1. Grasp a halteres in each hand with a pronated (palms forward) grip that is slightly less than epaules width. The halteres should be resting on top of your cuisses. vos bras should be extended with a slight bend at the coudes and votre dos should be straight. Position de depart. 2. Use your side epaules to lift the halteres en expirant. The halteres should be close to the body as you move it up and the coudes should drive the motion. Continue to lift them until they nearly touch your chin. Conseil : Your coudes should drive the motion. As you lift the halteres, your coudes should always be higher than your forearms. Also, keep your torse stationary and pause for a second at the top of le mouvement. 3. Lower the halteres back down Lentement, to the position de depart. Inhale as you perform this portion of le mouvement. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Dumbbell_Upright_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Elevated Quad Stretch', 'Quadriceps', 'Autre', '1. Start by standing with votre dos about two to three feet away from a banc or step. 2. Lift one leg behind you and rest your foot on the step,either on your instep or the ball of your foot, whichever you find most comfortable. 3. Keep your supporting genoux slightly bent and avoid letting that genoux extend out beyond your toes. Switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Elevated_Quad_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Front Barbell Raise Over Head', 'Épaules', 'Barre', '1. To begin, Tenez-vous debout avec a barre in vos mains. You should grip the bar with palms facing down and a closer than epaules width grip apart from each other. 2. vos pieds should be epaules width apart from each other. Your coudes should be slightly bent. Position de depart. 3. Lift the barre up until it is directly over your head while exhaling. Make sure to keep your coudes slightly bent when performing each repetition. 4. Once you feel the contraction, begin to lower the barre back down to the position de depart en inspirant. 5. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Front_Barbell_Raise_Over_Head/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Gastrocnemius Calf Stretch', 'Mollets', 'Autre', '1. Place your right heel on a step with your genoux extended and lean forward to grab your right toe with your right hand. Your left genoux should be slightly bent and votre dos should be straight. 2. Support your poids on your left leg and place your left hand on your left cuisses. 3. Pull your right toes toward your genoux until you feel a stretch in your calf.', 'Muscles secondaires : Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Gastrocnemius_Calf_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Hamstring and Calf Stretch', 'Ischio-jambiers', 'Autre', '1. Being by looping a belt, band, or rope around one foot. While standing, place that foot forward. 2. Bend votre dos leg, while keeping the front one straight. Now raise the toes of your front foot off of the ground and lean forward. 3. Using the belt, pull on the top of the foot to increase the stretch in the calf. Hold for 10-20 seconds and Repetez with the other foot.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Hamstring_and_Calf_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Hip Circles', 'Abducteurs', 'Poids de corps', '1. Begin standing on one leg, holding to a vertical support. 2. Raise the unsupported genoux to 90 degrees. Position de depart. 3. Open the hip as far as possible, attempting to make a big circle with your genoux. 4. Perform this movement Lentement, for a number of repetitions, and Repetez de l autre cote.', 'Muscles secondaires : Adducteurs. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Hip_Circles/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Hip Flexors', 'Quadriceps', 'Autre', '1. Tenez-vous debout avec the spine vertical, the left foot slightly in front of the right. 2. Bend both genoux and lift the back heel off le sol as you press the right hip forward. You can''t get a thorough, deep stretch in this position, however, because it''s hard to relax the hip flexor and stand on it at the same time. Switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Hip_Flexors/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Inner-Biceps Curl', 'Biceps', 'Haltères', '1. Tenez-vous debout avec a halteres in each hand being held bras tendus. The coudes should be close to the torse. vos jambes should be at about epaules''s width apart from each other. 2. Rotate the palms of the hands so that they are facing inward in a neutral position. Position de depart. 3. While holding the upper arms stationary, curl the poids out while contracting the biceps as you Expirez. Your poignets should turn so that when the poids are fully elevated you have supinated grip (palms facing up). 4. Only the forearms should move. Continue le mouvement until your biceps are entierement contracte and the halteres are at epaules level. Conseil : Keep the forearms aligned with your outer deltoids. 5. Maintenez 1 seconde as you squeeze the biceps. 6. Lentement, begin to bring the halteres back to the position de depart as your Inspirez. Remember to rotate the poignets as you lower the poids in order to switch back to a neutral grip. 7. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Inner-Biceps_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Lateral Stretch', 'Abdominaux', 'Autre', '1. Take a slightly wider than hip distance stance with your genoux slightly bent. 2. Place your right hand on your right hip to support the spine. 3. Raise your left arm in a vertical line and place your left hand behind your head. Keep it there as you incline your torse to the right. 4. Keep your poids evenly distributed between both legs (don''t lean into your left hip). Switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Lateral_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Leg Curl', 'Ischio-jambiers', 'Machine', '1. Adjust the machine lever to fit your height and lie with your torse bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for ischio-jambiers recruitment) with the pad of the lever on the back of your right leg (just a few inches under the mollets) and the front of the right leg on top of the machine pad. 2. Keeping the torse bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. Position de depart. 3. en expirant, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the entierement contracte position, hold it for a second. 4. en inspirant, bring the legs back to the initial position. Repetez selon le nombre souhaite. 5. Perform the same exercise now for the left leg.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Leg_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Long Jump', 'Quadriceps', 'Poids de corps', '1. This drill is best done in sand or other soft landing surface. Ensure that you are able to measure distance. Stand in a partial squat stance with feet epaules width apart. 2. Utilizing a big arm swing and a countermovement of the legs, jump forward as far as you can. 3. Attempt to land with vos pieds out in front you, reaching as far as possible with vos jambes. 4. Measure the distance from your landing point to the starting point and track results.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Long_Jump/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Low-Pulley Deltoid Raise', 'Épaules', 'Poulie', '1. Start by standing to the right side of a low pulley row. Use your left hand to come across the body and grab a single handle attached to the low pulley with a pronated grip (palms facing down). Rest your arm in front of you. Your right hand should grab the machine for better support and balance. 2. Make sure that votre dos is erect and vos pieds are epaules width apart from each other. Position de depart. 3. Begin to use the left hand and come across votre corps out until it is elevated to epaules height while exhaling. 4. Feel the contraction at the top for a second and begin to Lentement, lower the handle back down to the original position de depart while inhaling. 5. Repetez selon le nombre souhaite. 6. Switch arms and Repetez the exercise.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Low-Pulley_Deltoid_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Low-Pulley One-Arm Triceps Extension', 'Triceps', 'Poulie', '1. Grab a single handle with your left arm next to the low pulley machine. Turn away from the machine keeping the handle to the side of votre corps with your arm fully extended. Now use both hands to elevate the single handle directly above the head with the palm facing forward. Keep your upper arm completely vertical (perpendicular to le sol) and put your right hand on your left coudes to help keep it steady. Position de depart. 2. Keeping your upper arms close to your head (coudes in) and perpendicular to le sol, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Conseil : The upper arms should remain stationary and only the forearms should move. Inspirez as you perform this step. 3. Go back to the position de depart by using the triceps to raise the single handle. Expirez as you perform this step. 4. Repetez selon le nombre souhaite. 5. Switch arms and Repetez the exercise.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Low-Pulley_One-Arm_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Military Press', 'Épaules', 'Barre', '1. Start by placing a barre that is about poitrine high on a squat rack. Once you have selected the poids, grab the barre using a pronated (palms facing forward) grip. Make sure to grip the bar wider than epaules width apart from each other. 2. Slightly bend the genoux and place the barre on your collar bone. Lift the barre up keeping it lying on your poitrine. Take a step back and position vos pieds epaules width apart from each other. 3. Once you pick up the barre with the correct grip length, lift the bar up over your head by locking vos bras. Hold at about epaules level and slightly in front of your head. Position de depart. 4. Lower the bar down to the collarbone Lentement, en inspirant. 5. Lift the bar back up to the position de depart en expirant. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Military_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Olympic Plate Hand Squeeze', 'Avant-bras', 'Autre', '1. To begin, stand straight while holding a poids plate by the ridge at arm''s length in each hand using a neutral grip (palms facing in). You feet should be epaules width apart from each other. Position de depart. 2. Lower the plates until the fingers are nearly extended but can still hold poids. Inhale as you lower the plates. 3. Now raise the plates back to the position de depart en expirant by closing vos mains. 4. Repetez selon le nombre souhaite. prescribed in your program.', 'Muscles secondaires : Biceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Olympic_Plate_Hand_Squeeze/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing One-Arm Cable Curl', 'Biceps', 'Poulie', '1. Start out by grabbing single handle next to the low pulley machine. Make sure you are far enough from the machine so that your arm is supporting the poids. 2. Make sure that your upper arm is stationary, perpendicular to le sol with coudes in and palms facing forward. Your non lifting arm should be grabbing your waist. This will allow you to keep your balance. 3. Lentement, begin to curl the single handle upwards while keeping the upper arm stationary until your forearm touches your biceps while exhaling. Conseil : Only the forearm should move. 4. Hold the contraction position as you squeeze the biceps and then lower the single handle back down to the position de depart en inspirant. 5. Repetez selon le nombre souhaite. 6. Switch arms while performing this exercise.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_One-Arm_Cable_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing One-Arm Dumbbell Curl Over Incline Bench', 'Biceps', 'Haltères', '1. Stand on the back side of an incline banc as if you were going to be a spotter for someone. Have a halteres in one hand and rest it across the incline banc with a supinated (palms up) grip. 2. Position your non lifting hand at the corner or side of the incline banc. The poitrine should be pressed against the top part of the incline and vos pieds should be pressed against le sol at a wide stance. Position de depart. 3. While holding the upper arm stationary, curl the halteres upward while contracting the biceps as you Expirez. Only the forearms should move. Continue le mouvement until your biceps are entierement contracte and the halteres is at epaules level. Maintenez 1 seconde. 4. Lentement, begin to bring the halteres back to position de depart as your Inspirez. 5. Repetez selon le nombre souhaite. 6. Switch arms while performing this exercise.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing One-Arm Dumbbell Triceps Extension', 'Triceps', 'Haltères', '1. To begin, Tenez-vous debout avec a halteres held in one hand. vos pieds should be about epaules width apart from each other. Now fully extend the arm with the halteres over your head. Conseil : The small finger of your hand should be facing the ceiling and the palm of your hand should be facing forward. The halteres should be above your head. 2. Position de depart. 3. Keeping your upper arm close to your head (coudes in) and perpendicular to le sol, lower the resistance in a semicircular motion behind your head until your forearm touch your biceps. Conseil : The upper arm should remain stationary and only the forearm should move. Inspirez as you perform this step. 4. Go back to the position de depart by using the triceps to raise the halteres. Expirez as you perform this step. 5. Repetez selon le nombre souhaite. 6. Switch arms and Repetez the exercise.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_One-Arm_Dumbbell_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Overhead Barbell Triceps Extension', 'Triceps', 'Barre', '1. To begin, stand up holding a barre or e-z bar using a pronated grip (palms facing forward) with vos mains closer than epaules width apart from each other. vos pieds should be about epaules width apart. 2. Now elevate the barre above your head until vos bras are fully extended. Keep your coudes in. Position de depart. 3. Keeping your upper arms close to your head and coudes in, perpendicular to le sol, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Conseil : The upper arms should remain stationary and only the forearms should move. Inspirez as you perform this step. 4. Go back to the position de depart by using the triceps to raise the barre. Expirez as you perform this step. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Overhead_Barbell_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Palm-In One-Arm Dumbbell Press', 'Épaules', 'Haltères', '1. Start by having a halteres in one hand with your arm fully extended to the side using a neutral grip. Use your other arm to hold on to an incline banc to keep your balance. 2. vos pieds should be epaules width apart from each other. Now Lentement, lift the halteres up until you create a 90 degree angle with your arm. Note: Your forearm should be perpendicular to le sol. Continue to maintain a neutral grip throughout the entire exercise. 3. Lentement, lift the halteres up until your arm is fully extended. This the position de depart. 4. While inhaling lower the poids down until your arm is at a 90 degree angle again. 5. Feel the contraction for a second and then lift the poids back up towards the position de depart while exhaling. Remember to hold on to the incline banc and keep vos pieds positioned to keep balance during the exercise. 6. Repetez selon le nombre souhaite. 7. Switch arms and Repetez the exercise.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Palm-In_One-Arm_Dumbbell_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Palms-In Dumbbell Press', 'Épaules', 'Haltères', '1. Start by having a halteres in each hand with your arm fully extended to the side using a neutral grip. vos pieds should be epaules width apart from each other. Now Lentement, lift the halteres up until you create a 90 degree angle with vos bras. Note: Your forearms should be perpendicular to le sol. This the position de depart. 2. Continue to maintain a neutral grip throughout the entire exercise. Lentement, lift the halteres up until vos bras are fully extended. 3. While inhaling lower the poids down until your arm is at a 90 degree angle again. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Palms-In_Dumbbell_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Palms-Up Barbell Behind The Back Wrist Curl', 'Avant-bras', 'Barre', '1. Start by standing straight and holding a barre behind your fessiers at arm''s length while using a pronated grip (palms will be facing back away from the fessiers) and having vos mains epaules width apart from each other. 2. You should be looking straight forward while vos pieds are epaules width apart from each other. Position de depart. 3. While exhaling, Lentement, elevate the barre up by curling your poignets in a semi-circular motion towards the ceiling. Note: Your poignets should be the only body part moving for this exercise. 4. Hold the contraction for a second and lower the barre back down to the position de depart while inhaling. 5. Repetez selon le nombre souhaite. 6. When finished, lower the barre down to the squat rack or le sol by bending the genoux. Conseil : It is easiest to either pick it up from a squat rack or have a partner hand it to you.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Pelvic Tilt', 'Bas du dos', 'Autre', '1. Start off with vos pieds hip-distance apart. 2. Bend your genoux slightly to keep them soft and springy. 3. You may want to move your pelvis forward and backward and back few times before holding the tailbone forward in this stretch.', 'Muscles secondaires : Fessiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Pelvic_Tilt/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Rope Crunch', 'Abdominaux', 'Poulie', '1. Attach a rope to a high pulley and select an appropriate poids. 2. Tenez-vous debout avec votre dos to the cable tower. Take the rope with both hands over your epaules, holding it to your upper poitrine. Position de depart. 3. Perform le mouvement by flexing the spine, crunching the poids down as far as you can. 4. Hold the peak contraction for a moment before returning to the position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Rope_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Soleus And Achilles Stretch', 'Mollets', 'Autre', '1. Tenez-vous debout avec vos pieds hip-distance apart, one foot slightly in front of the other. 2. Bend both genoux, keeping votre dos heel on le sol. Switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Soleus_And_Achilles_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Toe Touches', 'Ischio-jambiers', 'Autre', '1. Tenez-vous debout avec some space in front and behind you. 2. Bend at the waist, keeping vos jambes straight, until you can relax and let your upper body hang down in front of you. Let vos bras and hands hang down naturally. Hold for 10 to 20 seconds.', 'Muscles secondaires : Mollets. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Toe_Touches/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Towel Triceps Extension', 'Triceps', 'Poids de corps', '1. To begin, Tenez-vous debout avec both arms fully extended above the head holding one end of a towel with both hands. Your coudes should be in and the arms perpendicular to le sol with the palms facing each other while vos pieds should be epaules width apart from each other. Position de depart. 2. Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance. Keeping your upper arms close to your head (coudes in) and perpendicular to le sol, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Conseil : The upper arms should remain stationary and only the forearms should move. Inspirez as you perform this step. 3. Go back to the position de depart by using the triceps to raise the towel. Expirez as you perform this step. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Towel_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Standing Two-Arm Overhead Throw', 'Épaules', 'Medecine ball', '1. Tenez-vous debout avec vos pieds epaules width apart holding a medicine ball in both hands. To begin, reach the medicine ball deep behind your head as you bend the genoux slightly and lean back. 2. Violently throw the ball forward, flexing at the hip and using your whole body to complete le mouvement. 3. The medicine ball can be thrown to a partner or to a wall, receiving it as it bounces back.', 'Muscles secondaires : Pectoraux, Dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Standing_Two-Arm_Overhead_Throw/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Star Jump', 'Quadriceps', 'Poids de corps', '1. Begin in a relaxed stance with vos pieds epaules width apart and hold vos bras close to the body. 2. To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, spreading vos jambes and arms away from the body. 3. As you land, bring your limbs back in and absorb your impact through the legs.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Star_Jump/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Step-up with Knee Raise', 'Fessiers', 'Poids de corps', '1. Stand facing a box or banc of an appropriate height with vos pieds together. Position de depart. 2. Begin le mouvement by stepping up, putting your left foot on the top of the banc. Extend through the hip and genoux of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right genoux and hip, bringing your genoux as high as you can. 3. Reverse this motion to step down off the box, and then Repetez the sequence on the opposite leg.', 'Muscles secondaires : Ischio-jambiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Step-up_with_Knee_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Step Mill', 'Quadriceps', 'Machine', '1. To begin, step onto the stepmill and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and poids to estimate the amount of calories burned during exercise. Use caution so that you don''t trip as you climb the stairs. It is recommended that you maintain your grip on the handles so that you don''t fall. 2. Stepmills offer convenience, cardiovascular benefits, and usually have less impact than running outside while offering a similar rate of calories burned. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Step_Mill/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Stiff-Legged Barbell Deadlift', 'Ischio-jambiers', 'Barre', '1. Grasp a bar using an prise en pronation (palms facing down). You may need some poignets wraps if using a significant amount of poids. 2. Tenez-vous debout avec your torse straight and vos jambes spaced using a epaules width or narrower stance. The genoux should be slightly bent. Position de depart. 3. Keeping the genoux stationary, lower the barre to over the top of vos pieds by bending at the hips while keeping votre dos straight. Keep moving forward as if you were going to pick something from le sol until you feel a stretch on the ischio-jambiers. Inhale as you perform this movement. 4. Start bringing your torse up straight again by extending your hips until you are back at the position de depart. Exhale as you perform this movement. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Fessiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Barbell_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Stiff-Legged Dumbbell Deadlift', 'Ischio-jambiers', 'Haltères', '1. Grasp a couple of halteres holding them by your side at arm''s length. 2. Tenez-vous debout avec your torse straight and vos jambes spaced using a epaules width or narrower stance. The genoux should be slightly bent. Position de depart. 3. Keeping the genoux stationary, lower the halteres to over the top of vos pieds by bending at the waist while keeping votre dos straight. Keep moving forward as if you were going to pick something from le sol until you feel a stretch on the ischio-jambiers. Exhale as you perform this movement 4. Start bringing your torse up straight again by extending your hips and waist until you are back at the position de depart. Inhale as you perform this movement. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Fessiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff-Legged_Dumbbell_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Stiff Leg Barbell Good Morning', 'Bas du dos', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your epaules (slightly below the neck) across it. 2. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Step away from the rack and position vos jambes using a epaules width medium stance. Keep your head up en permanence as looking down will get you off balance and also maintain a straight back. Position de depart. 4. Keeping vos jambes stationary, move your torse forward by bending at the hips while inhaling. Lower your torse until it is parallel with le sol. 5. Begin to raise the bar en expirant by elevating your torse back to the position de depart. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stiff_Leg_Barbell_Good_Morning/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Stomach Vacuum', 'Abdominaux', 'Poids de corps', '1. To begin, Tenez-vous debout avec vos pieds epaules width apart from each other. Place vos mains on your hips. Position de depart. 2. Now Lentement, inhale as much air as possible and then start to exhale as much as possible while bringing your stomach in as much as possible and hold this position. Try to visualize your navel touching your backbone. 3. One isometric contraction is around 20 seconds. During the 20 second hold, try to breathe normally. Then inhale and bring your stomach back to the position de depart. 4. Once you have practiced this exercise, try to perform this exercise for longer than 20 seconds. Conseil : You can work your way up to 40-60 seconds. 5. Repetez for the recommended amount of sets.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stomach_Vacuum/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Straight-Arm Dumbbell Pullover', 'Pectoraux', 'Haltères', '1. Place a halteres standing up on a flat banc. 2. Ensuring that the halteres stays securely placed at the top of the banc, lie perpendicular to the banc (torse across it as in forming a cross) with only your epaules lying on the surface. Hips should be below the banc and legs bent with feet firmly on le sol. The head will be off the banc as well. 3. Grasp the halteres with both hands and hold it straight over your poitrine bras tendus. Both palms should be pressing against the underside one of the sides of the halteres. Position de depart. Caution: Always ensure that the halteres used for this exercise is secure. Using a halteres with loose plates can result in the halteres falling apart and falling on your face. 4. While keeping vos bras straight, lower the poids Lentement, in an arc behind your head while breathing in until you feel a stretch on the poitrine. 5. At that point, bring the halteres back to the position de depart using the arc through which the poids was lowered and exhale as you perform this movement. 6. Hold the poids on the initial position for a second and Repetez the motion for the prescribed number of repetitions.', 'Muscles secondaires : Dos, Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Straight-Arm_Dumbbell_Pullover/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Straight-Arm Pulldown', 'Dos', 'Poulie', '1. You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than epaules-width pronated (palms down) grip. Step backwards two feet or so. 2. Bend your torse forward at the waist by around 30-degrees with vos bras fully extended in front of you and a slight bend at the coudes. If vos bras are not fully extended then you need to step a bit more backwards until they are. Once vos bras are fully extended and your torse is slightly bent at the waist, tighten the lats and then you are ready to begin. 3. While keeping the arms straight, pull the bar down by contracting the lats until vos mains are next to the side of the cuisses. Expirez as you perform this step. 4. While keeping the arms straight, go back to the position de depart while breathing in. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Straight-Arm_Pulldown/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Straight Bar Bench Mid Rows', 'Milieu du dos', 'Barre', '1. Place a loaded barre on the end of a banc. Standing on the banc behind the bar, take a medium, pronated grip. Tenez-vous debout avec your hips back and poitrine up, maintaining a neutral spine. Position de depart. 2. Row the bar to your torse by retracting the omoplates and flexing the coudes. Use a controlled movement with no jerking. 3. Apres une pause, Lentement, return the bar to the position de depart, ensuring to go all the way down.', 'Muscles secondaires : Biceps, Dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Straight_Bar_Bench_Mid_Rows/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Straight Raises on Incline Bench', 'Épaules', 'Barre', '1. Place a bar on the ground behind the head of an incline banc. 2. Lay on the banc face down. With a pronated grip, pick the barre up from le sol, keeping vos bras straight. Allow the bar to hang straight down. Position de depart. 3. To begin, raise the barre out in front of your head while keeping vos bras extended. 4. Revenez en position de depart.', 'Muscles secondaires : Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Straight_Raises_on_Incline_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Stride Jump Crossover', 'Quadriceps', 'Autre', '1. Stand to the side of a box with your inside foot on top of it, close to the edge. 2. Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite genoux upward. 3. Land in the opposite position that you started, on the opposite side of the box. The foot that was initially on the box will now be on the ground, with the opposite foot now on the box. 4. Repetez le mouvement, crossing back over to the other side.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Stride_Jump_Crossover/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Sumo Deadlift', 'Ischio-jambiers', 'Barre', '1. Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the epaules, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the epaules, which in effect lengthens vos bras. 2. Take a breath, and then lower your hips, looking forward with your head with your poitrine up. Drive through le sol, spreading vos pieds apart, with your poids on the back half of vos pieds. Extend through the hips and genoux. 3. As the bar passes through the genoux, lean back and drive the hips into the bar, pulling your omoplates together. 4. Return the poids to the ground by bending at the hips and controlling the poids on the way down.', 'Muscles secondaires : Adducteurs, Avant-bras, Fessiers, Bas du dos, Milieu du dos, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sumo_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Sumo Deadlift with Bands', 'Ischio-jambiers', 'Barre', '1. To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. Ensure that they under the back half of your foot, directly where you are driving into le sol. 2. Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the epaules, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. 3. Take a breath, and then lower your hips, looking forward with your head with your poitrine up. Drive through le sol, spreading vos pieds apart, with your poids on the back half of vos pieds. Extend through the hips and genoux. 4. As the bar passes through the genoux, lean back and drive the hips into the bar, pulling your omoplates together. 5. Return the poids to the ground by bending at the hips and controlling the poids on the way down.', 'Muscles secondaires : Adducteurs, Avant-bras, Fessiers, Bas du dos, Milieu du dos, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sumo_Deadlift_with_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Sumo Deadlift with Chains', 'Ischio-jambiers', 'Barre', '1. You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater poids increase as you lift. Attempt to keep the ends of the chains away from the plates so you don''t hit them when you lower the poids. 2. Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the epaules, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the epaules, which in effect lengthens vos bras. 3. Take a breath, and then lower your hips, looking forward with your head with your poitrine up. Drive through le sol, spreading vos pieds apart, with your poids on the back half of vos pieds. Extend through the hips and genoux. 4. As the bar passes through the genoux, lean back and drive the hips into the bar, pulling your omoplates together. 5. Return the poids to the ground by bending at the hips and controlling the poids on the way down.', 'Muscles secondaires : Abducteurs, Adducteurs, Avant-bras, Fessiers, Bas du dos, Milieu du dos, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Sumo_Deadlift_with_Chains/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Superman', 'Bas du dos', 'Poids de corps', '1. To begin, lie straight and face down on le sol or exercise mat. vos bras should be fully extended in front of you. Position de depart. 2. Simultaneously raise vos bras, legs, and poitrine off of le sol and hold this contraction for 2 seconds. Conseil : Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying. 3. Lentement, begin to lower vos bras, legs and poitrine back down to the position de depart while inhaling. 4. Repetez selon le nombre souhaite. prescribed in your program.', 'Muscles secondaires : Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Superman/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Supine Chest Throw', 'Triceps', 'Medecine ball', '1. This drill is great for poitrine passes when you lack a partner or a wall of sufficient strength. Lay on the ground on votre dos with your genoux bent. 2. Begin with the ball on your poitrine, held with both hands on the bottom. 3. Explode up, extending through the coudes to throw the ball directly above you as high as possible. 4. Catch the ball with both hands as it comes down.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Supine_Chest_Throw/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Supine One-Arm Overhead Throw', 'Abdominaux', 'Medecine ball', '1. Lay on the ground on votre dos with your genoux bent. Hold the ball with one hand, extending the arm fully behind your head. Position de depart. 2. Initiate le mouvement at the epaules, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance. 3. The ball can be thrown to a partner or bounced off of a wall.', 'Muscles secondaires : Pectoraux, Dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Supine_One-Arm_Overhead_Throw/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Supine Two-Arm Overhead Throw', 'Abdominaux', 'Medecine ball', '1. Lay on the ground on votre dos with your genoux bent. 2. Hold the ball with both hands, extending the arms fully behind your head. Position de depart. 3. Initiate le mouvement at the epaules, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance. 4. The ball can be thrown to a partner or bounced off of a wall.', 'Muscles secondaires : Pectoraux, Dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Supine_Two-Arm_Overhead_Throw/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Suspended Fallout', 'Abdominaux', 'Autre', '1. Adjust the straps so the handles are at an appropriate height, below waist level. 2. Begin standing and grasping the handles. Lean into the straps, moving to an incline push-up position. Position de depart. 3. Keeping vos bras straight, lean further into the suspension straps, bringing votre corps closer to the ground, allowing your epaules to extend, raising vos bras up and over your head. 4. Maintain a neutral spine and keep the rest of votre corps straight, your epaules being the only joints allowed to move. 5. Pause during the peak contraction, and then Revenez en position de depart.', 'Muscles secondaires : Pectoraux, Bas du dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Fallout/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Suspended Push-Up', 'Pectoraux', 'Autre', '1. Anchor your suspension straps securely to the top of a rack or other object. 2. Leaning into the straps, take a handle in each hand and move into a push-up plank position. You should be as close to parallel to the ground as you can manage with vos bras fully extended, maintaining good posture. 3. Maintaining a straight, rigid torse, descend Lentement, by allowing the coudes to flex. 4. Continue until your coudes break 90 degrees, pausing before you extend to Revenez en position de depart.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Push-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Suspended Reverse Crunch', 'Abdominaux', 'Autre', '1. Secure a set of suspension straps with the handles hanging about a foot off of the ground. Move yourself into a pushup plank position facing away from the rack. 2. Place vos pieds into the handles. You should maintain a straight posture, not allowing the hips to sag. Position de depart. 3. Begin le mouvement by flexing the genoux and hips, drawing the genoux to your torse. As you do so, anteriorly tilt your pelvis, allowing your spine to flex. 4. At the top of the controlled motion, Revenez en position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Reverse_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Suspended Row', 'Milieu du dos', 'Autre', '1. Suspend your straps at around poitrine height. Take a handle in each hand and lean back. Keep votre corps erect and your head and poitrine up. vos bras should be fully extended. Position de depart. 2. Begin by flexing the coudes to initiate le mouvement. Protract your omoplates as you do so. 3. At the completion of the motion pause, and then Revenez en position de depart.', 'Muscles secondaires : Biceps, Dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Suspended Split Squat', 'Quadriceps', 'Autre', '1. Suspend your straps so the handles are 18-30 inches from le sol. 2. Facing away from the setup, place your rear foot into the handle behind you. Keep your head looking forward and your poitrine up, with your genoux slightly bent. Position de depart. 3. Descend by flexing the genoux and hips, lowering yourself to the ground. Keep your poids on the heel of your foot and maintain your posture throughout the exercise. 4. At the bottom of le mouvement, reverse the motion, extending through the hip and genoux to Revenez en position de depart.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Suspended_Split_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Svend Press', 'Pectoraux', 'Autre', '1. Begin in a standing position. 2. Press two lightweight plates together with vos mains. Hold the plates together close to your poitrine to create an isometric contraction in your poitrine muscles. Your fingers should be pointed forward. Position de depart. 3. Squeeze the plates between your palms and extend vos bras directly out in front of you in a controlled motion. 4. Pause at the top of the motion, and then Lentement, Revenez en position de depart.', 'Muscles secondaires : Avant-bras, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Svend_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('T-Bar Row with Handle', 'Milieu du dos', 'Barre', '1. Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate poids onto your end. 2. Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position. 3. Assume a wide stance with your hips back and your poitrine up. vos bras should be extended. Position de depart. 4. Pull the poids to your upper abdomen by retracting the omoplates and flexing the coudes. Do not jerk the poids or cheat during le mouvement. 5. Apres une pause, Revenez en position de depart.', 'Muscles secondaires : Biceps, Dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/T-Bar_Row_with_Handle/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Tate Press', 'Triceps', 'Haltères', '1. Allongez-vous sur un banc plat with a halteres in each hand on top of your cuisses. The palms of your hand will be facing each other. 2. By using your cuisses to help you get the halteres up, clean the halteres one arm at a time so that you can hold them in front of you at epaules width. Note: when holding the halteres in front of you, make sure vos bras are wider than epaules width apart from each other using a pronated (palms forward) grip. Allow your coudes to point out. Position de depart. 3. Keeping the upper arms stationary, Lentement, move the halteres in and down in a semi circular motion until they touch the upper poitrine while inhaling. Keep full control of the halteres en permanence and do not move the upper arms nor rest the halteres on the poitrine. 4. As you Expirez, move the halteres up using your triceps and the same semi-circular motion but in reverse. Attempt to keep the halteres together as they move up. Lock vos bras in the contracted position, Maintenez 1 seconde and then start coming down again Lentement, again. Conseil : It should take at least twice as long to go down than to come up. 5. Repetez le mouvement for the prescribed amount of repetitions of your training program.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tate_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('The Straddle', 'Ischio-jambiers', 'Autre', '1. Begin in a seated, upright position. Start by extending vos jambes in front of you in a V. 2. With vos mains on le sol, lean forward as far as possible. Hold for 10 to 20 seconds.', 'Muscles secondaires : Adducteurs, Mollets. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/The_Straddle/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Thigh Abductor', 'Abducteurs', 'Machine', '1. To begin, sit down on the abductor machine and select a poids you are comfortable with. When vos jambes are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. Position de depart. 2. Lentement, press against the machine with vos jambes to move them away from each other while exhaling. 3. Feel the contraction for a second and begin to move vos jambes back to the position de depart while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Fessiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Thigh_Abductor/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Thigh Adductor', 'Adducteurs', 'Machine', '1. To begin, sit down on the adductor machine and select a poids you are comfortable with. When vos jambes are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. Position de depart. 2. Lentement, press against the machine with vos jambes to move them towards each other while exhaling. 3. Feel the contraction for a second and begin to move vos jambes back to the position de depart while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Thigh_Adductor/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Tire Flip', 'Quadriceps', 'Autre', '1. Begin by gripping the bottom of the tire on the tread, and position vos pieds back a bit. Your poitrine should be driving into the tire. 2. To lift the tire, extend through the hips, genoux, and ankles, driving into the tire and up. 3. As the tire reaches a 45 degree angle, step forward and drive a genoux into the tire. As you do so adjust your grip to the upper portion of the tire and push it forward as hard as possible to complete the turn. Repetez as necessary.', 'Muscles secondaires : Mollets, Pectoraux, Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Épaules, Trapèzes, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tire_Flip/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Toe Touchers', 'Abdominaux', 'Poids de corps', '1. To begin, Allongez-vous au sol or an exercise mat with votre dos pressed against le sol. vos bras should be lying across your sides with the palms facing down. 2. vos jambes should be touching each other. Lentement, elevate vos jambes up in the air until they are almost perpendicular to le sol with a slight bend at the genoux. vos pieds should be parallel to le sol. 3. Move vos bras so that they are fully extended at a 45 degree angle from le sol. Position de depart. 4. While keeping your lower back pressed against le sol, Lentement, lift your torse and use vos mains to try and touch your toes. Remember to exhale while perform this part of the exercise. 5. Lentement, begin to lower your torse and arms back down to the position de depart while inhaling. Remember to keep vos bras straight out pointing towards your toes. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Toe_Touchers/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Torso Rotation', 'Abdominaux', 'Swiss ball', '1. Stand upright holding an exercise ball with both hands. Extend vos bras so the ball is straight out in front of you. Position de depart. 2. Rotate your torse to one side, keeping your eyes on the ball as you move. Now, rotate back to the opposite direction. Repetez for 10-20 repetitions.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Torso_Rotation/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Trail Running/Walking', 'Quadriceps', 'Autre', '1. Running or hiking on trails will get the blood pumping and heart beating almost immediately. Make sure you have good shoes. While you use the muscles in your mollets and buttocks to pull yourself up a hill, the genoux, joints and ankles absorb the bulk of the pounding coming back down. Take smaller steps as you walk downhill, keep your genoux bent to reduce the impact and slow down to avoid falling. 2. A 150 lb person can burn over 200 calories for 30 minutes walking uphill, compared to 175 on a flat surface. If running the trail, a 150 lb person can burn well over 500 calories in 30 minutes.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Trail_Running_Walking/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Trap Bar Deadlift', 'Quadriceps', 'Autre', '1. For this exercise load a trap bar, also known as a hex bar, to an appropriate poids resting on the ground. Stand in the center of the apparatus and grasp both handles. 2. Lower your hips, look forward with your head and keep your poitrine up. 3. Begin le mouvement by driving through the heels and extend your hips and genoux. Avoid rounding votre dos en permanence. 4. At the completion of le mouvement, lower the poids back to the ground under control.', 'Muscles secondaires : Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Trap_Bar_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Tricep Dumbbell Kickback', 'Triceps', 'Haltères', '1. Start with a halteres in each hand and your palms facing your torse. Keep votre dos straight with a slight bend in the genoux and bend forward at the waist. Your torse should be almost parallel to le sol. Make sure to keep your head up. Your upper arms should be close to your torse and parallel to le sol. Your forearms should be pointed towards le sol as you hold the poids. There should be a 90-degree angle formed between your forearm and upper arm. Position de depart. 2. Now, while keeping your upper arms stationary, exhale and use your triceps to lift the poids until the arm is fully extended. Focus on moving the forearm. 3. Apres une pause, at the top contraction, inhale and Lentement, lower the halteres back down to the position de depart. 4. Repetez le mouvement for the prescribed amount of repetitions.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tricep_Dumbbell_Kickback/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Tricep Side Stretch', 'Triceps', 'Autre', '1. Bring right arm across votre corps and over your left epaules, holding your coudes with your left hand, until you feel a stretch in your triceps. Then Repetez for your other arm.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tricep_Side_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Triceps Overhead Extension with Rope', 'Triceps', 'Poulie', '1. Attach a rope to a low pulley. After selecting an appropriate poids, grasp the rope with both hands and face away from the cable. 2. Position vos mains behind your head with your coudes point straight up. Your coudes should start out flexed, and you can stagger your stance and lean gently away from the machine to create greater stability. Position de depart. 3. To perform le mouvement, extend through the coudes while keeping the upper arm in position, raising vos mains above your head. 4. Squeeze your triceps at the top of le mouvement, and Lentement, lower the poids back to the start position.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Overhead_Extension_with_Rope/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Triceps Pushdown', 'Triceps', 'Poulie', '1. Attach a straight or angled bar to a high pulley and grab with an prise en pronation (palms facing down) at epaules width. 2. Standing upright with the torse straight and a very small inclination forward, bring the upper arms close to votre corps and perpendicular to le sol. The forearms should be pointing up towards the pulley as they hold the bar. Position de depart. 3. Using the triceps, bring the bar down until it touches the front of your cuisses and the arms are fully extended perpendicular to le sol. The upper arms should always remain stationary next to your torse and only the forearms should move. Exhale as you perform this movement. 4. After a second hold at the contracted position, bring the bar Lentement, up to the starting point. Inspirez as you perform this step. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Triceps Pushdown - Rope Attachment', 'Triceps', 'Poulie', '1. Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other). 2. Standing upright with the torse straight and a very small inclination forward, bring the upper arms close to votre corps and perpendicular to le sol. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. Position de depart. 3. Using the triceps, bring the rope down as you bring each side of the rope to the side of your cuisses. At the end of le mouvement the arms are fully extended and perpendicular to le sol. The upper arms should always remain stationary next to your torse and only the forearms should move. Exhale as you perform this movement. 4. After holding for a second, at the contracted position, bring the rope Lentement, up to the starting point. Inspirez as you perform this step. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown_-_Rope_Attachment/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Triceps Pushdown - V-Bar Attachment', 'Triceps', 'Poulie', '1. Attach a V-Bar to a high pulley and grab with an prise en pronation (palms facing down) at epaules width. 2. Standing upright with the torse straight and a very small inclination forward, bring the upper arms close to votre corps and perpendicular to le sol. The forearms should be pointing up towards the pulley as they hold the bar. The thumbs should be higher than the small finger. Position de depart. 3. Using the triceps, bring the bar down until it touches the front of your cuisses and the arms are fully extended perpendicular to le sol. The upper arms should always remain stationary next to your torse and only the forearms should move. Exhale as you perform this movement. 4. After a second hold at the contracted position, bring the V-Bar Lentement, up to the starting point. Inspirez as you perform this step. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Pushdown_-_V-Bar_Attachment/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Triceps Stretch', 'Triceps', 'Autre', '1. Reach your hand behind your head, grasp your coudes and gently pull. Hold for 10 to 20 seconds, then switch sides.', 'Muscles secondaires : Dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Triceps_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Tuck Crunch', 'Abdominaux', 'Poids de corps', '1. To begin, Allongez-vous au sol or an exercise mat with votre dos pressed against le sol. vos bras should be lying across your sides with the palms facing down. 2. vos jambes should be crossed by wrapping one ankle around the other. Lentement, elevate vos jambes up in the air until your cuisses are perpendicular to le sol with a slight bend at the genoux. Note: Your genoux and toes should be parallel to le sol as opposed to the cuisses. 3. Move vos bras from le sol and cross them so they are resting on your poitrine. Position de depart. 4. While keeping your lower back pressed against le sol, Lentement, lift your torse. Remember to exhale while perform this part of the exercise. 5. Lentement, begin to lower your torse back down to the position de depart while inhaling. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Tuck_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Two-Arm Dumbbell Preacher Curl', 'Biceps', 'Haltères', '1. Grab a halteres with each arm and place the upper arms on top of the preacher banc or the incline banc. The halteres should be held at epaules length. Position de depart. 2. As you Inspirez, Lentement, lower the halteres until your upper arm is extended and the biceps is fully stretched. 3. en expirant, use the biceps to curl the poids up until your biceps is entierement contracte and the halteres are at epaules height. 4. Squeeze the biceps hard for a second at the contracted position and Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Two-Arm_Dumbbell_Preacher_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Two-Arm Kettlebell Clean', 'Épaules', 'Kettlebell', '1. Place two kettlebells between vos pieds. To get in the position de depart, push your butt back and look straight ahead. 2. Clean the kettlebells to your epaules by extending through the legs and hips as you raise the kettlebells towards your epaules. Rotate your poignets as you do so. 3. Lower the kettlebells back to the position de depart and Repetez.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Two-Arm_Kettlebell_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Two-Arm Kettlebell Jerk', 'Épaules', 'Kettlebell', '1. Clean two kettlebells to your epaules. Clean the kettlebells to your epaules by extending through the legs and hips as you swing the kettlebells towards your epaules. Rotate your poignets as you do so, so that the palms face forward. Squat down a few inches and reverse the motion rapidly driving both kettlebells overhead. Immediately after the initial push, squat down again and get under the kettlebells. Once the kettlebells are locked out, stand upright to complete the exercise.', 'Muscles secondaires : Mollets, Quadriceps, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Two-Arm_Kettlebell_Jerk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Two-Arm Kettlebell Military Press', 'Épaules', 'Kettlebell', '1. Clean two kettlebells to your epaules. Clean the kettlebells to your epaules by extending through the legs and hips as you swing the kettlebells towards your epaules. Rotate your poignets as you do so, so that the palms face forward. 2. Press the kettlebells up and out. As the kettlebells pass your head, lean into the poids so that the kettlebells are racked behind your head. Make sure to contract your lats, butt, and stomach for added stability.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Two-Arm_Kettlebell_Military_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Two-Arm Kettlebell Row', 'Milieu du dos', 'Kettlebell', '1. Place two kettlebells in front of vos pieds. Bend your genoux slightly and then push your butt out as much as possible as you bend over to get in the position de depart. 2. Grab both kettlebells and pull them to your stomach, retracting your omoplates and flexing the coudes. Keep votre dos straight. Lower and Repetez.', 'Muscles secondaires : Biceps, Dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Two-Arm_Kettlebell_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Underhand Cable Pulldowns', 'Dos', 'Poulie', '1. Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the genoux pad of the machine to fit your height. These pads will prevent votre corps from being raised by the resistance attached to the bar. 2. Grab the pull-down bar with the palms facing your torse (a supinated grip). Make sure that the hands are placed closer than the epaules width. 3. As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torse back around 30 degrees or so while creating a curvature on your lower back and sticking your poitrine out. Position de depart. 4. As you Expirez, pull the bar down until it touches your upper poitrine by drawing the epaules and the upper arms down and back. Conseil : Concentrate on squeezing the back muscles once you reach the entierement contracte position and keep the coudes close to votre corps. The upper torse should remain stationary as your bring the bar to you and only the arms should move. The forearms should do no other work other than hold the bar. 5. After a second on the contracted position, while breathing in, Lentement, bring the bar back to the position de depart when vos bras are fully extended and the lats are fully stretched. 6. Repetez this motion for the prescribed amount of repetitions.', 'Muscles secondaires : Biceps, Milieu du dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Underhand_Cable_Pulldowns/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Upper Back-Leg Grab', 'Ischio-jambiers', 'Autre', '1. While seated, bend forward to hug your cuisses from underneath with both arms. 2. Keep your genoux together and vos jambes extended out as you bring your poitrine down to your genoux. You can also stretch your middle back by pulling votre dos away from your genoux as your hugging them.', 'Muscles secondaires : Bas du dos, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upper_Back-Leg_Grab/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Upper Back Stretch', 'Milieu du dos', 'Autre', '1. Clasp fingers together with your thumbs pointing down, round your epaules as you reach vos mains forward.', 'Muscles secondaires : Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upper_Back_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Upright Barbell Row', 'Épaules', 'Barre', '1. Grasp a barre with an prise en pronation that is slightly less than epaules width. The bar should be resting on the top of your cuisses with vos bras extended and a slight bend in your coudes. votre dos should also be straight. Position de depart. 2. Now exhale and use the sides of your epaules to lift the bar, raising your coudes up and to the side. Keep the bar close to votre corps as you raise it. Continue to lift the bar until it nearly touches your chin. Conseil : Your coudes should drive the motion, and should always be higher than your forearms. Remember to keep your torse stationary and pause for a second at the top of le mouvement. 3. Lower the bar back down Lentement, to the position de depart. Inhale as you perform this portion of le mouvement. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Barbell_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Upright Cable Row', 'Trapèzes', 'Poulie', '1. Grasp a straight bar cable attachment that is attached to a low pulley with a pronated (palms facing your cuisses) grip that is slightly less than epaules width. The bar should be resting on top of your cuisses. vos bras should be extended with a slight bend at the coudes and votre dos should be straight. Position de depart. 2. Use your side epaules to lift the cable bar en expirant. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Conseil : Your coudes should drive the motion. As you lift the bar, your coudes should always be higher than your forearms. Also, keep your torse stationary and pause for a second at the top of le mouvement. 3. Lower the bar back down Lentement, to the position de depart. Inhale as you perform this portion of le mouvement. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Cable_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Upright Row - With Bands', 'Trapèzes', 'Élastique', '1. To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your cuisses) grip that is slightly less than epaules width. The handles should be resting on top of your cuisses. vos bras should be extended with a slight bend at the coudes and votre dos should be straight. Position de depart. 2. Use your side epaules to lift the handles en expirant. The handles should be close to the body as you move them up. Continue to lift the handles until they nearly touches your chin. Conseil : Your coudes should drive the motion. As you lift the handles, your coudes should always be higher than your forearms. Also, keep your torse stationary and pause for a second at the top of le mouvement. 3. Lower the handles back down Lentement, to the position de depart. Inhale as you perform this portion of le mouvement. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upright_Row_-_With_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Upward Stretch', 'Épaules', 'Autre', '1. Extend both hands straight above your head, palms touching. 2. Lentement, push vos mains up and back, keeping votre dos straight.', 'Muscles secondaires : Pectoraux, Dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Upward_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('V-Bar Pulldown', 'Dos', 'Poulie', '1. Sit down on a pull-down machine with a V-Bar attached to the top pulley. 2. Adjust the genoux pad of the machine to fit your height. These pads will prevent votre corps from being raised by the resistance attached to the bar. 3. Grab the V-bar with the palms facing each other (a neutral grip). Stick your poitrine out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. Position de depart. 4. Using your lats, pull the bar down as you squeeze your omoplates. Continue until your poitrine nearly touches the V-bar. Exhale as you execute this motion. Conseil : Keep the torse stationary throughout le mouvement. 5. After a second hold on the contracted position, Lentement, bring the bar back to the position de depart as you Inspirez. 6. Repetez for the prescribed number of repetitions.', 'Muscles secondaires : Biceps, Milieu du dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/V-Bar_Pulldown/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('V-Bar Pullup', 'Dos', 'Poids de corps', '1. Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles). The V-Bar handles will be facing down so that you can hang from the pull-up bar through the use of the handles. 2. Once you securely place the V-bar, take a hold of the bar from each side and hang from it. Stick your poitrine out and lean yourself back slightly in order to better engage the lats. Position de depart. 3. Using your lats, pull your torse up while leaning your head back slightly so that you do not hit yourself with the chin-up bar. Continue until your poitrine nearly touches the V-bar. Exhale as you execute this motion. 4. After a second hold on the contracted position, Lentement, lower votre corps back to the position de depart as you Inspirez. 5. Repetez for the prescribed number of repetitions.', 'Muscles secondaires : Biceps, Milieu du dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/V-Bar_Pullup/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Vertical Swing', 'Ischio-jambiers', 'Haltères', '1. Allow the halteres to hang bras tendus between vos jambes, holding it with both hands. Keep votre dos straight and your head up. 2. Swing the halteres between vos jambes, flexing at the hips and bending the genoux slightly. 3. Powerfully reverse the motion by extending at the hips, genoux, and ankles to propel yourself upward, swinging the dumbell over your head. 4. As you land, absorb the impact through vos jambes and draw the halteres to your torse before the next repetition.', 'Muscles secondaires : Fessiers, Quadriceps, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Vertical_Swing/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Walking, Treadmill', 'Quadriceps', 'Machine', '1. To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and poids to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout. 2. Treadmills offer convenience, cardiovascular benefits, and usually have less impact than walking outside. When walking, you should move at a moderate to fast pace, not a leisurely one. Being an activity of lower intensity, walking doesn''t burn as many calories as some other activities, but still provides great benefit. A 150 lb person will burn about 175 calories walking 4 miles per hour for 30 minutes, compared to 450 calories running twice as fast. Maintain proper posture as you walk, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Walking_Treadmill/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Weighted Ball Hyperextension', 'Bas du dos', 'Swiss ball', '1. To begin, lie down on an exercise ball with your torse pressing against the ball and parallel to le sol. The ball of vos pieds should be pressed against le sol to help keep you balanced. Place a weighted plate under your chin or behind your neck. Position de depart. 2. Lentement, raise your torse up by bending at the waist and lower back. Remember to exhale during this movement. 3. Hold the contraction on your lower back for a second and lower your torse back down to the position de depart while inhaling. 4. Repetez selon le nombre souhaite. prescribed in your program.', 'Muscles secondaires : Fessiers, Ischio-jambiers, Milieu du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Ball_Hyperextension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Weighted Ball Side Bend', 'Abdominaux', 'Swiss ball', '1. To begin, lie down on an exercise ball with your left side of the torse (waist, hips and epaules) pressed against the ball. 2. vos pieds should be on le sol while vos jambes are crossed and hanging from the ball. Hold a weighted plate with your right hand directly to the right side of your head. Conseil : Make sure the smooth side of the plate is resting against your head. 3. Place your left arm across your torse so that your palm is on your obliques. There should be a right angle between your left forearm and upper arm. Position de depart. 4. Raise the side of your torse up by laterally flexing at the waist while exhaling. 5. Hold the contraction for a second and Lentement, lower yourself back down to the position de depart while inhaling. 6. Repetez selon le nombre souhaite. 7. Switch sides and Repetez the exercise.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Ball_Side_Bend/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Weighted Bench Dip', 'Triceps', 'Autre', '1. For this exercise you will need to place a banc behind votre dos and another one in front of you. With the benches perpendicular to votre corps, hold on to one banc on its edge with the hands close to votre corps, separated at epaules width. vos bras should be fully extended. 2. The legs will be extended forward on top of the other banc. vos jambes should be parallel to le sol while your torse is to be perpendicular to le sol. Have your partner place the halteres on your lap. Note: This exercise is best performed with a partner as placing the poids on your lap can be challenging and cause injury without assistance. Position de depart. 3. Lentement, lower votre corps en inspirant by bending at the coudes until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Conseil : Keep the coudes as close as possible throughout le mouvement. Forearms should always be pointing down. 4. Using your triceps to bring your torse up again, lift yourself back to the position de depart while exhaling. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Bench_Dip/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Weighted Crunches', 'Abdominaux', 'Medecine ball', '1. Allongez-vous au sol with vos pieds flat on the ground or resting on a banc with your genoux bent at a 90 degree angle. 2. Hold a poids to your poitrine, or you may hold it extended above your torse. Position de depart. 3. Now, exhale and Lentement, begin to roll your epaules off le sol. Your epaules should come up off le sol about 4 inches while your lower back remains on le sol. 4. At the top of le mouvement, flex your abdominals and hold for a brief pause. 5. Then inhale and Lentement, lower yourself back down to the position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Crunches/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Weighted Jump Squat', 'Quadriceps', 'Barre', '1. Position a lightly loaded barre across the back of your epaules. You could also use a weighted vest, sandbag, or other type of resistance for this exercise. 2. The poids should be light enough that it doesn''t slow you down significantly. vos pieds should be just outside of epaules width with your head and poitrine up. Position de depart. 3. Using a countermovement, squat partially down and immediately reverse your direction to explode off of the ground, extending through your hips, genoux, and ankles. Maintain good posture throughout the jump. 4. As you return to the ground, absorb the impact through vos jambes.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Jump_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Weighted Pull Ups', 'Dos', 'Autre', '1. Attach a poids to a dip belt and secure it around your waist. Grab the pull-up bar with the palms of vos mains facing forward. For a prise moyenne, vos mains should be spaced at epaules width. Both arms should be extended in front of you holding the bar at the chosen grip. 2. You''ll want to bring your torse back about 30 degrees while creating a curvature in your lower back and sticking your poitrine out. Position de depart. 3. Now, exhale and pull your torse up until your head is above vos mains. Concentrate on squeezing yourshoulder blades back and down as you reach the top contracted position. 4. After a brief moment at the top contracted position, inhale and Lentement, lower your torse back to the position de depart with vos bras extended and your lats fully stretched.', 'Muscles secondaires : Biceps, Milieu du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Pull_Ups/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Weighted Sissy Squat', 'Quadriceps', 'Barre', '1. Standing upright, with feet at epaules width and toes raised, use one hand to hold onto the beams of a squat rack and the opposite arm to hold a plate on top of your poitrine. Position de depart. 2. As you use one arm to hold yourself, bend at the genoux and Lentement, lower your torse toward the ground by bringing your pelvis and genoux forward. Inhale as you go down and stop when your upper and lower legs almost create a 90-degree angle. Hold the stretch position for a second. 3. After your one second hold, use your cuisses muscles to bring your torse back up to the position de depart. Exhale as you move up. 4. Repetez for the recommended amount of times.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Sissy_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Weighted Sit-Ups - With Bands', 'Abdominaux', 'Autre', '1. Start out by strapping the bands around the base of the decline banc. Place the handles towards the inside of the decline banc so that when lying down, you can reach for both of them. 2. Position vos jambes through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your poignets to a neutral grip (palms facing the torse). Note: vos bras should remain stationary throughout the exercise. Position de depart. 3. Move your torse upward until your upper body is perpendicular to le sol while exhaling. Hold the contraction for a second and lower your upper body back down to the position de depart while inhaling. 4. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Sit-Ups_-_With_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Weighted Squat', 'Quadriceps', 'Autre', '1. Start by positioning two flat benches epaules width apart from each other. Stand on top of them and wrap the weighted belt around your waist with the amount of poids you feel comfortable with. Make sure your toes are facing out. 2. Once you are standing straight up with the poids hanging in between vos jambes, position vos bras so that they are fully extended to the side of votre corps. Position de depart. 3. Begin by bending the genoux as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the mollets becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to le sol). Inhale as you perform this portion of le mouvement. Conseil : If you performed the exercise correctly, the front of the genoux should make an imaginary straight line with the toes that are perpendicular to the front. If your genoux are past that imaginary line (if they are past your toes) then you are placing undue stress on the genoux and the exercise has been performed incorrectly. 4. Begin to move the body back up by pushing le sol of the flat banc with the ball of your foot mainly as you straighten the legs again and go back to the position de depart. Exhale as you perform this portion of the exercise. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Weighted_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Wide-Grip Barbell Bench Press', 'Pectoraux', 'Barre', '1. Allongez-vous au sol on a flat banc with feet firm on le sol. Using a wide, pronated (palms forward) grip that is around 3 inches away from epaules width (for each hand), lift the bar from the rack and hold it straight over you with vos bras locked. The bar will be perpendicular to the torse and le sol. Position de depart. 2. As you Inspirez, come down Lentement, until you feel the bar on your middle poitrine. 3. Apres une pause, bring the bar back to the position de depart as you Expirez and push the bar using your poitrine muscles. Lock vos bras and squeeze your poitrine in the contracted position, Maintenez 1 seconde and then start coming down Lentement, again. Conseil : It should take at least twice as long to go down than to come up. 4. Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Barbell_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Wide-Grip Decline Barbell Bench Press', 'Pectoraux', 'Barre', '1. Allongez-vous au sol on a decline banc with the feet securely locked at the front of the banc. Using a wide, pronated (palms forward) grip that is around 3 inches away from epaules width (for each hand), lift the bar from the rack and hold it straight over you with vos bras locked. The bar will be perpendicular to the torse and le sol. Position de depart. 2. As you Inspirez, come down Lentement, until you feel the bar on your lower poitrine. 3. Apres une pause, bring the bar back to the position de depart as you Expirez and push the bar using your poitrine muscles. Lock vos bras and squeeze your poitrine in the contracted position, Maintenez 1 seconde and then start coming down Lentement, again. Conseil : It should take at least twice as long to go down than to come up. 4. Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Decline_Barbell_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Wide-Grip Decline Barbell Pullover', 'Pectoraux', 'Barre', '1. Allongez-vous sur un banc decline with both legs securely locked in position. Reach for the barre behind the head using a pronated grip (palms facing out). Make sure to grab the barre wider than epaules width apart for this exercise. Lentement, lift the barre up from le sol by using vos bras. 2. When positioned properly, vos bras should be fully extended and perpendicular to le sol. Position de depart. 3. Begin by moving the barre back down in a semicircular motion as if you were going to place it on le sol, but instead, stop when the arms are parallel to le sol. Conseil : Keep the arms fully extended en permanence. le mouvement should only happen at the epaules joint. Inhale as you perform this portion of le mouvement. 4. Now bring the barre up while exhaling until you are back at the position de depart. Remember to keep full control of the barre en permanence. 5. Repetez le mouvement for the prescribed amount of repetitions of your training program. 6. When finished with your set, Lentement, lower the barre back down until it is level with your head and release it.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Decline_Barbell_Pullover/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Wide-Grip Lat Pulldown', 'Dos', 'Poulie', '1. Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the genoux pad of the machine to fit your height. These pads will prevent votre corps from being raised by the resistance attached to the bar. 2. Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a prise large, vos mains need to be spaced out at a distance wider than epaules width. For a prise moyenne, vos mains need to be spaced out at a distance equal to your epaules width and for a close grip at a distance smaller than your epaules width. 3. As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torse back around 30 degrees or so while creating a curvature on your lower back and sticking your poitrine out. Position de depart. 4. As you Expirez, bring the bar down until it touches your upper poitrine by drawing the epaules and the upper arms down and back. Conseil : Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torse should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms. 5. After a second at the contracted position squeezing your omoplates together, Lentement, raise the bar back to the position de depart when vos bras are fully extended and the lats are fully stretched. Inhale during this portion of le mouvement. 6. Repetez this motion for the prescribed amount of repetitions.', 'Muscles secondaires : Biceps, Milieu du dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Lat_Pulldown/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Wide-Grip Pulldown Behind The Neck', 'Dos', 'Poulie', '1. Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the genoux pad of the machine to fit your height. These pads will prevent votre corps from being raised by the resistance attached to the bar. 2. Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a prise large, vos mains need to be spaced out at a distance wider than your epaules width. For a prise moyenne, vos mains need to be spaced out at a distance equal to your epaules width and for a close grip at a distance smaller than your epaules width. 3. As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torse and head forward. Think of an imaginary line from the center of the bar down to the back of your neck. Position de depart. 4. As you Expirez, bring the bar down until it touches the back of your neck by drawing the epaules and the upper arms down and back. Conseil : Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torse should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms. 5. After a second on the contracted position squeezing your omoplates together, Lentement, raise the bar back to the position de depart when vos bras are fully extended and the lats are fully stretched. Inhale during this portion of le mouvement. 6. Repetez this motion for the prescribed amount of repetitions.', 'Muscles secondaires : Biceps, Milieu du dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Pulldown_Behind_The_Neck/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Wide-Grip Rear Pull-Up', 'Dos', 'Poids de corps', '1. Grab the pull-up bar with the palms facing forward using a prise large. 2. As you have both arms extended in front of you holding the bar, bring your torse forward and head so that there is an imaginary line from the pull-up bar to the back of your neck. Position de depart. 3. Pull your torse up until the bar is near the back of your neck. To do this, draw the epaules and upper arms down and back while slightly leaning your head forward. Exhale as you perform this portion of le mouvement. Conseil : Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torse should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar. 4. After a second on the contracted position, start to inhale and Lentement, lower your torse back to the position de depart when vos bras are fully extended and the lats are fully stretched. 5. Repetez this motion for the prescribed amount of repetitions.', 'Muscles secondaires : Biceps, Milieu du dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Rear_Pull-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Wide-Grip Standing Barbell Curl', 'Biceps', 'Barre', '1. Tenez-vous debout avec your torse upright while holding a barre at the wide outer handle. The palm of vos mains should be facing forward. The coudes should be close to the torse. Position de depart. 2. While holding the upper arms stationary, curl the poids forward while contracting the biceps as you Expirez. Conseil : Only the forearms should move. 3. Continue le mouvement until your biceps are entierement contracte and the bar is at epaules level. Maintenez 1 seconde and squeeze the biceps hard. 4. Lentement, begin to bring the bar back to position de depart as your Inspirez. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide-Grip_Standing_Barbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Wide Stance Barbell Squat', 'Quadriceps', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your epaules (slightly below the neck) across it. 2. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Step away from the rack and position vos jambes using a wider-than-epaules-width stance with the toes slightly pointed out. Keep your head up en permanence as looking down will get you off balance, and also maintain a straight back. Position de depart. 4. Begin to Lentement, lower the bar by bending the genoux as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the mollets becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to le sol). Inhale as you perform this portion of le mouvement. Conseil : If you performed the exercise correctly, the front of the genoux should make an imaginary straight line with the toes that is perpendicular to the front. If your genoux are past that imaginary line (if they are past your toes) then you are placing undue stress on the genoux and the exercise has been performed incorrectly. 5. Begin to raise the bar en expirant by pushing le sol with the heel of your foot as you straighten the legs again and go back to the position de depart. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide_Stance_Barbell_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Wide Stance Stiff Legs', 'Ischio-jambiers', 'Barre', '1. Begin with a barre loaded on le sol. Adopt a wide stance, and then bend at the hips to grab the bar. Your hips should be as far back as possible, and vos jambes nearly straight. Keep votre dos straight, and your head and poitrine up. Position de depart. 2. Begin le mouvement be engaging the hips, driving them forward as you allow the arms to hang straight. Continue until you are standing straight up, and then Lentement, return the poids to the position de depart. For successive reps, the poids need not touch le sol.', 'Muscles secondaires : Adducteurs, Fessiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wide_Stance_Stiff_Legs/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Wind Sprints', 'Abdominaux', 'Poids de corps', '1. Hang from a pull-up bar using a pronated grip. vos bras and legs should be extended. Position de depart. 2. Begin by quickly raising one genoux as high as you can. Do not swing votre corps or vos jambes. 3 3. Immediately reverse the motion, returning that leg to the position de depart. Simultaneously raise the opposite genoux as high as possible. 4. Continue alternating between legs until the set is complete.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wind_Sprints/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Windmills', 'Abducteurs', 'Autre', '1. Allongez-vous au sol with vos bras extended out to the sides and vos jambes straight. Position de depart. 2. Lift one leg and quickly cross it over votre corps, attempting to touch the ground near the opposite hand. 3. Revenez en position de depart, and Repetez with the opposite leg. Continue to alternate for 10-20 repetitions.', 'Muscles secondaires : Fessiers, Ischio-jambiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Windmills/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('World''s Greatest Stretch', 'Ischio-jambiers', 'Autre', '1. This is a three-part stretch. Begin by lunging forward, with your front foot flat on the ground and on the toes of votre dos foot. With your genoux bent, squat down until your genoux is almost touching the ground. Keep your torse erect, and hold this position for 10-20 seconds. 2. Now, place the arm on the same side as your front leg on the ground, with the coudes next to the foot. Your other hand should be placed on the ground, parallel to your lead leg, to help support you during this portion of the stretch. 3. After 10-20 seconds, place vos mains on either side of your front foot. Raise the toes of the front foot off of the ground, and straighten your leg. You may need to reposition your rear leg to do so. Hold for 10-20 seconds, and then Repetez the entire sequence for the other side.', 'Muscles secondaires : Mollets, Fessiers, Quadriceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Worlds_Greatest_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Wrist Circles', 'Avant-bras', 'Poids de corps', '1. Start by standing straight with vos pieds being epaules width apart from each other. Elevate vos bras to the side of you until they are fully extended and parallel to le sol at a height that is evenly aligned with your epaules. Conseil : Your torse and arms should form the letter "T: Your palms should be facing down. Position de depart. 2. Keeping your entire body stationary except for the poignets, begin to rotate both poignets forward in a circular motion. Conseil : Pretend that you are trying to draw circles by using vos mains as the brush. Breathe normally as you perform this exercise. 3. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wrist_Circles/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Wrist Roller', 'Avant-bras', 'Autre', '1. To begin, stand straight up grabbing a poignets roller using a pronated grip (palms facing down). vos pieds should be epaules width apart. 2. Lentement, lift both arms until they are fully extended and parallel to le sol in front of you. Note: Make sure the rope is not wrapped around the roller. Your entire body should be stationary except for the forearms. Position de depart. 3. Rotate one poignets at a time in an upward motion to bring the poids up to the bar by rolling the rope around the roller. 4. Once the poids has reached the bar, Lentement, begin to lower the poids back down by rotating the poignets in a downward motion until the poids reaches the position de depart. 5. Repetez for the prescribed amount of repetitions in your program.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wrist_Roller/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Wrist Rotations with Straight Bar', 'Avant-bras', 'Barre', '1. Hold a barre with both hands and your palms facing down; hands spaced about epaules width. Position de depart. 2. Alternating between each of vos mains, perform le mouvement by extending the poignets as though you were rolling up a newspaper. Continue alternating back and forth until failure. 3. Reverse the motion by flexing the poignets, rolling the opposite direction. Continue the alternating motion until failure.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Wrist_Rotations_with_Straight_Bar/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Yoke Walk', 'Quadriceps', 'Autre', '1. The yoke is usually done with a yoke apparatus, but is sometimes seen with refrigerators or other heavy objects. 2. Begin by racking the apparatus across the back of the epaules. With your head looking forward and back arched, lift the yoke by driving through the heels. 3. Begin walking as quickly as possible using short, quick steps. You may hold the side posts of the yoke to help steady it and hold it in position. Continue for the given distance as fast as possible, usually 75-100 feet.', 'Muscles secondaires : Abdominaux, Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Yoke_Walk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Zercher Squats', 'Quadriceps', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. The correct height should be anywhere above the waist but below the poitrine. Once the correct height is chosen and the bar is loaded, lock vos mains together and place the bar on top of vos bras in between the forearm and upper arm. 2. Lift the bar up so that it is resting on top of your forearms. If you are holding the bar properly, it should look as if you have vos bras crossed but with a bar running across them. 3. Step away from the rack and position vos jambes using a epaules width medium stance with the toes slightly pointed out. Keep your head up en permanence as looking down will get you off balance and also maintain a straight back. Position de depart. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section). 4. Begin to lower the bar by bending the genoux as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the mollets becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to le sol). Inhale as you perform this portion of le mouvement. Conseil : If you performed the exercise correctly, the front of the genoux should make an imaginary straight line with the toes that is perpendicular to the front. If your genoux are past that imaginary line (if they are past your toes) then you are placing undue stress on the genoux and the exercise has been performed incorrectly. 5. Begin to raise the bar en expirant by pushing le sol with the ball of your foot mainly as you straighten the legs again and go back to the position de depart. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zercher_Squats/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Zottman Curl', 'Biceps', 'Haltères', '1. Tenez-vous debout avec your torse upright and a halteres in each hand being held bras tendus. The coudes should be close to the torse. 2. Make sure the palms of the hands are facing each other. Position de depart. 3. While holding the upper arm stationary, curl the poids while contracting the biceps as you Expirez. Only the forearms should move. Your poignets should rotate so that you have a supinated (palms up) grip. Continue le mouvement until your biceps are entierement contracte and the halteres are at epaules level. 4. Maintenez 1 seconde as you squeeze the biceps. 5. Now during the contracted position, rotate your poignets until you now have a pronated (palms facing down) grip with the thumb at a higher position than the pinky. 6. Lentement, begin to bring the halteres back down using the pronated grip. 7. As the halteres close your cuisses, start rotating the poignets so that you go back to a neutral (palms facing votre corps) grip. 8. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zottman_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Zottman Preacher Curl', 'Biceps', 'Haltères', '1. Grab a halteres in each hand and place your upper arms on top of the preacher banc or the incline banc. The halteres should be held at epaules height and the coudes should be flexed. Hold the halteres with the palms of vos mains facing down. Position de depart. 2. As you Inspirez, Lentement, lower the halteres keeping the palms down until your upper arm is extended and your biceps are fully stretched. 3. Now rotate your poignets once you are at the bottom of le mouvement so that the palms of the hands are facing up. 4. en expirant, use your biceps to curl the poids up until they are entierement contracte and the halteres are at epaules height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb. 5. Squeeze the biceps hard for a second at the contracted position and rotate your poignets so that the palms are facing down again. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Zottman_Preacher_Curl/0.jpg') ON CONFLICT DO NOTHING;
